# Ancien système gardé pour compatibilité

# Garder l'ancienne classe pour compatibilité mais elle n'est plus utilisée

async def is_fully_immune(member):
    """Vérifie si un membre est totalement immunisé (rôle ou utilisateur)"""
    if not member or not member.guild:
        return False
    
    # Owner / super-owner / admins sont toujours immunisés (audit 2026-07-02 : + super-owner)
    try:
        if owner_ids_module.is_super_owner(member.id):
            return True
    except Exception:
        pass
    if member.id == member.guild.owner_id or member.guild_permissions.administrator:
        return True
    #  19/10/2026 : la tête (fondateur, direction) et le staff et au-dessus ne sont jamais sanctionnés
    #  par un automatisme ; la tête les sanctionne elle-même, depuis le site.
    if member.id in TETE_IDS:
        return True
    try:
        if _staff_ou_plus(member.guild, member, await cfg(member.guild.id)):
            return True
    except Exception as ex:
        _logerr("immunite.staff", ex, guild_id=member.guild.id)
        return True

    # ⚠️ CORRECTIF MAJEUR (owner 2026-07-12) — LE CLONE OUBLIÉ.
    # Le cache d'immunité avait été branché sur `is_immune` et `is_channel_immune`… mais PAS ici.
    # Or `is_fully_immune` est appelée **2 à 5 fois PAR MESSAGE** (honeypot ~56915, anti_monologue
    # ~58198, pièces jointes, mentions…) et faisait 2 SELECT + 1 emprunt du pool À CHAQUE APPEL.
    # Résultat : 5 à 11 emprunts du pool (20 conns) par message humain → sous rafale, plus une
    # seule connexion libre → les callbacks de BOUTONS et les COMMANDES attendaient > 3 s →
    # « L'application ne répond plus » PARTOUT, avec **CPU à 0** (personne ne calcule : tout le
    # monde ATTEND). Le commentaire du pool (~l.647) décrivait déjà exactement ce symptôme.
    # → On passe par le MÊME cache 30 s (`_get_immunity`) : sémantique STRICTEMENT identique
    #   (mêmes tables immune_roles/immune_users, même guilde), invalidé par `_invalidate_immunity`.
    #   Les early-returns super-owner/owner/admin ci-dessus sont conservés, et `_get_immunity`
    #   PROPAGE l'erreur DB → le FAIL-SAFE « doute = immunisé » (invariant #1) marche toujours.
    try:
        _imm = await _get_immunity(member.guild.id)

        # Vérifier si le membre a un rôle immunisé
        if any(role.id in _imm['roles'] for role in member.roles):
            return True

        # Vérifier si l'utilisateur est directement immunisé
        if member.id in _imm['users']:
            return True

    except Exception as ex:
        print(f"Erreur vérification immunité: {ex}")
        return True  # FAIL-SAFE (audit 2026-07-02) : doute (erreur DB) → immunisé (invariant #1)

    return False


# ═════════════════════════════════════════════════════════════════════════════
#  🛡️ PRIMITIVE D'ISOLEMENT (founder-only security — TASK A1)
# ─────────────────────────────────────────────────────────────────────────────
#  RÈGLE DURE OWNER (2026-06-13) : AUCUN staff / AUCUN automatisme ne peut kick ni
#  bannir un membre. La seule réponse autorisée à un compte phishé/compromis/raid
#  côté bot est d'ISOLER (quarantaine) + ALERTER le fondateur. Le kick/ban réel
#  reste l'exclusivité du fondateur (owner_ids.is_super_owner).
#
#  `isolate_member` GÉNÉRALISE le rôle « Vérification » déjà créé par
#  raid_detector.run_lockdown : on l'ajoute au membre, on lui RETIRE ses rôles
#  sensibles (perms d'écriture/élevées), et on pose un timeout natif Discord en
#  filet. 100% FAIL-SAFE et IDEMPOTENT.
# ═════════════════════════════════════════════════════════════════════════════

# Noms reconnus comme rôle de quarantaine (alignés sur raid_detector).
_QUARANTINE_ROLE_NAMES = ("vérification", "verification", "verify", "quarantaine")
# Timeout natif posé en filet (max Discord = 28 jours).
_ISOLATION_TIMEOUT_DAYS = 28


def _is_sensitive_role(role) -> bool:
    """True si le rôle confère des perms 'sensibles' (écriture/modération/élevées)
    qu'on doit retirer en isolement. Fail-safe : en cas de doute => sensible (on
    préfère sur-restreindre un membre isolé que laisser une perm dangereuse)."""
    try:
        if role.is_default():  # @everyone : jamais retirable
            return False
        if getattr(role, "managed", False):  # rôles gérés (bot/booster/intégration)
            return False
        p = role.permissions
        return bool(
            p.administrator or p.manage_guild or p.manage_channels or p.manage_roles
            or p.manage_messages or p.kick_members or p.ban_members or p.moderate_members
            or p.mention_everyone or p.send_messages or p.send_messages_in_threads
            or p.create_public_threads or p.create_private_threads or p.add_reactions
            or p.connect or p.speak or p.manage_webhooks
        )
    except Exception:
        return True


# ═══════════════ /off — RADIATION TOTALE (owner 2026-06-21, « pris très au sérieux ») ═══════════════
# Retire TOUS les rôles (sauvegardés pour restauration), pose un rôle « 🚫 Radié » qui REFUSE
# view_channel + écriture + vocal PARTOUT → le membre reste présent mais ne voit/peut plus RIEN,
# jusqu'à /off off. Persistant (c'est un rôle Discord → survit aux reboots). Réservé via les
# permissions de commande Discord (défaut = admin ; l'owner attribue un rôle précis via
# Paramètres serveur → Intégrations → [bot] → /off). Filet : timeout natif 28 j en plus du rôle.
_RADIE_ROLE_NAME = "🚫 Radié"


#  ⚠️ NOIR, PAS 0x000000. Discord traite le noir pur comme « aucune couleur » :
#  le pseudo reprendrait la couleur du rôle suivant. 0x010101 est visuellement
#  noir ET compte comme une vraie couleur. Comme la radiation retire tous les
#  autres rôles, c'est LA couleur du membre : son nom s'affiche en noir.
_RADIE_COULEUR = 0x010101


def _radie_pseudo(membre) -> str:
    """Le pseudo de serveur d'un radié. Détruit l'identité, garde une trace.

    ⚠️ CE QUE ÇA FAIT ET CE QUE ÇA NE FAIT PAS. Le pseudo de SERVEUR disparaît
    de la liste des membres, des mentions et de la recherche par surnom. Le nom
    de compte Discord, lui, n'appartient pas au serveur : aucun bot ne peut le
    changer, et une recherche par `@identifiant` le retrouvera toujours. Le
    dire est plus utile que de laisser croire à un effacement total.

    Les quatre derniers chiffres de l'identifiant restent pour que le staff
    distingue deux radiés dans la liste — sinon ils portent tous le même nom.
    """
    return f"⛔ RADIÉ-{int(getattr(membre, 'id', 0)) % 10000:04d}"[:32]


def _radie_overwrite():
    """DENY TOTAL appliqué au rôle « 🚫 Radié » (vue/écriture/réactions/threads/vocal/
    historique/slash). Factorisé pour que _ensure_radie_role ET on_guild_channel_create
    posent EXACTEMENT le même refus (zéro dérive : un nouveau salon hérite du même blocage)."""
    return discord.PermissionOverwrite(
        view_channel=False, read_message_history=False, send_messages=False,
        add_reactions=False, create_public_threads=False, create_private_threads=False,
        send_messages_in_threads=False, connect=False, speak=False,
        use_application_commands=False)


off_group = app_commands.Group(
    name="off",
    description="🚫 Radiation totale d'un membre (Direction)",
    #  ⚠️ CE RÉGLAGE NE FAIT QUE L'AFFICHAGE, ET C'EST TOUT CE QU'ON PEUT
    #  FAIRE DEPUIS UN BOT. Discord réserve les autorisations par rôle
    #  (Intégrations) à un jeton d'utilisateur : aucun bot ne peut les
    #  poser. Avec `administrator`, une Direction non-admin ne voyait même
    #  pas la commande — donc en pleine attaque, rien. `moderate_members`
    #  est le plancher juste : c'est exactement le pouvoir qu'exerce la
    #  commande (couper la parole). QUI a le droit, lui, se décide DANS la
    #  commande — voir `_autorise_radiation`.
    default_permissions=discord.Permissions(moderate_members=True),
    guild_only=True,
)


#  Les tâches de verrouillage en cours. ⚠️ SANS CETTE RÉFÉRENCE, le ramasse-
#  miettes peut collecter une tâche `create_task` avant sa fin : le verrouillage
#  des salons s'arrêterait au milieu, sans erreur, sans trace.
_VERROUS_RADIATION: set = set()


async def _verrouiller_salons_radie(guild, role, membre_id: int):
    """Pose le refus total sur tous les salons. LENT, donc EN TÂCHE DE FOND.

    ⚠️ CE N'EST PAS CE QUI ARRÊTE L'ATTAQUE — le timeout l'a déjà fait. Ceci
    ne fait que masquer le serveur à la personne. Le mettre sur le chemin
    critique coûtait 0,3 s par salon avant la moindre neutralisation.
    """
    poses, sautes, echecs = 0, 0, 0
    try:
        ow = _radie_overwrite()
        for ch in list(guild.channels):
            try:
                cur = ch.overwrites_for(role)
                if (cur.view_channel is False and cur.send_messages is False
                        and cur.connect is False):
                    sautes += 1
                    continue
                await ch.set_permissions(role, overwrite=ow,
                                         reason="Radiation totale (/off)")
                poses += 1
                await asyncio.sleep(0.3)
            except Exception:
                echecs += 1
        print(f"[off] verrouillage {guild.id} pour {membre_id} : "
              f"{poses} salon(s) posé(s) · {sautes} déjà en place · "
              f"{echecs} échec(s)")
    except Exception as ex:
        print(f"[off verrouillage] {ex}")


async def _radier_membre(guild, membre, auteur, raison: str) -> dict:
    """LE corps de la radiation. Rend le compte rendu de CE QUI A MARCHÉ.

    ⚠️ UN SEUL CORPS POUR TOUTES LES PORTES : la commande `/off on` et le menu
    contextuel « Radier » y arrivent tous les deux. Deux copies divergeraient,
    et c'est la sauvegarde des rôles qui manquerait à l'une — donc des rôles
    perdus pour toujours.

    ⚠️ ON NE S'ARRÊTE PAS AU PREMIER ÉCHEC. Si le timeout passe mais que le
    retrait des rôles échoue, la personne est déjà muette : abandonner là
    serait pire. On fait tout ce qu'on peut, et on DIT ce qui a manqué.
    """
    res = {"timeout": False, "roles_retires": 0, "role_pose": False,
           "sauvegarde": False, "verrou": False, "pseudo_detruit": False,
           "recours_envoye": False, "manques": []}
    me = guild.me

    # ── 1. LE COUP D'ARRÊT, EN PREMIER — un appel, immédiat ──────────────
    #  Coupe l'écriture, les réactions, le vocal et les commandes dans TOUT
    #  le serveur. C'est la seule action qui compte dans les deux premières
    #  secondes d'une attaque.
    try:
        await membre.timeout(timedelta(days=28),
                             reason=f"/off radiation — {raison}"[:400])
        res["timeout"] = True
    except Exception as ex:
        res["manques"].append(f"réduction au silence impossible ({ex})")

    # ── 2. Sauvegarder les rôles AVANT de les retirer ────────────────────
    #  ⚠️ L'ORDRE EST NON NÉGOCIABLE. Retirer d'abord et écrire ensuite fait
    #  perdre la liste si l'écriture échoue — et des rôles perdus ne se
    #  devinent pas. `/off off` deviendrait un mensonge.
    #  ⚠️ `managed` EXCLU : un rôle d'intégration (boost, bot, abonnement) ne
    #  PEUT pas être retiré — l'API refuse TOUT l'appel si on le demande. Le
    #  compter ici gonflerait le compte rendu, et ferait promettre à `/off off`
    #  de rendre des rôles qu'on n'a jamais pris.
    removable = [r for r in membre.roles
                 if not r.is_default() and not r.managed and me.top_role > r]
    saved_ids = [r.id for r in removable if r.name != _RADIE_ROLE_NAME]
    try:
        async with get_db() as db:
            await db.execute(
                "CREATE TABLE IF NOT EXISTS radiated_members (guild_id INTEGER, "
                "user_id INTEGER, saved_roles TEXT, reason TEXT, "
                "by_user_id INTEGER, radiated_at DATETIME DEFAULT "
                "CURRENT_TIMESTAMP, PRIMARY KEY (guild_id, user_id))")
            #  ⚠️ DEUX COLONNES AJOUTÉES APRÈS COUP. `ALTER TABLE` échoue si la
            #  colonne existe déjà : c'est attendu, on avale l'erreur. Sans ce
            #  rattrapage, une base créée par une version antérieure n'aurait
            #  jamais ces colonnes et le pseudo ne serait jamais rendu.
            for _sql in (
                "ALTER TABLE radiated_members ADD COLUMN saved_nick TEXT",
                "ALTER TABLE radiated_members ADD COLUMN appel_utilise INTEGER DEFAULT 0",
            ):
                try:
                    await db.execute(_sql)
                except Exception:
                    pass
            await db.execute(
                "INSERT INTO radiated_members(guild_id, user_id, saved_roles, "
                "reason, by_user_id, saved_nick, appel_utilise) "
                "VALUES(?,?,?,?,?,?,0) "
                # Déjà radié : on garde les rôles et le pseudo d'AVANT la première radiation (les
                # remplacer par ceux d'un membre déjà radié les perdait pour toujours).
                "ON CONFLICT(guild_id, user_id) DO UPDATE SET "
                "reason=excluded.reason, by_user_id=excluded.by_user_id, appel_utilise=0",
                (guild.id, membre.id, json.dumps(saved_ids),
                 str(raison or "")[:300], auteur.id,
                 (membre.nick or "")[:32]))
            await db.commit()
        res["sauvegarde"] = True
    except Exception as ex:
        res["manques"].append(f"sauvegarde des rôles échouée ({ex})")

    # ── 3. Le rôle « Radié » et le retrait, en UN SEUL appel ─────────────
    #  ⚠️ `edit(roles=…)` PLUTÔT QUE remove_roles + add_roles : un seul appel
    #  au lieu de deux, une seule entrée d'audit, et surtout AUCUN instant où
    #  la personne se retrouve sans rôle mais sans étiquette non plus.
    role = None
    try:
        role = discord.utils.get(guild.roles, name=_RADIE_ROLE_NAME)
        if role is None:
            role = await guild.create_role(
                name=_RADIE_ROLE_NAME, colour=discord.Colour(_RADIE_COULEUR),
                hoist=False, mentionable=False,
                reason="Radiation totale (/off)")
        elif role.colour.value != _RADIE_COULEUR:
            #  Le rôle existait déjà (créé avant cette version, ou recoloré à la
            #  main) : on le remet en noir, sinon les anciens radiés gardent la
            #  couleur d'origine et rien ne les distingue à l'œil.
            try:
                await role.edit(colour=discord.Colour(_RADIE_COULEUR),
                                hoist=False, mentionable=False,
                                reason="Radiation : nom en noir")
            except Exception:
                pass
    except Exception as ex:
        res["manques"].append(f"rôle « Radié » indisponible ({ex})")

    try:
        #  On garde @everyone, les rôles d'intégration et tout ce qu'on ne
        #  PEUT pas retirer (au-dessus du bot) ; on ajoute l'étiquette. Tout
        #  le reste part.
        garder = [r for r in membre.roles
                  if r.is_default() or r.managed or not (me.top_role > r)]
        if role is not None and role not in garder:
            garder.append(role)
        #  ⚠️ PSEUDO ET RÔLES DANS LE MÊME APPEL. Deux `edit` séparés, c'est
        #  deux entrées d'audit, deux occasions d'échouer à moitié, et un
        #  instant où le membre est dépouillé mais porte encore son nom.
        _nick = _radie_pseudo(membre)
        try:
            await membre.edit(roles=garder, nick=_nick,
                              reason=f"/off radiation — {raison}"[:400])
            res["pseudo_detruit"] = True
        except Exception:
            #  Le pseudo peut échouer seul (permission « Gérer les pseudos »
            #  manquante). Le retrait des rôles, lui, ne doit PAS être perdu
            #  pour autant : on réessaie sans le pseudo.
            await membre.edit(roles=garder,
                              reason=f"/off radiation — {raison}"[:400])
            res["manques"].append("pseudo de serveur non modifié (permission "
                                  "« Gérer les pseudos » ?)")
        res["roles_retires"] = len(removable)
        res["role_pose"] = role is not None
    except Exception as ex:
        res["manques"].append(f"retrait des rôles échoué ({ex})")

    # ── 4. Le droit de recours, par message privé ────────────────────────
    #  ⚠️ APRÈS LA NEUTRALISATION, JAMAIS AVANT. Prévenir quelqu'un qu'on va le
    #  radier lui laisse le temps de faire des dégâts. Et si le message ne part
    #  pas (MP fermés), le compte rendu le DIT : cette personne n'a alors
    #  AUCUN autre chemin, puisqu'elle ne voit plus aucun salon.
    res["recours_envoye"] = await _envoyer_recours_radie(guild, membre, raison)
    if not res["recours_envoye"]:
        res["manques"].append("message privé de recours non remis (MP fermés)")

    # ── 4. Le verrouillage des salons, EN FOND ───────────────────────────
    if role is not None:
        try:
            t = asyncio.create_task(
                _verrouiller_salons_radie(guild, role, membre.id))
            _VERROUS_RADIATION.add(t)
            t.add_done_callback(_VERROUS_RADIATION.discard)
            res["verrou"] = True
        except Exception as ex:
            res["manques"].append(f"verrouillage des salons non lancé ({ex})")

    return res


async def _autorise_radiation(i, cible=None) -> str | None:
    """QUI a le droit de radier. Rend le motif de refus, ou None.

    ⚠️ LE CONTRÔLE VIT ICI, PAS DANS DISCORD. `default_permissions` ne règle
    que l'affichage de la commande ; le droit réel se décide dans le code, à
    partir du rôle Direction configuré dans le panneau. Sans ce contrôle,
    abaisser l'affichage à « Exclure temporairement » aurait donné la
    radiation à tous les modérateurs.

    ⚠️ HIÉRARCHIE APPELANT-VS-CIBLE pour les non-admins. `/off` retire TOUT et
    réduit au silence : sans cette garde, un membre de la Direction pouvait
    radier quelqu'un de rang égal ou supérieur — l'escalade de privilège déjà
    corrigée sur `/mod direction`. L'owner et le super-owner passent outre,
    sinon personne ne pourrait plus arrêter un compte de direction compromis.
    """
    auteur, guild = i.user, i.guild
    try:
        if auteur.id == guild.owner_id or owner_ids_module.is_super_owner(auteur.id):
            return None
        if getattr(auteur.guild_permissions, "administrator", False):
            #  26/10/2026 (sécurité) : un administrateur respecte la hiérarchie, comme dans Discord — sinon le plus bas
            #  des administrateurs radiait un administrateur plus haut que lui (tous ses rôles retirés, 28 jours muet).
            if cible is not None and cible.top_role >= auteur.top_role:
                return ("❌ Cette personne a un rôle **égal ou supérieur au vôtre** "
                        "— seul le propriétaire peut la radier.")
            return None
        c = await cfg(guild.id)
        rid = int(c.get('direction_allowed_role', 0) or 0)
        uid = int(c.get('direction_allowed_user', 0) or 0)
        ok = ((rid and any(r.id == rid for r in auteur.roles))
              or (uid and auteur.id == uid))
        if not ok:
            if not rid and not uid:
                return ("⛔ **Réservé à la Direction**, et aucun rôle Direction "
                        "n'est configuré.\nLe propriétaire peut le désigner en "
                        "une fois : `/configure` → **Sanctions** → "
                        "**🚫 Rôle Direction**.")
            return "⛔ **Réservé à la Direction.**"
        if cible is not None and cible.top_role >= auteur.top_role:
            return ("❌ Cette personne a un rôle **égal ou supérieur au vôtre** "
                    "— seul le propriétaire peut la radier.")
        return None
    except Exception as ex:
        _logerr("_autorise_radiation", ex, guild_id=getattr(guild, "id", 0))
        #  ⚠️ FAIL-CLOSED. Une panne de configuration ne doit pas ouvrir la
        #  radiation à tout le monde ; l'owner, lui, est déjà sorti plus haut.
        return "⛔ Impossible de vérifier vos droits — radiation refusée."


def _refus_radiation(guild, membre, auteur) -> str | None:
    """Le motif de refus, ou None si on peut y aller. AUCUN appel réseau.

    ⚠️ TOUT SE DÉCIDE AVANT LE MOINDRE APPEL : en pleine attaque, un refus
    doit revenir instantanément et DIRE quoi faire, pas échouer à moitié.
    """
    me = guild.me
    if membre.bot:
        return "❌ Cible interdite : c'est un bot."
    if membre.id == guild.owner_id:
        return "❌ Cible interdite : propriétaire du serveur."
    if owner_ids_module.is_super_owner(membre.id):
        return "❌ Cible interdite : super-owner."
    if membre.id in TETE_IDS and not owner_ids_module.is_super_owner(auteur.id):   # 26/10/2026 (sécurité)
        return "❌ Cible interdite : la direction (seul le fondateur peut la radier)."
    if membre.id == auteur.id:
        return "❌ Vous ne pouvez pas vous radier vous-même."
    if me is None:
        return "❌ Je ne me trouve pas sur ce serveur."
    if not me.guild_permissions.moderate_members:
        return ("❌ Il me manque **Modérer les membres** — c'est la permission "
                "qui coupe la parole immédiatement. Ajoutez-la à mon rôle.")
    if not me.guild_permissions.manage_roles:
        return ("❌ Il me manque **Gérer les rôles**. Ajoutez-la à mon rôle.")
    if me.top_role <= membre.top_role:
        return ("❌ Cette personne a un rôle **au-dessus du mien**. Montez mon "
                "rôle plus haut dans la liste, sinon je ne peux rien lui "
                "retirer.")
    return None


def _compte_rendu_radiation(membre, res: dict) -> str:
    """Ce qui a été fait, ce qui a manqué. Jamais « c'est fait » en bloc.

    ⚠️ UNE RADIATION PARTIELLE ANNONCÉE COMME TOTALE EST PIRE QU'UN ÉCHEC :
    on croit le serveur protégé et on passe à autre chose.
    """
    if res["timeout"]:
        tete = (f"🚫 **{membre.mention} est neutralisé** — plus un mot, plus "
                f"une réaction, plus de vocal, plus de commandes.")
    else:
        tete = (f"⚠️ **{membre.mention} n'a PAS pu être réduit au silence.** "
                f"Vérifiez la permission **Modérer les membres**.")
    lignes = [tete]
    detail = []
    if res["roles_retires"]:
        detail.append(f"`{res['roles_retires']}` rôle(s) retiré(s)")
    if res["role_pose"]:
        detail.append("étiquette « Radié » posée")
    if res["sauvegarde"]:
        detail.append("rôles sauvegardés")
    if detail:
        lignes.append("-# " + " · ".join(detail))
    if res.get("pseudo_detruit"):
        lignes.append("-# 🏷️ Pseudo de serveur détruit · nom affiché en noir.")
    if res["verrou"]:
        lignes.append("-# 🔒 Verrouillage des salons en cours (quelques "
                      "secondes) — la personne ne peut déjà plus rien faire.")
    if res.get("recours_envoye"):
        lignes.append("-# 📩 Droit de recours envoyé en message privé — **un "
                      "seul**, par formulaire.")
    else:
        #  ⚠️ SANS CE MESSAGE, ON CROIRAIT LUI AVOIR LAISSÉ UNE PORTE. Elle ne
        #  voit aucun salon : le MP était son unique chemin.
        lignes.append("⚠️ **Message privé non remis** — cette personne n'a "
                      "donc **aucun chemin pour se défendre**. Si vous voulez "
                      "lui laisser un recours, contactez-la autrement.")
    if res["manques"]:
        lignes.append("⚠️ **Incomplet :** " + " · ".join(res["manques"])[:600])
    if not res["sauvegarde"]:
        lignes.append("⚠️ **Les rôles n'ont PAS été sauvegardés** : `/off off` "
                      "ne pourra pas les rendre. Notez-les avant de fermer.")
    lignes.append("-# Annuler : `/off off`")
    return "\n".join(lignes)


async def _journal_radiation(guild, membre, auteur, raison, res):
    """Logs forts + journal staff. Ne lève jamais : un log raté ne doit pas
    faire échouer une radiation réussie."""
    try:
        await ulogger2026.log_event(
            bot, guild, ulogger2026.EventType.SEC_ESCALATION,
            description=(f"🚫 **RADIATION TOTALE** — {membre.mention} "
                         f"`{membre.id}`\nPar : {auteur.mention}\n"
                         f"**Raison :** {str(raison or '')[:500]}\n"
                         f"_Silence immédiat, "
                         f"{res.get('roles_retires', 0)} rôle(s) retiré(s), "
                         f"salons verrouillés. Réintégration : `/off off`._"),
            user=membre, moderator=auteur)
    except Exception:
        pass
    try:
        await log_staff_action(guild.id, auteur.id, membre.id, "radiation",
                               detail=str(raison or "")[:200], surface="slash")
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════════════
#  LE RECOURS D'UN RADIÉ — un seul, par formulaire privé
# ═══════════════════════════════════════════════════════════════════════════════
#
#  ⚠️ POURQUOI UN FORMULAIRE ET PAS UN SALON. Le propriétaire veut les deux :
#  « ils ne voient plus AUCUN salon, mais vraiment plus aucun » ET « ils peuvent
#  créer un ticket pour s'expliquer ». Or la radiation applique un `timeout`
#  Discord — c'est lui qui coupe l'attaque en une seconde — et un membre en
#  timeout NE PEUT PAS ÉCRIRE, même dans un salon qu'on lui ouvrirait. Un salon
#  de recours serait une porte peinte sur un mur.
#
#  Le formulaire privé résout les deux : aucun salon visible, aucune écriture
#  possible dans le serveur, et pourtant l'explication arrive — le bot la
#  dépose dans un vrai ticket côté staff.
#
#  ⚠️ UN SEUL RECOURS, JAMAIS DEUX. La marque vit en base (`appel_utilise`),
#  pas en mémoire : un redémarrage ne doit pas rouvrir le droit.


#  24/10/2026 (revue) : le ticket de recours a son propre « panneau » — il était enregistré sous celui du
#  ticket « Serveur » et, jamais fermé, comptait dans son maximum : après « Lever la radiation », le
#  prochain ticket Serveur répondait « ❌ Max 1 ticket(s) » pendant 7 jours. Il se ferme à la décision.
RECOURS_PID = "recours"
RECOURS_MARQUE = '"recours": true'   # les réponses d'un ticket de recours (json.dumps({"recours": True}))


async def _panneau_ticket_serveur(guild):
    """(pid, panneau) du ticket « serveur », ou (None, {}) — sans réseau. Sert à ranger le recours
    (sa catégorie) ; le recours n'est pas compté comme un ticket de ce type (`RECOURS_PID`).

    Le propriétaire a dit « un ticket de type serveur ». On cherche donc CE
    type-là ; à défaut, le premier panneau configuré, parce qu'un recours qui
    n'arrive nulle part est pire qu'un recours mal rangé.
    """
    try:
        c = await cfg(guild.id)
        panels = c.get('ticket_panels', {}) or {}
        for pid, pnl in panels.items():
            if "serv" in str(pnl.get('name', '')).lower():
                return pid, pnl
        for pid, pnl in panels.items():
            return pid, pnl
    except Exception as ex:
        print(f"[radie recours panneau] {ex}")
    return None, {}


async def _recours_deja_utilise(guild_id: int, user_id: int) -> bool:
    """Fail-CLOSED : si la base ne répond pas, on considère le recours utilisé.

    ⚠️ LE SENS COMPTE. Fail-open laisserait un radié rouvrir un recours à
    chaque panne de base — donc autant de tickets qu'il veut, ce qui est
    exactement ce qu'on interdit.
    """
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT appel_utilise FROM radiated_members "
                "WHERE guild_id=? AND user_id=?", (guild_id, user_id)) as cur:
                row = await cur.fetchone()
        if row is None:
            return True          # pas radié → aucun recours à ouvrir
        return bool(row[0])
    except Exception as ex:
        print(f"[radie recours lecture] {ex}")
        return True


class _RadieAppelModal(discord.ui.Modal, title="Recours — expliquez-vous"):
    """⚠️ DEUX CHAMPS, PAS DIX. C'est la seule fenêtre d'expression d'une
    personne déjà neutralisée : elle doit pouvoir tout dire sans se heurter à
    un questionnaire."""

    pourquoi = discord.ui.TextInput(
        label="Pourquoi avez-vous été sanctionné ?",
        style=discord.TextStyle.paragraph, required=True, max_length=1000,
        placeholder="Décrivez ce qui s'est passé, de votre point de vue.")
    conteste = discord.ui.TextInput(
        label="Que contestez-vous, et pourquoi ?",
        style=discord.TextStyle.paragraph, required=False, max_length=1000,
        placeholder="Facultatif — éléments concrets, preuves, contexte.")

    def __init__(self, guild):
        super().__init__(timeout=900)
        self._guild = guild

    async def on_submit(self, i):
        try:
            await i.response.defer(ephemeral=True, thinking=True)
        except Exception:
            pass
        try:
            ok = await _ouvrir_ticket_recours(
                self._guild, i.user, str(self.pourquoi), str(self.conteste))
            await i.followup.send(ok, ephemeral=True)
        except Exception as ex:
            _logerr("radie.appel_submit", ex)
            try:
                await i.followup.send(
                    "❌ Votre recours n'a pas pu être transmis. Réessayez dans "
                    "un instant — votre droit de recours n'est PAS consommé.",
                    ephemeral=True)
            except Exception:
                pass


class RadieAppelButton(discord.ui.DynamicItem[Button],
                       template=r"radieappel:(?P<gid>\d+)"):
    """Le bouton du message privé. Persistant : le radié peut cliquer des
    heures plus tard, après n'importe quel redémarrage."""

    def __init__(self, gid: int):
        super().__init__(Button(emoji=visuels.icone("envoyer"), label="Faire mon recours (1 seul)",
                                style=discord.ButtonStyle.primary,
                                custom_id=f"radieappel:{gid}"))
        self.gid = int(gid)

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["gid"]))

    async def callback(self, i):
        try:
            guild = bot.get_guild(self.gid)
            if guild is None:
                return await i.response.send_message(
                    "❌ Serveur introuvable.", ephemeral=True)
            if await _recours_deja_utilise(guild.id, i.user.id):
                #  ⚠️ ON REFUSE AVANT LE FORMULAIRE. Laisser remplir puis
                #  refuser à l'envoi serait cruel et inutile.
                return await i.response.send_message(
                    "⛔ **Votre recours a déjà été utilisé.**\n"
                    "Il n'y en a qu'un. L'équipe examine votre message ; "
                    "vous serez prévenu de sa décision ici même.",
                    ephemeral=True)
            await i.response.send_modal(_RadieAppelModal(guild))
        except Exception as ex:
            _logerr("radie.appel_bouton", ex)
            try:
                if not i.response.is_done():
                    await i.response.send_message(
                        "❌ Erreur. Réessayez dans un instant.", ephemeral=True)
            except Exception:
                pass


async def _ouvrir_ticket_recours(guild, membre, pourquoi: str,
                                 conteste: str) -> str:
    """Crée le ticket de recours et y dépose l'explication. Rend le message
    à afficher au radié.

    ⚠️ LE SALON N'EST PAS VISIBLE PAR LE RADIÉ, ET C'EST VOULU. Il ne voit
    aucun salon — c'est la consigne — et il n'aurait de toute façon pas pu y
    écrire (timeout). Son texte est déjà là ; la suite se joue entre le staff
    et lui, par message privé.

    ⚠️ ON MARQUE LE RECOURS CONSOMMÉ *APRÈS* LA CRÉATION RÉUSSIE. L'inverse
    ferait perdre le droit de recours sur une simple panne de salon.
    """
    pid, pnl = await _panneau_ticket_serveur(guild)
    c = await cfg(guild.id)
    staff = guild.get_role(int(c.get('ticket_staff', 0) or 0))
    cat = guild.get_channel(int((pnl or {}).get('category', 0) or 0))

    ow = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        guild.me: discord.PermissionOverwrite(
            view_channel=True, send_messages=True, manage_channels=True,
            manage_permissions=True),
    }
    if staff:
        ow[staff] = discord.PermissionOverwrite(
            view_channel=True, send_messages=True, read_message_history=True,
            attach_files=True, embed_links=True)
    if guild.owner:
        ow[guild.owner] = discord.PermissionOverwrite(
            view_channel=True, send_messages=True, read_message_history=True,
            manage_channels=True)

    for _cible in _equipe_direction(guild, c):  # la direction et le fondateur voient tous les tickets (22/10)
        ow.setdefault(_cible, discord.PermissionOverwrite(**tickets_fils.DROITS_SALON))

    ch = await guild.create_text_channel(
        f"recours-{membre.name}"[:50], category=cat, overwrites=ow,
        reason=f"Recours de radiation — {membre.id}")

    tid = 0
    try:
        async with get_db() as db:
            await db.execute(
                'INSERT INTO tickets(guild_id, channel_id, user_id, panel_id, '
                'claimed_by, status, answers, created_at) VALUES(?,?,?,?,0,"open",?,CURRENT_TIMESTAMP)',
                (guild.id, ch.id, membre.id, RECOURS_PID,
                 json.dumps({"recours": True}, ensure_ascii=False)))
            await db.commit()
            async with db.execute(
                'SELECT id FROM tickets WHERE channel_id=?', (ch.id,)) as cur:
                row = await cur.fetchone()
                tid = row[0] if row else 0
    except Exception as ex:
        #  Le salon existe : le recours n'est PAS perdu. On le dit et on
        #  continue — un ticket non enregistré reste lisible par le staff.
        _logerr("radie.recours_enregistrement", ex, guild_id=guild.id)

    #  Son texte ne mentionne personne : seul le rôle du staff est prévenu.
    corps = [discord.ui.TextDisplay("**Pourquoi avez-vous été sanctionné ?**\n"
                                    + discord.utils.escape_mentions(pourquoi or "—")[:1000])]
    if (conteste or "").strip():
        corps.append(discord.ui.TextDisplay("**Ce qu'il conteste**\n" + discord.utils.escape_mentions(conteste)[:1000]))
    tete = discord.ui.TextDisplay(
        f"### ⚖️ Recours de radiation · ticket n°{tid}\n{membre.mention} · `{membre.id}` · compte `{membre}`\n"
        "-# Cette personne est radiée : elle ne voit aucun salon et ne peut écrire nulle part. "
        "Ce texte est son unique prise de parole.")
    vue = LayoutView(timeout=None)
    if staff:
        vue.add_item(discord.ui.TextDisplay(f"{staff.mention} · un recours à trancher"))
    vue.add_item(discord.ui.Container(
        discord.ui.Section(tete, accessory=discord.ui.Thumbnail(membre.display_avatar.url)),
        discord.ui.Separator(), *corps, discord.ui.Separator(),
        discord.ui.TextDisplay("-# Décision : lever la radiation, ou bannir définitivement."),
        discord.ui.ActionRow(RadieDecisionButton("lever", membre.id).item,
                             RadieDecisionButton("bannir", membre.id).item),
        accent_color=0x010101))
    await ch.send(view=vue, allowed_mentions=discord.AllowedMentions(
        everyone=False, users=False, roles=[staff] if staff else False))

    try:
        async with get_db() as db:
            await db.execute(
                "UPDATE radiated_members SET appel_utilise=1 "
                "WHERE guild_id=? AND user_id=?", (guild.id, membre.id))
            await db.commit()
    except Exception as ex:  # non marqué = un second recours possible : à savoir
        _logerr("radie.recours_marque", ex, guild_id=guild.id)

    return ("✅ **Votre recours a été transmis à l'équipe.**\n"
            "-# C'était votre seule demande possible. Vous recevrez la "
            "décision ici même, en message privé.")


class RadieDecisionButton(discord.ui.DynamicItem[Button],
                          template=r"radiedec:(?P<act>lever|bannir):(?P<uid>\d+)"):
    """La décision du staff, sur le ticket de recours. Persistante.

    ⚠️ AUCUNE DÉCISION AUTOMATIQUE. Le propriétaire l'a posé comme règle pour
    l'inactivité, et ça vaut ici : « c'est pas le bot qui va décider de les
    expulser, c'est moi ». Le bot instruit le dossier ; un humain tranche.
    """

    def __init__(self, act: str, uid: int):
        lever = act == "lever"
        super().__init__(Button(
            emoji=(visuels.icone("valider") if lever else visuels.icone("interdit")), label=("Lever la radiation" if lever
                   else "Bannir définitivement"),
            style=(discord.ButtonStyle.success if lever
                   else discord.ButtonStyle.danger),
            custom_id=f"radiedec:{act}:{uid}"))
        self.act = act
        self.uid = int(uid)

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["act"], int(match["uid"]))

    async def callback(self, i):
        try:
            await i.response.defer(ephemeral=True, thinking=True)
        except Exception:
            pass
        try:
            # Le même droit que /off : la direction et au-dessus (le staff ne bannit pas).
            refus = await _autorise_radiation(i)
            if refus:
                return await i.followup.send(refus, ephemeral=True)

            membre = i.guild.get_member(self.uid)
            if self.act == "lever":
                if membre is None:
                    return await i.followup.send(
                        "❌ Ce membre n'est plus sur le serveur.",
                        ephemeral=True)
                erreur = await _lever_radiation(i.guild, membre, i.user, "Recours accepté")
                if erreur:
                    return await i.followup.send(f"❌ {erreur}", ephemeral=True)
                reste = await _fiche_sanction("restricted_members", i.guild.id, self.uid) is not None
                await i.followup.send(
                    (f"✅ Radiation levée : {membre.mention} reste **restreint** par la direction — ses rôles reviendront "
                     "avec `/mod undirection`.") if reste else
                    f"✅ Radiation levée : {membre.mention} retrouve ses rôles et son pseudo.",
                    ephemeral=True)
                await _prevenir_radie(
                    i.guild, self.uid,
                    "✅ **Votre recours a été accepté.** Votre radiation est levée.")
            else:
                #  26/10/2026 (sécurité) : seulement un membre ENCORE radié (une radiation levée par « /off off » laissait
                #  la carte et ses boutons : un membre réintégré se bannissait d'un clic), jamais la direction, et la
                #  hiérarchie de /off sur le rang d'AVANT la radiation (ses rôles gardés : il ne lui reste que « Radié »).
                try:
                    async with get_db() as db:
                        async with db.execute("SELECT saved_roles FROM radiated_members WHERE guild_id=? AND user_id=?",
                                              (i.guild.id, self.uid)) as cur:
                            fiche = await cur.fetchone()
                except Exception as ex:  # fiche illisible : on ne bannit pas à l'aveugle
                    _logerr("radie.bannir.verif", ex, guild_id=i.guild.id)
                    fiche = None
                if fiche is None:
                    return await i.followup.send("❌ Ce membre n'est plus radié : rien à bannir.", ephemeral=True)
                try:
                    sauves = json.loads(fiche[0] or "[]") or []
                except ValueError:
                    sauves = []
                refus = _refus_rang_radie(i.guild, membre, i.user, sauves, "le bannir", membre_id=self.uid)
                if refus:
                    return await i.followup.send(f"❌ {refus}", ephemeral=True)
                #  ⚠️ LE BANNISSEMENT EST DÉFINITIF ET IRRÉVERSIBLE CÔTÉ MEMBRE :
                #  on le prévient AVANT de bannir, sinon le message ne part
                #  jamais (on ne peut plus écrire à quelqu'un qui n'a plus
                #  aucun serveur en commun). Donc on vérifie d'abord que le
                #  bannissement PASSERA : sinon le membre lirait un mensonge.
                moi = i.guild.me
                if not moi.guild_permissions.ban_members or (membre is not None and (
                        membre.id == i.guild.owner_id or membre.top_role >= moi.top_role)):
                    return await i.followup.send(
                        "❌ Je ne peux pas bannir ce membre (permission « Bannir » ou rôle plus haut "
                        "que le mien). Rien n'a été envoyé.", ephemeral=True)
                await _prevenir_radie(
                    i.guild, self.uid,
                    "⛔ **Votre recours a été rejeté.** Vous êtes banni "
                    "définitivement du serveur.")
                await i.guild.ban(
                    discord.Object(id=self.uid),
                    reason=f"Recours rejeté — décision de {i.user} ({i.user.id})",
                    delete_message_seconds=0)
                try:  # banni : il n'est plus « actuellement radié » (/off list)
                    async with get_db() as db:
                        await db.execute("DELETE FROM radiated_members WHERE guild_id=? AND user_id=?",
                                         (i.guild.id, self.uid))
                        await db.commit()
                except Exception as ex:
                    _logerr("radie.bannir.fiche", ex, guild_id=i.guild.id)
                await i.followup.send(
                    f"⛔ <@{self.uid}> est **banni définitivement**.",
                    ephemeral=True)

            quand = f"<t:{int(time.time())}:f>"
            ligne = (f"✅ **Radiation levée** par {i.user.mention} · {quand}" if self.act == "lever"
                     else f"⛔ **Banni définitivement** par {i.user.mention} · {quand}")
            try:  # la décision prend la place des boutons : on ne tranche pas deux fois
                await _carte_recours_decidee(i.message, ligne)
            except discord.HTTPException as ex:
                _logerr("radie.decision_carte", ex, guild_id=i.guild.id)
            await _fermer_recours(i, "Recours accepté : radiation levée" if self.act == "lever"
                                  else "Recours rejeté : bannissement définitif")
        except Exception as ex:
            _logerr("radie.decision", ex, guild_id=getattr(i.guild, "id", 0))
            try:
                await i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
            except Exception:
                pass


async def _fermer_recours(i, raison: str) -> bool:
    """24/10/2026 (revue) : la décision ferme le ticket de recours (transcript au site, salon supprimé) — il
    restait ouvert, sans bouton pour le fermer. Pas de MP de fermeture : la décision vient de lui être
    envoyée. Rend True si la fermeture est lancée."""
    try:
        ch = getattr(i, "channel", None)
        tk = await get_ticket(ch.id) if ch is not None else None
        if not tk:
            return False
        _fermer_en_fond(_fermer_ticket(i.guild, ch, tk, i.user, raison, mp=False))
        return True
    except Exception as ex:
        _logerr("radie.recours_fermer", ex, guild_id=getattr(getattr(i, "guild", None), "id", 0))
        return False


async def _carte_recours_decidee(message, ligne: str) -> None:
    """Après la décision : les boutons partent et la décision s'inscrit à leur place, dans la carte.
    `edit(view=None)` viderait une carte Components V2 entière (Discord refuse un message vide) : les
    boutons resteraient actifs. Un ancien recours (embed) garde son embed et perd seulement ses boutons."""
    if message.embeds:
        await message.edit(view=None)
        return
    v = LayoutView.from_message(message, timeout=None)
    for bloc_ in v.children:
        if isinstance(bloc_, discord.ui.Container):
            for x in bloc_.children:
                if isinstance(x, discord.ui.ActionRow):
                    bloc_.remove_item(x)
            bloc_.add_item(discord.ui.TextDisplay(ligne))
    await message.edit(view=v, allowed_mentions=discord.AllowedMentions.none())


async def _prevenir_radie(guild, user_id: int, texte: str) -> bool:
    """Message privé au radié. Ne lève jamais : des MP fermés ne doivent pas
    faire échouer une décision de staff."""
    try:
        u = bot.get_user(user_id) or await bot.fetch_user(user_id)
        await u.send(f"**{guild.name}** — {texte}")
        return True
    except Exception:
        return False


async def _envoyer_recours_radie(guild, membre, raison: str) -> bool:
    """Le message privé qui ouvre le droit de recours. Rend True s'il est parti.

    ⚠️ S'IL NE PART PAS, IL FAUT LE DIRE AU MODÉRATEUR. Un radié aux messages
    privés fermés n'a AUCUN autre chemin — il ne voit aucun salon. Sans cette
    remontée, on croirait lui avoir laissé une porte de sortie qui n'existe
    pas.
    """
    try:
        tete = discord.ui.TextDisplay(
            f"### ⛔ Vous avez été radié de {discord.utils.escape_markdown(guild.name)}\n"
            f"**Motif indiqué :** {discord.utils.escape_mentions(str(raison or 'non précisé'))[:500]}")
        v = LayoutView(timeout=None)
        v.add_item(discord.ui.Container(
            discord.ui.Section(tete, accessory=discord.ui.Thumbnail(guild.icon.url)) if guild.icon else tete,
            discord.ui.TextDisplay(
                "Vous ne voyez plus aucun salon et ne pouvez plus écrire sur le serveur.\n\n"
                "**Vous avez droit à UN recours, un seul.** Cliquez ci-dessous et expliquez pourquoi vous pensez "
                "avoir été sanctionné, et ce que vous contestez. L'équipe lira votre message et tranchera."),
            discord.ui.TextDisplay("-# Si la sanction est confirmée, elle devient un bannissement définitif."),
            discord.ui.ActionRow(RadieAppelButton(guild.id).item),
            accent_color=0x010101))
        u = bot.get_user(membre.id) or await bot.fetch_user(membre.id)
        await u.send(view=v, allowed_mentions=discord.AllowedMentions.none())
        return True
    except Exception as ex:
        print(f"[radie recours dm] {ex}")
        return False


