    refus = _refus_bouclier(i)
    if refus:
        return await i.followup.send(refus, ephemeral=True)
    n, pause = None, False
    try:
        n = await _shield_lock(g)
    except Exception as ex:
        _logerr("bouclier.on", ex, guild_id=g.id)
