def get_gif_type(msg):
    ct = (msg.content or "").lower()
    if 'tenor.com' in ct: return 'tenor'
    if 'giphy.com' in ct: return 'giphy'
    for emb in msg.embeds:
        if emb.url and 'tenor' in emb.url.lower(): return 'tenor'
        if emb.url and 'giphy' in emb.url.lower(): return 'giphy'
    for att in msg.attachments:
        if att.filename.lower().endswith('.gif'): return 'gif'
    return None


def check_badwords(ct, words, whitelist=None):
    """Vérifie si le message contient des mots interdits (mots entiers uniquement).

    Phase 24 : la `whitelist` (mots autorisés) court-circuite la détection.
    Un mot présent dans la whitelist ne sera JAMAIS bloqué, même s'il est dans
    `words`. Cas d'usage : "retard" est autorisé en FR mais aurait pu être bloqué.

    ⚠️ 14/10/2026 : la détection vit dans `mots_interdits.cherche`. L'ancienne
    recollait les mots voisins — « j'ai pu te répondre » lu « pute », « la mer
    de » lu « merde » — et retirait les espaces de tout le message, si bien que
    « c0n » dans une phrase n'était pas vu.
    """
    return mots_interdits.cherche(ct, words, whitelist)


def _strip_media_urls(text):
    """Retire du texte les liens GIF/image (via trust_system.is_media_url) AVANT le scan des mots
    interdits (owner 2026-07-17).

    POURQUOI : un GIF Discord légitime `cdn.discordapp.com/…/image0.gif` matchait « discordapp.com »
    de la liste badwords (check_badwords retire les points → « discordappcom ») → GIF bloqué à tort.
    Le filtre d'INSULTES retire DÉJÀ les URLs avant de scanner (`_URL_INMSG_RE`), pas le filtre
    badword → incohérence. On aligne : les liens MÉDIA (gif/image, hôtes tenor/giphy/discordapp/…)
    ne sont plus scannés comme des mots. Directive owner : « autorise TOUS les GIFs, on modère à la
    main ». ⚠️ Les liens NON-média (invitations, phishing, usurpation `discordapp.com.evil.tld`)
    restent scannés — vérifié : is_media_url les rejette. FAIL-SAFE (au moindre doute → texte inchangé)."""
    try:
        def _repl(m):
            _u = m.group(0)
            try:
                return ' ' if trust_system.is_media_url(_u) else _u
            except Exception:
                return _u
        return _URL_INMSG_RE.sub(_repl, text or '')
    except Exception:
        return text or ''


def check_link(ct, wl):
    """
    Vérifie si un message contient des liens non autorisés.
    Retourne (True, url) si un lien non autorisé est trouvé.
    La whitelist contient des domaines autorisés (ex: trello.com, youtube.com)
    """
    # Extraire toutes les URLs du message
    urls = re.findall(r'https?://([^\s<>"\']+)', ct, re.IGNORECASE)
    
    if not urls:
        return False, None
    
    # Normaliser la whitelist
    whitelist = []
    for w in (wl or []):
        w = str(w).lower().strip()
        # Enlever http:// ou https:// si présent
        w = re.sub(r'^https?://', '', w)
        # Enlever le / final
        w = w.rstrip('/')
        if w:
            whitelist.append(w)
    
    # Toujours autoriser certains domaines de base
    default_whitelist = [
        'discord.com', 'discordapp.com', 'cdn.discordapp.com',
        'media.discordapp.net', 'images-ext-1.discordapp.net',
        'tenor.com', 'giphy.com', 'imgur.com',
    ]
    whitelist.extend(default_whitelist)
    
    for url in urls:
        url_lower = url.lower()
        # owner 2026-07-12 : EXEMPTER tous les GIFs/images (même détection que le trust system :
        # hôte média, extension, ou 'gif' dans l'URL) → klipy/tenor/giphy & co passent quel que
        # soit le fournisseur. Un GIF déplacé se modère À LA MAIN, pas via ce filtre.
        try:
            if trust_system.is_media_url(url_lower):
                continue
        except Exception:
            pass
        # Extraire le domaine (avant le premier /)
        domain = url_lower.split('/')[0].split('?')[0]
        
        # Vérifier si le domaine est dans la whitelist
        is_allowed = False
        for allowed in whitelist:
            # Vérifier correspondance exacte ou sous-domaine
            if domain == allowed or domain.endswith('.' + allowed):
                is_allowed = True
                break
            # ⚠️ Ici se trouvait `if allowed in domain` (SOUS-CHAÎNE) → RETIRÉ le 2026-07-17
            # (feu vert owner) : « tenor.com » est en whitelist par défaut, donc
            # « tenor.com.evil.tld/vol-de-token » était autorisé. Le test exact + sous-domaine
            # ci-dessus couvre déjà tout usage légitime.
            # Seule tolérance conservée : une entrée SANS point (l'owner a tapé « youtube » au
            # lieu de « youtube.com ») → on la compare au domaine de 2e niveau, ce qui autorise
            # youtube.com et m.youtube.com mais PAS youtube.evil.tld.
            if '.' not in allowed:
                _labels = domain.split('.')
                if len(_labels) >= 2 and _labels[-2] == allowed:
                    is_allowed = True
                    break
        
        if not is_allowed:
            return True, url
    
    return False, None

def check_invite(ct):
    m = re.search(r'discord\.gg/\w+|discord\.com/invite/\w+|discordapp\.com/invite/\w+', ct, re.I)
    return (True, m.group()) if m else (False, None)

# FIX sécu P1-1 : normalisation anti-obfuscation pour la détection de liens.
# Les regex/substrings de phishing cassaient sur : homoglyphes (disсord = с cyrillique),
# zero-width (disc​ord), points Unicode (discord．com U+FF0E), défang ([.] / hxxp).
# On scanne EN PLUS une copie normalisée (defense in depth) sans toucher le scan brut.
_ZERO_WIDTH_RE = re.compile('[​‌‍⁠﻿]')   # ZWSP, ZWNJ, ZWJ, WJ, BOM
_DOT_LOOKALIKE_RE = re.compile('[。․．·‧]')  # 。 ․ ． · ‧
_DEFANG_DOT_RE = re.compile(r'\s*[\[\(\{]\s*\.\s*[\]\)\}]\s*')          # [.]  (.)  {.}
_DEFANG_SCHEME_RE = re.compile(r'\bh(?:xx|XX)p(s?)://', re.IGNORECASE)  # hxxp:// -> http://


def _normalize_for_scan(text: str) -> str:
    """Renvoie une version dé-obfusquée du texte pour la détection de liens malveillants.
    Neutralise homoglyphes + zero-width + points Unicode + défang. Best-effort : utilisée
    EN PLUS du scan du texte brut, jamais à la place (defense in depth)."""
    if not text:
        return ""
    try:
        import impersonation_detector as _imp
        s = _imp._collapse_homoglyphs(text)
    except Exception:
        s = text
    try:
        s = unicodedata.normalize('NFKC', s)
    except Exception:
        pass
    s = _ZERO_WIDTH_RE.sub('', s)
    s = _DOT_LOOKALIKE_RE.sub('.', s)
    s = _DEFANG_DOT_RE.sub('.', s)
    s = _DEFANG_SCHEME_RE.sub(r'http\1://', s)
    return s


# Séparateurs de maquillage. ⚠️ DEUX classes distinctes :
#  • _OBF_PUNCT (ponctuation SEULE, PAS l'espace) → neutralisée ENTRE deux lettres (« conn.ard »).
#    Surtout PAS l'espace ici, sinon on collerait toutes les phrases normales (« il a sa maison »).
#  • _OBF_SEP (ponctuation + espace) → pour COLLER les runs de lettres ISOLÉES (« c o n n a r d »),
#    où la garde de frontière empêche d'avaler un mot normal.
_OBF_PUNCT = r'[._\-*~|/\\+=:;°#"`^]'
_OBF_SEP = r'[\s._\-*~|/\\+=:;°#"`^]'


def _deobfuscate_for_insult(text: str) -> str:
    """Reconstruit un mot MAQUILLÉ pour le RE-scanner contre le lexique (owner 2026-06-27, anti-
    contournement). ⚠️ NE SANCTIONNE RIEN PAR LUI-MÊME : c'est juste une VARIANTE de plus passée
    au filtre — seule une correspondance avec un VRAI mot interdit agit. Donc quelqu'un qui écrit
    mal (espaces, fautes, vocabulaire limité) → son texte recollé ne donne pas une insulte → AUCUNE
    conséquence. On neutralise : (1) la ponctuation ENTRE lettres (« conn.ard »→« connard »),
    (2) les RUNS de lettres ISOLÉES espacées ≥3 (« c o n n a r d »→« connard » ; la garde de
    frontière empêche de coller « il a sa maison »), (3) les répétitions 3+→2 (« connnnard »→
    « connard »). FAIL-SAFE → ''."""
    if not text:
        return ""
    try:
        s = _ZERO_WIDTH_RE.sub('', text.lower())
        s = re.sub(r'(?<=\w)' + _OBF_PUNCT + r'+(?=\w)', '', s)          # (1) PONCTUATION inter-lettres (pas l'espace)
        s = re.sub(r'(?<!\w)\w(?:' + _OBF_SEP + r'+\w){2,}(?!\w)',       # (2) runs de lettres isolées (espace OK)
                   lambda m: re.sub(_OBF_SEP + r'+', '', m.group(0)), s)
        s = re.sub(r'(.)\1{2,}', r'\1\1', s)                            # (3) répétitions 3+ -> 2
        return s
    except Exception:
        return ""


def analyse_phishing(ct):
    """(trouvé, détail, type). Type « domain » = domaine piège connu, une certitude ; « homoglyph »,
    « typosquatting », « suspect_tld », « url_pattern », « message_pattern » = des ressemblances —
    jamais assez pour présumer un compte volé (cf. `_vol_de_compte_prouve`)."""
    ct = sans_liens_officiels(ct)
    if not ct.strip():
        return False, None, None
    # FIX sécu P1-1 : liens démaquillés (invisibles, points Unicode, [.], hxxp). Les lettres
    # trompeuses se lisent nom par nom dans `_analyse_hote`, jamais sur tout le message.
    demasque = _normaliser_liens(ct)
    textes = list(dict.fromkeys((ct, demasque)))
    for texte in textes:
        found, detail, ptype = advanced_phishing_check(texte)
        if found:
            return True, detail, ptype
    # Domaines pièges connus écrits sans « https:// » : nom de domaine entier, jamais un bout de mot.
    for texte in textes:
        pieges = _domaines_pieges_cites(texte)
        if pieges:
            return True, pieges[0], "domain"
    # Phrases d'appât maquillées (homoglyphes), toujours accompagnées d'un lien douteux.
    if _URL_COMPLETE.search(demasque):
        motif = _phrase_de_phishing(_normalize_for_scan(ct).lower())
        if motif:
            return True, f"Pattern phishing: {motif}", "message_pattern"
    return False, None, None


def check_phishing(ct):
    """Vérification de phishing améliorée : (trouvé, détail)."""
    found, detail, _type = analyse_phishing(ct)
    return found, detail

def check_scam(ct):
    """Vérification de scam améliorée"""
    ct = sans_liens_officiels(ct)
    if not ct.strip():
        return False, None
    # Utiliser la fonction avancée
    found, detail, score = advanced_scam_check(ct)
    if found:
        return True, detail

    # Patterns compilés
    for p in SCAM_PATTERNS:
        if p.search(ct):
            return True, p.pattern

    # audit 2026-07-02 : re-scan sur la version normalisée (anti-homoglyphe/zero-width),
    # comme check_phishing (FIX sécu P1-1). Sinon un scam obfusqué passe le filtre texte.
    try:
        norm = _normalize_for_scan(ct)
        if norm and norm != ct:
            found, detail, score = advanced_scam_check(norm)
            if found:
                return True, detail
            for p in SCAM_PATTERNS:
                if p.search(norm):
                    return True, p.pattern
    except Exception:
        pass
    #  29/10/2026 (audit) : « mrbeast giveaway 5000$ crypto withdraw now https://… » passait. Il faut les TROIS : un lien
    #  externe (les officiels sont déjà retirés), le registre argent facile (_IMG_SCAM_MONEY_RE) et un appât.
    try:
        if re.search(r"https?://|www\.", ct, re.I) and _IMG_SCAM_MONEY_RE.search(ct) and _APPAT_SCAM_RE.search(ct):
            return True, "lien + argent + appât"
    except Exception:
        pass
    return False, None


_APPAT_SCAM_RE = re.compile(r"\b(giveaway|mr\.?\s?beast|claim\w*|airdrop|crypto|bitcoin|btc|usdt|eth|wallet|"
                            r"withdraw\w*|r[ée]clame\w*|cadeau\s+gratuit)\b", re.I)

def check_caps(ct, pct):
    ltrs = [c for c in ct if c.isalpha()]
    if len(ltrs) < 10: return False
    return sum(1 for c in ltrs if c.isupper()) / len(ltrs) * 100 >= pct

def check_mass_mention(msg, max_mentions=5):
    """Détecte les messages avec trop de mentions (@user, @role, @everyone, @here)"""
    total = len(msg.mentions) + len(msg.role_mentions)
    if msg.mention_everyone:
        total += msg.guild.member_count  # @everyone = mention massive
    return total >= max_mentions

def check_image(msg, allowed):
    blocked = []
    gt = get_gif_type(msg)
    if gt and gt not in allowed: blocked.append(gt)
    for att in msg.attachments:
        ext = att.filename.lower().split('.')[-1]
        if ext in ['png', 'jpg', 'jpeg', 'webp', 'bmp'] and ext not in allowed:
            blocked.append(ext)
    return blocked


# ═══════════════ RENFORT ANTI-SCAM « IMAGE » (owner 2026-06-18) ═══════════════
# Vague « crypto image spam » : des comptes PIRATÉS postent une IMAGE (faux gains
# crypto/casino, « cashout », giveaway) avec « gagne de l'argent facilement / DM moi ».
# Le texte est DANS l'image → check_scam(texte) le rate. Heuristique HAUTE PRÉCISION :
# une image + AU MOINS 2 signaux indépendants = le motif exact (improbable pour un meme).
# Bilingue FR/EN. Jamais bloquant seul ; l'action reste « timeout, pas ban » (comptes
# piratés → le vrai proprio récupère son compte) via sanction() qui dégrade déjà.
# HAUTE SPÉCIFICITÉ (revue adverse 2026-06-18) : UNIQUEMENT des collocations quasi-toujours
# scam. On NE met PAS de mots de jargon NUS (trader/trading/invest/profit/crypto/bitcoin/
# casino…) : en MMORPG « je veux trader ça » est banal → faux positifs. Le combo scam visé
# contient TOUJOURS un registre « argent facile / free X / cash out / X% par jour / gros montant ».
_IMG_SCAM_MONEY_RE = re.compile(
    r"(easy money|argent facile|gagn\w*\s+de\s+l['’ ]?argent\s+(facile|rapide|vite)|"
    r"fais\w*\s+de\s+l['’ ]?argent\s+(facile|rapide|vite)|"
    r"free\s+(money|cash|nitro|robux|vbucks|crypto|bitcoin|btc|eth|usdt|skins?|gift\s?cards?)|"
    r"(crypto|robux|nitro|vbucks)\s+(gratuit|gratuits|free)|"
    r"cash\s?out|withdraw\w*|airdrop|gains?\s+garantis?|revenus?\s+passifs?|"
    r"profit\s+guaranteed|guaranteed\s+(profit|returns?)|"
    r"double\s+(your|ton)\s+(crypto|money|argent|btc|eth)|x2\s+(crypto|your)|"
    r"make\s+money\s+(fast|online|easy)|earn\s+\$\s?\d|"
    r"\d{1,3}\s?%\s*(par\s+jour|/\s?jour|a\s+day|daily|per\s+day)|"
    r"\$\s?\d{3,}|\d{3,}\s?\$|\d{3,}\s?€|\d{3,}\s?usd)",
    re.IGNORECASE)
# Lien d'image BRUT collé dans le texte (compte piraté postant une image HÉBERGÉE en lien
# plutôt qu'en upload) — l'embed n'arrive parfois qu'après on_message → on le voit ici.
_IMG_URL_RE = re.compile(
    r"https?://\S+\.(?:png|jpe?g|webp|gif|bmp)(?:\?\S*)?|"
    r"https?://(?:cdn\.discordapp\.com|media\.discordapp\.net|i\.imgur\.com)/\S+",
    re.IGNORECASE)
_IMG_SCAM_CONTACT_RE = re.compile(
    r"(t\.me/|telegram|whats\s?app|wa\.me/|\bdm\s?me\b|\bmp\s?moi\b|écris[ -]?moi|"
    r"add\s?me\b|contacte[\s-]?moi|inbox\s?me|hit\s?me\s?up|message\s+privé|envoie[\s-]?moi\s+un\s+mp)",
    re.IGNORECASE)


def _msg_has_image(msg):
    """True si le message porte une image (pièce jointe OU image d'embed). FAIL-OPEN→False."""
    try:
        for att in (getattr(msg, 'attachments', None) or []):
            mt = (getattr(att, 'content_type', '') or '').lower()
            fn = (getattr(att, 'filename', '') or '').lower()
            if mt.startswith('image/') or fn.rsplit('.', 1)[-1] in (
                    'png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp'):
                return True
        for emb in (getattr(msg, 'embeds', None) or []):
            if getattr(getattr(emb, 'image', None), 'url', None) or \
               getattr(getattr(emb, 'thumbnail', None), 'url', None):
                return True
        # Lien d'image brut dans le texte (l'embed Discord peut n'arriver qu'APRÈS on_message).
        if _IMG_URL_RE.search(getattr(msg, 'content', '') or ""):
            return True
        # audit 2026-07-02 : images des messages TRANSFÉRÉS (payload dans message_snapshots).
        for _s in (getattr(msg, 'message_snapshots', None) or []):
            for att in (getattr(_s, 'attachments', None) or []):
                mt = (getattr(att, 'content_type', '') or '').lower()
                fn = (getattr(att, 'filename', '') or '').lower()
                if mt.startswith('image/') or fn.rsplit('.', 1)[-1] in (
                        'png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp'):
                    return True
            for emb in (getattr(_s, 'embeds', None) or []):
                if getattr(getattr(emb, 'image', None), 'url', None) or \
                   getattr(getattr(emb, 'thumbnail', None), 'url', None):
                    return True
    except Exception:
        pass
    return False


def check_image_scam(msg):
    """Détecte le motif « scam en image » des comptes piratés : une IMAGE + un registre ARGENT
    OBLIGATOIRE (free X / argent facile / cash out / X% par jour / gros montant…) ET AU MOINS un
    2e signal parmi {redirection de contact (Telegram/DM…), lien externe non whitelisté}. Scanne
    le texte BRUT ET NORMALISÉ (anti-obfuscation zero-width/homoglyphes/leet, comme check_phishing).
    ⚠️ COUVERTURE : ne voit que l'image AVEC une LÉGENDE parlante — l'image MUETTE (texte
    uniquement DANS l'image) nécessiterait de l'OCR (hors scope, documenté). Retourne (True,
    raison) ou (False, None). FAIL-OPEN (erreur → aucun blocage)."""
    try:
        if not _msg_has_image(msg):
            return False, None
        raw = (getattr(msg, 'content', '') or "")
        try:
            norm = _normalize_for_scan(raw)
        except Exception:
            norm = raw
        # ARGENT = signal OBLIGATOIRE (sans lui → trop de faux positifs ; revue adverse 2026-06-18).
        if not (_IMG_SCAM_MONEY_RE.search(raw) or _IMG_SCAM_MONEY_RE.search(norm)):
            return False, None
        signals = ["argent (free X / cash out / gros gains)"]
        if _IMG_SCAM_CONTACT_RE.search(raw) or _IMG_SCAM_CONTACT_RE.search(norm):
            signals.append("redirection de contact (Telegram/DM…)")
        try:
            f_link, lk = check_link(raw, [])
            if not f_link:
                f_link, lk = check_link(norm, [])
        except Exception:
            f_link, lk = (False, None)
        if f_link:
            signals.append(f"lien externe ({(lk or '')[:40]})")
        # Argent (obligatoire) + au moins un 2e signal (contact OU lien) → motif scam.
        if len(signals) >= 2:
            return True, " + ".join(signals)
        return False, None
    except Exception:
        return False, None

# ═══════════════════════════════════════════════════════════════════════════════
#  ANALYSE DE CONTENU DU SPAM (owner 2026-07-17)
# ═══════════════════════════════════════════════════════════════════════════════
# DIRECTIVE OWNER : « il y a 2 types de spam. Celui qui formule une phrase complète, puis une
# autre phrase, puis une autre : CE N'EST PAS DU SPAM. Et celui qui répète plusieurs fois le même
# caractère, ou qui met un mot / entrée / un mot / entrée tout le temps : ça, c'est du spam. »
#
# `check_spam` ne mesure que la VITESSE et ne lit JAMAIS le contenu → aux réglages par défaut
# (6 messages en 5 s), 6 phrases légitimes écrites vite étaient SUPPRIMÉES, alors que 5 « aaaaaaa »
# lents passaient. Exactement l'inverse de la demande.
#
# ⚠️ ON CLASSE LA RAFALE, PAS LE MESSAGE ISOLÉ. Un « ok » seul n'est pas du spam — l'owner décrit
# une RÉPÉTITION (« il va faire ça tout le temps »). Juger un message isolé punirait quelqu'un qui
# répond « oui » (règle n°1 : ne jamais punir un innocent).
# ⚠️ 100 % SYNC, sans I/O, regex PRÉ-COMPILÉES ici (niveau module) et contenu borné : ça tourne
# sur CHAQUE message (chemin chaud), et l'enquête gel pointe déjà une boucle asyncio fragile.
_SPAM_REPEAT_CHAR_RE = re.compile(r'(.)\1{5,}', re.DOTALL)      # aaaaaaa / !!!!!!! / 😂 ×6
_SPAM_WORD_RE = re.compile(r"[^\W_]+", re.UNICODE)              # « mots » (lettres/chiffres)
_spam_texts: dict = {}          # (guild_id, user_id) -> [derniers messages normalisés]
_SPAM_BURST_KEEP = 6            # on ne garde que la rafale récente (borné par clé)


def _spam_content_kind(guild_id, user_id, content: str) -> str:
    """Classe la RAFALE du membre : 'toxic' (spam à sanctionner) ou 'neutral' (à laisser vivre).

    N'est consulté QUE si le débit a déjà déclenché : il faut le cumul VITESSE **ET** CONTENU.
    Ne lève jamais ; dans le doute → 'neutral' (on n'embête personne).
    """
    try:
        raw = (content or '')[:400]
        norm = ' '.join(raw.lower().split())
        key = (int(guild_id), int(user_id))
        buf = _spam_texts.get(key)
        if buf is None:
            buf = []
            _spam_texts[key] = buf
        buf.append(norm)
        if len(buf) > _SPAM_BURST_KEEP:
            del buf[:-_SPAM_BURST_KEEP]
        # Éviction paresseuse (même patron éprouvé que spam_tracker ci-dessous).
        if len(_spam_texts) > 5000:
            _spam_texts.clear()
        if not norm:
            return 'neutral'                     # image/sticker nu → pas notre affaire ici
        # 1) Même caractère martelé DANS ce message : « aaaaaaaa », « !!!!!!! ».
        if _SPAM_REPEAT_CHAR_RE.search(norm):
            return 'toxic'
        # 2) Le MÊME message répété : 3 fois d'affilée le même texte.
        if len(buf) >= 3 and len(set(buf[-3:])) == 1:
            return 'toxic'
        # 3) La chaîne « un mot / entrée » : ≥4 des 5 derniers messages font ≤ 2 mots.
        #    C'est la RÉPÉTITION qui compte — un « ok » isolé ne matche jamais.
        last = [t for t in buf[-5:] if t]
        if len(last) >= 4:
            _short = sum(1 for t in last if len(_SPAM_WORD_RE.findall(t)) <= 2)
            if _short >= 4:
                return 'toxic'
        # Sinon : il écrit des phrases → c'est une conversation, pas du spam.
        return 'neutral'
    except Exception:
        return 'neutral'


async def check_spam(msg, mx, intv):
    key = (msg.guild.id, msg.author.id)
    n = now()
    if key not in spam_tracker: spam_tracker[key] = []
    spam_tracker[key] = [t for t in spam_tracker[key] if (n - t).total_seconds() < intv]
    spam_tracker[key].append(n)
    # FIX sécu (anti-fuite mémoire / DoS) : éviction paresseuse des clés mortes.
    # Sans ça, chaque (guild,user) ayant écrit UNE fois gardait une entrée à vie →
    # un raid de comptes jetables faisait gonfler le dict sans borne (OOM sur longue
    # uptime). On purge quand le dict dépasse 5000 clés (timestamps tous périmés).
    if len(spam_tracker) > 5000:
        _cut = 3600  # 1 h : large devant n'importe quel intervalle anti-spam
        for _k in [k for k, v in spam_tracker.items()
                   if not v or (n - v[-1]).total_seconds() > _cut]:
            spam_tracker.pop(_k, None)
    return len(spam_tracker[key]) > mx


def _register_protection_strike(guild_id, user_id, kind):
    """Enregistre un écart (spam/mentions) dans une fenêtre glissante et renvoie le
    nombre d'écarts CUMULÉS de ce membre pour ce 'kind'. Sert à graduer la réponse :
    1er/2e = simple avertissement, 3e+ = sanction + escalade staff.
    Calque spam_tracker : fenêtre glissante + éviction paresseuse (anti-fuite mémoire /
    DoS via comptes jetables). 100% sync, ne lève jamais."""
    n = now()
    key = (guild_id, user_id, kind)
    bucket = _protection_strikes.get(key)
    if bucket is None:
        bucket = []
        _protection_strikes[key] = bucket
    # Purge les écarts hors fenêtre (10 min) puis ajoute l'écart courant.
    bucket[:] = [t for t in bucket if (n - t).total_seconds() < _PROTECTION_STRIKE_WINDOW]
    bucket.append(n)
    # Éviction paresseuse des clés mortes (mêmes bornes/logique que spam_tracker).
    if len(_protection_strikes) > 5000:
        for _k in [k for k, v in list(_protection_strikes.items())
                   if not v or (n - v[-1]).total_seconds() > _PROTECTION_STRIKE_WINDOW]:
            _protection_strikes.pop(_k, None)
    return len(bucket)


async def _warn_calm_down(channel, text):
    """Avertissement GENTIL posté DANS le salon (rétention : on calme, on ne brutalise
    pas). Auto-supprimé ~10s. Calque exactement le pattern anti-phishing (webhook_send
    'protection' + task de suppression). 100% fail-safe : ne lève jamais, ne casse pas
    le pipeline on_message."""
    try:
        warn_e = discord.Embed(color=0xF1C40F, description=text)
        warn_e.set_footer(text="Protection — reste cool 🙏")
        warn_msg = await webhook_send(channel, 'protection', view=carte_embed(warn_e),
                                      allowed_mentions=discord.AllowedMentions.none())
        if warn_msg:
            async def _del_warn(m):
                await asyncio.sleep(10)
                try:
                    await m.delete()
                except Exception:
                    pass
            asyncio.create_task(_del_warn(warn_msg))
    except Exception as ex:
        print(f"[_warn_calm_down] {ex}")


_trust_notice_cd = {}  # (gid, uid, kind) -> dernier ts de notice (throttle anti-spam)


async def _trust_block_notice(msg, kind, *, fresh_escalate=False, fresh_minutes=15):
    """Notice DOUCE auto-supprimée quand le système de confiance bloque un contenu. Si
    `fresh_escalate` et que le compte est FRAIS (arrivé il y a < fresh_minutes) → quarantaine
    (timeout 1 h) + alerte owner : un lien/invitation dès l'arrivée = signature d'arnaqueur
    (#3). FAIL-SAFE : n'interrompt jamais on_message."""
    texts = {
        'invite': f"🔗 {msg.author.mention}, les **invitations** ne sont pas autorisées ici 🙏",
        'link': f"🔗 {msg.author.mention}, les **liens** ne sont pas autorisés ici — les GIFs et images, oui 🙂",
        'media_newbie': (f"🖼️ {msg.author.mention}, tu pourras envoyer **images & GIFs** dans un petit "
                         f"moment, le temps qu'on fasse connaissance 🙂 (le texte, c'est tout bon !)"),
    }
    try:
        _k = (msg.guild.id, msg.author.id, kind)
        _n = now()
        _last = _trust_notice_cd.get(_k)
        if _last is None or (_n - _last).total_seconds() > 30:
            _trust_notice_cd[_k] = _n
            if len(_trust_notice_cd) > 20000:
                _trust_notice_cd.clear()
            await _warn_calm_down(msg.channel, texts.get(kind, ''))
    except Exception:
        pass
    if not fresh_escalate:
        return
    try:
        joined = getattr(msg.author, 'joined_at', None)
        if joined is None:
            return
        if (discord.utils.utcnow() - joined).total_seconds() >= max(1, int(fresh_minutes)) * 60:
            return
        try:
            await msg.author.timeout(
                timedelta(hours=1),
                reason="Compte frais : lien/invitation dès l'arrivée (anti-arnaque)")
        except Exception:
            pass
        try:
            await ulogger2026.log_event(
                bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                description=(f"🧷 **Compte frais** {msg.author.mention} a posté un **{kind}** dans ses "
                             f"premières minutes → quarantaine (1 h). Vérifie avant de relâcher."),
                user=msg.author, moderator=bot.user, channel=msg.channel,
                extra={"⏱️ Arrivé": f"<t:{int(joined.timestamp())}:R>"})
        except Exception:
            pass
    except Exception:
        pass


def _msg_url_slugs(text):
    """Mots des slugs d'URL (GIF Tenor/Giphy, liens descriptifs) → pour jauger une insulte
    présente SEULEMENT dans un GIF/lien (≠ dite directement). owner 2026-06-24."""
    out = []
    try:
        for um in _URL_INMSG_RE.finditer(text or ''):
            for seg in re.split(r'[/?#&=]', um.group(0).lower()):
                if len(seg) >= 4 and ('-' in seg or '_' in seg):
                    out.append(seg.replace('-', ' ').replace('_', ' '))
    except Exception:
        pass
    return ' '.join(out)


def _gif_texte(msg, ct: str = "") -> str:
    """Le texte d'un GIF ou d'un lien : les mots de l'adresse (Tenor, Giphy…) et le titre / la description de ses
    aperçus (27/10/2026 : « GIF insultants bloqués : lien, titre »). FAIL-SAFE → ""."""
    morceaux = [_msg_url_slugs(ct)]
    try:
        for emb in (getattr(msg, 'embeds', None) or []):
            for x in (getattr(emb, 'title', None), getattr(emb, 'description', None)):
                if x:
                    morceaux.append(str(x)[:300])
    except Exception:
        pass
    return " ".join(m for m in morceaux if m).strip()


def _sujet_interdit(c, texte: str, msg=None) -> str:
    """« catégorie · terme » d'un sujet interdit (religion, politique, extrémisme) dans le texte, ses liens ou ses
    GIF ; "" sinon. L'ancien lexique des slogans d'abord, puis `sujets_interdits` (texte, puis GIF : le titre
    désigne l'image). Réglages : clé `sujets_interdits` de la configuration. FAIL-SAFE → ""."""
    try:
        t = offtopic_filter.scan(texte, _normalize_for_scan(texte))
        if t:
            return "politique · " + str(t)[:60]
    except Exception:
        pass
    try:
        reglages = (c or {}).get('sujets_interdits') if isinstance(c, dict) else None
        v = sujets_interdits.juger(texte, reglages=reglages)
        if not v:
            gif = _gif_texte(msg, texte) if msg is not None else _msg_url_slugs(texte)
            if gif:
                v = sujets_interdits.juger(gif, gif=True, reglages=reglages)
        if v:
            return f"{v['categorie']} · {v['terme']}"[:80]
    except Exception:
        pass
    return ""


# ═══════════════ RAFALE D'INFRACTIONS → EXCLUSION 1 H ═══════════════
# Quelqu'un qui enchaîne des infractions AUTOMATIQUES en quelques secondes = signature d'un BOT,
# d'un compte PIRATÉ ou d'un RAID → exclusion temporaire d'une heure et alerte. Le ban (2026-06-26)
# est retiré le 19/10/2026 : « ça expulse des gens qui n'ont rien fait ». Immunisés, owner, tête et
# staff jamais touchés, FAIL-OPEN, mémoire bornée.
_offense_burst: dict = {}     # (gid, uid) -> [datetime, ...] des infractions auto récentes
_burst_banned: dict = {}      # (gid, uid) -> datetime du ban burst (anti-rejeu, éviction par fenêtre)
_offense_last_tick: dict = {}  # (gid, uid) -> datetime du dernier tick (dédup même-message)


async def _offense_tick(guild, member, channel=None):
    """Compte une infraction AUTOMATIQUE ; si le membre en enchaîne trop en quelques secondes (bot,
    compte piraté, raid), exclusion temporaire d'une heure. Renvoie True SSI elle vient d'être posée
    (l'appelant peut alors s'arrêter). Owner, tête, staff et immunisés exclus. FAIL-OPEN, borné."""
    try:
        if guild is None or member is None or getattr(member, 'bot', False):
            return False
        gid, uid = guild.id, member.id
        try:
            if owner_ids_module.is_super_owner(uid) or await is_fully_immune(member):
                return False
        except Exception:
            return False
        conf = await cfg(gid)
        if not conf.get('burst_autoban', 1):
            return False
        need = max(3, int(conf.get('burst_autoban_count', 4) or 4))   # plancher de sécurité = 3
        window = max(3.0, float(conf.get('burst_autoban_window', 12) or 12))
        n = now()
        key = (gid, uid)
        # Dédup même-message : plusieurs sanctions pour UN message ne comptent qu'une fois.
        _last = _offense_last_tick.get(key)
        if _last is not None and (n - _last).total_seconds() < 0.3:
            return False
        _offense_last_tick[key] = n
        bucket = _offense_burst.setdefault(key, [])
        bucket[:] = [t for t in bucket if (n - t).total_seconds() < window]
        bucket.append(n)
        if len(_offense_burst) > 5000:
            for _k in [k for k, v in list(_offense_burst.items())
                       if not v or (n - v[-1]).total_seconds() > window]:
                _offense_burst.pop(_k, None)
                _offense_last_tick.pop(_k, None)
        # Une exclusion par heure au plus : elle dure une heure, la suivante peut repartir après.
        _deja = _burst_banned.get(key)
        if len(bucket) >= need and (_deja is None or (n - _deja).total_seconds() > 3600):
            _burst_banned[key] = n
            if len(_burst_banned) > 10000:
                for _bk in [k for k, t in list(_burst_banned.items()) if (n - t).total_seconds() > 3600]:
                    _burst_banned.pop(_bk, None)
            await _burst_timeout(guild, member, channel, len(bucket), int(window))
            return True
    except Exception as ex:
        _logerr("rafale.compte", ex, guild_id=getattr(guild, 'id', 0))
    return False


async def _burst_timeout(guild, member, channel, count, window):
    """Rafale d'infractions automatiques : exclusion temporaire d'une heure et alerte. Plus de ban
    (19/10/2026, « ça expulse des gens qui n'ont rien fait ») : la direction bannit depuis le site
    si c'est un bot ou un compte piraté ; sinon l'exclusion se lève seule."""
    reason = f"Rafale d'infractions automatiques ({count} en {window} s)"
    try:
        await member.timeout(timedelta(hours=1), reason=reason)
    except discord.HTTPException as ex:
        _logerr("rafale.exclusion", ex, guild_id=guild.id)
        return
    try:
        await _dm_sanction(member, guild, "Exclusion temporaire (1 h)",
                           "Plusieurs de tes messages ont été retirés en quelques secondes. "
                           "Si c'est une erreur, ouvre un ticket.")
    except Exception as ex:
        _logerr("rafale.mp", ex, guild_id=guild.id)
    await _record_infraction(guild.id, member.id, 'mute', reason, '1 h')
    await ulogger2026.log_event(
        bot, guild, ulogger2026.EventType.SEC_ESCALATION,
        description=(f"{member.mention} (`{member.id}`) exclu 1 h : {count} infractions automatiques "
                     f"en {window} s. Bot ou compte piraté ? Bannis depuis le site ; sinon ça se lève seul."),
        user=member, moderator=bot.user, channel=channel)


async def _isoler_par_securite(member, guild, channel, reason, heures=24):
    """Contenu dangereux sûr (lien de phishing connu, image explicite, ping de masse avec un lien
    d'arnaque) : exclusion temporaire et alerte. 19/10/2026 : plus jamais de ban automatique (« ça
    expulse des gens qui n'ont rien fait ») ; la direction bannit depuis le site si c'est confirmé.
    Owner, tête, staff et immunisés ne sont jamais visés."""
    try:
        if member is None or guild is None or getattr(member, 'bot', False):
            return
        if member.id == getattr(guild, 'owner_id', 0) or owner_ids_module.is_super_owner(member.id):
            return
        if await is_fully_immune(member):
            return
    except Exception as ex:
        _logerr("securite.immunite", ex, guild_id=getattr(guild, 'id', 0))
        return
    reason = str(reason or "Contenu dangereux")[:480]
    try:
        await member.timeout(timedelta(hours=heures), reason=reason)
    except discord.HTTPException as ex:
        _logerr("securite.exclusion", ex, guild_id=guild.id)
        return
    try:
        await _dm_sanction(member, guild, f"Exclusion temporaire ({heures} h)",
                           "Un contenu dangereux a été retiré de ton message. Si c'est une erreur, ouvre un ticket.")
    except Exception as ex:
        _logerr("securite.mp", ex, guild_id=guild.id)
    await _record_infraction(guild.id, member.id, 'mute', reason, f"{heures} h")
    await ulogger2026.log_event(
        bot, guild, ulogger2026.EventType.SEC_ESCALATION,
        description=(f"{member.mention} (`{member.id}`) exclu {heures} h — {reason}\n"
                     f"Confirmé ? Bannis depuis le site. Erreur ? Lève l'exclusion."),
        user=member, moderator=bot.user, channel=channel)


async def _lockdown_role_mentions(guild):
    """owner 2026-06-27 : AUCUN rôle ne doit être mentionnable par les membres (un ping de rôle =
    notification de masse = vecteur de raid/scam). Passe tous les rôles ÉDITABLES en
    mentionable=False. Le bot continue de pinger ses rôles d'event via allowed_mentions(roles=True)
    (il a la perm « Mentionner @everyone, @here et tous les rôles »). IDEMPOTENT (ne touche que les
    rôles encore mentionnables) → no-op aux boots suivants. FAIL-SAFE."""
    try:
        me = getattr(guild, 'me', None)
        if not (me and me.guild_permissions.manage_roles):
            return
        top = me.top_role
        changed = 0
        for role in list(guild.roles):
            try:
                if role.is_default() or role.managed or not role.mentionable or role >= top:
                    continue
                await role.edit(mentionable=False,
                                reason="Anti ping de masse — aucun rôle mentionnable (owner 2026-06-27)")
                changed += 1
            except Exception:
                pass
        if changed:
            print(f"[role_lockdown] {guild.id}: {changed} rôle(s) rendus non-mentionnables")
    except Exception as ex:
        print(f"[_lockdown_role_mentions] {ex}")


# OCR anti-scam image (owner 2026-06-27) : lit le texte DANS l'image (faux gains MrBeast/crypto)
# que le détecteur basé sur la légende ne voit pas. Tesseract = CPU bloquant → exécuté dans un
# thread (run_in_executor) ; sémaphore = au plus 2 OCR simultanés (anti-DoS / charge bornée).
_OCR_SEM = asyncio.Semaphore(2)
_IMG_EXTS = ('png', 'jpg', 'jpeg', 'webp', 'bmp')


async def _ocr_scam_check(msg, immune: bool = False, lire=None):
    """Tâche de fond : lit le texte DANS les images (et les QR codes) et retire une image d'arnaque.
    19/10/2026 : plus de ban sur une lecture d'image (« ça expulse des gens qui n'ont rien fait »).
    Image retirée et direction alertée ; l'infraction compte pour la rafale (bot ou compte piraté →
    exclu 1 h). Seul un QR code menant à un site de phishing exclut 24 h. Immunisés : retrait et
    alerte « compte probablement piraté », jamais de sanction. Sans Tesseract : rien. FAIL-SAFE."""
    try:
        if not ocr_scan.available():
            # Visible dans [DIAG] Railway : sans ça, un Tesseract absent = zéro scan, en silence.
            # (Pas encore vérifié — les 2 premières minutes après un démarrage — : on passe, sans alarme.)
            if ocr_scan.etat() is False:
                try:
                    diag.warn("security", "ocr_scan", "Tesseract indisponible → scan d'image OCR inactif")
                except Exception:
                    pass
            return
        atts = []
        _srcs = list(getattr(msg, 'attachments', None) or [])
        for _s in (getattr(msg, 'message_snapshots', None) or []):  # images transférées (audit 2026-07-02)
            _srcs += list(getattr(_s, 'attachments', None) or [])
        for a in _srcs:
            ct = (getattr(a, 'content_type', '') or '').lower()
            fn = (getattr(a, 'filename', '') or '').lower()
            if ct.startswith('image/') or fn.rsplit('.', 1)[-1] in _IMG_EXTS:
                if (getattr(a, 'size', 0) or 0) <= 8_000_000:      # >8 Mo : on saute (perf)
                    atts.append(a)
        if not atts:
            return
        loop = asyncio.get_event_loop()
        # La vague « casino » poste 4 captures d'un coup ; le coût reste borné (sémaphore 2, thread,
        # ≤8 Mo/image).
        for a in atts[:4]:
            try:
                data = await (lire(a) if lire else a.read())
            except Exception:
                continue
            try:
                qrs = await loop.run_in_executor(None, ocr_scan.qr_payloads, data)
            except Exception as ex:
                _logerr("ocr.qr", ex, guild_id=msg.guild.id)
                qrs = []
            for _qp in qrs:
                phishing = check_phishing(_qp)[0]
                if not (phishing or check_scam(_qp)[0] or check_shortener(_qp)[0]):
                    continue
                await _retirer_image_arnaque(msg, "QR code piégé (destination malveillante)", _qp[:80], immune)
                if not immune:
                    if phishing:
                        await _isoler_par_securite(msg.author, msg.guild, msg.channel,
                                                   f"QR code vers un site de phishing ({_qp[:60]})")
                    else:
                        await _offense_tick(msg.guild, msg.author, msg.channel)
                return
            try:
                async with _OCR_SEM:
                    text = await loop.run_in_executor(None, ocr_scan.image_text, data)
            except Exception:
                continue
            is_scam, reason, score = ocr_scan.scan_scam(text, threshold=6)
            if is_scam:
                await _retirer_image_arnaque(msg, "Image d'arnaque détectée par OCR", f"{reason} (score {score})", immune)
                if not immune:
                    await _offense_tick(msg.guild, msg.author, msg.channel)
                return
            #  27/10/2026 : le texte écrit DANS l'image ou le GIF — une insulte grave, du validisme ou un sujet interdit
            #  retirent l'image (le journal le dit) ; aucune sanction sur une lecture d'image.
            if not immune and await _retirer_si_texte_interdit(msg, text, "une image"):
                return
            # Routine (caché sauf DIAG_VERBOSE=1) : prouve que le scan a TOURNÉ et ce qu'il a lu.
            try:
                diag.trace("security", "ocr_scan",
                           f"image scannée — {msg.author.id} texte={len(text)}c score={score}")
            except Exception:
                pass
    except Exception as ex:
        _logerr("ocr.scan", ex, guild_id=getattr(getattr(msg, 'guild', None), 'id', 0))


async def _texte_image_interdit(c: dict, text: str) -> str:
    """Le texte lu dans une image ou un GIF : « insulte · … », « validisme · … », « religion · … »… ou ""."""
    if not text or len(text.strip()) < 3:
        return ""
    if c.get('anti_insults', 1):
        _niv, _mot = insult_filter.scan(text, lg=insult_filter.langue(text, "en"))
        if _niv >= 3:
            return "insulte · " + str(_mot)
        _abl = insult_filter.ableist_hit(text)
        if _abl:
            return "validisme · " + str(_abl)
    if c.get('anti_offtopic', 1):
        return _sujet_interdit(c, text)
    return ""


async def _retirer_si_texte_interdit(msg, text: str, ou: str) -> bool:
    """Retire le message quand le texte de son image (ou de son GIF) est interdit ; le journal le dit. FAIL-SAFE."""
    try:
        lu = await _texte_image_interdit(await cfg(msg.guild.id), text)
        if not lu:
            return False
        try:
            await msg.delete()
        except discord.HTTPException:
            pass
        await send_log(msg.guild, 'anti_badwords', msg.author, msg, f"Texte interdit dans {ou}", f"||{lu[:60]}||")
        return True
    except Exception as ex:
        _logerr("ocr.texte", ex, guild_id=getattr(msg.guild, 'id', 0))
        return False


_HOTES_APERCU = ("discordapp.net", "discordapp.com", "discord.com")
_GIF_LIEN_RE = re.compile(r"https?://(?:[a-z0-9-]+\.)*(?:tenor\.com|giphy\.com|klipy\.com)/", re.I)


async def _ocr_gif_lien(msg) -> None:
    """28/10/2026 (exigence 11 : « GIF insultants bloqués : lien, titre, TEXTE DE L'IMAGE ») : le texte écrit dans un GIF
    Tenor / Giphy posté en lien. Discord pose l'aperçu après coup : on relit le message 3 s plus tard, on prend la
    première image de l'aperçu PAR LE RELAIS DE DISCORD (jamais l'hôte du GIF), 4 Mo au plus, et l'OCR la lit. En fond,
    au plus 2 lectures à la fois (le sémaphore de l'OCR). FAIL-SAFE."""
    from urllib.parse import urlsplit
    try:
        if not ocr_scan.available() or not _GIF_LIEN_RE.search(msg.content or ""):
            return
        await asyncio.sleep(3)
        try:
            msg = await msg.channel.fetch_message(msg.id)
        except discord.HTTPException:
            return   # retiré entre-temps (la modération), ou illisible
        url = ""
        for e in msg.embeds or []:
            for x in (getattr(e, 'thumbnail', None), getattr(e, 'image', None)):
                u = str(getattr(x, 'proxy_url', None) or "")
                hote = (urlsplit(u).hostname or "").lower() if u.startswith("https://") else ""
                if hote and any(hote == h or hote.endswith("." + h) for h in _HOTES_APERCU):
                    url = u
                    break
            if url:
                break
        if not url:
            return
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as s:
            async with s.get(url) as r:
                if r.status != 200 or int(r.headers.get("Content-Length") or 0) > 4_000_000:
                    return
                data = await r.content.read(4_000_001)
        if len(data) > 4_000_000:
            return
        async with _OCR_SEM:
            text = await asyncio.get_event_loop().run_in_executor(None, ocr_scan.image_text, data)
        await _retirer_si_texte_interdit(msg, text, "un GIF")
    except Exception as ex:
        _logerr("ocr.gif", ex, guild_id=getattr(getattr(msg, 'guild', None), 'id', 0))


