# ANTI-DOXXING / COORDONNÉES PERSO (owner 2026-06-27, protection mineurs) : on retire les
# coordonnées personnelles postées en public (tél FR, e-mail, adresse postale) — qu'un jeune
# divulgue les siennes OU qu'on « dox » celles d'un autre. Pas de sanction (souvent une
# maladresse) ; suppression + rappel + alerte owner (qui vérifie si c'est un doxxing). Précis
# pour limiter les faux positifs (n° FR 06/07 ou +33, vrai e-mail, numéro+type de voie).
# Téléphone FR : SÉPARATEUR OBLIGATOIRE entre les paires (« 06 12 34 56 78 » / « 06.12… »), sinon
# un nombre brut de 10 chiffres (seed de jeu, ID…) ferait un faux positif. +33 accepté.
_PII_PHONE_RE = re.compile(r'(?<!\d)(?:\+33\s?|0)[67](?:[ .\-]\d{2}){4}(?!\d)')
_PII_EMAIL_RE = re.compile(r'\b[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}\b', re.IGNORECASE)
# Adresse : numéro + TYPE DE VOIE. On EXCLUT « cours/place/quai » (FP : « 3 cours demain »,
# « 4 place de libre »). « bd / av / chemin » sont aussi des mots du quotidien (« 3 bd de one
# piece », « 2 chemin pour l'obby ») : il leur faut une suite de nom de voie (« du », « des »,
# « de la », « de l' ») ou une majuscule (« 12 bd Haussmann ») — 20/10/2026.
_VOIE_SURE = r"(?:rue|avenue|av\.|boulevard|impasse|all[ée]e|r[ée]sidence)\s+[a-zà-ÿ]"
_VOIE_AMBIGUE = r"(?:bd|av|chemin)\s+(?:d(?:u|es|e\s+la|e\s+l['’])\s*[a-zà-ÿ]|(?-i:[A-ZÀ-Ý]))"
_PII_ADDR_RE = re.compile(
    r"\b\d{1,4}\s*(?:bis|ter)?\s*,?\s*(?:" + _VOIE_SURE + "|" + _VOIE_AMBIGUE + ")", re.IGNORECASE)
# Une adresse de SERVICE (support@roblox.com, contact@…) n'est pas une coordonnée personnelle.
_EMAIL_DE_SERVICE = frozenset((
    "support", "contact", "info", "infos", "help", "aide", "noreply", "no-reply", "abuse", "privacy",
    "security", "securite", "press", "presse", "hello", "bonjour", "team", "equipe", "admin", "legal",
    "dpo", "rgpd", "gdpr", "service", "sav", "partners", "partenariat", "partenariats", "business",
    "jobs", "careers", "recrutement", "feedback", "webmaster", "postmaster", "communication",
    "marketing", "sales", "commercial", "accueil", "billing", "facturation", "news", "newsletter",
    "media", "medias", "creators", "developers", "appeals", "safety", "trust", "moderation"))


def _email_perso(ct: str) -> bool:
    """Au moins une adresse e-mail qui n'est pas celle d'un service."""
    return any(m.group(0).split("@", 1)[0].split("+", 1)[0].lower() not in _EMAIL_DE_SERVICE
               for m in _PII_EMAIL_RE.finditer(ct))


async def _doxxing_check(msg, ct):
    """Retire les coordonnées perso d'un message public. Retourne True si traité. FAIL-SAFE."""
    try:
        kind = None
        if _PII_PHONE_RE.search(ct):
            kind = "numéro de téléphone"
        elif _PII_ADDR_RE.search(ct):
            kind = "adresse postale"
        elif _email_perso(ct):
            kind = "adresse e-mail"
        if not kind:
            return False
        try:
            await msg.delete()
        except Exception:
            pass
        try:
            await send_log(msg.guild, 'anti_badwords', msg.author, msg,
                           f"Coordonnées perso retirées ({kind})", None)
        except Exception:
            pass
        try:
            await _warn_calm_down(
                msg.channel,
                f"🔒 {msg.author.mention}, on ne partage **pas de coordonnées personnelles** "
                f"({kind}) en public — ni les tiennes, ni celles de quelqu'un d'autre. C'est pour "
                f"votre sécurité. 💚 _(Besoin de les donner ? Fais-le en privé, à une personne de "
                f"confiance.)_")
        except Exception:
            pass
        try:
            await ulogger2026.log_event(
                bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                description=(f"🔒 **Coordonnées perso retirées** ({kind}) — {msg.author.mention} "
                             f"(`{msg.author.id}`) dans {msg.channel.mention}.\n"
                             f"➡️ Vérifie : **doxxing** (infos d'un AUTRE membre) → sanctionne ; "
                             f"ou simple maladresse d'un jeune → rien à faire."),
                user=msg.author, moderator=bot.user, channel=msg.channel,
                extra={"🔒 Protection mineurs": "Anti-doxxing / coordonnées"})
        except Exception:
            pass
        return True
    except Exception:
        return False


# 🎯 DÉTECTION DU HARCÈLEMENT (owner 2026-06-27) : quand une VRAIE attaque (insulte ciblée / haine
# / validisme / menace, déjà filtrée) vise une personne IDENTIFIABLE (mention ou réponse), on
# enregistre (agresseur → victime). ACHARNEMENT = un agresseur ≥4 attaques/10 min sur la même
# victime → exclusion 1 h + alerte. MEUTE = ≥3 agresseurs distincts sur la même victime/10 min →
# alerte URGENTE owner + protéger la victime. On ne compte QUE de vraies attaques (le banter léger
# N1 n'en est pas une) → un groupe d'amis qui se charrient gentiment ne déclenche pas. FAIL-SAFE.
_harass_events = {}    # (gid, victim_id) -> [(aggressor_id, ts)]
_harass_alerted = {}   # (gid, victim_id) -> dernier ts d'alerte (anti-spam)


async def _note_attack(msg, kind, term):
    try:
        guild, aggressor = msg.guild, msg.author
        victim_id = None
        ref = getattr(msg, 'reference', None)
        rr = getattr(ref, 'resolved', None) if ref else None
        ra = getattr(rr, 'author', None) if rr else None
        if ra is not None and not getattr(ra, 'bot', False) and ra.id != aggressor.id:
            victim_id = ra.id
        if victim_id is None:
            for mm in (getattr(msg, 'mentions', None) or []):
                if not getattr(mm, 'bot', False) and mm.id != aggressor.id:
                    victim_id = mm.id
                    break
        if not victim_id:
            return
        conf = await cfg(guild.id)
        if not conf.get('anti_harassment', 1):
            return
        now = discord.utils.utcnow().timestamp()
        win = 600
        key = (guild.id, victim_id)
        evs = [(a, t) for (a, t) in _harass_events.get(key, []) if now - t <= win]
        evs.append((aggressor.id, now))
        _harass_events[key] = evs
        # Éviction PROPRE (anti-fuite) : on retire les clés sans évènement récent, jamais un
        # clear() brutal qui oublierait un harcèlement en cours.
        if len(_harass_events) > 5000:
            for _k in [k for k, v in list(_harass_events.items())
                       if not v or (now - v[-1][1]) > win]:
                _harass_events.pop(_k, None)
                _harass_alerted.pop(_k, None)
        if now - _harass_alerted.get(key, 0) < 300:
            return
        a_count = sum(1 for (a, t) in evs if a == aggressor.id)
        distinct = set(a for (a, t) in evs)
        if len(distinct) >= 3:
            _harass_alerted[key] = now
            await _harass_respond(guild, victim_id, list(distinct), 'meute', None)
        elif a_count >= 4:
            # MUTUALITÉ : si la « victime » a AUSSI attaqué l'agresseur (≥2×) dans la fenêtre, c'est
            # une DISPUTE réciproque (ou du charriage entre amis) → PAS un harcèlement à sens unique
            # → on ne timeout pas (les insultes individuelles sont de toute façon déjà traitées).
            _back = sum(1 for (a, t) in _harass_events.get((guild.id, aggressor.id), [])
                        if a == victim_id and now - t <= win)
            if _back >= 2:
                return
            _harass_alerted[key] = now
            await _harass_respond(guild, victim_id, [aggressor.id], 'acharnement', aggressor)
    except Exception as ex:
        print(f"[_note_attack] {ex}")


async def _harass_respond(guild, victim_id, aggressor_ids, mode, aggressor):
    victim = guild.get_member(victim_id)
    vname = victim.mention if victim else f"<@{victim_id}>"
    if mode == 'acharnement' and aggressor is not None:
        try:
            await aggressor.timeout(timedelta(hours=1),
                                    reason="Harcèlement : acharnement répété sur un membre")
        except Exception:
            pass
        try:
            await _record_infraction(guild.id, aggressor.id, 'harcelement',
                                     f"Acharnement sur le membre {victim_id}", '1h')
        except Exception:
            pass
        desc = (f"🎯 **HARCÈLEMENT (acharnement)** — {aggressor.mention} (`{aggressor.id}`) s'en prend "
                f"de façon **répétée** à {vname} → exclusion 1 h.\n"
                f"➡️ Si ça continue, **bannis** (`/off`). La victime mérite d'être protégée. 🛡️")
    else:
        ag = ", ".join(f"<@{a}>" for a in aggressor_ids[:10])
        desc = (f"🚨 **HARCÈLEMENT EN MEUTE** — {vname} est pris pour cible par **{len(aggressor_ids)}** "
                f"membres en quelques minutes : {ag}.\n"
                f"➡️ Interviens vite : calme le salon (slowmode) + sanctionne les meneurs. "
                f"La victime a besoin de soutien. 🛡️")
    try:
        await ulogger2026.log_event(
            bot, guild, ulogger2026.EventType.SEC_ESCALATION, description=desc,
            user=victim, moderator=bot.user,
            extra={"🎯 Protection": "Anti-harcèlement", "🙂 Cible": f"<@{victim_id}>"})
    except Exception:
        pass


async def _cumulative_insult_sanction(msg, iterm):
    """Wrapper rétro-compatible : insulte ciblée → escalade cumulative générique."""
    await _cumulative_offense_sanction(msg.guild, msg.author, msg.channel, 'insulte')


#  31/10/2026, le fondateur : une seule échelle pour TOUTE infraction automatique (insultes, spam, mentions, liens,
#  invitations, majuscules…), comptée sur 24 h : 1re → il est prévenu ; 2e → mute 30 min ; 3e (juste après son mute)
#  → muet jusqu'à la décision de la direction (28 jours, le plus long que Discord permet) et UN panneau dans 📋logs avec
#  ce qu'il a fait et les boutons de décision. Plus de « 1 h, 1 jour, 1 semaine, blacklist » automatiques.
ECHELLE_FENETRE_H = 24
ECHELLE_MUTE_MIN = 30
ECHELLE_DECISION_J = 28


async def _cumulative_offense_sanction(guild, member, channel, label='infraction', preuve=''):
    """L'échelle unique des infractions automatiques (voir ECHELLE_*). À appeler APRÈS avoir enregistré l'infraction.
    FAIL-SAFE : n'interrompt jamais la modération. Jamais un immunisé (fondateur, direction, rôles immunisés)."""
    try:
        if await is_fully_immune(member):
            return
    except Exception:
        return
    n = 1
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT COUNT(*) FROM infractions WHERE guild_id=? AND user_id=? AND mod_id=? AND "
                "type NOT IN ('mute','unmute','ban','kick') AND "
                f"datetime(created_at) >= datetime('now','-{ECHELLE_FENETRE_H} hours')",
                (guild.id, member.id, getattr(getattr(bot, 'user', None), 'id', 0) or 0)) as cur:
                n = int((await cur.fetchone())[0] or 1)
    except Exception:
        n = 1
    motif = str(label or 'infraction')[:120]
    extrait = (" — « " + str(preuve)[:120] + " »") if preuve else ""

    async def _notice(text):
        if channel is not None:
            await _warn_calm_down(channel, text)

    if n <= 1:
        await _notice(f"🚫 {member.mention}, ce comportement (**{motif}**) n'est pas autorisé ici. Premier avertissement : "
                      f"à la prochaine, tu seras rendu muet.")
        try:
            await _dm_sanction(member, guild, "Avertissement ⚠️", f"{motif}{extrait}. À la prochaine infraction, tu seras "
                               f"rendu muet {ECHELLE_MUTE_MIN} minutes.")
        except Exception:
            pass
        return
    if n == 2:
        try:
            await member.timeout(timedelta(minutes=ECHELLE_MUTE_MIN), reason=f"2e infraction en 24 h : {motif}"[:500])
        except Exception:
            pass
        try:
            await _record_infraction(guild.id, member.id, 'mute', f"2e infraction en 24 h : {motif}{extrait}",
                                     f"{ECHELLE_MUTE_MIN} minutes")
        except Exception:
            pass
        await _notice(f"🔇 {member.mention} est rendu muet **{ECHELLE_MUTE_MIN} minutes** (2e infraction : {motif}).")
        try:
            await _dm_sanction(member, guild, f"Mute ({ECHELLE_MUTE_MIN} minutes)",
                               f"{motif}{extrait}. Si tu recommences après ce mute, tu resteras muet jusqu'à la décision "
                               f"de la direction.", f"{ECHELLE_MUTE_MIN} minutes")
        except Exception:
            pass
        return
    #  3e infraction ou plus : muet jusqu'à la décision (une seule fois — ensuite le panneau se met à jour).
    deja = False
    try:
        fin_mute = getattr(member, "timed_out_until", None)
        deja = bool(fin_mute and fin_mute > now() + timedelta(days=7))
    except Exception:
        deja = False
    if not deja:
        try:
            await member.timeout(timedelta(days=ECHELLE_DECISION_J), reason=f"Infractions répétées ({n} en 24 h) : "
                                 f"muet jusqu'à la décision de la direction"[:500])
        except Exception:
            pass
        try:
            await _record_infraction(guild.id, member.id, 'mute', f"{n}e infraction en 24 h : {motif}{extrait} — muet "
                                     f"jusqu'à la décision de la direction", "jusqu'à décision")
        except Exception:
            pass
        await _notice(f"⛔ {member.mention} est rendu muet **jusqu'à la décision de la direction** ({n} infractions en "
                      f"24 h).")
        try:
            await _dm_sanction(member, guild, "Mute jusqu'à décision",
                               f"{n} infractions en 24 h (dernière : {motif}{extrait}). La direction va décider de la suite.",
                               "jusqu'à décision")
        except Exception:
            pass
    try:
        await vigilance.examiner(guild.id, member.id, forcer=True)
    except Exception as ex:
        _logerr("echelle.panneau", ex, guild_id=guild.id)

def check_channel_cfg(msg, conf):
    if not conf: return False, None
    ct = (msg.content or "").strip()
    # Commands only - bloque tout sauf les commandes slash (qui n'apparaissent pas comme messages normaux)
    if conf.get('commands_only', False):
        # Si le message n'est pas vide, c'est pas une commande slash
        if ct or msg.attachments:
            return True, "commands_only"
    if not conf.get('messages', True):
        has_txt = bool(re.sub(r'<a?:\w+:\d+>|https?://\S+', '', ct).strip())
        if has_txt and not msg.attachments and not msg.embeds:
            return True, "messages"
    if not conf.get('images', True):
        for att in msg.attachments:
            if att.filename.lower().split('.')[-1] in ['png', 'jpg', 'jpeg', 'webp', 'bmp']:
                return True, "images"
    if not conf.get('gifs', True) and get_gif_type(msg):
        return True, "gifs"
    if not conf.get('emojis', True) and re.search(r'<a?:\w+:\d+>', ct):
        return True, "emojis"
    if not conf.get('links', True) and re.search(r'https?://', ct):
        return True, "links"
    return False, None

