async def get_ticket(ch_id):
    try:
        async with get_db() as db:
            async with db.execute('SELECT id, user_id, claimed_by, answers, panel_id FROM tickets WHERE channel_id=? AND status="open"', (ch_id,)) as c:
                r = await c.fetchone()
                if r:
                    ans = {}
                    try: ans = json.loads(r[3]) if r[3] else {}
                    except: pass
                    return {'id': r[0], 'user': r[1], 'claimed': r[2] or 0, 'answers': ans, 'panel_id': r[4] or ''}
                return None
    except: return None

async def count_user_tickets(g, uid, pid=None):
    cnt = 0
    to_close = []
    try:
        q = "SELECT id, channel_id FROM tickets WHERE guild_id=? AND user_id=? AND status='open'"
        p = [g.id, uid]
        if pid:
            #  Un recours d'avant le 24/10/2026 porte le panneau « Serveur » : il ne compte pas dans son maximum.
            q += " AND panel_id=? AND COALESCE(answers, '') NOT LIKE ?"
            p += [pid, f"%{RECOURS_MARQUE}%"]
        async with get_db() as db:
            async with db.execute(q, p) as c:
                tks = await c.fetchall()
        for tid, chid in tks:
            if await tickets_fils.existe(g, chid): cnt += 1
            else: to_close.append(tid)
        if to_close:
            async with get_db() as db:
                for t in to_close:
                    await db.execute("UPDATE tickets SET status='closed' WHERE id=?", (t,))
                await db.commit()
        return cnt
    except: return 0

def _ticket_event_parts(lt, user, extra, closer):
    """(actor_id, detail) à stocker pour un événement de ticket. FAIL-OPEN."""
    uid = user.id if hasattr(user, 'id') else user
    actor, detail = 0, ''
    try:
        if lt in ('create', 'leave'):
            actor = uid
        elif lt == 'close':
            actor = getattr(closer, 'id', 0) or 0
            detail = str(extra or '')[:200] if isinstance(extra, str) else ''
        elif lt in ('claim', 'add_staff', 'blacklist'):
            actor = extra or 0
        elif lt == 'priority':
            actor, detail = int(extra[0]), str(extra[1])
        elif lt == 'note':
            actor, detail = int(extra[0]), str(extra[1])[:300]
    except Exception:
        try:
            actor = int(extra) if extra else 0
        except Exception:
            actor = 0
    return int(actor or 0), detail


def _ticket_timeline_line(kind, actor_id, detail, ts):
    """Une ligne LISIBLE de la timeline d'un ticket (horodatage Discord relatif)."""
    t = f" · <t:{int(ts)}:t>" if ts else ""
    who = f"<@{int(actor_id)}>" if actor_id else "—"
    lab = {
        'create':    f"**Créé** par {who}",
        'claim':     f"**Pris en charge** par {who}",
        'close':     f"**Fermé** par {who}" + (f" · _{str(detail)[:150]}_" if detail else ""),
        'leave':     f"{who} a **quitté** le ticket",
        'add_staff': f"Staff ajouté (par {who})",
        'blacklist': f"**Blacklisté** par {who}" + (f" · panel {detail}" if detail else ""),
        'priority':  f"Priorité → **{detail}** (par {who})",
        'note':      f"Note de {who}" + (f" : _{str(detail)[:150]}_" if detail else ""),
    }.get(kind, f"{kind} ({who})")
    return lab + t


def _staff_ou_plus(g, membre, c) -> bool:
    """19/10/2026 : « seulement le rôle staff et au-dessus — direction, les rôles les plus élevés ».
    Propriétaire et administrateurs, ou un rôle placé au niveau du rôle staff (tickets) ou plus
    haut ; sans rôle staff réglé, le rôle direction sert de seuil ; sans aucun des deux, personne
    d'autre que l'administration."""
    if membre is None or g is None:
        return False
    if membre.id == g.owner_id or getattr(membre.guild_permissions, "administrator", False):
        return True
    seuils = [g.get_role(int(c.get(k, 0) or 0)) for k in ('ticket_staff', 'direction_allowed_role')]
    seuils = [r for r in seuils if r is not None]
    if not seuils:
        return False
    plancher = min(seuils, key=lambda r: r.position)
    return any(r.position >= plancher.position for r in getattr(membre, "roles", []) or [])


#  19/10/2026 : « je vais t'envoyer les ID, c'est ceux-là et uniquement eux qui sont à la tête…
#  premier, c'est moi, le fondateur même, et le deuxième, c'est la direction ». Eux seuls entrent sur
#  le site ; jamais suspendus.
TETE_IDS = frozenset({781205382923288593, 827633340797681714})
#  26/10/2026 (sécurité) — des refus STABLES (aucune valeur dedans) : le fondateur et la direction, protégés EN DUR partout
#  où un membre peut être visé (/mod mute, warn, direction, infractions, panneau du staff, dossiers suspects) ; et le
#  nettoyage d'un salon où l'auteur ne gère pas les messages.
REFUS_TETE = "Cible protégée : le fondateur et la direction ne sont jamais sanctionnés."
REFUS_CLEAR = "❌ Il te faut « Gérer les messages » dans ce salon pour le vider."


def _a_la_tete(g, membre, c=None) -> bool:
    """« C'est ceux-là et uniquement eux » : les deux comptes de TETE_IDS, par identifiant. 24/10/2026 :
    le propriétaire du serveur en faisait aussi partie — celui d'un autre serveur où se trouve le bot
    entrait sur le site et y lisait les erreurs du bot entier."""
    return membre is not None and g is not None and membre.id in TETE_IDS


def _direction_ou_plus(g, membre, c) -> bool:
    """19/10/2026 : « seulement le fondateur et le rôle direction » ont le droit d'agir depuis le
    tableau de bord (supprimer, retirer) — et les rôles placés au-dessus de la direction."""
    if membre is None or g is None:
        return False
    if membre.id == g.owner_id or owner_ids_module.is_super_owner(membre.id):
        return True
    direction = g.get_role(int(c.get('direction_allowed_role', 0) or 0))
    return direction is not None and any(r.position >= direction.position
                                         for r in getattr(membre, "roles", []) or [])


