async def _ticket_ouvert(g, ticket_id: int):
    """(salon, ticket) d'un ticket encore ouvert de ce serveur, ou (None, None). 24/10/2026 (revue) : un fil
    archivé (7 jours sans message) n'est pas en cache — `tickets_fils.salon` va le chercher ; avant, un
    ticket bien ouvert répondait « Ce ticket n'est plus ouvert. ». Une panne de Discord lève."""
    async with get_db() as db:
        async with db.execute("SELECT channel_id FROM tickets WHERE id=? AND guild_id=? AND status='open'",
                              (int(ticket_id), g.id)) as cur:
            r = await cur.fetchone()
    if not r:
        return None, None
    ch = await tickets_fils.salon(g, int(r[0]))
    tk = await get_ticket(int(r[0])) if ch is not None else None
    return (ch, tk) if tk else (None, None)


async def _decision_recrutement(g, ticket_id: int, auteur, accepte: bool, motif: str = "", *, annonce=None,
                                mp: bool = True):
    """Accepter (rôle du clan, puis fermeture) ou refuser (fermeture) une candidature : la
    fermeture passe par le circuit normal — dossier, transcript, suivi des recrutements.
    24/10/2026 (revue) : le motif d'un refus reste à l'équipe (historique, journal du site, suivi) ; le
    candidat lit « Candidature refusée » (MP et fil) — le formulaire promet « le candidat ne le voit pas ».
    La décision suit le ticket jusqu'au suivi des recrutements, qui ne la devine plus dans le texte.
    26/10/2026 (le ticket propre) : `annonce()` (questionnaire.py) pose le message de la décision et le message privé
    juste avant la fermeture — le rôle est déjà donné ; `mp=False` : pas de second message privé à la fermeture."""
    try:
        ch, tk = await _ticket_ouvert(g, ticket_id)
    except discord.HTTPException as ex:
        _logerr("recrutement.ticket", ex, guild_id=g.id)
        return False, "Discord ne répond pas : réessaie dans un instant."
    if ch is None:
        return False, "Ce ticket n'est plus ouvert."
    candidat = g.get_member(int(tk['user']))
    if accepte:
        c = await cfg(g.id)
        role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
        if role is None:
            return False, "Aucun rôle Rell Seas réglé dans /configure."
        if candidat is None:
            return False, "Le candidat a quitté le serveur : rien à donner."
        #  26/10/2026 (sécurité) : la règle de /rellseas — jamais le rôle du clan à un membre sanctionné (radié, isolé,
        #  restreint) ; la carte du ticket et le site passent tous deux ici.
        refus = _refus_cible_rellseas(g, auteur, candidat, True)
        if refus:
            return False, f"Candidature non acceptée : {refus}."
        if g.me is None or role >= g.me.top_role or not g.me.guild_permissions.manage_roles:
            return False, "Je ne peux pas donner ce rôle (permission ou hiérarchie)."
        try:
            await candidat.add_roles(role, reason=f"Candidature acceptée par {auteur} ({auteur.id})")
        except discord.HTTPException as ex:
            _logerr("recrutement.role", ex, guild_id=g.id)
            return False, "Discord a refusé de donner le rôle."
    raison = "Accepté" if accepte else ("Refusé" + (f" : {motif[:150]}" if motif else ""))
    tk = dict(tk, decision="acceptes" if accepte else "refuses")
    #  26/10/2026 : ce que lit le candidat vient de Textes & noms (sinon le texte d'origine).
    public = await textes.texte(g.id, "recrutement.fermeture.acceptee" if accepte else "recrutement.fermeture.refusee")
    if annonce is not None:
        #  26/10/2026 : le message de la décision (avec le choix du métier, s'il est réglé) et le message privé.
        try:
            await annonce()
        except Exception as ex:
            _logerr("recrutement.annonce", ex, guild_id=g.id)
    elif accepte:
        #  25/10/2026 (rôles des métiers) : AVANT la fermeture, une carte dans le ticket dit au nouveau membre de
        #  choisir son métier dans le guide du clan ; le lien suit dans le MP de fermeture (le ticket part en 5 s).
        try:
            guide = await metiers.inviter_au_choix(g, ch, candidat)
        except Exception as ex:
            guide = None
            _logerr("recrutement.metier", ex, guild_id=g.id)
        if guide:
            public += " · " + await textes.texte(g.id, "metiers.mp_lien", lien=guide)
    _fermer_en_fond(_fermer_ticket(g, ch, tk, auteur, raison, public=public, mp=mp))
    await _journal_rellseas(g, f"**Candidature {'acceptée' if accepte else 'refusée'}** · <@{tk['user']}> "
                               f"par {auteur.mention}" + (f" — {motif[:150]}" if motif and not accepte else ""),
                            membre_id=int(tk['user']), auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, int(tk['user']), "recrutement_" + ("accepte" if accepte else "refuse"),
                           raison, surface="recrutement")
    return True, ("Candidature acceptée : rôle donné, ticket fermé." if accepte
                  else "Candidature refusée : ticket fermé.")


async def _accueil_recrutement(g, ch, tid: int, candidat_id: int, pnl: dict, pid: str = "") -> bool:
    """26/10/2026 (le ticket propre, questionnaire.py) : l'AFFICHE — le message unique d'un ticket de recrutement (la
    bannière, le candidat cité sans être prévenu, les conditions, sa fiche, où il en est, « Direction » pour la tête) ;
    un panneau « automatique » envoie aussitôt la première étape du questionnaire. Le ticket est déjà ouvert : une erreur
    ici ne le défait jamais — elle est journalisée, et sans l'affiche, l'ancienne carte de décision (accepter, refuser)
    est posée pour que l'équipe puisse toujours trancher. Rend True si l'affiche est posée."""
    try:
        await questionnaire.poser_affiche(g, ch, tid, candidat_id, pnl, pid)
        return True
    except Exception as ex:
        _logerr("recrutement.affiche", ex, guild_id=g.id)
    try:
        await ch.send(view=recrutements.carte_decision(tid), allowed_mentions=discord.AllowedMentions.none())
    except discord.HTTPException as ex2:
        _logerr("recrutement.carte_repli", ex2, guild_id=g.id)
    return False


async def _recrutement_extras(g, tid: int, pris_par=None) -> dict:
    """Le bas du panneau « Direction » d'une affiche (éphémère, la tête seule) : le contexte du dossier (son compte, son
    ancienneté, ses tickets, son casier), qui l'a pris en charge, et « Fermer » — le bouton du ticket, avec son
    gestionnaire de toujours (`TicketControlView`, enregistré au démarrage). Pas « Prendre en charge » : il poste un
    message de plus, et le ticket de recrutement n'en garde que deux."""
    async with get_db() as db:
        async with db.execute("SELECT user_id, claimed_by FROM tickets WHERE id=? AND guild_id=?",
                              (int(tid), g.id)) as cur:
            r = await cur.fetchone()
    if r is None:
        return {}
    ctrl = TicketControlView()
    boutons = {b.custom_id: b for b in list(ctrl.children) if isinstance(b, discord.ui.Button)}
    garde = [boutons[k] for k in ("ticket_ctrl_close",) if k in boutons]
    for b in boutons.values():
        ctrl.remove_item(b)
    return {"contexte": await _contexte_ticket(g, int(r[0]), int(tid)), "pris_par": int(pris_par or r[1] or 0),
            "boutons": garde}


async def _liste_noire_recrutement(g, membre_id, ajouter: bool) -> bool:
    """26/10/2026 : la liste noire des panneaux de RECRUTEMENT (celle que lit `_ticket_ouvrir`, le système d'avant) —
    un membre ajouté ou retiré, ou toute la liste vidée (`membre_id` None, `ajouter` faux). Les autres panneaux ne
    bougent pas. Tenue par questionnaire.py (qui, quand, pourquoi, par qui : la liste du site)."""
    c = await cfg(g.id)
    panels = c.get('ticket_panels') or {}
    change = False
    for pid in rellseas_ui.panneaux_tickets(c):
        pnl = panels.get(pid)
        if not isinstance(pnl, dict):
            continue
        avant = [int(x) for x in pnl.get('blacklist') or [] if str(x).isdigit()]
        if membre_id is None:
            apres = avant if ajouter else []
        elif ajouter:
            apres = avant if int(membre_id) in avant else avant + [int(membre_id)]
        else:
            apres = [x for x in avant if x != int(membre_id)]
        if apres != avant:
            pnl['blacklist'] = apres
            change = True
    return bool(await db_set(g.id, 'ticket_panels', panels)) if change else True


async def _role_clan_de(g):
    """Le rôle du clan (/configure → Rell Seas), ou None."""
    return g.get_role(int((await cfg(g.id)).get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))


async def _metiers_catalogue(g) -> list:
    """Les métiers du catalogue RELL Seas ({cle, nom}) : la banque et les rôles des chefs d'équipe."""
    return [{"cle": e["cle"], "nom": e["nom"]} for e in await metiers.metiers_du_catalogue()]


async def _fiche_recue(i, pid, champs: list, reponses: dict) -> None:
    """26/10/2026 : la FICHE remplie (l'étape obligatoire, AVANT le ticket). Une réponse éliminatoire (une tranche d'âge,
    par exemple) n'ouvre aucun ticket : un avis pour lui seul, le message privé du refus, la liste noire si le panneau
    le règle, la trace « Éliminé d'office » sur le site. Sinon le ticket s'ouvre, comme avec le formulaire d'avant."""
    try:
        await i.response.defer(ephemeral=True)
        elimine = questionnaire.eliminatoire(champs, reponses)
        if elimine is not None:
            await questionnaire.eliminer(i.guild, i.user, pid, *elimine)
            return await i.followup.send(view=_vue_ticket_message(
                await textes.texte(i.guild.id, "recrutement.elimine"), Palette.WARNING), ephemeral=True)
        ch, err = await create_ticket(i, pid, reponses)
        await i.followup.send(view=_vue_ticket_message(err if err else f"✅ Ticket créé : {ch.mention}",
                                                       Palette.WARNING if err else Palette.SUCCESS), ephemeral=True)
    except Exception as ex:
        _logerr("ticket.fiche", ex, guild_id=getattr(i.guild, 'id', 0))
        try:
            await i.followup.send(view=_vue_ticket_message(f"❌ {type(ex).__name__}", Palette.DANGER), ephemeral=True)
        except discord.HTTPException as ex2:
            _logerr("ticket.fiche.reponse", ex2, guild_id=getattr(i.guild, 'id', 0))


async def _peut_decider(i) -> bool:
    """Décider d'une candidature : l'équipe /rellseas, ou la direction et au-dessus."""
    if await _rellseas_autorise(i):
        return True
    return _direction_ou_plus(i.guild, i.user, await cfg(i.guild.id))


async def _action_ticket_fermer(g, auteur, d):
    try:
        ch, tk = await _ticket_ouvert(g, int(d.get("ticket", 0) or 0))
    except discord.HTTPException as ex:
        _logerr("ticket.site_fermer", ex, guild_id=g.id)
        return False, "Discord ne répond pas : réessaie dans un instant."
    if ch is None:
        return False, "Ce ticket n'est plus ouvert."
    motif = str(d.get("motif") or "").strip()[:150] or "Fermé depuis le tableau de bord"
    _fermer_en_fond(_fermer_ticket(g, ch, tk, auteur, motif))
    await log_staff_action(g.id, auteur.id, int(tk['user']), "ticket_ferme", motif, surface="tableau")
    return True, "Ticket fermé : transcript et journal comme d'habitude."


async def _action_candidature(g, auteur, d):
    """19/10/2026 : « ils ne peuvent attribuer de rôle à personne » — l'ancienne action du site refuse ou ferme.
    25/10/2026 : accepter passe par le recrutement en deux étapes (questionnaire.py, `recrutement/decision`) : les
    réponses de l'étape 2 corrigées, puis le circuit de `_decision_recrutement`. Le message le dit (la carte du
    ticket n'a plus de bouton « Accepter »)."""
    if d.get("decision") == "accepter":
        return False, ("Cette action ne donne aucun rôle : accepter passe par l'étape 2 — corrige ses réponses dans "
                       "la rubrique Candidatures du site, puis accepte (rôle du clan, fermeture).")
    return await _decision_recrutement(g, int(d.get("ticket", 0) or 0), auteur, False,
                                       str(d.get("motif") or "").strip())


async def _cible_site(g, auteur, membre_id, c):
    """(membre, None) ou (None, la raison du refus). 19/10/2026 : « si quelqu'un se fait voler son
    compte, il n'a aucune interaction sur nous-mêmes, fondateur ou direction ». Ni les immunisés, ni
    les bots, ni un rôle égal ou supérieur à celui de l'auteur ou du bot. Le staff, oui : « la
    direction et le fondateur appliquent des sanctions directes par le panel en fonction de tout »."""
    cible = g.get_member(int(membre_id or 0))
    if cible is None:
        return None, "Ce membre n'est plus sur le serveur."
    if cible.bot:
        return None, "Un bot ne se gère pas depuis le site."
    if (cible.id == g.owner_id or owner_ids_module.is_super_owner(cible.id) or cible.id in TETE_IDS
            or _direction_ou_plus(g, cible, c)):
        return None, "Le fondateur et la direction sont protégés : aucune action possible depuis le site."
    if await is_fully_immune(cible):
        return None, "Membre immunisé : à voir sur Discord."
    chef = auteur.id == g.owner_id or owner_ids_module.is_super_owner(auteur.id)
    if not chef and cible.top_role >= auteur.top_role:
        return None, "Ce membre a un rôle égal ou supérieur au tien."
    if g.me is None or cible.top_role >= g.me.top_role:
        return None, "Mon rôle est sous le sien : je ne peux rien faire."
    return cible, None


async def _retirer_du_clan(g, auteur, membre_id, c, role):
    """Le seul rôle que le site touche : celui du clan Rell Seas, et seulement pour le retirer."""
    membre, refus = await _cible_site(g, auteur, membre_id, c)
    if membre is None:
        return False, refus
    if role not in membre.roles:
        return False, f"{membre.display_name} n'a pas (ou plus) le rôle du clan."
    if role >= g.me.top_role or not g.me.guild_permissions.manage_roles:
        return False, "Je ne peux pas retirer ce rôle (permission ou hiérarchie)."
    try:
        await membre.remove_roles(role, reason=f"Retiré du clan par {auteur} ({auteur.id}) — tableau de bord")
    except discord.HTTPException as ex:
        _logerr("clan.retirer", ex, guild_id=g.id)
        return False, "Discord a refusé de retirer le rôle (hiérarchie)."
    await _journal_rellseas(g, f"**Retiré du clan** · {membre.mention} par {auteur.mention} (tableau de bord)",
                            membre_id=membre.id, auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, membre.id, "clan_retire", role.name, surface="tableau")
    await clan.clore(g.id, membre.id, "retire", auteur.id)
    return True, f"{membre.display_name} n'a plus le rôle du clan."


async def _action_clan_ajouter(g, auteur, d):
    """« La direction et le fondateur peuvent ajouter le rôle RILSI… » Le seul rôle que le site donne."""
    c = await cfg(g.id)
    role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
    if role is None:
        return False, "Aucun rôle Rell Seas réglé dans /configure."
    membre, refus = await _cible_site(g, auteur, d.get("membre", 0), c)
    if membre is None:
        return False, refus
    if role in membre.roles:
        return False, f"{membre.display_name} est déjà dans le clan."
    if role >= g.me.top_role or not g.me.guild_permissions.manage_roles:
        return False, "Je ne peux pas donner ce rôle (permission ou hiérarchie)."
    try:
        await membre.add_roles(role, reason=f"Ajouté au clan par {auteur} ({auteur.id}) — tableau de bord")
    except discord.HTTPException as ex:
        _logerr("clan.ajouter", ex, guild_id=g.id)
        return False, "Discord a refusé de donner le rôle (hiérarchie)."
    if rellseas_ui._marquer_suivi is not None:
        await rellseas_ui._marquer_suivi(g.id, membre.id)
    await _journal_rellseas(g, f"**Ajouté au clan** · {membre.mention} par {auteur.mention} (tableau de bord)",
                            membre_id=membre.id, auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, membre.id, "clan_ajoute", role.name, surface="tableau")
    return True, f"{membre.display_name} a rejoint le clan."


async def _action_clan_prevenir(g, auteur, d):
    """« Ping dans un salon spécifique… ou un message en privé : attention, vous êtes inactif, vous allez
    être expulsé du clan d'ici une semaine. » Le site rappelle l'échéance et propose le retrait."""
    c = await cfg(g.id)
    role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
    mode = str(d.get("mode") or "")
    ids = list(dict.fromkeys(int(x) for x in (d.get("membres") or []) if str(x).isdigit()))[:clan.MAX_LOT]
    if role is None or mode not in ("mp", "salon") or not ids:
        return False, "Demande invalide."
    salon = None
    if mode == "salon":
        salon = g.get_channel(int(d.get("salon", 0) or 0))
        if not isinstance(salon, discord.TextChannel) or not salon.permissions_for(g.me).send_messages:
            return False, "Je ne peux pas écrire dans ce salon."
    cibles, refus = [], []
    for uid in ids:
        m = g.get_member(uid)
        if m is None or role not in m.roles:
            refus.append(uid)
        elif m.id == g.owner_id or _direction_ou_plus(g, m, c):
            refus.append(uid)
        else:
            cibles.append(m)
    if not cibles:
        return False, "Personne à prévenir : ils ne sont plus dans le clan, ou sont de la direction."
    echeance = int(time.time()) + clan.DELAI
    remis = {}
    if mode == "mp":
        for m in cibles:
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(discord.ui.TextDisplay(clan.texte_mp(g.name, role.name, echeance)),
                                            accent_color=Palette.WARNING))
            try:
                await m.send(view=v)
                remis[m.id] = True
            except discord.HTTPException:
                remis[m.id] = False
            await asyncio.sleep(0.5)
    else:
        for k in range(0, len(cibles), 20):
            lot = cibles[k:k + 20]
            #  24/10/2026 (revue) : une carte V2 (plus un message texte) ; la mention, dans la carte,
            #  ne réveille que ce lot.
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(
                discord.ui.TextDisplay(clan.texte_salon([m.mention for m in lot], role.name, echeance)),
                accent_color=Palette.WARNING))
            await salon.send(view=v, allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=lot))
    await clan.prevenir(g.id, [m.id for m in cibles], auteur.id, mode, salon.id if salon else 0, remis)
    comment = "message privé" if mode == "mp" else f"ping dans #{salon.name}"
    for m in cibles:
        await _au_journal(g, "Clan", "clan.prevenu", f"Prévenu de son inactivité ({comment}) par {auteur.display_name}"
                          + ("" if remis.get(m.id, True) else " — message privé refusé"), membre_id=m.id, auteur_id=auteur.id)
    fermes = sum(1 for v in remis.values() if not v)
    texte = f"{len(cibles)} membre(s) prévenu(s) : retrait proposé le {_heure_courte(echeance)[:5]} s'ils ne reviennent pas."
    if fermes:
        texte += f" {fermes} message(s) privé(s) refusé(s) : préviens-les par un ping dans un salon."
    return True, texte


async def _action_staff_prevenir(g, auteur, d):
    """31/10/2026 : prévenir le staff peu présent, en message privé ou par une mention dans un salon du staff — comme
    pour le clan, sans retrait automatique : la direction décide."""
    c = await cfg(g.id)
    mode = str(d.get("mode") or "")
    ids = list(dict.fromkeys(int(x) for x in (d.get("membres") or []) if str(x).isdigit()))[:clan.MAX_LOT]
    if mode not in ("mp", "salon") or not ids:
        return False, "Demande invalide."
    salon = None
    if mode == "salon":
        salon = g.get_channel(int(d.get("salon", 0) or 0))
        if not isinstance(salon, discord.TextChannel) or not salon.permissions_for(g.me).send_messages:
            return False, "Je ne peux pas écrire dans ce salon."
    cibles = []
    for uid in ids:
        m = g.get_member(uid)
        if m is not None and _est_du_staff(g, m, c) and m.id != g.owner_id and not _direction_ou_plus(g, m, c):
            cibles.append(m)
    if not cibles:
        return False, "Personne à prévenir : ils ne sont plus dans le staff, ou sont de la direction."
    echeance = int(time.time()) + clan.DELAI
    remis = {}
    if mode == "mp":
        for m in cibles:
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(discord.ui.TextDisplay(clan.texte_mp_staff(g.name, echeance)),
                                            accent_color=Palette.WARNING))
            try:
                await m.send(view=v)
                remis[m.id] = True
            except discord.HTTPException:
                remis[m.id] = False
            await asyncio.sleep(0.5)
    else:
        for k in range(0, len(cibles), 20):
            lot = cibles[k:k + 20]
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(discord.ui.TextDisplay(clan.texte_salon_staff([m.mention for m in lot], echeance)),
                                            accent_color=Palette.WARNING))
            await salon.send(view=v, allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=lot))
    await clan.prevenir(g.id, [m.id for m in cibles], auteur.id, mode, salon.id if salon else 0, remis, groupe="staff")
    comment = "message privé" if mode == "mp" else f"ping dans #{salon.name}"
    for m in cibles:
        await _au_journal(g, "Staff", "staff.prevenu", f"Staff prévenu de son inactivité ({comment}) par {auteur.display_name}"
                          + ("" if remis.get(m.id, True) else " — message privé refusé"), membre_id=m.id, auteur_id=auteur.id)
    fermes = sum(1 for v in remis.values() if not v)
    texte = f"{len(cibles)} membre(s) du staff prévenu(s) : point proposé le {_heure_courte(echeance)[:5]} sans activité."
    if fermes:
        texte += f" {fermes} message(s) privé(s) refusé(s) : préviens-les par une mention dans un salon."
    return True, texte


