async def _action_clan_retirer(g, auteur, d):
    c = await cfg(g.id)
    role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
    if role is None:
        return False, "Aucun rôle Rell Seas réglé dans /configure."
    return await _retirer_du_clan(g, auteur, d.get("membre", 0), c, role)


async def _action_clan_retirer_lot(g, auteur, d):
    """« Une réelle interaction avec ceux qui sont inactifs » : le rôle du clan retiré à une
    sélection (25 au plus d'un coup), chacun vérifié comme s'il était seul."""
    c = await cfg(g.id)
    role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
    ids = [int(x) for x in (d.get("membres") or []) if str(x).isdigit()][:25]
    if role is None or not ids:
        return False, "Rien à retirer."
    faits, refus = 0, []
    for uid in ids:
        ok, message = await _retirer_du_clan(g, auteur, uid, c, role)
        if ok:
            faits += 1
        else:
            refus.append(message)
        await asyncio.sleep(0.4)
    return faits > 0, (f"{faits} membre(s) retiré(s) du clan." + (f" {len(refus)} refus : {refus[0]}" if refus else ""))


_SANCTIONS_SITE = {"warn": "Avertissement", "mute": "Mute", "unmute": "Fin du mute", "kick": "Expulsion",
                   "ban": "Bannissement"}
_DUREES_MUTE = {10: "10 minutes", 60: "1 heure", 360: "6 heures", 1440: "1 jour", 10080: "7 jours"}


async def _inscrire_sanction(g, membre_id, mod_id, typ, raison, duree=""):
    async with get_db() as db:
        cur = await db.execute(
            "INSERT INTO infractions(guild_id, user_id, mod_id, type, reason, duration) VALUES(?,?,?,?,?,?)",
            (g.id, int(membre_id), int(mod_id), typ, str(raison)[:300], str(duree)[:30]))
        await db.commit()
        return cur.lastrowid


async def _action_moderer(g, auteur, d):
    """« Un vrai système de modération intégré » : avertir, muter, lever un mute, expulser,
    bannir — depuis la fiche d'un membre, avec le même circuit que les commandes (fiche, MP au
    membre au nom du serveur, escalade, journal). Fondateur et direction seulement."""
    c = await cfg(g.id)
    sanction = str(d.get("sanction") or "")
    if sanction not in _SANCTIONS_SITE:
        return False, "Sanction inconnue."
    raison = str(d.get("motif") or "").strip()[:300]
    if sanction != "unmute" and len(raison) < 3:
        return False, "Indique un motif (3 caractères au moins)."
    cible, refus = await _cible_site(g, auteur, d.get("membre", 0), c)
    if cible is None:
        return False, refus
    perms = g.me.guild_permissions
    trace = f"{raison or 'Sans motif'} — {auteur} ({auteur.id}) via le tableau de bord"[:500]
    message = ""
    if sanction == "warn":
        iid = await _inscrire_sanction(g, cible.id, auteur.id, "warn", raison)
        async with get_db() as db:
            async with db.execute("SELECT COUNT(*) FROM infractions WHERE guild_id=? AND user_id=? AND type='warn'",
                                  (g.id, cible.id)) as cur:
                total = (await cur.fetchone())[0]
        await _dm_sanction(cible, g, "Avertissement ⚠️", raison)
        auto = await _escalade_warns(g, cible, total)
        await send_mod_log(g, "warn", auteur, cible, raison,
                           extra=f"Fiche {_format_warn_id(iid)} · Total warns: {total} · tableau de bord")
        if total in (3, 5, 10):
            try:
                await ulogger2026.log_member_escalation(
                    bot, g, cible, total, total, reason=raison, moderator=auteur,
                    severity="moyenne" if total == 3 else ("haute" if total == 5 else "critique"))
            except Exception as ex:
                _logerr("site.escalade", ex, guild_id=g.id)
        message = f"Avertissement enregistré ({total} au total)." + (" " + registre.propre(auto) if auto else "")
    elif sanction == "mute":
        try:
            minutes = int(d.get("duree") or 60)
        except (TypeError, ValueError):
            minutes = 0
        if minutes not in _DUREES_MUTE:
            return False, "Durée invalide."
        if not perms.moderate_members:
            return False, "Il me manque la permission « Exclure temporairement des membres »."
        await _dm_sanction(cible, g, f"Mute ({_DUREES_MUTE[minutes]})", raison, _DUREES_MUTE[minutes])
        await cible.timeout(timedelta(minutes=minutes), reason=trace)
        await _inscrire_sanction(g, cible.id, auteur.id, "mute", raison, _DUREES_MUTE[minutes])
        await send_mod_log(g, "mute", auteur, cible, raison, _DUREES_MUTE[minutes])
        message = f"{cible.display_name} est muté {_DUREES_MUTE[minutes]}."
    elif sanction == "unmute":
        if not cible.is_timed_out():
            return False, "Ce membre n'est pas muté."
        await cible.timeout(None, reason=trace)
        await send_mod_log(g, "unmute", auteur, cible, raison or "Levé depuis le tableau de bord")
        message = f"Le mute de {cible.display_name} est levé."
    elif sanction == "kick":
        if not perms.kick_members:
            return False, "Il me manque la permission « Expulser des membres »."
        await _dm_sanction(cible, g, "Expulsion", raison)
        await cible.kick(reason=trace)
        await _inscrire_sanction(g, cible.id, auteur.id, "kick", raison)
        await send_mod_log(g, "kick", auteur, cible, raison)
        message = f"{cible.display_name} est expulsé."
    else:
        if not perms.ban_members:
            return False, "Il me manque la permission « Bannir des membres »."
        await _dm_sanction(cible, g, "Bannissement", raison)
        await g.ban(cible, reason=trace, delete_message_seconds=0)
        await _inscrire_sanction(g, cible.id, auteur.id, "ban", raison)
        await send_mod_log(g, "ban", auteur, cible, raison)
        message = f"{cible.display_name} est banni."
    await log_staff_action(g.id, auteur.id, cible.id, f"site_{sanction}", raison[:200], surface="tableau")
    return True, message


async def _action_question(g, auteur, d):
    statut = str(d.get("statut") or "")
    if statut not in ("traitee", "ignoree", "ouverte"):
        return False, "Statut inconnu."
    if not await questions.marquer(g.id, int(d.get("question", 0) or 0), statut, auteur.id):
        return False, "Question introuvable."
    #  24/10/2026 : le libellé du statut donnait « Question sans réponse par X » pour une réouverture
    #  et « Question pas une question par X ».
    geste = {"traitee": "marquée traitée", "ignoree": "retirée (pas une question)", "ouverte": "rouverte"}[statut]
    await _au_journal(g, "Questions", "question." + statut, f"Question {geste} par {auteur.display_name}",
                      auteur_id=auteur.id)
    return True, {"traitee": "Question marquée traitée.", "ignoree": "Retirée : ce n'était pas une question.",
                  "ouverte": "Question rouverte."}[statut]


async def _action_alerte_geree(g, auteur, d):
    membre_id = int(d.get("membre", 0) or 0)
    if not membre_id:
        return False, "Alerte inconnue."
    ouverte = await vigilance.gerer(g.id, membre_id, auteur.id)
    if ouverte:
        salon = g.get_channel(ouverte[0])
        if salon is not None:
            try:
                await salon.get_partial_message(ouverte[1]).delete()
            except discord.HTTPException as ex:
                if not isinstance(ex, discord.NotFound):
                    _logerr("alerte.geree", ex, guild_id=g.id)
    await _au_journal(g, "Sécurité", "alerte.geree", f"Alerte gérée par {auteur.display_name}",
                      membre_id=membre_id, auteur_id=auteur.id)
    return True, "Alerte gérée : elle disparaît du salon des logs."


async def _action_fiche_retirer(g, auteur, d):
    cid = int(d.get("candidat", 0) or 0)
    n = await recrutements.retirer_fiche(g.id, cid)
    if not n:
        return False, "Fiche déjà retirée."
    await _journal_rellseas(g, f"**Fiche de candidature retirée** · <@{cid}> par {auteur.mention} (tableau de bord)",
                            membre_id=cid, auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, cid, "fiche_retiree", f"{n} ligne(s)", surface="tableau")
    return True, "Fiche retirée."


async def _apres_casier(g, membres, *, lever_mute: bool = False, motif: str = "Casier effacé (tableau de bord)"):
    """« Que quand on enlève les infractions, ça s'enlève bien aussi sur le serveur Discord » :
    compteurs du filtre remis à zéro, rôle de récidive recalculé (retiré s'il n'a plus lieu d'être),
    mute en cours levé si demandé."""
    for uid in membres:
        try:
            async with get_db() as db:
                await db.execute("DELETE FROM badword_strikes WHERE guild_id=? AND user_id=?", (g.id, int(uid)))
                await db.execute("DELETE FROM user_toxicity_scores WHERE guild_id=? AND user_id=?", (g.id, int(uid)))
                await db.commit()
            m = g.get_member(int(uid))
            if m is not None:
                await recidivism_module.recompute(g, m)
                if lever_mute and m.is_timed_out():
                    await m.timeout(None, reason=motif)
        except (discord.HTTPException, aiosqlite.Error) as ex:
            _logerr("casier.discord", ex, guild_id=g.id)
        await asyncio.sleep(0.2)


async def _action_sanction_retirer(g, auteur, d):
    sid = int(d.get("sanction", 0) or 0)
    async with get_db() as db:
        async with db.execute("SELECT user_id, type, reason FROM infractions WHERE id=? AND guild_id=?",
                              (sid, g.id)) as cur:
            r = await cur.fetchone()
        if not r:
            return False, "Sanction déjà retirée."
        dernier_mute = False
        if str(r[1]).lower() == "mute":
            async with db.execute("SELECT MAX(id) FROM infractions WHERE guild_id=? AND user_id=? AND type='mute'",
                                  (g.id, r[0])) as cur:
                dernier_mute = (await cur.fetchone())[0] == sid
        await db.execute("DELETE FROM infractions WHERE id=? AND guild_id=?", (sid, g.id))
        await db.commit()
    await _apres_casier(g, [int(r[0] or 0)], lever_mute=dernier_mute, motif="Mute retiré du casier (tableau de bord)")
    await log_staff_action(g.id, auteur.id, int(r[0] or 0), "sanction_retiree",
                           f"{r[1]} — {str(r[2] or '')[:120]}", surface="tableau")
    await _au_journal(g, "Modération", "mod.sanction_retiree",
                      f"Sanction retirée du casier · {tableau._libelle(str(r[1]))} · par {auteur.display_name}"
                      " (tableau de bord)", membre_id=int(r[0] or 0), auteur_id=auteur.id, detail=str(r[2] or ''))
    c = await cfg(g.id)
    logs = None if c.get('logs_sur_site_v1') else g.get_channel(int(c.get('mod_log_channel', 0) or 0))
    if logs is not None:
        try:
            await logs.send(f"**Sanction retirée du casier** · <@{r[0]}> · {r[1]} par {auteur.mention} "
                            f"(tableau de bord)", allowed_mentions=discord.AllowedMentions.none())
        except discord.HTTPException as ex:
            _logerr("sanction.retirer", ex, guild_id=g.id)
    return True, "Sanction retirée du casier."


async def _action_casier_effacer(g, auteur, d):
    """« Enlever tous les avertissements de quelqu'un d'un seul coup » — ou tout son casier."""
    quoi = str(d.get("quoi") or "")
    uid = int(d.get("membre", 0) or 0)
    if quoi not in ("warns", "tout") or not uid:
        return False, "Demande invalide."
    if uid == g.owner_id:
        return False, "Le fondateur n'a pas de casier à effacer."
    bilan = await casier.effacer_membre(g.id, uid, quoi, auteur.id)
    if not bilan["n"]:
        return False, "Rien à effacer."
    await _apres_casier(g, [uid], lever_mute=quoi == "tout")
    quoi_txt = "avertissement(s)" if quoi == "warns" else "entrée(s) du casier"
    await _au_journal(g, "Modération", "mod.casier_efface",
                      f"{bilan['n']} {quoi_txt} effacé(s) par {auteur.display_name} (tableau de bord, annulable 30 jours)",
                      membre_id=uid, auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, uid, "casier_efface", f"{quoi} · {bilan['n']}", surface="tableau")
    return True, f"{bilan['n']} {quoi_txt} effacé(s). Annulable pendant 30 jours."


async def _action_casier_serveur(g, auteur, d):
    """« Nettoyer tous les avertissements du serveur d'un seul coup… repartir de zéro… nettoyer
    une zone. » Confirmation écrite, bannissements jamais touchés, annulable pendant 30 jours."""
    portee = str(d.get("portee") or "")
    try:
        jours = int(d.get("jours") or 0)
    except (TypeError, ValueError):
        jours = -1
    if portee not in casier.PORTEES or jours not in casier.AGES:
        return False, "Demande invalide."
    if str(d.get("confirmation") or "").strip().upper() != "EFFACER":
        return False, "Écris EFFACER pour confirmer."
    bilan = await casier.nettoyer(g.id, portee, jours, auteur.id, bot.user.id)
    if not bilan["n"]:
        return False, "Rien à effacer dans cette zone."
    asyncio.create_task(_apres_casier(g, bilan["membres"]))
    await _au_journal(g, "Modération", "mod.casier_serveur",
                      f"Casier du serveur nettoyé par {auteur.display_name} : {bilan['quoi']} — {bilan['n']} entrée(s), "
                      f"{len(bilan['membres'])} personne(s). Annulable 30 jours.", auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, 0, "casier_serveur", f"{portee} · {jours} j · {bilan['n']}", surface="tableau")
    return True, f"{bilan['n']} entrée(s) effacée(s) pour {len(bilan['membres'])} personne(s). Annulable pendant 30 jours."


async def _action_casier_restaurer(g, auteur, d):
    lot = str(d.get("lot") or "")[:80]
    bilan = await casier.restaurer(g.id, lot, auteur.id)
    if not bilan["n"]:
        return False, "Ce nettoyage est déjà annulé, ou trop ancien."
    asyncio.create_task(_apres_casier(g, bilan["membres"]))
    await _au_journal(g, "Modération", "mod.casier_restaure",
                      f"Nettoyage du casier annulé par {auteur.display_name} : {bilan['n']} entrée(s) remise(s)",
                      auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, 0, "casier_restaure", f"{lot} · {bilan['n']}", surface="tableau")
    return True, f"{bilan['n']} entrée(s) remise(s) au casier."


async def _action_debannir(g, auteur, d):
    uid = int(d.get("membre", 0) or 0)
    if not uid or g.get_member(uid) is not None:
        return False, "Ce membre n'est pas banni."
    if not g.me.guild_permissions.ban_members:
        return False, "Il me manque la permission « Bannir des membres »."
    try:
        await g.unban(discord.Object(id=uid), reason=f"Débanni par {auteur} ({auteur.id}) — tableau de bord")
    except discord.NotFound:
        return False, "Ce membre n'est pas banni."
    await _au_journal(g, "Modération", "mod.unban", f"Bannissement levé par {auteur.display_name} (tableau de bord)",
                      membre_id=uid, auteur_id=auteur.id)
    await log_staff_action(g.id, auteur.id, uid, "site_unban", "", surface="tableau")
    return True, "Bannissement levé : il peut revenir sur le serveur."


async def _dates_de_depart(guild_id: int) -> dict:
    """Le jour de départ connu de chaque membre parti (journal des arrivées et départs)."""
    out = {}
    try:
        async with get_db() as db:
            async with db.execute("SELECT user_id, left_day FROM daily_join_log WHERE guild_id=? AND left_day IS NOT NULL",
                                  (guild_id,)) as cur:
                for uid, jour in await cur.fetchall():
                    try:
                        out[int(uid)] = datetime.strptime(str(jour)[:10], "%Y-%m-%d").replace(tzinfo=timezone.utc).timestamp()
                    except ValueError:
                        continue
    except aiosqlite.Error as ex:
        _logerr("amnistie.departs", ex, guild_id=guild_id)
    return out


@tasks.loop(hours=6)
async def amnistie_task():
    """« Si quelqu'un n'a pas commis d'infraction depuis plus de 3 mois non-stop, tu enlèves toutes
    les infractions… sauf s'il a vraiment été très agressif… et les avertissements des joueurs partis
    depuis plus de 3 mois. » Une fois par jour et par serveur, seulement quand la liste des membres
    est complète (sinon un présent passerait pour parti)."""
    for g in list(bot.guilds):
        try:
            c = await cfg(g.id)
            if not g.chunked or time.time() - float(c.get('amnistie_derniere', 0) or 0) < 86400 - 900:
                continue
            bilan = await casier.amnistie(g.id, {m.id for m in g.members}, await _dates_de_depart(g.id))
            await db_set(g.id, 'amnistie_derniere', int(time.time()))
            if bilan["membres"]:
                await _apres_casier(g, bilan["membres"], motif="Amnistie : 3 mois sans infraction")
                await _au_journal(g, "Modération", "mod.amnistie",
                                  f"Amnistie : {bilan['n']} entrée(s) retirée(s) du casier de {len(bilan['membres'])} "
                                  "personne(s) — 3 mois sans infraction, ou partie depuis 3 mois. Annulable 30 jours.")
            print(f"[AMNISTIE] {g.id} · {len(bilan['membres'])} casier(s) · {bilan['n']} entrée(s) · "
                  f"{len(bilan['gardes'])} gardé(s)")
        except Exception as ex:  # un serveur en échec n'arrête pas les autres ; réessai au tour suivant
            _logerr("amnistie", ex, guild_id=getattr(g, 'id', 0))


@amnistie_task.before_loop
async def _amnistie_attente():
    await bot.wait_until_ready()
    await asyncio.sleep(1800)


