def _heure_courte(t) -> str:
    d = datetime.fromtimestamp(int(t), timezone.utc)
    if ZoneInfo is not None:
        d = d.astimezone(ZoneInfo(_TICKET_TZ))
    return d.strftime('%d/%m %H:%M')


def _carte_vigilance(g, membre_id, incidents, points, evenements):
    """Le panneau d'UN joueur dans 📋logs (31/10/2026) : ce qu'il a fait, ligne par ligne, où il en est, et la décision."""
    m = g.get_member(int(membre_id))
    nom = m.display_name if m else f"Membre {membre_id}"
    lignes = "\n".join(f"- `{_heure_courte(e['quand'])}` · {str(e['texte'])[:180]}" for e in evenements[-10:])
    fin_mute = getattr(m, "timed_out_until", None) if m else None
    attente = bool(fin_mute and fin_mute > now() + timedelta(days=7))
    if attente:
        etat = "⛔ **Muet jusqu'à votre décision.** Que fait-on de lui ?"
    elif fin_mute and fin_mute > now():
        etat = f"🔇 Muet jusqu'à <t:{int(fin_mute.timestamp())}:t>."
    else:
        etat = "Pas de sanction en cours."
    v = LayoutView(timeout=None)
    v.add_item(discord.ui.Container(
        discord.ui.TextDisplay(f"### 🚨 {nom} — {'décision requise' if attente else 'à surveiller'}\n<@{int(membre_id)}> · "
                               f"{incidents} infraction(s) en 24 h\n{etat}"),
        discord.ui.TextDisplay("**Ce qu'il a fait**\n" + (lignes or "-")),
        discord.ui.ActionRow(BoutonDecision("warn", int(membre_id)), BoutonDecision("mute7", int(membre_id)),
                             BoutonDecision("kick", int(membre_id)), BoutonDecision("ban", int(membre_id)),
                             BoutonDecision("unmute", int(membre_id))),
        discord.ui.ActionRow(BoutonFicheSite(int(membre_id)), BoutonGere(int(membre_id))),
        discord.ui.TextDisplay("-# Une décision ferme le panneau. « Géré » le retire sans rien faire."),
        accent_color=Palette.DANGER))
    return v


_DECISIONS = {"warn": ("Avertir", "warn", discord.ButtonStyle.secondary),
              "mute7": ("Mute 7 jours", "mute", discord.ButtonStyle.primary),
              "kick": ("Expulser", "kick", discord.ButtonStyle.danger),
              "ban": ("Bannir", "ban", discord.ButtonStyle.danger),
              "unmute": ("Lever le mute", "unmute", discord.ButtonStyle.success)}


async def _decider(i, cle: str, membre_id: int, motif: str, panneau=None) -> None:
    """La décision prise depuis le panneau : le même circuit que le site (vérifications, fiche, MP, journal)."""
    libelle, sanction_, _style = _DECISIONS[cle]
    ok, message = await _action_moderer(i.guild, i.user, {"sanction": sanction_, "membre": membre_id, "motif": motif,
                                                         "duree": 10080})
    if ok:
        await vigilance.gerer(i.guild.id, membre_id, i.user.id)
        try:
            if panneau is not None:
                await panneau.delete()
        except discord.HTTPException:
            pass
        await _au_journal(i.guild, "Modération", "alerte.decision", f"Décision « {libelle} » prise par {i.user.display_name}",
                          membre_id=membre_id, auteur_id=i.user.id, detail=motif[:300])
    await i.followup.send(message, ephemeral=True)


class _MotifDecision(discord.ui.Modal):
    def __init__(self, cle: str, membre_id: int, message):
        super().__init__(title=_DECISIONS[cle][0][:45])
        self.cle, self.membre_id, self.message = cle, membre_id, message
        self.motif = discord.ui.TextInput(label="Motif (envoyé au membre)", max_length=300, min_length=3,
                                          default="Infractions répétées sur le serveur (décision de la direction)")
        self.add_item(self.motif)

    async def on_submit(self, i: discord.Interaction):
        await i.response.defer(ephemeral=True)
        await _decider(i, self.cle, self.membre_id, str(self.motif.value).strip(), self.message)


class BoutonDecision(discord.ui.DynamicItem[Button], template=r"alerte:dec:(?P<a>warn|mute7|kick|ban|unmute):(?P<m>\d+)"):
    """« Est-ce qu'on le warn ? On le mute encore plus ? On le kick ? On le banne ? » — fondateur et direction."""

    def __init__(self, cle: str = "warn", membre_id: int = 0):
        self.cle, self.membre_id = cle, int(membre_id)
        libelle, _s, style = _DECISIONS[cle]
        super().__init__(Button(label=libelle, style=style, custom_id=f"alerte:dec:{cle}:{self.membre_id}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["a"], int(match["m"]))

    async def callback(self, i: discord.Interaction):
        if not _direction_ou_plus(i.guild, i.user, await cfg(i.guild.id)):
            return await i.response.send_message("Réservé au fondateur et à la direction.", ephemeral=True)
        if self.cle == "unmute":
            await i.response.defer(ephemeral=True)
            return await _decider(i, "unmute", self.membre_id, "Mute levé par la direction", i.message)
        await i.response.send_modal(_MotifDecision(self.cle, self.membre_id, i.message))


_BOTS_REFUSES: dict = {}  # {bot_id: instant} — expulsés par l'anti-bot-voyou, approuvables depuis l'alerte


def _vue_alerte(membre_id: int = 0):
    """Sous chaque alerte du salon des logs : la fiche sur le site, et « Géré » — plus « Approuver ce
    bot » sous l'alerte d'un bot que l'anti-bot-voyou vient d'arrêter."""
    v = discord.ui.View(timeout=None)
    if membre_id and int(membre_id) in _BOTS_REFUSES:
        v.add_item(BoutonApprouverBot(int(membre_id)))
    elif membre_id:
        v.add_item(BoutonFicheSite(int(membre_id)))
    v.add_item(BoutonGere(int(membre_id or 0)))
    return v


async def _carte_alerte_decidee(message, ligne: str) -> None:
    """Après « Approuver ce bot » : la carte d'alerte garde son texte, la décision s'y inscrit au-dessus
    des boutons, « Approuver » s'éteint (« Géré » reste, pour retirer l'alerte). 24/10/2026 (revue) : la
    carte V2 était remplacée par une vue classique et tout le texte de l'alerte disparaissait. Une
    alerte en ancien format (embed) garde son embed et perd seulement ses boutons."""
    if message.embeds:
        await message.edit(view=None)
        return
    v = LayoutView.from_message(message, timeout=None)
    for bloc_ in v.children:
        if isinstance(bloc_, discord.ui.Container):
            for x in list(bloc_.walk_children()):
                if isinstance(x, discord.ui.Button) and str(x.custom_id or "").startswith("alerte:botok:"):
                    x.disabled = True
            enfants = list(bloc_.children)
            place = next((k for k, x in enumerate(enfants) if isinstance(x, discord.ui.ActionRow)), len(enfants))
            bloc_.clear_items()
            for x in enfants[:place] + [discord.ui.TextDisplay(ligne)] + enfants[place:]:
                bloc_.add_item(x)
    await message.edit(view=v, allowed_mentions=discord.AllowedMentions.none())


class BoutonApprouverBot(discord.ui.DynamicItem[Button], template=r"alerte:botok:(?P<b>\d+)"):
    """20/10/2026 : l'alerte disait « ajoute son ID à `approved_bots` (/configure) », réglage que rien
    n'écrivait — un bot voulu ne pouvait jamais entrer. Réservé à la tête : un compte de staff volé ne
    doit pas pouvoir faire entrer un bot de nuke."""

    def __init__(self, bot_id: int):
        self.bot_id = int(bot_id)
        super().__init__(Button(label="Approuver ce bot", style=discord.ButtonStyle.primary,
                                emoji=visuels.icone("valider"), custom_id=f"alerte:botok:{self.bot_id}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["b"]))

    async def callback(self, i: discord.Interaction):
        if not _a_la_tete(i.guild, i.user):
            return await i.response.send_message("Réservé au fondateur et à la direction.", ephemeral=True)
        await i.response.defer(ephemeral=True)
        c = await cfg(i.guild.id)
        approuves = [int(x) for x in (c.get('approved_bots') or []) if str(x).isdigit()]
        if self.bot_id not in approuves and not await db_set(i.guild.id, 'approved_bots', approuves + [self.bot_id]):
            return await i.followup.send("❌ L'approbation n'a pas pu être enregistrée. Réessaie.", ephemeral=True)
        _BOTS_REFUSES.pop(self.bot_id, None)
        await _au_journal(i.guild, "Sécurité", "bot.approuve", f"Bot {self.bot_id} approuvé par {i.user.display_name}",
                          membre_id=self.bot_id, auteur_id=i.user.id)
        try:  # la carte garde son texte ; la décision s'y inscrit et « Approuver » s'éteint
            await _carte_alerte_decidee(i.message, f"✅ **Bot approuvé** par {i.user.mention} · "
                                                   f"<t:{int(time.time())}:R> — il ne sera plus expulsé.")
        except discord.HTTPException as ex:
            _logerr("alerte.bot_approuve", ex, guild_id=i.guild.id)
        await i.followup.send("✅ Bot approuvé : il ne sera plus expulsé. S'il l'a été, ré-ajoute-le.",
                              ephemeral=True)


async def _alerte_securite_site(g, membre, raison: str, suspendu: bool = True):
    """Trop d'actions graves depuis le site : le signe d'un compte volé. Le fondateur est prévenu —
    sauf de ses propres actions. La tête n'est jamais suspendue, seulement signalée.
    24/10/2026 : la mention partait en `content=` à côté de la carte V2 — refusé (400) par Discord,
    l'alerte ne partait jamais. Elle est DANS la carte ; seul le fondateur est pingé."""
    salon = await _salon_alertes_site(g)
    if salon is None or membre.id == g.owner_id or owner_ids_module.is_super_owner(membre.id):
        return
    proprio = g.owner_id
    titre = "🔒 Accès au site suspendu une heure" if suspendu else "⚠️ Beaucoup d'actions graves depuis le site"
    v = LayoutView(timeout=None)
    v.add_item(discord.ui.Container(
        discord.ui.TextDisplay(f"### {titre}\n{membre.mention} — {raison}.\n<@{proprio}>, si ce n'est pas "
                               "lui, son compte est peut-être volé : vérifie avec lui avant tout."),
        discord.ui.ActionRow(BoutonGere(0)), accent_color=Palette.DANGER))
    await salon.send(view=v, allowed_mentions=discord.AllowedMentions(everyone=False, roles=False,
                                                                     users=[discord.Object(id=proprio)]))


async def _alerte_forte_site(g, titre: str, texte: str) -> bool:
    """26/10/2026 (sécurité) — les SEULES alertes de sécurité du site (décisions du fondateur : « aucune fausse alerte ») :
    un signal FORT (une action privilégiée du site qui aboutit hors de la tête ; une permission dangereuse donnée hors de
    la tête, lue dans le journal d'audit), déjà regroupé par `securite_site`. Une carte dans « 📋logs », le fondateur
    mentionné DANS la carte (V2 : jamais de `content=`), personne d'autre pingé. Rien n'est retiré ni bloqué. Rend True si
    la carte est partie."""
    salon = await _salon_alertes_site(g)
    if salon is None:
        return False
    v = LayoutView(timeout=None)
    v.add_item(discord.ui.Container(
        discord.ui.TextDisplay(f"### 🛡️ {titre}\n{texte[:3500]}\n-# Rien n'a été retiré ni bloqué. Le détail : site → "
                               f"Le Port → Sécurité.\n<@{SUPER_OWNER_ID}>"),
        accent_color=Palette.DANGER))
    await salon.send(view=v, allowed_mentions=discord.AllowedMentions(everyone=False, roles=False,
                                                                     users=[discord.Object(id=SUPER_OWNER_ID)]))
    return True


class BoutonGere(discord.ui.DynamicItem[Button], template=r"alerte:gere:(?P<m>\d+)"):
    """« Et après, ça s'enlève une fois qu'on a géré. »"""

    def __init__(self, membre_id: int = 0):
        self.membre_id = int(membre_id)
        super().__init__(Button(label="Géré", style=discord.ButtonStyle.success, emoji=visuels.icone("valider"),
                                custom_id=f"alerte:gere:{self.membre_id}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["m"]))

    async def callback(self, i: discord.Interaction):
        if not _direction_ou_plus(i.guild, i.user, await cfg(i.guild.id)):
            return await i.response.send_message("Réservé au fondateur et à la direction.", ephemeral=True)
        await i.response.defer(ephemeral=True)
        if self.membre_id:
            await vigilance.gerer(i.guild.id, self.membre_id, i.user.id)
        try:
            await i.message.delete()
        except discord.HTTPException as ex:
            if not isinstance(ex, discord.NotFound):
                _logerr("alerte.gere", ex, guild_id=i.guild.id)
        await _au_journal(i.guild, "Sécurité", "alerte.geree", f"Alerte gérée par {i.user.display_name}",
                          membre_id=self.membre_id, auteur_id=i.user.id)
        await i.followup.send("Alerte retirée.", ephemeral=True)


