class TicketPriorityView(LayoutView):
    """Vue éphémère (timeout 60s, Components V2) : un select des 4 niveaux de priorité.
    Ouverte par le bouton 🚩 Priorité de TicketControlView."""
    def __init__(self, chid):
        super().__init__(timeout=60)
        self.add_item(discord.ui.Container(
            discord.ui.TextDisplay("### 🚩 La priorité du ticket\nElle s'affiche devant le nom du ticket."),
            discord.ui.ActionRow(TicketPrioritySelect(chid)), accent_color=Palette.WARNING))


class TicketPrioritySelect(Select):
    def __init__(self, chid):
        # Construit les options depuis PRIORITY_LEVELS pour rester cohérent avec
        # la slash command /ticket priority (même libellés, mêmes emojis).
        opts = []
        try:
            for val, (emoji, label) in tix_module.PRIORITY_LEVELS.items():
                opts.append(discord.SelectOption(label=label.capitalize(), value=val, emoji=emoji))
        except Exception:
            # Fallback défensif si le module n'est pas chargé (ne casse jamais l'UI).
            opts = [
                discord.SelectOption(label="Urgent", value="urgent", emoji='🔴'),
                discord.SelectOption(label="Haute", value="high", emoji='🟠'),
                discord.SelectOption(label="Normale", value="normal", emoji='🟡'),
                discord.SelectOption(label="Basse", value="low", emoji='🔵'),
            ]
        super().__init__(placeholder="Choisir le niveau de priorité…", options=opts, min_values=1, max_values=1)
        self.chid = chid

    async def callback(self, i):
        try:
            await i.response.defer(ephemeral=True)  # defer-first : anti « Échec interaction »
            level = self.values[0]
            ch = i.guild.get_channel_or_thread(self.chid)
            if not ch:
                return await i.followup.send("❌ Salon introuvable", ephemeral=True)
            # Backend partagé : persiste la priorité + renomme le salon (préfixe emoji).
            await tix_module.set_priority(self.chid, level)
            await tix_module.update_channel_name_for_priority(ch, level)
            emoji, label = tix_module.PRIORITY_LEVELS.get(level, ("⚪", level.upper()))
            await i.followup.send(view=_vue_ticket_message(f"✅ Priorité réglée : {emoji} **{label}**"), ephemeral=True)
            # Trace visible dans le salon (entre au transcript) + log staff.
            try:
                await webhook_send(ch, 'ticket', view=_carte_ticket(
                    "🚩 Priorité", f"Passée à {emoji} **{label}** par {i.user.mention}.", Palette.WARNING),
                    allowed_mentions=discord.AllowedMentions.none())
            except discord.HTTPException as ex:
                _logerr("ticket.priorite.annonce", ex, guild_id=i.guild.id)
            tk = await get_ticket(self.chid)
            if tk:
                await send_ticket_log(i.guild, 'priority', tk['user'], tk, extra=(i.user.id, f"{emoji} {label}"))
        except Exception as _tk_ex:
            print(f"[ticket_priority_select] {type(_tk_ex).__name__}: {_tk_ex}")
            try:
                await i.followup.send(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
            except Exception:
                pass


# ═══════════════════════════════════════════════════════════════════════════════
#       📌 NOTE INTERNE STAFF (passage de relais) — au suivi du ticket, jamais dans le ticket
# ═══════════════════════════════════════════════════════════════════════════════

NOTE_MAX = 300  # ce que garde le suivi du ticket (`ticket_log_events`) et l'historique « Gérer »


class TicketNoteModal(Modal):
    """Note interne staff : passage de relais entre staff. 24/10/2026 (revue) : elle était postée DANS le
    ticket — le membre la lisait, et elle partait dans le transcript qu'il reçoit. Elle va maintenant au
    suivi du ticket (le site, l'historique du bouton « Gérer ») ; le staff reçoit une confirmation à lui seul.
    Jamais de fermeture, jamais d'action destructrice."""
    def __init__(self, tk):
        super().__init__(title="Note interne (staff)")
        self.tk = tk
        self.note = TextInput(
            label="Note (le membre ne la voit pas)",
            placeholder="Va au suivi : bouton « Gérer » et site. Ex. en attente d'une preuve…",
            style=discord.TextStyle.paragraph, required=True, max_length=NOTE_MAX)
        self.add_item(self.note)

    async def on_submit(self, i):
        try:
            await i.response.defer(ephemeral=True)  # defer-first
        except discord.HTTPException as ex:
            return _logerr("ticket.note.defer", ex, guild_id=getattr(i.guild, 'id', 0))
        txt = (self.note.value or '').strip()[:NOTE_MAX]
        if not txt:
            try:
                await i.followup.send("❌ Note vide.", ephemeral=True)
            except discord.HTTPException as ex:
                _logerr("ticket.note.reponse", ex, guild_id=i.guild.id)
            return
        ch_id = getattr(i.channel, 'id', 0) or 0
        try:
            # Le suivi du ticket (site, transcript du staff) et l'historique du bouton « Gérer ».
            await send_ticket_log(i.guild, 'note', self.tk['user'], self.tk, extra=(i.user.id, txt))
            await tix_module.log_action(i.guild.id, ch_id, i.user.id, "note", txt)
            await i.followup.send(view=_vue_ticket_message(
                "✅ Note enregistrée. Le membre ne la voit pas : elle est dans le suivi du ticket (bouton « Gérer » "
                "et site)."), ephemeral=True)
        except Exception as _tk_ex:
            _logerr("ticket.note", _tk_ex, guild_id=getattr(i.guild, 'id', 0))
            try:
                await i.followup.send("❌ La note n'a pas pu être enregistrée.", ephemeral=True)
            except discord.HTTPException as ex:
                _logerr("ticket.note.reponse", ex, guild_id=getattr(i.guild, 'id', 0))


