#  ⚔️ ANTI-RAID PANEL (Phase 28.2)
# ═══════════════════════════════════════════════════════════════════════════════

# Cache des joins récents par guild (pour détection de raid)
_recent_joins: dict[int, list[float]] = {}

# ─── TASK C.1 : GARDE ANTI-RAID SUR LES BIENVENUES ────────────────────────────
# Pendant une vague de raid détectée, on NE spamme PAS une bienvenue par arrivée :
# on suspend les annonces individuelles et on poste ENSUITE un seul récap groupé
# « +N membres arrivés pendant la vague ». État 100 % en mémoire, FAIL-SAFE :
# si l'état raid n'est pas lisible, le comportement actuel reste inchangé.
#  guild_id -> {"until": ts_fin_fenêtre, "count": nb_supprimés,
#               "channel_id": salon où poster le récap, "first": ts_début, "flush": task?}
_WELCOME_RAID_WINDOW_SEC = 600.0   # une vague tient la garde active ~10 min (glissant)
_welcome_raid_state: dict[int, dict] = {}


def mark_welcome_raid(guild_id: int) -> None:
    """Marque (ou prolonge) une fenêtre de raid pour le guild : pendant cette
    fenêtre, les bienvenues individuelles sont suspendues. Appelé par les DEUX
    détecteurs de raid (anti-raid configurable + raid_detector). FAIL-SAFE."""
    try:
        now_ts = time.time()
        st = _welcome_raid_state.get(int(guild_id))
        if st is None:
            st = {"until": 0.0, "count": 0, "channel_id": 0,
                  "first": now_ts, "flush": None}
            _welcome_raid_state[int(guild_id)] = st
        # fenêtre glissante : chaque nouvelle détection repousse la fin
        st["until"] = now_ts + _WELCOME_RAID_WINDOW_SEC
    except Exception as ex:
        print(f"[mark_welcome_raid] {ex}")


def _welcome_raid_active(guild_id: int) -> bool:
    """True si une vague de raid est en cours pour ce guild (fenêtre non expirée).
    Lecture pure, FAIL-SAFE (toute erreur → False = comportement normal)."""
    try:
        st = _welcome_raid_state.get(int(guild_id))
        return bool(st and st.get("until", 0.0) > time.time())
    except Exception:
        return False


async def _flush_welcome_raid_recap(guild_id: int):
    """Attend la fin de la fenêtre de raid puis poste UN SEUL récap groupé
    « +N membres arrivés pendant la vague » dans le salon d'accueil. Tâche
    one-shot lancée à la 1re suppression. FAIL-OPEN : toute erreur est avalée."""
    try:
        while True:
            st = _welcome_raid_state.get(int(guild_id))
            if not st:
                return
            remaining = st.get("until", 0.0) - time.time()
            if remaining <= 0:
                break
            await asyncio.sleep(min(remaining + 1.0, 60.0))
        st = _welcome_raid_state.pop(int(guild_id), None)
        if not st:
            return
        count = int(st.get("count", 0) or 0)
        ch_id = int(st.get("channel_id", 0) or 0)
        if count <= 0 or not ch_id:
            return
        guild = bot.get_guild(int(guild_id))
        if guild is None:
            return
        ch = guild.get_channel_or_thread(ch_id)   # un post de forum compris
        me = guild.me
        if ch is None or me is None:
            return
        try:
            _p = ch.permissions_for(me)
            if not (_p.send_messages_in_threads if isinstance(ch, discord.Thread) else _p.send_messages):
                return
        except Exception:
            return
        try:
            _lang = await i18n_module.lang_of(None, guild_id=guild.id)   # la langue du serveur
        except Exception:
            _lang = "fr"
        texte = i18n_module.t("welcome.wave", _lang or "fr", n=count, count=_nombre_membres(guild))
        try:
            await ch.send(texte, allowed_mentions=discord.AllowedMentions.none())
        except Exception as ex:
            print(f"[welcome raid recap send] {ex}")
    except Exception as ex:
        print(f"[_flush_welcome_raid_recap] {ex}")


def _defer_welcome_during_raid(guild_id: int, channel, member_id: int = 0) -> bool:
    """Si une vague de raid est active, compte cette arrivée pour le récap groupé
    (au lieu d'une bienvenue individuelle) et renvoie True (= NE PAS poster). Sinon
    renvoie False (= poster normalement). FAIL-SAFE : toute erreur → False.

    Dédoublonné par `member_id` : un même membre peut traverser deux handlers
    d'accueil (_handle_welcome + _post_onboarding_welcome) ; on ne le compte qu'une
    fois (set `seen`) pour que le récap affiche le bon total."""
    try:
        if not _welcome_raid_active(guild_id):
            return False
        st = _welcome_raid_state.get(int(guild_id))
        if st is None:
            return False
        mid = int(member_id or 0)
        if mid:
            seen = st.get("seen")
            if seen is None:
                seen = set()
                st["seen"] = seen
            seen.add(mid)
            st["count"] = len(seen)
        else:
            st["count"] = int(st.get("count", 0) or 0) + 1
        # mémorise un salon pour le récap (le 1er salon d'accueil rencontré)
        if not st.get("channel_id") and channel is not None:
            st["channel_id"] = getattr(channel, "id", 0) or 0
        # lance la tâche de flush une seule fois
        if st.get("flush") is None or st["flush"].done():
            try:
                st["flush"] = asyncio.create_task(
                    _flush_welcome_raid_recap(int(guild_id)))
            except Exception:
                st["flush"] = None
        return True
    except Exception as ex:
        print(f"[_defer_welcome_during_raid] {ex}")
        return False


class AntiRaidPanelV2(LayoutView):
    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        enabled = bool(c.get('antiraid_enabled', False))
        threshold = int(c.get('antiraid_join_threshold', 5))
        window = int(c.get('antiraid_join_window_sec', 10))
        min_age = int(c.get('antiraid_min_account_age_days', 7))
        action = str(c.get('antiraid_action', 'kick'))
        log_ch_id = int(c.get('antiraid_log_channel', 0) or 0)
        log_ch = self.g.get_channel(log_ch_id) if log_ch_id else None

        self.clear_items()

        b_toggle = Button(
            emoji=('🔘' if enabled else '⚪'), label=("Désactiver" if enabled else "Activer"),
            style=(discord.ButtonStyle.danger if enabled else discord.ButtonStyle.success),
            custom_id="ar_toggle",
        )
        b_toggle.callback = self._cb_toggle

        b_thresh = Button(emoji=visuels.icone("reglages"), label="Seuils", style=discord.ButtonStyle.primary, custom_id="ar_thresh")
        b_thresh.callback = self._cb_thresholds

        b_action = Button(emoji=visuels.icone("cible"), label="Action", style=discord.ButtonStyle.primary, custom_id="ar_action")
        b_action.callback = self._cb_action

        log_select = discord.ui.ChannelSelect(
            placeholder=f"Salon logs raid : {(log_ch.name if log_ch else 'aucun')}",
            channel_types=[discord.ChannelType.text, discord.ChannelType.news],
            min_values=0, max_values=1, custom_id="ar_log",
        )
        log_select.callback = self._cb_log_channel

        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="ar_back")
        b_back.callback = self._cb_back

        # Le scan de comptes suspects n'était atteignable que depuis le panneau de
        # l'ancien anti-raid, supprimé en 08/2026. Capacité de sécurité réelle : elle
        # est transplantée ici plutôt que perdue avec lui.
        b_scan = Button(
            label="Scanner les comptes suspects", emoji=visuels.icone("recherche"),
            style=discord.ButtonStyle.secondary, custom_id="arv2_scan",
        )
        b_scan.callback = self._cb_scan

        pretty_action = {'kick': '👢 Kick auto', 'ban': '🔨 Ban auto', 'lockdown': '🔒 Lockdown serveur'}.get(action, action)

        items = [
            visuels.bandeau("antiraid", "Anti-raid"),
            v2_subtitle("Vague d'arrivées → riposte immédiate"),
            v2_divider(),
            v2_body(
                f"**État** · {'🟢 actif' if enabled else '⚪ désactivé'}\n"
                f"**Détection** · `{threshold}` joins en `{window}`s déclenche le raid\n"
                f"**Âge min compte** · `{min_age}` jours (sinon flag suspect)\n"
                f"**Action auto** · {pretty_action}\n"
                f"**Salon logs** · {log_ch.mention if log_ch else '_non défini_'}"
            ),
            v2_divider(),
            v2_divider(),
            discord.ui.ActionRow(log_select),
            discord.ui.ActionRow(b_toggle, b_thresh, b_action, b_scan, b_back),
        ]
        self.add_item(v2_container(*items, color=Palette.DANGER))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_scan(self, i):
        # Repris tel quel de l'ancien panneau anti-raid : le scan est long, on acquitte
        # d'abord (anti-429) puis on rend le résultat en followup.
        try:
            await i.response.send_message(
                "🔍 **Scan en cours…**\n\nAnalyse des membres du serveur…", ephemeral=True)
            scanner = SuspectScanPanelV2(self.u, self.g)
            await scanner.scan_members()
            await scanner.render_after_defer(i)
        except Exception as ex:
            print(f"[AntiRaidPanelV2 _cb_scan] {ex}")
            try:
                await i.edit_original_response(
                    content=f"❌ **Erreur scan**\n```{str(ex)[:500]}```",
                    embed=None, view=None,
                )
            except Exception:
                pass

    async def _cb_toggle(self, i):
        try:
            c = await cfg(self.g.id)
            await db_set(self.g.id, 'antiraid_enabled', not bool(c.get('antiraid_enabled', False)))
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[AntiRaidPanelV2 _cb_toggle] {ex}")

    async def _cb_thresholds(self, i):
        try:
            c = await cfg(self.g.id)
            modal = _AntiRaidThresholdsModal(self.g, self.u)
            modal.threshold.default = str(c.get('antiraid_join_threshold', 5))
            modal.window.default = str(c.get('antiraid_join_window_sec', 10))
            modal.min_age.default = str(c.get('antiraid_min_account_age_days', 7))
            await i.response.send_modal(modal)
        except Exception as ex:
            print(f"[AntiRaidPanelV2 _cb_thresholds] {ex}")

    async def _cb_action(self, i):
        try:
            v = _AntiRaidActionPickerV2(self.u, self.g)
            await v.render_to(i, edit=True)
        except Exception as ex:
            print(f"[AntiRaidPanelV2 _cb_action] {ex}")

    async def _cb_log_channel(self, i):
        try:
            vals = i.data.get('values', [])
            ch_id = int(vals[0]) if vals else 0
            await db_set(self.g.id, 'antiraid_log_channel', ch_id)
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[AntiRaidPanelV2 _cb_log_channel] {ex}")

    async def _cb_back(self, i):
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class _AntiRaidThresholdsModal(Modal, title="Seuils Anti-Raid"):
    threshold = TextInput(label="Nb de joins pour déclencher (entier ≥ 2)", placeholder="5", max_length=3, required=True)
    window = TextInput(label="Fenêtre temporelle en secondes (5-300)", placeholder="10", max_length=3, required=True)
    min_age = TextInput(label="Âge minimum du compte en jours (0-365)", placeholder="7", max_length=3, required=True)

    def __init__(self, g, u):
        super().__init__()
        self.g = g
        self.u = u

    async def on_submit(self, i):
        try:
            t = max(2, min(50, int(self.threshold.value.strip())))
            w = max(5, min(300, int(self.window.value.strip())))
            a = max(0, min(365, int(self.min_age.value.strip())))
            await db_set(self.g.id, 'antiraid_join_threshold', t)
            await db_set(self.g.id, 'antiraid_join_window_sec', w)
            await db_set(self.g.id, 'antiraid_min_account_age_days', a)
            await AntiRaidPanelV2(self.u, self.g).render_to(i, edit=True)
        except Exception as ex:
            try:
                await i.response.send_message(f"❌ Valeurs invalides : `{ex}`", ephemeral=True)
            except Exception:
                pass


