# ═══════════════ NOTE D'ENTRAIDE (#14) ═══════════════
# Après une entraide résolue, le DEMANDEUR reçoit en MP 3 boutons pour noter l'aide reçue.
# Persistant (DynamicItem), 1 note/demande, alimente la réputation moyenne de l'aidant
# (affichée dans le remerciement public). Entraide OFF → simplement jamais déclenché.
_ERATE_META = {3: ("👍 Super", discord.ButtonStyle.success),
               2: ("🙂 Correct", discord.ButtonStyle.secondary),
               1: ("😕 Bof", discord.ButtonStyle.danger)}


async def _ensure_entraide_ratings_table():
    try:
        async with get_db() as db:
            await db.execute(
                "CREATE TABLE IF NOT EXISTS entraide_helper_ratings ("
                "guild_id INTEGER, helper_id INTEGER, rater_id INTEGER, request_id INTEGER, "
                "rating INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "
                "PRIMARY KEY (request_id, rater_id))")
            await db.commit()
    except Exception as ex:
        print(f"[entraide_ratings table] {ex}")


class EntraideRatingButton(discord.ui.DynamicItem[Button],
                           template=r"erate:(?P<g>\d+):(?P<h>\d+):(?P<q>\d+):(?P<r>[123])"):
    """Bouton de note d'entraide (persistant, capté dans le MP du demandeur)."""
    def __init__(self, gid, hid, qid, rating):
        self.gid, self.hid, self.qid, self.rating = int(gid), int(hid), int(qid), int(rating)
        label, style = _ERATE_META.get(int(rating), ("Note", discord.ButtonStyle.secondary))
        super().__init__(Button(label=label, style=style,
                                custom_id=f"erate:{int(gid)}:{int(hid)}:{int(qid)}:{int(rating)}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["g"]), int(match["h"]), int(match["q"]), int(match["r"]))

    async def callback(self, i):
        try:
            await _ensure_entraide_ratings_table()
            async with get_db() as db:
                await db.execute(
                    "INSERT INTO entraide_helper_ratings(guild_id, helper_id, rater_id, request_id, rating) "
                    "VALUES(?,?,?,?,?) ON CONFLICT(request_id, rater_id) DO UPDATE SET "
                    "rating=excluded.rating, created_at=CURRENT_TIMESTAMP",
                    (self.gid, self.hid, i.user.id, self.qid, self.rating))
                await db.commit()
        except Exception as ex:
            print(f"[entraide rating record] {ex}")
        try:
            await i.response.send_message("🙏 Merci pour ta note ! Ça valorise les bons aidants.", ephemeral=True)
        except Exception:
            try:
                await i.followup.send("🙏 Merci pour ta note !", ephemeral=True)
            except Exception:
                pass


