_FLUX_RESEAUX = ("youtube", "twitch", "tiktok", "twitter", "reddit")


def _flux_du_studio(f) -> bool:
    """Un flux du studio Rell (Rell Seas, Rell Games…) : son nom ou son identifiant le dit."""
    if not isinstance(f, dict):
        return True
    noms = " ".join(str(f.get(k) or "") for k in ("name", "username", "subreddit", "id", "titre"))
    return "rell" in config_salons.normaliser(noms).replace(" ", "")


def _cle_de_suivi(reseau: str, f: dict) -> str:
    """La clé sous laquelle `tracking2026` range les publications de ce flux."""
    if reseau == "youtube":
        return str(f.get("id") or "")
    return str(f.get("username") or f.get("subreddit") or f.get("name") or f.get("id") or "")


async def _titre_youtube(uc: str):
    """Le nom public d'une chaîne YouTube, lu dans son flux RSS — None si illisible."""
    from html import unescape
    if not re.fullmatch(r"UC[\w-]{20,}", uc or ""):
        return None
    try:
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as s:
            async with s.get(f"https://www.youtube.com/feeds/videos.xml?channel_id={uc}") as r:
                if r.status != 200:
                    return None
                m = re.search(r"<title>([^<]+)</title>", await r.text())
                return unescape(m.group(1)).strip() if m else None
    except (aiohttp.ClientError, asyncio.TimeoutError) as ex:
        print(f"[FLUX:DETAIL] titre {uc} : {type(ex).__name__}")
        return None


#  La rattache automatique du 19/10 (13 h 33 UTC) a relié un flux sans salon au salon des
#  sneaks : ce qui a été publié depuis par un flux retiré l'a été à tort.
_RATTACHE_FAUTIVE = datetime(2026, 10, 19, 13, 30, tzinfo=timezone.utc)


async def _flux_studio_rell(g) -> list:
    """19/10/2026 : « enlève dans la chaîne YouTube tous les autres, tout ce qui ne correspond
    pas au studio de Rell ». Une fois par serveur : YouTube ne garde que les chaînes du studio,
    et le salon des sneaks que des comptes du studio ; les publications faites à tort sont
    effacées. Rend la liste des flux retirés."""
    c = await cfg(g.id)
    if c.get('flux_rell_v1'):
        return []
    tous = {p: [f for f in (c.get(f'ads_{p}_feeds') or [])] for p in _FLUX_RESEAUX}
    for f in tous['youtube']:
        if isinstance(f, dict) and not _flux_du_studio(f):
            titre = await _titre_youtube(str(f.get('id') or ''))
            if titre:
                f['titre'] = titre
            elif not str(f.get('name') or '').strip():
                f['titre'] = 'rell ?'          # illisible et sans nom : dans le doute, on garde
    salons_rell = {int(f.get('channel_id', 0) or 0) for p in _FLUX_RESEAUX for f in tous[p]
                   if isinstance(f, dict) and _flux_du_studio(f)} - {0}
    retires = []
    for p, flux in tous.items():
        garde = []
        for f in flux:
            hors_studio = isinstance(f, dict) and not _flux_du_studio(f)
            if hors_studio and (p == 'youtube' or int(f.get('channel_id', 0) or 0) in salons_rell):
                retires.append((p, f))
            else:
                if isinstance(f, dict):
                    f.pop('titre', None)
                garde.append(f)
        if len(garde) != len(flux):
            await db_set(g.id, f'ads_{p}_feeds', garde)
    effaces = 0
    for p, f in retires:
        cle = _cle_de_suivi(p, f)
        for tp in await tracking2026.list_announcements(g.id, p, username=cle) if cle else []:
            mid = int(tp.discord_message_id or 0)
            salon = g.get_channel(int(tp.discord_channel_id or 0))
            if not mid or salon is None or discord.utils.snowflake_time(mid) < _RATTACHE_FAUTIVE:
                continue
            try:
                await salon.get_partial_message(mid).delete()
                effaces += 1
            except discord.NotFound:
                pass
            except discord.HTTPException as ex:
                _logerr("flux.rell_effacer", ex, guild_id=g.id)
                continue
            await tracking2026.mark_deleted(g.id, p, cle, tp.post_id)
    await db_set(g.id, 'flux_rell_v1', now().isoformat())
    if retires:
        noms = ", ".join(f"{str(f.get('name') or f.get('username') or _cle_de_suivi(p, f))} ({p})"
                         for p, f in retires)
        print(f"[FLUX] studio Rell seul : retirés {noms} · {effaces} publication(s) effacée(s)")
        logs = g.get_channel(int(await ulogger2026.get_log_channel(g.id) or 0))
        if logs is not None:
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(
                discord.ui.TextDisplay("### Réseaux · studio Rell uniquement\n"
                                       f"Retirés : {noms}\n-# {effaces} publication(s) effacée(s) du salon des sneaks"),
                accent_color=Palette.INFO))
            await logs.send(view=v, allowed_mentions=discord.AllowedMentions.none())
    return retires


async def _rattacher_flux_orphelins(g) -> int:
    """Un flux du studio Rell sans salon prend le salon des autres flux du studio. Un flux hors
    studio n'est jamais rattaché : c'est ce qui avait mis @miranzaugc dans les sneaks."""
    from collections import Counter
    c = await cfg(g.id)
    vus = Counter()
    for p in _FLUX_RESEAUX:
        for f in (c.get(f'ads_{p}_feeds') or []):
            cid = int((f.get('channel_id', 0) if isinstance(f, dict) else 0) or 0)
            if g.get_channel(cid) is not None and _flux_du_studio(f):
                vus[cid] += 1
    if not vus:
        return 0
    cible = vus.most_common(1)[0][0]
    rattaches = 0
    for p in _FLUX_RESEAUX:
        flux = c.get(f'ads_{p}_feeds') or []
        defaut = g.get_channel(int(c.get(f'ads_{p}_channel', 0) or 0))
        live = g.get_channel(int(c.get(f'ads_{p}_live_channel', 0) or 0))
        change = False
        for f in flux:
            if isinstance(f, dict) and _flux_du_studio(f) and defaut is None and live is None \
                    and g.get_channel(int(f.get('channel_id', 0) or 0)) is None:
                f['channel_id'] = cible
                change, rattaches = True, rattaches + 1
        if change:
            await db_set(g.id, f'ads_{p}_feeds', flux)
    return rattaches


async def _configurer_salons(g) -> None:
    """Une fois par serveur : @everyone voit tous les salons sauf ceux réservés à des rôles,
    communautaire ouvert à la parole, radié aveugle partout. Résumé et « Annuler » aux logs."""
    try:
        c = await cfg(g.id)
        if c.get('config_salons_v1'):
            return
        me = g.me
        if not (me and me.guild_permissions.manage_roles and me.guild_permissions.manage_channels):
            return
        ids_prives = {i for i in _ids_configures(dict(c)) if g.get_channel(i) is not None}
        ids_prives |= {ch.id for ch in await _salons_de_logs(g, c)}
        ids_lecture = {ch.id for ch in await _salons_de_flux(g, c)}
        radie = discord.utils.get(g.roles, name=_RADIE_ROLE_NAME)
        actions = config_salons.plan(g, ids_prives, ids_lecture, radie)
        await db_set(g.id, 'config_salons_v1', now().isoformat())
        if not actions:
            return
        avant = config_salons.instantane(actions)
        async with get_db() as db:
            await db.execute("CREATE TABLE IF NOT EXISTS config_salons_historique ("
                             "id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER, avant TEXT,"
                             " cree_le TEXT DEFAULT CURRENT_TIMESTAMP)")
            cur = await db.execute("INSERT INTO config_salons_historique(guild_id, avant) VALUES(?,?)",
                                   (g.id, avant))
            hid = cur.lastrowid
            await db.commit()
        faits = await config_salons.appliquer(actions)
        logs = g.get_channel(int(await ulogger2026.get_log_channel(g.id) or 0))
        if logs is not None:
            v = LayoutView(timeout=None)
            v.add_item(discord.ui.Container(
                discord.ui.TextDisplay(f"### Configuration des salons\n-# {faits} réglage(s) appliqué(s)"),
                discord.ui.TextDisplay(config_salons.resume(actions)),
                discord.ui.ActionRow(BoutonAnnulerConfig(hid)), accent_color=Palette.INFO))
            await logs.send(view=v, allowed_mentions=discord.AllowedMentions.none())
    except Exception as ex:
        _logerr("salons.config", ex, guild_id=getattr(g, 'id', 0))


def _roles_staff_et_plus(g, c) -> list:
    """Les rôles du staff et au-dessus (rôle staff des tickets, sinon la direction), hors intégrations."""
    seuils = [g.get_role(int(c.get(k, 0) or 0)) for k in ('ticket_staff', 'direction_allowed_role')]
    seuils = [r for r in seuils if r is not None]
    if not seuils:
        return []
    plancher = min(r.position for r in seuils)
    return [r for r in g.roles if r.position >= plancher and not r.managed and not r.is_default()]


async def _configurer_salons_v2(g) -> None:
    """19/10/2026, une fois par serveur : les salons comme le fondateur les a décrits (voir
    `config_salons.plan_v2`), le Join du clan réservé au clan, les invitations interdites partout.
    L'état d'avant est gardé : « Annuler » dans 📋logs remet tout comme avant."""
    try:
        c = await cfg(g.id)
        if c.get('config_salons_v2'):
            return
        me = g.me
        if not (me and me.guild_permissions.manage_roles and me.guild_permissions.manage_channels):
            return
        clan_role = g.get_role(int(c.get(rellseas_ui.CLE_ROLE_CIBLE, 0) or 0))
        voix = dict(c.get('temp_voice_config') or {})
        hubs = {int(k) for k in (voix.get('hubs') or {}) if str(k).isdigit()}
        ids_prives = {int(c.get(k, 0) or 0) for k in ('sondages_salon', 'tableau_salon')}
        ids_prives |= {ch.id for ch in await _salons_de_logs(g, c)}
        ids_prives |= zones.ids_salons(c)
        actions = config_salons.plan_v2(g, clan_role, _roles_staff_et_plus(g, c), hubs,
                                        me.guild_permissions.move_members, ids_prives)
        await db_set(g.id, 'config_salons_v2', now().isoformat())
        if not c.get('anti_invite'):
            await db_set(g.id, 'anti_invite', 1)
        if clan_role is not None and hubs:
            hubs_cfg = dict(voix.get('hubs') or {})
            for k, v in list(hubs_cfg.items()):
                hub = g.get_channel(int(k)) if str(k).isdigit() else None
                if hub is not None and hub.category is not None and config_salons.est_clan(hub.category.name):
                    hubs_cfg[k] = dict(v, required_role=clan_role.id)
            voix['hubs'] = hubs_cfg
            await db_set(g.id, 'temp_voice_config', voix)
        resume = "Invitations Discord interdites partout."
        if actions:
            avant = config_salons.instantane(actions)
            async with get_db() as db:
                await db.execute("CREATE TABLE IF NOT EXISTS config_salons_historique ("
                                 "id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER, avant TEXT,"
                                 " cree_le TEXT DEFAULT CURRENT_TIMESTAMP)")
                cur = await db.execute("INSERT INTO config_salons_historique(guild_id, avant) VALUES(?,?)",
                                       (g.id, avant))
                hid = cur.lastrowid
                await db.commit()
            faits = await config_salons.appliquer(actions)
            resume = config_salons.resume(actions) + "\n" + resume
            salon = await _salon_alertes_site(g)
            if salon is not None:
                v = LayoutView(timeout=None)
                v.add_item(discord.ui.Container(
                    discord.ui.TextDisplay(f"### Salons réglés comme décrit\n-# {faits} réglage(s) · l'état d'avant est gardé"),
                    discord.ui.TextDisplay(resume), discord.ui.ActionRow(BoutonAnnulerConfig(hid)),
                    accent_color=Palette.INFO))
                await salon.send(view=v, allowed_mentions=discord.AllowedMentions.none())
        await _au_journal(g, "Config", "salons.v2", f"Salons réglés selon le récapitulatif : {len(actions)} réglage(s). "
                                                    "Invitations interdites partout.")
        print(f"[SALONS] v2 : {g.id} · {len(actions)} réglage(s)")
    except Exception as ex:  # un serveur en échec n'empêche pas le démarrage ; réessai au suivant
        _logerr("salons.v2", ex, guild_id=getattr(g, 'id', 0))


INVITATIONS_MOTS = ["discord.gg/*", "discord.com/invite/*", "discordapp.com/invite/*", "dsc.gg/*"]
INVITATIONS_REGEX = [r"(discord\.gg|discord(app)?\.com/invite|dsc\.gg)/[a-z0-9-]+"]


async def _automod_invitations(g) -> bool:
    """« Les invitations Discord sont interdites… partout » : en plus du bot (qui retire après coup),
    une règle AutoMod de Discord les bloque AVANT l'envoi, même si le bot est éteint. Une fois par
    serveur ; une règle d'invitations déjà en place est gardée. Le staff et au-dessus restent libres,
    comme pour le bot. Sans « Gérer le serveur », rien n'est posé et on réessaie au démarrage suivant."""
    try:
        c = await cfg(g.id)
        if c.get('automod_invitations_v1'):
            return False
        me = g.me
        if not (me and me.guild_permissions.manage_guild):
            print("[AUTOMOD] invitations : il me manque « Gérer le serveur »")
            return False
        regles = await g.fetch_automod_rules()
        deja = any("discord.gg" in " ".join(getattr(r.trigger, "keyword_filter", None) or [])
                   + " ".join(getattr(r.trigger, "regex_patterns", None) or []) for r in regles)
        if not deja:
            exempts = _roles_staff_et_plus(g, c)[:20]
            action = discord.AutoModRuleAction(custom_message="Les invitations vers d'autres serveurs sont interdites ici.")
            for regex in (INVITATIONS_REGEX, None):
                try:
                    await g.create_automod_rule(
                        name="🛡️ Invitations interdites", event_type=discord.AutoModRuleEventType.message_send,
                        trigger=discord.AutoModTrigger(type=discord.AutoModRuleTriggerType.keyword,
                                                       keyword_filter=INVITATIONS_MOTS, regex_patterns=regex),
                        actions=[action], enabled=True, exempt_roles=exempts,
                        reason="Invitations interdites partout (fondateur, 19/10)")
                    break
                except discord.HTTPException as ex:
                    if regex is None or ex.status != 400:
                        raise
                    print("[AUTOMOD] motif refusé par Discord, règle posée sur les mots seuls")
        await db_set(g.id, 'automod_invitations_v1', now().isoformat())
        await _au_journal(g, "Config", "automod.invitations",
                          "Règle AutoMod des invitations déjà en place." if deja else
                          "Invitations bloquées par Discord avant l'envoi, même bot éteint (règle AutoMod).")
        return not deja
    except discord.HTTPException as ex:
        _logerr("automod.invitations", ex, guild_id=getattr(g, 'id', 0))
        return False


NOM_AIDE = "aide"
AIDE_VERSION = 4  # 4 : salons simples, un groupe par jeu (24/10)


def _salon_des_tickets(g):
    """Le salon où l'on ouvre un ticket (« ticket »), pas un « 🎫・tickets-staff » qui porte les fils."""
    for ch in getattr(g, "text_channels", []) or []:
        if "ticket" in config_salons.normaliser(ch.name).split():
            return ch
    return _salon_par_nom(g, "ticket")


def _salon_par_nom(g, *mots, exclus=("log", "transcript")):
    for ch in getattr(g, "text_channels", []) or []:
        n = config_salons.normaliser(ch.name)
        if all(m in n for m in mots) and not any(x in n for x in exclus):
            return ch
    return None


async def _vue_aide(g, c):
    """« Il faudrait que tu refasses le salon aide. » 22/10/2026 : « mieux fait, plus beau… séparer les
    compartiments au propre, expliquer bien l'international ». 24/10 : Communautaire en salons simples, un
    forum par jeu. L'orientation en français · anglais : la langue (le bot parle celle de chacun), puis un
    groupe par compartiment — un titre, une phrase, une rangée de boutons —, puis le staff. Un bouton
    n'apparaît que si son salon existe (aucun bouton qui ment)."""
    ticket = _salon_des_tickets(g)
    clan = bool(rellseas_ui.panneaux_tickets(c))
    regles = getattr(g, "rules_channel", None) or _salon_par_nom(g, "regle") or _salon_par_nom(g, "rules")
    items = [visuels.bandeau("orientation", "Bienvenue · Welcome"),
             discord.ui.TextDisplay("🇫🇷 **Serveur international** : écris en français ou en anglais, tout le monde "
                                    "se comprend. Le bot te parle dans ta langue :\n"
                                    "🇬🇧 **International server**: write in French or English, everyone gets along. "
                                    "The bot speaks your language:"),
             discord.ui.ActionRow(LangSelectButton("fr"), LangSelectButton("en"))]
    ids = []

    def _composants(xs) -> int:   # le conteneur compris (limite Discord : 40)
        return 1 + sum(getattr(x, "_total_count", 1) for x in xs)
    for titre, phrase, boutons in zones.groupes_aide(g, c, await zones.conf(g)):
        if not boutons:
            continue
        groupe = [discord.ui.Separator(), discord.ui.TextDisplay(f"### {titre}\n{phrase}"),
                  discord.ui.ActionRow(*[Button(label=libelle, url=x.jump_url) for x, libelle in boutons[:5]])]
        if _composants(items + groupe) + 5 > 40:   # 5 : le staff (séparateur, section, bouton) et la ligne du bas
            print("[AIDE][E1] panneau plein : un compartiment n'entre pas")
            break
        items += groupe
        ids += [x.jump_url for x, _l in boutons[:5]]
    if ticket is not None:
        items.append(discord.ui.Separator())
        items.append(discord.ui.Section(
            discord.ui.TextDisplay("### Staff\n🎫 **Ticket** — une question, un souci" + (", rejoindre le clan" if clan else "")
                                   + " · a question, a problem" + (", join the clan" if clan else "")),
            accessory=Button(label="Ouvrir · Open", url=ticket.jump_url)))
    items.append(discord.ui.TextDisplay("-# " + (f"📜 Règles · Rules : <#{regles.id}> · " if regles else "")
                                        + "pas d'invitation vers d'autres serveurs · no invites to other servers"))
    v = LayoutView(timeout=None)
    v.add_item(discord.ui.Container(*items, accent_color=Palette.INFO))
    signature = (f"{AIDE_VERSION}|" + "|".join(str(x) for x in ids)
                 + f"|{getattr(ticket, 'id', 0)}|{getattr(regles, 'id', 0)}")
    return v, signature


async def _retirer_recherche_de_groupe(salon) -> int:
    """L'ancien tableau « Recherche de groupe / Alertes groupes (on/off) » : son bouton ne répond
    plus depuis le 11/08, il part."""
    n = 0
    async for m in salon.history(limit=100):
        composants = " ".join(getattr(x, "custom_id", "") or "" for r in getattr(m, "components", []) or []
                              for x in getattr(r, "children", []) or [])
        textes = " ".join([m.content or ""] + [(e.title or "") + (e.description or "") for e in m.embeds])
        if nettoyage._du_bot(m, bot.user.id) and ("szone_" in composants or "Recherche de groupe" in textes):
            try:
                await m.delete()
                n += 1
            except discord.HTTPException as ex:
                _logerr("aide.ancien", ex, guild_id=salon.guild.id)
    return n


async def _salon_aide(g) -> None:
    """Le panneau d'aide reste en place : posé une fois (l'ancien « Recherche de groupe » retiré),
    reposé s'il disparaît, réécrit si un salon cité change."""
    try:
        c = await cfg(g.id)
        aide_id = int(c.get('aide_salon', 0) or 0)
        salon = g.get_channel_or_thread(aide_id) if aide_id else None
        if salon is None and aide_id:
            try:
                salon = await g.fetch_channel(aide_id)
            except discord.NotFound:
                salon = None
        if salon is None and c.get('zones_v2'):
            return  # le post ❓ Aide revient avec « Réparer » (/configure → Entraide Rell Seas)
        if isinstance(salon, discord.Thread) and salon.archived:
            await salon.edit(archived=False)
        if salon is None:
            ancien_lfg = g.get_channel(int(c.get('lfg_board_channel', 0) or 0))
            salon = next((ch for ch in getattr(g, "text_channels", []) or []
                          if NOM_AIDE in config_salons.normaliser(ch.name).split()), None) or ancien_lfg
            if salon is None:
                return
            await db_set(g.id, 'aide_salon', salon.id)
            await db_set(g.id, 'lfg_board_channel', 0)
            for ch in {salon, ancien_lfg} - {None}:
                await _retirer_recherche_de_groupe(ch)
        vue, signature = await _vue_aide(g, c)
        mid = int(c.get('aide_message', 0) or 0)
        if mid:
            try:
                msg = await salon.fetch_message(mid)
                if str(c.get('aide_message_v', '')) != signature:
                    await msg.edit(view=vue, allowed_mentions=discord.AllowedMentions.none())
                    await db_set(g.id, 'aide_message_v', signature)
                return
            except discord.NotFound:
                pass
        msg = await salon.send(view=vue, allowed_mentions=discord.AllowedMentions.none())
        await db_set(g.id, 'aide_message', msg.id)
        await db_set(g.id, 'aide_message_v', signature)
    except discord.HTTPException as ex:
        _logerr("aide.salon", ex, guild_id=getattr(g, 'id', 0))


@tasks.loop(minutes=5)
async def entraide_task():
    """L'entraide Rell Seas : les demandes sans activité se ferment, les demandes closes disparaissent
    après leur délai, l'orientation suit les compteurs, les panneaux restent en place."""
    for g in list(bot.guilds):
        try:
            c = await cfg(g.id)
            if g.owner_id in TETE_IDS and not c.get('rs_installation_auto'):
                await db_set(g.id, 'rs_installation_auto', now().isoformat())
                if not c.get('rs_actif'):
                    faits = await zones.installer(g)
                    await _entraide_journal(g, "entraide.installation",
                                            "Entraide Rell Seas installée : " + (", ".join(faits) or "rien ne manquait") + ".")
                    await _salon_aide(g)
            if c.get('rs_actif') and not c.get('rs_v2'):
                # 22/10 (soir) : « trop de salons… tout dans Communautaire » — deux forums, rangés.
                faits = await entraide.migrer_v2(g)
                if faits:
                    await _entraide_journal(g, "entraide.regroupement",
                                            "Entraide regroupée dans Communautaire : " + ", ".join(faits) + ".")
                    await _salon_aide(g)
            if g.owner_id in TETE_IDS and c.get('rs_actif') and not c.get('zones_v3') and \
                    int(c.get('zones_v3_essais', 0) or 0) < ZONES_ESSAIS:
                # 24/10, le fondateur : « refais tout l'onglet communautaire… avec des salons simples… la
                # même chose pour un nouveau jeu… Clover RPG ».
                await _installer_zones(g, c)
            if g.owner_id in TETE_IDS and c.get('zones_v2') and not c.get('zones_guide_v1'):
                # 22/10 (nuit) : « dans Rell Seas, la même chose… un fil ultra professionnel » — le post guide.
                await db_set(g.id, 'zones_guide_v1', now().isoformat())
                faits = await zones.installer(g)
                await _entraide_journal(g, "zones.guide", "Guide Rell Seas en place : " + (", ".join(faits) or
                                                                                          "rien ne manquait") + ".")
            if g.owner_id in TETE_IDS and c.get('zones_v2') and not c.get('equipages_retires_v1'):
                # 22/10 (nuit), le fondateur : « le crew équipage… pour éviter que les gens fassent leur pub…
                # c'est une mauvaise idée ». Plus de post ⚓ Crews, plus de lien qui y mène.
                await db_set(g.id, 'equipages_retires_v1', now().isoformat())
                await _retirer_equipages(g)
            if not c.get('tickets_visibilite_v1'):
                # 22/10 (nuit), le fondateur : « que les tickets soient bien vus par le rôle administrateur
                # en question… la direction et le fondateur voient les tickets ».
                await db_set(g.id, 'tickets_visibilite_v1', now().isoformat())
                await _tickets_visibilite(g)
            if not c.get('tickets_vus_v1'):
                # 25/10/2026, le fondateur : « vérifie les tickets qui sont actifs et ceux que je ne vois pas ».
                await db_set(g.id, 'tickets_vus_v1', now().isoformat())
                await _verifier_tickets_ouverts(g)
            if not c.get('tickets_vus_v2'):
                # 25/10/2026 : la 1re passe a compté 4 erreurs sans détail — on complète sans nouvelle carte, et on dit.
                await db_set(g.id, 'tickets_vus_v2', now().isoformat())
                await _verifier_tickets_ouverts(g, carte=False, cle="verification_2")
            if not c.get('tickets_visibilite_v2'):
                # 24/10/2026 (revue) : seuls le rôle direction et les comptes de tête voient tout — les rôles
                # rangés au-dessus de la direction perdent « Gérer les fils » posé le 22/10 ; le panneau
                # unifié déjà posé perd sa promesse « l'équipe prévenue ».
                await db_set(g.id, 'tickets_visibilite_v2', now().isoformat())
                await _tickets_visibilite(g)
                await _rafraichir_hub_tickets(g)
            if g.owner_id in TETE_IDS and not c.get('game_link_v1'):
                # 24/10, le fondateur : « un nouveau salon avec un emoji de manette qui s'appelle Game Link ».
                await db_set(g.id, 'game_link_v1', now().isoformat())
                ch = await liens_jeux.salon(g, creer=True)
                if ch is not None:
                    await liens_jeux.assurer_carte(g)
                    await _au_journal(g, "Config", "gamelink.salon", f"Salon {ch.mention} créé : les liens pour "
                                                                     "rejoindre nos jeux (« 🎮 Liens des jeux » dans 📋logs).")
                    await _salon_aide(g)
            if g.owner_id in TETE_IDS and c.get('zones_archives') and not c.get('archives_supprimees_v1'):
                # 22/10 (nuit), le fondateur : « je veux pas d'archive, tu peux tout enlever ».
                await db_set(g.id, 'archives_supprimees_v1', now().isoformat())
                await _supprimer_toutes_archives(g)
            if g.owner_id in TETE_IDS and (c.get('zones_v1') or c.get('zones_v2')) and not c.get('menage_v1'):
                await db_set(g.id, 'menage_v1', now().isoformat())
                await _menage_categories(g)
            if g.owner_id in TETE_IDS and not c.get('clan_v2') and int(c.get('clan_v2_essais', 0) or 0) < ZONES_ESSAIS:
                # 22/10 (nuit), le fondateur choisit « Un seul forum » pour la zone du clan.
                await _installer_clan(g, c)
            elif g.owner_id in TETE_IDS and c.get('clan_v2') and not c.get('clan_demenage_v2') and \
                    int(c.get('clan_demenage_essais', 0) or 0) < ZONES_ESSAIS:
                await _demenager_clan(g, c)
            await entraide.entretenir(g)
            await _lire_commandes(g)
            if g.owner_id in TETE_IDS:
                _faq_vus[g.id] = _faq_trouves(g, await cfg(g.id))
            if time.monotonic() - _zones_entretenues.get(g.id, -1e9) > 1800:
                _zones_entretenues[g.id] = time.monotonic()
                try:
                    await suggestions.assurer_panneau(g)   # 24/10/2026 (revue) : 30 min au lieu de 12 h
                except Exception as ex:
                    _logerr("suggestions.panneau", ex, guild_id=g.id)
                await zones.entretenir(g)
        except Exception as ex:
            _logerr("entraide.entretien", ex, guild_id=g.id)
    await _etat_public()  # /stats dit si l'entraide est en place et les tickets regroupés


_zones_entretenues: dict = {}
ZONES_ESSAIS = 3
_commandes_vues: dict = {}   # guild_id → les commandes que Discord a vraiment (lues toutes les 5 minutes)
_faq_vus: dict = {}          # guild_id → ce que les réponses toutes faites trouvent (oui/non)


def _faq_trouves(g, c) -> dict:
    """Les endroits que les réponses toutes faites trouvent sur ce serveur : oui ou non, rien d'autre."""
    d = _faq_destinations(g, c)
    out = {k: bool(d.get(k)) for k in ("ticket", "suggestions", "game_link", "annonces", "roblox", "goripe")}
    out["jeux"] = {j["cle"]: {k: bool(j.get(k)) for k in ("trade", "help", "annonces", "lien")}
                   for j in d.get("jeux", [])}
    return out


async def _lire_commandes(g) -> None:
    """Les commandes enregistrées chez Discord pour ce serveur : l'état réel, pas l'arbre du code."""
    try:
        _commandes_vues[g.id] = sorted(c.name for c in await bot.tree.fetch_commands(guild=g))
    except discord.HTTPException as ex:
        _logerr("commandes.lecture", ex, guild_id=g.id)
MENAGE_MOTS = ("echange", "echanges", "groupe", "groupes")
EMOJI_ANCIEN_TICKET = "\N{ADMISSION TICKETS}"


async def _installer_zones(g, c) -> None:
    """24/10/2026 : « refais tout l'onglet communautaire… avec des salons simples… un salon discussion,
    média… Boost, Suggestion… en dehors… un forum pour Rell Seas… la même chose pour un nouveau jeu…
    Clover RPG ». Une fois ; le témoin est posé AVANT (jamais deux installations en parallèle), retiré si
    l'installation casse — elle reprend au passage suivant, trois essais au plus (elle ne recrée que ce
    qui manque)."""
    await db_set(g.id, 'zones_v3', now().isoformat())
    try:
        faits = await zones.installer(g)
    except (discord.HTTPException, PermissionError) as ex:
        essais = int(c.get('zones_v3_essais', 0) or 0) + 1
        await db_set(g.id, 'zones_v3_essais', essais)
        if essais < ZONES_ESSAIS:
            await db_set(g.id, 'zones_v3', "")
        _logerr("zones.installation", ex, guild_id=g.id)
        return
    await _entraide_journal(g, "zones.installation", "Communautaire en salons simples, un forum par jeu (Rell Seas, "
                            "Clover RPG) : " + (", ".join(faits) or "rien ne manquait") + ".")
    await _reporter_immunites(g, await cfg(g.id))
    await _salon_aide(g)
    await _salon_tableau(g)


async def _reporter_immunites(g, c) -> int:
    """Un ancien salon immunisé (l'automodération s'y tait) : son post l'est aussi."""
    paires = {int(k): int(v) for k, v in (c.get('zones_correspondances') or {}).items() if str(k).isdigit()}
    if not paires:
        return 0
    n = 0
    async with get_db() as db:
        async with db.execute("SELECT channel_id FROM immune_channels WHERE guild_id=?", (g.id,)) as cur:
            immunises = {int(r[0]) for r in await cur.fetchall()}
        for ancien, neuf in paires.items():
            if ancien in immunises and neuf not in immunises:
                await db.execute("INSERT INTO immune_channels(guild_id, channel_id) VALUES(?, ?)", (g.id, neuf))
                n += 1
        await db.commit()
    _immunity_cache.pop(g.id, None)
    return n


async def _tickets_visibilite(g) -> int:
    """Les salons qui portent les fils donnent « Gérer les fils » au rôle direction et aux deux comptes de
    tête ; un ticket Rell Seas encore ouvert accueille les rôles du clan s'ils ne le voient pas ; un ticket
    en salon classique reçoit les mêmes droits. 24/10/2026 (revue) : les rôles placés au-dessus de la
    direction (ni staff d'un type, ni clan) perdent ce que le bot leur avait posé le 22/10 — rien d'autre
    n'est retiré."""
    c = await cfg(g.id)
    direction = _equipe_direction(g, c)
    anciens = _au_dessus_de_la_direction(g, c)
    n = retires = 0
    noms: list = []   # les rôles qui perdent l'accès : nommés au journal, pour pouvoir les rendre à la main
    porteurs = dict.fromkeys(int(v) for v in (c.get(tickets_fils.CLE_PARENTS) or {}).values() if str(v).isdigit())
    for cid in porteurs:
        ch = g.get_channel(cid)
        if not isinstance(ch, discord.TextChannel):
            continue
        try:
            n += await tickets_fils.completer(ch, direction)
            retires += await tickets_fils.retirer(ch, anciens, noms=noms)
        except discord.HTTPException as ex:
            _logerr("tickets.visibilite", ex, guild_id=g.id)
    async with get_db() as db:
        async with db.execute("SELECT channel_id, panel_id FROM tickets WHERE guild_id=? AND status='open'",
                              (g.id,)) as cur:
            ouverts = await cur.fetchall()
    for chid, pid in ouverts:
        staff, equipe_type, _groupe = _equipe_du_type(g, c, str(pid))
        try:
            ch = await tickets_fils.salon(g, chid)
            if isinstance(ch, discord.Thread):
                porteur = ch.parent
                for role in equipe_type:
                    if porteur is not None and porteur.permissions_for(role).manage_threads:
                        continue
                    for m in [m for m in role.members if not m.bot][:25]:
                        await ch.add_user(m)
                        n += 1
            elif isinstance(ch, discord.TextChannel):
                n += await tickets_fils.completer(ch, (staff, *equipe_type, *direction), tickets_fils.DROITS_SALON)
                retires += await tickets_fils.retirer(ch, anciens, tickets_fils.DROITS_SALON, noms=noms)
        except discord.HTTPException as ex:
            _logerr("tickets.visibilite", ex, guild_id=g.id)
    await _au_journal(g, "Tickets", "tickets.visibilite",
                      "Tickets : la direction et le fondateur voient tous les tickets, l'équipe Rell Seas les siens"
                      + (f" ({n} accès ajouté(s))" if n else " (rien ne manquait)")
                      + (f" ; {retires} accès retiré(s) à des rôles placés au-dessus de la direction ("
                         + ", ".join(sorted(set(noms)))[:900] + ")." if retires else "."))
    return n


async def _retirer_equipages(g) -> int:
    """Le post ⚓ Crews (s'il reste) et les équipages partent ; le guide Rell Seas et ❓ aide suivent."""
    c = await cfg(g.id)
    posts = dict(c.get('zones_posts') or {})
    info = posts.pop('crews', None) or {}
    pid = int(info.get('id', 0) or 0)
    if pid:
        fil = g.get_channel_or_thread(pid)
        try:
            if fil is None:
                fil = await g.fetch_channel(pid)
            await fil.delete(reason="Équipages retirés : pas de pub")
        except discord.NotFound:
            pass
        except discord.HTTPException as ex:
            _logerr("zones.equipages", ex, guild_id=g.id)
        await db_set(g.id, 'zones_posts', posts)
    for cle in ('eq_forum', 'eq_panneau', 'eq_ouverture'):
        await db_set(g.id, cle, 0)
    n = await equipages.tout_retirer(g.id)
    await _au_journal(g, "Config", "zones.equipages", "Équipages retirés de 🌊rell-seas (éviter la pub)"
                      + (f" : {n} équipage(s) sorti(s) de la liste." if n else "."))
    try:
        await zones.assurer_guide(g)
    except discord.HTTPException as ex:
        _logerr("zones.guide", ex, guild_id=g.id)
    await _salon_aide(g)
    return n


async def _supprimer_toutes_archives(g) -> int:
    """« Je veux pas d'archive, tu peux tout enlever » (le fondateur, 22/10) : les salons de « 📦 Archives »
    — seulement ceux que le bot y a rangés — partent, et la catégorie avec eux."""
    salons = zones.archives(g, await cfg(g.id))
    noms = [f"#{ch.name}" for ch in salons]
    n = await zones.supprimer_archives(g, [ch.id for ch in salons])
