@tasks.loop(seconds=30)
async def cadeaux_task():
    """Les cadeaux : une fois, le salon 🎁giveaways (sans catégorie, à ranger où le fondateur veut) ;
    toutes les 30 s, les compteurs en base et le tirage des cadeaux arrivés à leur fin."""
    if not bot.is_ready():
        return
    for g in list(bot.guilds):
        try:
            c = await cfg(g.id)
            if g.owner_id in TETE_IDS and not c.get('cadeaux_salon_v1'):
                # 22/10 (nuit), le fondateur : « un salon unique… tu me le crées, après, moi, je le place
                # où je veux ».
                await db_set(g.id, 'cadeaux_salon_v1', now().isoformat())
                ch = await cadeaux.salon_cadeaux(g, creer=True)
                if ch is not None:
                    await _au_journal(g, "Cadeaux", "cadeaux.salon",
                                      f"Salon des cadeaux créé : {ch.mention} — à ranger où tu veux.")
        except Exception as ex:
            _logerr("cadeaux.salon", ex, guild_id=g.id)
    try:
        await cadeaux.tic(list(bot.guilds))
    except Exception as ex:
        _logerr("cadeaux.tic", ex)
    for g in list(bot.guilds):
        try:   # les invitations : la photo des liens au démarrage, les départs manqués rattrapés chaque heure
            await invitations.entretenir(g)
        except Exception as ex:
            _logerr("invitations.entretien", ex, guild_id=g.id)
    for g in list(bot.guilds):
        try:
            c = await cfg(g.id)
            if not c.get('cadeaux_elagage_v1'):
                #  24/10/2026 : « les conditions d'abord ». Une fois : ceux déjà inscrits sans les remplir
                #  sont retirés et prévenus sous la carte (après `tic` : les compteurs sont en base).
                n = await cadeaux.elaguer(g)
                await db_set(g.id, 'cadeaux_elagage_v1', {"le": now().isoformat(), "retires": n})
            if time.monotonic() - _cadeaux_avis.get(g.id, -1e9) > 3600:
                #  24/10/2026 : « je veux que ce soit vu individuellement » — un avis public part ; les
                #  retirés qu'il nommait le liront en cliquant, pour eux seuls. Toutes les heures, et le
                #  relevé dit ce qui a été lu (la preuve que le salon est propre).
                _cadeaux_avis[g.id] = time.monotonic()
                releve = await cadeaux.nettoyer_avis(g)
                await db_set(g.id, 'cadeaux_avis_v1', dict(releve, le=now().isoformat()))
        except Exception as ex:
            _logerr("cadeaux.elagage", ex, guild_id=g.id)
    if time.monotonic() - _cadeaux_purge[0] > 3600:
        _cadeaux_purge[0] = time.monotonic()
        for g in list(bot.guilds):
            try:
                await cadeaux.purger(g)
            except Exception as ex:
                _logerr("cadeaux.purge", ex, guild_id=g.id)


_cadeaux_purge = [-1e9]
