def _equipes_droits(g, c) -> tuple:
    """(staff, direction) pour droits_staff : les rôles du staff et au-dessus, et tout rôle dont le nom dit « staff »
    (Staff GoRP) ; la Direction (acces_direction). Les rôles « Fondateur » ne sont jamais touchés."""
    fondateurs = {r.id for r in g.roles if acces_direction._nom(r) in acces_direction.NOMS_FONDATEUR}
    direction = [r for r in acces_direction.roles(g) if r.id not in fondateurs]
    pris = fondateurs | {r.id for r in direction}
    staff = [r for r in _roles_staff_et_plus(g, c) if r.id not in pris]
    staff += [r for r in g.roles if "staff" in config_salons.normaliser(r.name) and not r.managed
              and r.id not in pris and r not in staff]
    return staff, direction


async def _droits_staff(g) -> None:
    """29/10/2026, à chaque démarrage : qui écrit, qui modère, qui déplace, salon par salon (droits_staff.py)."""
    me = g.me
    if not (me and me.guild_permissions.manage_roles):
        return
    #  29/10/2026 : le salon du panneau des tickets est « automatique » — on clique, personne n'y écrit.
    panneau = await _salon_panneau_tickets(g)
    b = await droits_staff.appliquer(g, *_equipes_droits(g, await cfg(g.id)),
                                     automatiques=frozenset({panneau.id}) if panneau is not None else frozenset())
    health_server_module.ETAT_PUBLIC["droits_staff"] = dict(b)
    print(f"[droits_staff] {b}")


async def _retirer_annonce_wiki(g) -> None:
    """29/10/2026, le fondateur : « mets pas des annonces quand c'est pas moi qui l'ai dit… c'est moi qui poste ». Le bot
    avait posté l'ouverture du wiki dans les annonces : retirée, une fois. Le bot ne poste plus JAMAIS d'annonce de
    lui-même — l'atelier d'annonces (site, la tête) publie seulement ce que la direction écrit."""
    c = await cfg(g.id)
    mid = int(c.get('wiki_annonce_v1', 0) or 0)
    if mid <= 1 or c.get('wiki_annonce_retiree'):
        return
    publics = [ch for ch in (getattr(g, "text_channels", []) or []) if ch.permissions_for(g.default_role).view_channel]
    salon = faq.salons_du_serveur(publics, [j.mots for j in zones.JEUX])["annonces"]
    if salon is not None:
        try:
            msg = await salon.fetch_message(mid)
            if msg.author.id == g.me.id:
                await msg.delete()
        except discord.NotFound:
            pass
    await db_set(g.id, 'wiki_annonce_retiree', 1)
    health_server_module.ETAT_PUBLIC["wiki_annonce_retiree"] = True


