async def _travaux_de_demarrage():
    """Les migrations, en tâche de fond, serveur par serveur. 19/10/2026 (audit) : chacune dans son
    propre `try` — avant, une erreur sautait toutes les suivantes, à chaque démarrage, en silence."""
    await bot.wait_until_ready()
    for g in list(bot.guilds):
        for nom in _TRAVAUX:
            module, _, fonction = nom.rpartition(".")
            etape = getattr(globals()[module], fonction) if module else globals()[fonction]
            try:
                await etape(g)
            except Exception as ex:
                _logerr(f"demarrage.{nom}", ex, guild_id=g.id)
    for etape in (_etat_public, _retirer_tables_mortes):
        try:
            await etape()
        except Exception as ex:
            _logerr(f"demarrage.{etape.__name__}", ex)


async def _relever_actus(forcer: bool = False) -> dict:
    """Un passage de l'actualité Roblox : toutes les sources, mise en file, publication.
    `forcer` (le bouton « Relever maintenant ») ignore la cadence de chaque source."""
    out = {"lus": 0, "enfiles": 0, "publies": 0, "pannes": 0}
    guildes = []
    for g in list(bot.guilds):
        try:
            if await roblox_news_module.actif(g.id):
                guildes.append(g)
        except Exception as ex:
            _logerr("veille.actif", ex, guild_id=g.id)
    if not guildes:
        return out
    for src in roblox_news_module.SOURCES:
        rel = await roblox_news_module.relever(src, forcer=forcer)
        if rel.get("sautee"):
            continue
        if rel["code"] != 200:
            out["pannes"] += 1
            await asyncio.sleep(2)
            continue
        out["lus"] += len(rel.get("billets") or [])
        out["enfiles"] += (await _enfiler_billets(guildes, rel)).get("enfiles", 0)
        await asyncio.sleep(2)
    out["publies"] = (await _publier_file_actualites(guildes))["publies"]
    await roblox_news_module.purger()
    await roblox_news_module.purger_file_actu()
    return out


