# ═══════════════════════════════════════════════════════════════════════════════
#  🏪 LA TÊTE DU CLASSEMENT « PUBLIÉ RÉCEMMENT »
# ═══════════════════════════════════════════════════════════════════════════════
#  Demandé le 30/08 : « toutes les 2 à 5 minutes, exécuter la requête
#  officielle, trouver le premier accessoire valide, enregistrer les 20
#  premiers et leur ordre, déclencher une mise à jour uniquement si la tête du
#  classement change ».
#
#  ⚠️ POURQUOI CETTE BOUCLE PEUT ÊTRE SI RAPIDE, alors que la veille tourne
#  toutes les 30 minutes : elle ne coûte UNE SEULE REQUÊTE. Le budget mesuré
#  est de ~8 requêtes par fenêtre de 60 s sur ce chemin ; une requête toutes
#  les quatre minutes en consomme un huitième de pour-cent. C'est la
#  différence entre surveiller une tête de liste et paginer un catalogue.
#
#  ⚠️ ET ELLE N'ENVOIE RIEN. Elle observe et mémorise. Publier depuis ici
#  doublerait le chemin d'envoi des accessoires, et deux chemins qui font la
#  même chose divergent au premier correctif.
#  ⚠️ LE DRAPEAU QUI ÉVITE LA COLLISION DE DÉBIT. Les deux boucles tapent le
#  MÊME chemin (`/v2/search/items/details`), dont le budget mesuré est de
#  12 requêtes par fenêtre de 60 s. Le passage de la veille en consomme 13 sur
#  environ trois minutes, et le relevé du 30/08 est descendu à `reste_min=2`.
#  Une requête de suivi tombant dans cette fenêtre-là serait celle de trop.
#  Le suivi s'efface donc pendant le passage : il repassera quatre minutes plus
#  tard, ce qui ne coûte rien à une tête de classement qui bouge de loin en
#  loin.
#  (Le drapeau lui-même vit dans `roblox_veille` : voir `catalogue_occupe`.
#   Il y a été déplacé le 30/08 pour que le bouton « Relever maintenant » du
#   panneau puisse le lever lui aussi — il ne le pouvait pas depuis ici.)


def _age_s(quand) -> float | None:
    if quand is None:
        return None
    try:
        return (datetime.now(timezone.utc) - quand).total_seconds()
    except Exception:
        return None


# ── L'éclaireur d'ACTUALITÉS ─────────────────────────────────────────────────
#  Le forum Discourse, en JSON : 88 Ko par catégorie, cinq catégories, et c'est
#  là que tombent annonces, mises à jour, alertes et événements. Les salles de
#  presse (560 Ko pour deux articles par mois, mesuré) restent au passage
#  complet et à leur cadence de deux heures.
#
#  ⚠️ UNE REQUÊTE PAR PASSAGE DEPUIS LE 24/09 : `relever_mises_a_jour` lit
#  les quatre catégories « updates » d'un coup. Le passage complet relit
#  chacune à sa cadence : le filet, et la seule lecture de « ressources ».
#  Si l'éclaireur meurt, le superviseur le relance.
_ECLAIREUR_ACTU = {"amorce": False, "vus": set(), "passages": 0, "erreurs": 0,
                   "billets": 0, "publies": 0,
                   "dernier_passage": None, "dernier_signal": None,
                   #  Le ralentissement quand le forum refuse le serveur.
                   "palier": 0, "pause_jusqu": None, "sautes": 0}
#  30 s au lieu de 90 : la sonde ne lit plus que 5 billets par catégorie
#  (15 Ko contre 84), donc trois fois plus souvent coûte deux fois moins.
ECLAIREUR_ACTU_SECONDES = 30
ECLAIREUR_ACTU_BATTEMENT = 60          # 60 × 30 s = 30 min
#  ⚠️ QUAND LE FORUM REFUSE (HTTP 202 le 24/09, depuis l'IP du serveur) : on
#  RALENTIT au lieu d'insister — 1, 2, 5 puis 10 minutes entre deux essais —
#  et on reprend les 30 s dès qu'il répond. Marteler une porte fermée ne
#  l'ouvre pas ; c'est même ce qui la ferme.
ECLAIREUR_ACTU_PAUSES = (0, 60, 120, 300, 600)


@tasks.loop(seconds=ECLAIREUR_ACTU_SECONDES)
async def eclaireur_actu_task():
    E = _ECLAIREUR_ACTU
    try:
        guildes = []
        for g in list(bot.guilds):
            try:
                if await roblox_news_module.actif(g.id):
                    guildes.append(g)
            except Exception:
                continue
        if not guildes:
            return
        if not E["amorce"]:
            E["vus"] |= await roblox_news_module.identifiants_connus_actus()
            E["amorce"] = True
            print(f"[eclaireur_actu] amorcé : {len(E['vus'])} billet(s) déjà "
                  f"connu(s)")
        #  Le ralentissement : pendant la pause, on ne frappe pas.
        _maint = datetime.now(timezone.utc)
        if E.get("pause_jusqu") and _maint < E["pause_jusqu"]:
            E["sautes"] = E.get("sautes", 0) + 1
            return
        E["passages"] += 1
        E["dernier_passage"] = _maint

        neufs_total, enfiles_total = 0, 0
        #  ⚠️ UNE REQUÊTE PAR PASSAGE (24/09) : les quatre catégories
        #  « updates », 10 sujets, 30 Ko. Avant : 2 requêtes toutes les 30 s et
        #  3 de plus toutes les 90 s, ~8 600 par jour — jusqu'au 202.
        rel = await roblox_news_module.relever_mises_a_jour(leger=True)
        if rel.get("code") != 200:
            E["erreurs"] += 1
            E["palier"] = min(E.get("palier", 0) + 1, len(ECLAIREUR_ACTU_PAUSES) - 1)
            E["pause_jusqu"] = _maint + timedelta(
                seconds=ECLAIREUR_ACTU_PAUSES[E["palier"]])
            return
        E["palier"], E["pause_jusqu"] = 0, None
        billets = rel.get("billets") or []
        neufs = [b for b in billets if str(b.get("topic_id")) not in E["vus"]]
        for b in billets:
            E["vus"].add(str(b.get("topic_id")))
        if neufs:
            neufs_total = len(neufs)
            _re = await _enfiler_billets(guildes, {"billets": neufs})
            enfiles_total = _re["enfiles"]

        if enfiles_total:
            E["dernier_signal"] = datetime.now(timezone.utc)
            E["billets"] += neufs_total
            rn = await _publier_file_actualites(guildes, etiquette="eclaireur_actu")
            E["publies"] += rn["publies"]
            print(f"[eclaireur_actu] 🔔 {neufs_total} billet(s) jamais vu(s) · "
                  f"{enfiles_total} mis en file · {rn['publies']} publié(s) "
                  f"sur l'instant")
        elif E["passages"] % ECLAIREUR_ACTU_BATTEMENT == 0:
            _ds = _age_s(E["dernier_signal"])
            print(f"[eclaireur_actu] {E['passages']} passage(s) · rien de "
                  f"nouveau sur le forum · dernier signal : "
                  + (f"il y a {_ds / 60:.0f} min" if _ds is not None
                     else "jamais depuis le démarrage"))
    except Exception as ex:
        E["erreurs"] += 1
        print(f"[eclaireur_actu] {type(ex).__name__}: {ex}")


