class LogsPanelV2(LayoutView):
    """Panneau Logs Unifiés : configurer le salon + catégories actives."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        if await ulogger2026.mode_site(self.g.id):
            return await self._rendre_site(interaction, edit)
        chan_id = await ulogger2026.get_log_channel(self.g.id)
        cats_enabled = await ulogger2026.get_enabled_categories(self.g.id)
        all_cats = sorted(set(m["cat"] for m in ulogger2026.EVENT_META.values()))
        log_ch = self.g.get_channel(chan_id) if chan_id else None
        wh_mode = await ulogger2026.get_webhook_mode(self.g.id)

        self.clear_items()

        # Section header
        items: list = []
        items.append(visuels.bandeau("logs", "Logs unifiés"))
        items.append(v2_subtitle("Un salon · tous les événements"))
        items.append(v2_divider())

        # ─── État du salon (radio visuel) ───
        if log_ch:
            chan_line = f"🔘 **Salon actif** · {log_ch.mention}"
        elif chan_id:
            chan_line = f"⚠️ **Salon configuré mais introuvable** (`{chan_id}`)"
        else:
            chan_line = "⚪ **Salon non défini** — logs unifiés désactivés"
        items.append(v2_body(chan_line))

        # ─── Catégories (checkbox visuel) ───
        if log_ch:
            items.append(v2_divider())
            cat_emojis = {
                "Modération": "🔨", "Sécurité": "🛡️", "Membres": "👥",
                "Messages": "💬", "Vocal": "🎤", "Serveur": "🏷️",
                "Tickets": "🎫", "Config": "⚙️",
            }
            cats_lines = []
            for c in all_cats:
                icon = "✅" if c in cats_enabled else "☐"
                emoji = cat_emojis.get(c, "📋")
                cats_lines.append(f"{icon} {emoji} {c}")
            items.append(v2_title("Catégories", level=3))
            items.append(v2_body("\n".join(cats_lines)))
            items.append(v2_body(
                "**Mode webhook :** "
                + ("🟢 ON — chaque catégorie a son expéditeur (« 🛡️ Sécurité »…)"
                   if wh_mode else "⚪ OFF — envoi classique par le bot")
            ))

        items.append(v2_divider())

        # ─── Boutons ───
        if log_ch:
            b_chan = Button(emoji=visuels.icone("position"), label="Changer salon", style=discord.ButtonStyle.primary, custom_id="logsv2_chan")
            b_chan.callback = self._cb_set_channel
            b_cats = Button(emoji=visuels.icone("curseurs"), label="Catégories", style=discord.ButtonStyle.primary, custom_id="logsv2_cats")
            b_cats.callback = self._cb_categories
            b_events = Button(emoji=visuels.icone("recherche"), label="Détail par évènement", style=discord.ButtonStyle.primary, custom_id="logsv2_evts")
            b_events.callback = self._cb_events
            b_excl = Button(emoji=visuels.icone("bouclier"), label="Rôles épargnés", style=discord.ButtonStyle.primary, custom_id="logsv2_excl")
            b_excl.callback = self._cb_exclusions
            # Phase 158 : bouton Salons sécurité (honeypot, staff sanction)
            b_sec = Button(emoji=visuels.icone("bouclier"), label="Salons sécurité", style=discord.ButtonStyle.primary, custom_id="logsv2_sec")
            b_sec.callback = self._cb_security_channels
            # Phase 268 : router chaque catégorie vers un salon dédié
            b_route = Button(emoji=visuels.icone("cible"), label="Salon par catégorie", style=discord.ButtonStyle.primary, custom_id="logsv2_route")
            b_route.callback = self._cb_routing
            # Phase 268 : mode webhook (expéditeur au nom de la catégorie)
            b_wh = Button(
                emoji=(visuels.icone("actu") if wh_mode else visuels.icone("actu")), label=("Webhook : ON" if wh_mode else "Webhook : OFF"),
                style=(discord.ButtonStyle.success if wh_mode else discord.ButtonStyle.secondary),
                custom_id="logsv2_wh",
            )
            b_wh.callback = self._cb_toggle_webhook
            b_clear = Button(emoji='⚪', label="Désactiver", style=discord.ButtonStyle.danger, custom_id="logsv2_clear")
            b_clear.callback = self._cb_disable
            b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_back")
            b_back.callback = self._cb_back
            items.append(discord.ui.ActionRow(b_chan, b_cats, b_events, b_excl))
            items.append(discord.ui.ActionRow(b_sec, b_route, b_wh, b_clear, b_back))
        else:
            b_chan = Button(emoji=visuels.icone("position"), label="Définir le salon", style=discord.ButtonStyle.success, custom_id="logsv2_chan")
            b_chan.callback = self._cb_set_channel
            # Phase 158 : même sans log unifié, on peut configurer les salons sécurité
            b_sec = Button(emoji=visuels.icone("bouclier"), label="Salons sécurité", style=discord.ButtonStyle.primary, custom_id="logsv2_sec")
            b_sec.callback = self._cb_security_channels
            b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_back")
            b_back.callback = self._cb_back
            items.append(discord.ui.ActionRow(b_chan, b_sec, b_back))

        self.add_item(v2_container(*items, color=Palette.INFO if log_ch else Palette.NEUTRAL))

        await _afficher_panneau(self, interaction, edit)

    async def _rendre_site(self, interaction, edit):
        """19/10/2026 : plus aucun log sur Discord. Ce qui reste réglable filtre le journal du site.
        24/10/2026 : plus de bouton « Catégories » — le site garde tout (`log_event` consigne avant ce
        filtre) et les alertes passent toujours : il ne changeait rien."""
        self.clear_items()
        c = await cfg(self.g.id)
        salon = self.g.get_channel(int(c.get('tableau_salon', 0) or 0))
        boutons = []
        for emoji, label, cid, cb in (("recherche", "Détail par évènement", "logsv2_evts", self._cb_events),
                                      ("bouclier", "Rôles épargnés", "logsv2_excl", self._cb_exclusions),
                                      ("alerte", "Salons sécurité", "logsv2_sec", self._cb_security_channels),
                                      ("retour", "Retour", "logsv2_back", self._cb_back)):
            b = Button(emoji=visuels.icone(emoji), label=label, custom_id=cid,
                       style=discord.ButtonStyle.secondary if cid == "logsv2_back" else discord.ButtonStyle.primary)
            b.callback = cb
            boutons.append(b)
        self.add_item(v2_container(
            visuels.bandeau("logs", "Logs du serveur"),
            v2_subtitle("Sur le site · plus aucun log sur Discord"),
            v2_divider(),
            v2_body("🌐 **Tout est consigné sur le site**, lisible par personne, nettoyé tout seul "
                    "(messages et vocal 30 jours, le reste 90 jours).\n"
                    + (f"Lien personnel : {salon.mention} → « Ouvrir le tableau de bord ».\n" if salon else "")
                    + "-# Discord ne reçoit plus que les alertes qui demandent une réaction. Le détail par "
                      "évènement et les rôles épargnés choisissent ce qui n'est pas consigné."),
            v2_divider(),
            discord.ui.ActionRow(*boutons[:3]), discord.ui.ActionRow(*boutons[3:]),
            color=Palette.INFO))
        await _afficher_panneau(self, interaction, edit)

    async def _cb_set_channel(self, i):
        async def _save_log_channel(guild_id: int, channel_id: int):
            await ulogger2026.set_log_channel(guild_id, channel_id)

        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key="_unified_log_channel",  # ignored, save_fn handles it
            return_panel_factory=lambda: LogsPanelV2(self.u, self.g),
            title="Salon de logs unifiés",
            description="Choisis le salon où arriveront tous les évènements.",
            color=0x3498DB,
            save_fn=_save_log_channel,
        )
        await v.render_to(i, edit=True)

    async def _cb_categories(self, i):
        v = LogsCategoriesPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_routing(self, i):
        # Phase 268 : routage par catégorie (1 salon par type de log)
        v = LogsRoutingPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_toggle_webhook(self, i):
        # Phase 268 : bascule le mode webhook (expéditeur au nom de la catégorie)
        try:
            cur = await ulogger2026.get_webhook_mode(self.g.id)
            await ulogger2026.set_webhook_mode(self.g.id, not cur)
        except Exception as ex:
            print(f"[LogsPanelV2 toggle_webhook] {ex}")
        await self.render_to(i, edit=True)

    async def _cb_events(self, i):
        # Phase 26.3 : toggle par event-type précis
        v = LogsEventsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_exclusions(self, i):
        # Phase 26.3 : rôles épargnés par event
        v = LogsExclusionsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_disable(self, i):
        try:
            await ulogger2026.set_log_channel(self.g.id, 0)
        except Exception as ex:
            print(f"[LogsPanelV2 disable] {ex}")
        await self.render_to(i, edit=True)

    async def _cb_security_channels(self, i):
        """Phase 158 : ouvre le panel salons sécurité."""
        v = SecurityChannelsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        # Refonte 2026-08 : passer par render_to(), sinon la racine s'affiche
        # sans son résumé d'état (celui-ci est lu en base, donc en async).
        await MainPanelV2(self.u, self.g).render_to(i, edit=True)


class SecurityChannelsPanelV2(LayoutView):
    """Phase 158/163.4 : sous-panel pour configurer les salons spécifiques.

    Permet à l'owner de pointer chaque feature vers un salon dédié
    (au lieu d'auto-créer des salons avec des noms imposés).

    Salons configurables :
    - 🍯 Honeypot : salon piège que l'owner crée avec n'importe quel nom
      (suggéré : 🎁-claim-free-nitro pour appâter les bots scrapers)
    - 🚨 Staff Sanction : salon où le bot pose les panels d'action quand
      un module détecte une infraction (Mute/Warn/Kick/Ban)
    """

    CHANNEL_KEYS = [
        ("honeypot_channel_id", "🍯 Honeypot",
         "Salon piège anti-bot — doit être invisible aux humains. "
         "Quiconque poste dedans = compte 99% piraté ou self-bot. "
         "Action : mute 24h auto + alerte staff."),
        ("staff_sanction_channel_id", "🚨 Staff Sanction",
         "Salon où le bot envoie les panels d'action quand un module "
         "(token grabber, webhook leak, honeypot, anomaly) détecte "
         "une infraction. Boutons Mute/Warn/Kick/Ban."),
    ]

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        cfg_data = await db_get(self.g.id)
        self.clear_items()

        items: list = []
        items.append(visuels.bandeau("salons_securite", "Salons sécurité"))
        items.append(v2_subtitle(
            "Configure chaque salon de sécurité individuellement"
        ))
        items.append(v2_divider())

        for key, label, desc in self.CHANNEL_KEYS:
            ch_id = int(cfg_data.get(key, 0) or 0)
            ch = self.g.get_channel(ch_id) if ch_id else None
            if ch:
                state_line = f"🔘 **{label}** · {ch.mention}"
            elif ch_id:
                state_line = (
                    f"⚠️ **{label}** · ID `{ch_id}` introuvable"
                )
            else:
                state_line = f"⚪ **{label}** · _non défini_"
            items.append(v2_body(state_line))
            items.append(v2_body(f"_{desc}_"))
            items.append(v2_divider())

        items.append(v2_subtitle(
            "Crée le salon dans Discord, puis lie-le ici"
        ))

        self.add_item(v2_container(*items, color=0xE74C3C))

        # Boutons par feature — Phase 235.5 : un bouton NU est interdit en
        # top-level d'une LayoutView (400 50035) → grouper en ActionRow (max 5/row).
        _sec_btns = []
        for key, label, _ in self.CHANNEL_KEYS:
            btn = Button(
                emoji=visuels.icone("position"), label=f"Définir : {label}",
                style=discord.ButtonStyle.primary,
                custom_id=f"secch_set_{key}",
            )

            async def _cb(i_inter: discord.Interaction, _k=key, _l=label):
                await self._open_picker(i_inter, _k, _l)

            btn.callback = _cb
            _sec_btns.append(btn)

        b_back = Button(
            emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary,
            custom_id="secch_back",
        )
        b_back.callback = self._cb_back
        _sec_btns.append(b_back)
        for _k in range(0, len(_sec_btns), 5):
            self.add_item(discord.ui.ActionRow(*_sec_btns[_k:_k + 5]))

        if edit:
            #  `_afficher_panneau` : aussi après un `defer()` (retour du sélecteur ci-dessous).
            try:
                await _afficher_panneau(self, interaction, True)
            except discord.HTTPException as ex:
                _logerr("salons_securite.panneau", ex, guild_id=self.g.id)

    async def _open_picker(
        self, i: discord.Interaction, cfg_key: str, label: str,
    ):
        """Le choix du salon, à la place du panneau ; le panneau revient ensuite, relu en base.
        24/10/2026 : le sélecteur partait dans un message à part, remplacé après le choix par un
        panneau jamais construit (vide) — et le vrai panneau affichait toujours « non défini »."""
        async def _salon_habite(ch) -> bool:
            """Des membres ont-ils déjà écrit ici (50 derniers messages) ? Illisible : oui, par prudence."""
            try:
                async for m in ch.history(limit=50):
                    if not m.author.bot and m.webhook_id is None:
                        return True
                return False
            except discord.HTTPException:
                return True
        sel = discord.ui.ChannelSelect(
            channel_types=[discord.ChannelType.text],
            placeholder=f"Choisir le salon pour {label}",
            min_values=1, max_values=1,
        )

        async def _on_pick(i_pick: discord.Interaction):
            if not sel.values:
                return await i_pick.response.send_message(
                    "❌ Aucun salon choisi.", ephemeral=True
                )
            picked = sel.values[0]
            # Répondre d'abord : verrouiller le salon-piège pose des droits un par un (20/10/2026 :
            # l'interaction expirait au-delà de 6 rôles).
            await i_pick.response.defer()
            try:
                real_ch = self.g.get_channel(int(picked.id))
                if cfg_key == "honeypot_channel_id":
                    if real_ch is None:
                        return await i_pick.followup.send("❌ Salon introuvable.", ephemeral=True)
                    if await _salon_habite(real_ch):
                        return await i_pick.followup.send(
                            "❌ Des membres ont déjà écrit dans ce salon. Le salon-piège devient invisible "
                            "pour tout le monde : crée un salon neuf et vide pour lui.", ephemeral=True)
                if not await db_set(self.g.id, cfg_key, int(picked.id)):
                    return await i_pick.followup.send("❌ Le salon n'a pas pu être enregistré.", ephemeral=True)
                extra = ""
                if cfg_key == "honeypot_channel_id":
                    result = await honeypot_module.apply_honeypot_perms(real_ch)
                    extra = (f"\n🔒 Salon verrouillé : {'OK' if result['success'] else 'partiel'}"
                             f" ({len(result.get('errors', []))} erreur(s))")
                await i_pick.followup.send(f"✅ **{label}** défini : <#{picked.id}>{extra}", ephemeral=True)
            except Exception as ex:
                _logerr("salons_securite.choix", ex, guild_id=self.g.id)
                await i_pick.followup.send("❌ Le salon n'a pas pu être réglé.", ephemeral=True)
            finally:
                # Le vrai panneau, reconstruit et relu en base, revient à la place du sélecteur :
                # l'état réel, choix refusé compris.
                await SecurityChannelsPanelV2(self.u, self.g).render_to(i_pick, edit=True)

        sel.callback = _on_pick
        b_retour = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary)

        async def _retour(i_ret: discord.Interaction):
            await SecurityChannelsPanelV2(self.u, self.g).render_to(i_ret, edit=True)
        b_retour.callback = _retour
        self.clear_items()
        self.add_item(v2_container(v2_body(f"Choisis le salon pour **{label}** :"),
                                   discord.ui.ActionRow(sel), discord.ui.ActionRow(b_retour), color=0xE74C3C))
        await _afficher_panneau(self, i, True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


_LOG_CAT_EMOJIS = {
    "Modération": "🔨", "Sécurité": "🛡️", "Membres": "👥",
    "Messages": "💬", "Vocal": "🎤", "Serveur": "🏷️",
    "Tickets": "🎫", "Config": "⚙️",
}


class LogsRoutingPanelV2(LayoutView):
    """Phase 268 (demande owner) : router CHAQUE catégorie de logs vers un salon
    dédié. Sans routage explicite, une catégorie retombe sur le salon global."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        global_id = await ulogger2026.get_log_channel(self.g.id)
        cat_map = await ulogger2026.get_category_channels(self.g.id)
        g_ch = self.g.get_channel(global_id) if global_id else None

        self.clear_items()
        items: list = []
        items.append(visuels.bandeau("logs_routage", "Salon par catégorie"))
        items.append(v2_subtitle("Un salon par type de log"))
        items.append(v2_divider())
        items.append(v2_body(
            f"**Salon global** (par défaut) : "
            f"{g_ch.mention if g_ch else '⚪ non défini'}"
        ))
        lines = []
        for cat in ulogger2026.LOG_CATEGORIES:
            emoji = _LOG_CAT_EMOJIS.get(cat, "📋")
            cid = cat_map.get(cat)
            if cid:
                ch = self.g.get_channel(cid)
                dest = ch.mention if ch else f"⚠️ introuvable (`{cid}`)"
            else:
                dest = "_→ salon global_"
            lines.append(f"{emoji} **{cat}** · {dest}")
        items.append(v2_body("\n".join(lines)))
        items.append(v2_divider())
        items.append(v2_body(
            "🟢 Serveur · 🟠 Sanctions · 🔴 Sécurité — un salon et un interrupteur chacun"))

        opts = [
            discord.SelectOption(label=cat, value=cat, emoji=_LOG_CAT_EMOJIS.get(cat, "📋"))
            for cat in ulogger2026.LOG_CATEGORIES
        ]
        sel = Select(
            placeholder="Catégorie à router…",
            min_values=1, max_values=1,
            options=opts,
        )
        sel.callback = self._cb_pick
        items.append(discord.ui.ActionRow(sel))

        b_ev = Button(emoji=visuels.icone("detail"), label="Par évènement précis", style=discord.ButtonStyle.primary, custom_id="logsroute_ev")
        b_ev.callback = self._cb_event_routing
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsroute_back")
        b_back.callback = self._cb_back
        # 3 NIVEAUX (owner 2026-06-21) : chaque bouton = 1 salon + activer/désactiver le groupe.
        b_lo = Button(emoji='🟢', label="Logs faibles", style=discord.ButtonStyle.success, custom_id="logslvl_faible")
        b_lo.callback = lambda ii: self._cb_level(ii, 'faible')
        b_mi = Button(emoji='🟠', label="Logs moyens", style=discord.ButtonStyle.success, custom_id="logslvl_moyen")
        b_mi.callback = lambda ii: self._cb_level(ii, 'moyen')
        b_hi = Button(emoji='🔴', label="Logs forts", style=discord.ButtonStyle.danger, custom_id="logslvl_fort")
        b_hi.callback = lambda ii: self._cb_level(ii, 'fort')
        items.append(discord.ui.ActionRow(b_lo, b_mi, b_hi))
        items.append(discord.ui.ActionRow(b_ev, b_back))

        self.add_item(v2_container(*items, color=Palette.INFO))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_event_routing(self, i):
        v = LogsEventRoutingPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_level(self, i, level_key):
        v = LogLevelPanelV2(self.u, self.g, level_key)
        await v.render_to(i, edit=True)

    async def _cb_pick(self, i):
        try:
            cat = (i.data.get('values') or [None])[0]
        except Exception:
            cat = None
        if not cat or cat not in ulogger2026.LOG_CATEGORIES:
            return await self.render_to(i, edit=True)

        async def _save_cat_channel(guild_id, channel_id):
            # channel_id == 0 ⇒ on retire le routage (retour au salon global)
            await ulogger2026.set_category_channel(guild_id, cat, int(channel_id or 0))

        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key=f"_logcat_{cat}",  # ignoré : save_fn gère tout
            return_panel_factory=lambda: LogsRoutingPanelV2(self.u, self.g),
            title=f"Salon pour « {cat} »",
            description=(
                f"Choisis le salon où arriveront les logs **{cat}**.\n"
                f"_Efface la sélection pour repasser au salon global._"
            ),
            color=0x3498DB,
            save_fn=_save_cat_channel,
        )
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class LogLevelPanelV2(LayoutView):
    """3 NIVEAUX de logs (owner 2026-06-21) : 🟢 faible (serveur) · 🟠 moyen (sanctions) ·
    🔴 fort (cybersécurité). Pour CHAQUE niveau : 1 salon (toutes ses catégories y vont) +
    activer/désactiver. S'appuie sur set_category_channel + enabled_categories existants."""

    _LEVELS = {
        'faible': {'emoji': '🟢', 'name': 'faibles · serveur',
                   'cats': ("Membres", "Messages", "Vocal", "Serveur", "Tickets", "Config"),
                   'desc': "arrivées/départs · messages supprimés · vocal · salons/rôles · tickets · config"},
        'moyen': {'emoji': '🟠', 'name': 'moyens · sanctions',
                  'cats': ("Modération",),
                  'desc': "sanctions staff : mute · warn · kick · ban · timeout · purge · lock"},
        'fort': {'emoji': '🔴', 'name': 'forts · cybersécurité',
                 'cats': ("Sécurité",),
                 'desc': "raids · phishing · scam · insultes · NSFW · alts · escalades · profils à surveiller"},
    }

    def __init__(self, u, g, level_key):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.level_key = level_key if level_key in self._LEVELS else 'faible'

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        lvl = self._LEVELS[self.level_key]
        cats = lvl['cats']
        cat_map = await ulogger2026.get_category_channels(self.g.id)
        enabled = await ulogger2026.get_enabled_categories(self.g.id)
        cid = cat_map.get(cats[0]) or 0
        ch = self.g.get_channel(cid) if cid else None
        is_on = all(c in enabled for c in cats)

        self.clear_items()
        items = [
            visuels.bandeau("logs", "Logs"),
            v2_title(f"Logs {lvl['name']}", level=3),
            v2_subtitle(f"_{lvl['desc']}_"),
            v2_divider(),
            v2_body(
                f"**Salon** : {ch.mention if ch else '⚪ non défini (→ salon global)'}\n"
                f"**État** : {'✅ Activé' if is_on else 'Désactivé'}"),
        ]
        b_ch = Button(emoji=visuels.icone("position"), label="Choisir le salon", style=discord.ButtonStyle.primary, custom_id="loglvl_ch")
        b_ch.callback = self._cb_pick_channel
        b_tog = Button(
            emoji=(visuels.icone("interdit") if is_on else visuels.icone("valider")), label=("Désactiver" if is_on else "Activer"),
            style=(discord.ButtonStyle.danger if is_on else discord.ButtonStyle.success),
            custom_id="loglvl_tog")
        b_tog.callback = self._cb_toggle
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="loglvl_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_ch, b_tog, b_back))
        self.add_item(v2_container(*items, color=Palette.INFO))
        await _afficher_panneau(self, interaction, edit)

    async def _cb_pick_channel(self, i):
        cats = self._LEVELS[self.level_key]['cats']

        async def _save(guild_id, channel_id):
            for _cat in cats:
                try:
                    await ulogger2026.set_category_channel(guild_id, _cat, int(channel_id or 0))
                except Exception:
                    pass
            # Choisir un salon ACTIVE aussi le niveau (sinon rien ne s'y afficherait).
            if channel_id:
                try:
                    _en = set(await ulogger2026.get_enabled_categories(guild_id))
                    await ulogger2026.set_enabled_categories(guild_id, _en | set(cats))
                except Exception:
                    pass

        lvl = self._LEVELS[self.level_key]
        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key="_loglevel",  # ignoré : _save gère tout
            return_panel_factory=lambda: LogLevelPanelV2(self.u, self.g, self.level_key),
            title=f"{lvl['emoji']} Salon des logs {lvl['name']}",
            description=(
                "Choisis LE salon qui recevra ces logs.\n"
                "_Efface la sélection pour repasser au salon global._"),
            color=0x3498DB,
            save_fn=_save,
        )
        await v.render_to(i, edit=True)

    async def _cb_toggle(self, i):
        cats = self._LEVELS[self.level_key]['cats']
        try:
            en = set(await ulogger2026.get_enabled_categories(self.g.id))
            if all(c in en for c in cats):
                en -= set(cats)  # tout activé → on désactive le groupe
            else:
                en |= set(cats)  # on (ré)active le groupe
            await ulogger2026.set_enabled_categories(self.g.id, en)
        except Exception as ex:
            print(f"[LogLevelPanelV2 toggle] {ex}")
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsRoutingPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class LogsEventRoutingPanelV2(LayoutView):
    """Phase 268 — routage au niveau de l'ÉVÈNEMENT précis (ex: sec.phishing seul).
    Priorité : override évènement > salon de catégorie > salon global."""

    def __init__(self, u, g, cat=None):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.cat = cat  # catégorie sélectionnée (filtre)

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        ev_map = await ulogger2026.get_event_channels(self.g.id)

        self.clear_items()
        items: list = []
        items.append(visuels.bandeau("logs_evenement", "Salon par évènement"))
        items.append(v2_subtitle("Encore plus fin : un salon dédié pour UN type d'évènement"))
        items.append(v2_divider())

        cat_opts = [
            discord.SelectOption(label=c, value=c, emoji=_LOG_CAT_EMOJIS.get(c, "📋"),
                                 default=(c == self.cat))
            for c in ulogger2026.LOG_CATEGORIES
        ]
        cat_sel = Select(placeholder="1) Catégorie…", min_values=1, max_values=1, options=cat_opts)
        cat_sel.callback = self._cb_cat
        items.append(discord.ui.ActionRow(cat_sel))

        if self.cat:
            evs = [(et, m) for et, m in ulogger2026.EVENT_META.items() if m["cat"] == self.cat]
            lines, ev_opts = [], []
            for et, m in evs:
                cid = ev_map.get(et.value)
                if cid:
                    ch = self.g.get_channel(cid)
                    dest = ch.mention if ch else f"⚠️ introuvable (`{cid}`)"
                else:
                    dest = "_→ salon de catégorie / global_"
                lines.append(f"{m['icon']} **{m['label']}** · {dest}")
                ev_opts.append(discord.SelectOption(
                    label=m["label"][:100], value=et.value, emoji=m["icon"]))
            items.append(v2_body("\n".join(lines)))
            ev_sel = Select(placeholder="2) Évènement à router…", min_values=1, max_values=1,
                            options=ev_opts[:25])
            ev_sel.callback = self._cb_event
            items.append(discord.ui.ActionRow(ev_sel))

        items.append(v2_divider())
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsevroute_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.INFO))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_cat(self, i):
        try:
            self.cat = (i.data.get('values') or [None])[0]
        except Exception:
            self.cat = None
        await self.render_to(i, edit=True)

    async def _cb_event(self, i):
        try:
            ev = (i.data.get('values') or [None])[0]
        except Exception:
            ev = None
        if not ev:
            return await self.render_to(i, edit=True)
        cat = self.cat

        async def _save_event_channel(guild_id, channel_id):
            await ulogger2026.set_event_channel(guild_id, ev, int(channel_id or 0))

        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key=f"_logev_{ev}",  # ignoré : save_fn gère tout
            return_panel_factory=lambda: LogsEventRoutingPanelV2(self.u, self.g, cat=cat),
            title=f"Salon pour « {ev} »",
            description=(
                "Salon dédié à CET évènement (prioritaire sur la catégorie).\n"
                "_Efface la sélection pour revenir au salon de catégorie._"
            ),
            color=0x3498DB,
            save_fn=_save_event_channel,
        )
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsRoutingPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class LogsCategoriesPanelV2(LayoutView):
    """Sous-panel : toggle des catégories de logs."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        cats_enabled = await ulogger2026.get_enabled_categories(self.g.id)
        all_cats = sorted(set(m["cat"] for m in ulogger2026.EVENT_META.values()))

        self.clear_items()
        items: list = []
        items.append(visuels.bandeau("logs_categories", "Catégories de logs"))
        items.append(v2_subtitle("Coche/décoche les catégories à logger dans le salon unifié"))
        items.append(v2_divider())

        # Compter combien d'event types par catégorie
        cat_counts = {}
        for ev_type, meta in ulogger2026.EVENT_META.items():
            cat_counts[meta["cat"]] = cat_counts.get(meta["cat"], 0) + 1

        cat_emojis = {
            "Modération": "🔨", "Sécurité": "🛡️", "Membres": "👥",
            "Messages": "💬", "Vocal": "🎤", "Serveur": "🏷️",
            "Tickets": "🎫", "Config": "⚙️",
        }

        lines = []
        for c in all_cats:
            emoji = cat_emojis.get(c, "📋")
            count = cat_counts.get(c, 0)
            state = "✅ Activée" if c in cats_enabled else "❌ Désactivée"
            lines.append(f"{emoji} **{c}** · {count} types d'évènements · {state}")
        items.append(v2_body("\n".join(lines)))
        items.append(v2_divider())
        items.append(v2_subtitle("Utilise le menu ci-dessous pour cocher/décocher"))

        # Select multi avec defaults
        opts = []
        for c in all_cats:
            opts.append(discord.SelectOption(
                label=c,
                value=c,
                default=(c in cats_enabled),
                emoji=cat_emojis.get(c, "📋"),
                description=f"{cat_counts.get(c, 0)} types d'évènements",
            ))
        sel = Select(
            placeholder="Catégories actives…",
            min_values=0,
            max_values=len(opts),
            options=opts,
        )
        sel.callback = self._cb_select
        items.append(discord.ui.ActionRow(sel))

        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2cats_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.PRIMARY))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_select(self, i):
        try:
            chosen = set(i.data.get('values', []))
            await ulogger2026.set_enabled_categories(self.g.id, chosen)
        except Exception as ex:
            print(f"[LogsCategoriesPanelV2 _cb_select] {ex}")
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


# ═══════════════════════════════════════════════════════════════════════════════
#  📋 Phase 26.3 : LogsEventsPanelV2 — toggle individuel par event_type
# ═══════════════════════════════════════════════════════════════════════════════

class LogsEventsPanelV2(LayoutView):
    """Phase 26.3 — toggle individuel par event_type (en plus des catégories).

    Permet de désactiver précisément certains événements (ex: 'msg.delete' uniquement)
    sans toucher à la catégorie entière.
    """

    def __init__(self, u, g, category: str = None):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.category = category  # filtre par catégorie ; None = toutes

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit: bool = True):
        all_cats = sorted(set(m["cat"] for m in ulogger2026.EVENT_META.values()))
        disabled = await ulogger2026.get_disabled_events(self.g.id)

        # Si aucune catégorie choisie : afficher select catégorie
        self.clear_items()
        items = [
            visuels.bandeau("logs_details", "Détail par évènement"),
            v2_subtitle("Active/désactive chaque type d'évènement individuellement"),
            v2_divider(),
        ]

        if self.category is None:
            # Étape 1 : choix de la catégorie
            opts = []
            cat_emojis = {
                "Modération": "🔨", "Sécurité": "🛡️", "Membres": "👥",
                "Messages": "💬", "Vocal": "🎤", "Serveur": "🏷️",
                "Tickets": "🎫", "Config": "⚙️",
            }
            for c in all_cats:
                count = sum(1 for m in ulogger2026.EVENT_META.values() if m["cat"] == c)
                opts.append(discord.SelectOption(
                    label=c, value=c, emoji=cat_emojis.get(c, "📋"),
                    description=f"{count} types d'évènements",
                ))
            sel = Select(placeholder="Choisis une catégorie…", options=opts[:25])
            sel.callback = self._cb_pick_cat
            items.append(v2_body("Étape 1 : choisis la catégorie à détailler."))
            items.append(discord.ui.ActionRow(sel))
        else:
            # Étape 2 : toggles des events de la catégorie
            ev_items = [(ev, meta) for ev, meta in ulogger2026.EVENT_META.items() if meta["cat"] == self.category]
            ev_items.sort(key=lambda x: x[1]["label"])

            # Construire le multi-select avec defaults selon disabled
            sel_opts = []
            for ev, meta in ev_items[:25]:
                value = ev.value
                is_enabled = value not in disabled
                sel_opts.append(discord.SelectOption(
                    label=meta["label"][:80],
                    value=value,
                    description=f"`{value}`"[:90],
                    emoji=meta["icon"],
                    default=is_enabled,
                ))
            sel = Select(
                placeholder=f"Évènements actifs dans « {self.category} »…",
                min_values=0, max_values=len(sel_opts),
                options=sel_opts,
            )
            sel.callback = self._cb_pick_events

            items.append(v2_body(
                f"**Catégorie :** {self.category}\n"
                f"Coche/décoche pour activer ou désactiver chaque type.\n"
                f"_Si la catégorie est désactivée globalement (`Catégories`), tout est skippé peu importe ces toggles._"
            ))
            items.append(v2_divider())
            items.append(discord.ui.ActionRow(sel))

            b_change_cat = Button(emoji=visuels.icone("annuler"), label="Changer de catégorie", style=discord.ButtonStyle.secondary)
            b_change_cat.callback = self._cb_change_cat
            items.append(discord.ui.ActionRow(b_change_cat))

        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_evts_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.PRIMARY))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_pick_cat(self, i):
        try:
            cat = i.data['values'][0]
            self.category = cat
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsEventsPanelV2 _cb_pick_cat] {ex}")

    async def _cb_pick_events(self, i):
        try:
            chosen = set(i.data.get('values', []))
            disabled = await ulogger2026.get_disabled_events(self.g.id)

            # Tous les events de la catégorie courante
            cat_events = {
                ev.value for ev, meta in ulogger2026.EVENT_META.items()
                if meta["cat"] == self.category
            }
            # On retire de disabled tous ceux de cette catégorie, puis on ajoute ceux non cochés
            new_disabled = set(disabled) - cat_events
            for ev_value in cat_events:
                if ev_value not in chosen:
                    new_disabled.add(ev_value)

            await ulogger2026.set_disabled_events(self.g.id, new_disabled)
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsEventsPanelV2 _cb_pick_events] {ex}")

    async def _cb_change_cat(self, i):
        self.category = None
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


# ═══════════════════════════════════════════════════════════════════════════════
#  🛡️ Phase 26.3 : LogsExclusionsPanelV2 — rôles épargnés par event
# ═══════════════════════════════════════════════════════════════════════════════

class LogsExclusionsPanelV2(LayoutView):
    """Phase 26.3 — pour chaque event_type, choisir les rôles épargnés.

    Si un membre concerné (user ou modérateur) a l'un des rôles épargnés,
    le log n'est PAS envoyé. Utile pour ne pas pister les actions du staff.
    """

    def __init__(self, u, g, selected_event: str = None):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.selected_event = selected_event  # ex: 'msg.delete'
        self.selected_cat = None              # ex: 'Messages' (étape 1)

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit: bool = True):
        exclusions = await ulogger2026.get_role_exclusions(self.g.id)

        self.clear_items()
        items = [
            visuels.bandeau("logs_exclusions", "Rôles épargnés"),
            v2_subtitle("Choisis quels rôles ne doivent JAMAIS apparaître dans tel ou tel log"),
            v2_divider(),
        ]

        if not self.selected_event and not self.selected_cat:
            # Étape 1 : la catégorie. 50 évènements, un menu Discord en montre 25 : avant le
            # 20/10/2026, seuls Modération et Sécurité étaient réglables.
            cats: dict = {}
            for ev, meta in ulogger2026.EVENT_META.items():
                compte = cats.setdefault(meta['cat'], [0, 0])
                compte[0] += 1
                compte[1] += 1 if exclusions.get(ev.value) else 0
            opts = [discord.SelectOption(label=cat[:80], value=cat[:100],
                                         description=(f"{n} évènement(s)" + (f" · {k} avec rôles épargnés" if k else ""))[:90])
                    for cat, (n, k) in sorted(cats.items())][:25]
            sel = Select(placeholder="Choisis une catégorie…", options=opts)
            sel.callback = self._cb_pick_cat

            # Résumé : combien d'events ont des exclusions
            with_excl = sum(1 for v in exclusions.values() if v)
            items.append(v2_body(
                f"**Statut :** `{with_excl}` type(s) d'évènements ont des rôles épargnés.\n\n"
                f"_Cas d'usage : si tu mets le rôle Owner épargné sur `msg.delete`, "
                f"quand tu supprimes un message, ça n'apparaît pas dans les logs._"
            ))
            items.append(v2_divider())
            items.append(discord.ui.ActionRow(sel))
        elif not self.selected_event:
            # Étape 2 : un évènement de cette catégorie
            opts = []
            for ev, meta in ulogger2026.EVENT_META.items():
                if meta['cat'] != self.selected_cat:
                    continue
                excl_count = len(exclusions.get(ev.value, []) or [])
                opts.append(discord.SelectOption(
                    label=f"{meta['label']}"[:80], value=ev.value, emoji=meta["icon"],
                    description=(f"{excl_count} rôle(s) épargné(s)" if excl_count else "aucun rôle épargné")[:90]))
            sel = Select(placeholder=f"{self.selected_cat} : choisis un évènement…", options=opts[:25])
            sel.callback = self._cb_pick_event
            b_cats = Button(emoji=visuels.icone("annuler"), label="Autre catégorie", style=discord.ButtonStyle.secondary)
            b_cats.callback = self._cb_change_cat
            items.append(discord.ui.ActionRow(sel))
            items.append(discord.ui.ActionRow(b_cats))
        else:
            # Étape 2 : RoleSelect pour cet event
            meta = ulogger2026.EVENT_META.get(_resolve_event_type(self.selected_event), {})
            current_role_ids = exclusions.get(self.selected_event, []) or []
            current_roles = [self.g.get_role(rid) for rid in current_role_ids if self.g.get_role(rid)]

            current_str = ", ".join(r.mention for r in current_roles) if current_roles else "_aucun_"

            items.append(v2_body(
                f"**Évènement :** {meta.get('icon', '📋')} {meta.get('label', self.selected_event)}\n"
                f"`{self.selected_event}`\n\n"
                f"**Rôles actuellement épargnés :** {current_str}"
            ))
            items.append(v2_divider())

            role_sel = discord.ui.RoleSelect(
                placeholder="Choisis les rôles épargnés (multi)…",
                min_values=0,
                max_values=10,
                custom_id="logsv2_excl_roles",
            )
            role_sel.callback = self._cb_pick_roles
            items.append(discord.ui.ActionRow(role_sel))

            b_change = Button(emoji=visuels.icone("annuler"), label="Autre évènement", style=discord.ButtonStyle.secondary)
            b_change.callback = self._cb_change_event
            items.append(discord.ui.ActionRow(b_change))

        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_excl_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.PRIMARY))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_pick_cat(self, i):
        self.selected_cat = i.data['values'][0]
        await self.render_to(i, edit=True)

    async def _cb_change_cat(self, i):
        self.selected_cat = None
        await self.render_to(i, edit=True)

    async def _cb_pick_event(self, i):
        self.selected_event = i.data['values'][0]
        await self.render_to(i, edit=True)

    async def _cb_pick_roles(self, i):
        try:
            role_ids = [int(rid) for rid in i.data.get('values', [])]
            exclusions = await ulogger2026.get_role_exclusions(self.g.id)
            exclusions[self.selected_event] = role_ids
            await ulogger2026.set_role_exclusions(self.g.id, exclusions)
        except Exception as ex:
            _logerr("logs.exclusions", ex, guild_id=self.g.id)
            return await i.response.send_message("❌ Les rôles épargnés n'ont pas pu être enregistrés.",
                                                 ephemeral=True)
        await self.render_to(i, edit=True)

    async def _cb_change_event(self, i):
        self.selected_event = None  # retour aux évènements de la même catégorie
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


def _resolve_event_type(value: str):
    """Retourne l'EventType pour une valeur 'msg.delete' etc."""
    for ev in ulogger2026.EventType:
        if ev.value == value:
            return ev
    return None


# ═══════════════════════════════════════════════════════════════════════════════
