class ProtPanelV2(LayoutView):
    """Panneau Protection du Serveur en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)

        enabled_count = 0
        lines_out = []
        for key, emoji, name in PROTS:
            is_on = bool(c.get(key))
            if is_on:
                enabled_count += 1
            # Phase 5.3 : radio-style 🔘 / ⚪ au lieu de feu 🟢 / 🔴
            dot = "🔘" if is_on else "⚪"
            lines_out.append(f"{dot} {emoji} **{name}**")

        total = len(PROTS)
        pct = round(enabled_count / total * 100) if total > 0 else 0

        sel = Select(
            placeholder="Choisir une protection à configurer…",
            options=[discord.SelectOption(label=nm, value=k, emoji=em) for k, em, nm in PROTS],
            custom_id="ppv2_sel",
        )
        sel.callback = self._cb_sel
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="ppv2_back")
        b_back.callback = self._cb_back

        self.clear_items()
        items: list = []
        items.append(visuels.bandeau("protections", "Protection"))
        items.append(v2_subtitle(f"`{enabled_count}/{total}` filtres actifs · `{pct}%`"))

        items.append(v2_divider())
        items.append(v2_body("\n".join(lines_out)))
        items.append(v2_divider())
        items.append(discord.ui.ActionRow(sel))
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.INFO))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_sel(self, interaction):
        val = interaction.data['values'][0]
        prot = next(p for p in PROTS if p[0] == val)
        v = ProtDetailV2(self.u, self.g, prot)
        await v.render_to(interaction, edit=True)

    async def _cb_back(self, i):
        # Refonte 2026-08 : retour direct à la racine /configure (MainPanelV2).
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class ProtDetailV2(LayoutView):
    """Detail d'une protection en V2 — toutes les sub-panels accessibles."""

    def __init__(self, u, g, prot):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.prot = prot
        self.key = prot[0]

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        on = bool(c.get(self.key))

        # Helper sanction (action + durée)
        def _sanction_line(protection_key):
            try:
                ak = get_prot_action_key(protection_key)
                dk = get_prot_duration_key(protection_key)
                act = c.get(ak, get_prot_default_action(protection_key))
                dur = c.get(dk, get_prot_default_duration(protection_key))
                act_emoji = {'delete': '🗑️', 'mute': '🔇', 'kick': '👢', 'ban': '🔨'}.get(act, '⚡')
                line = f"⚡ **Sanction** · {act_emoji} `{act.upper()}`"
                if act == 'mute':
                    line += f"  ·  ⏱️ Durée mute · `{dur}` min"
                return line
            except Exception:
                return None

        # Items de base : titre + status (Phase 11 : radio dot)
        items: list = [
            visuels.bandeau("protections", "Protection"),
            v2_title(f"{self.prot[2]}", level=3),
            v2_subtitle(f"{'🔘 Activé' if on else '⚪ Désactivé'}"),
            v2_divider(),
        ]

        # Configs spécifiques par protection
        if self.key == "anti_link":
            wl = c.get('link_whitelist', [])
            chs = c.get('link_allowed_channels', [])
            wl_txt = ", ".join(f"`{d}`" for d in wl[:15]) if wl else "_Aucun domaine_"
            ch_txt = ", ".join(f"<#{x}>" for x in chs[:10]) if chs else "_Aucun salon_"
            items.append(v2_body(f"**Whitelist domaines** · {wl_txt}\n**Salons autorisés** · {ch_txt}"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_image":
            allowed = c.get('image_allowed', [])
            fmts = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'tenor', 'giphy']
            fmt_txt = "  ".join(f"{'✅' if f in allowed else '❌'} `{f}`" for f in fmts)
            items.append(v2_body(f"**Formats autorisés**\n{fmt_txt}"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_badwords":
            words = c.get('badwords_list', [])
            if words:
                if len(words) <= 30:
                    words_txt = ", ".join(f"`{w}`" for w in words)
                else:
                    words_txt = ", ".join(f"`{w}`" for w in words[:30]) + f"\n_… + {len(words) - 30} autres_"
                items.append(v2_body(f"**Mots interdits** ({len(words)})\n{words_txt[:1000]}"))
            else:
                items.append(v2_body("**Mots interdits** · _Aucun mot configuré_"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_spam":
            items.append(v2_body(
                f"**Max messages** · `{c.get('spam_max', 5)}`  ·  "
                f"**Intervalle** · `{c.get('spam_interval', 5)}` sec"
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_caps":
            items.append(v2_body(f"**Pourcentage max** · `{c.get('caps_percent', 70)}%`"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_mass_mention":
            items.append(v2_body(f"**Max mentions** · `{c.get('mention_limit', 5)}` par message"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_newaccount":
            items.append(v2_body(f"**Jours minimum** · `{c.get('newaccount_days', 7)}`"))

        elif self.key == "anti_invite":
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_compromised":
            # Ce bloc décrivait `check_compromised_behavior`, une fonction morte, et
            # affichait une ligne « Sanction » construite sur des clés jamais appliquées.
            # Il décrit maintenant ce que le détecteur fait RÉELLEMENT.
            _cad_ch = self.g.get_channel(
                c.get('compromised_alerts_channel', 0)
                or c.get('log_anti_compromised', 0)
                or c.get('mod_log_channel', 0)
            )
            items.append(v2_body(
                "Un score par message (phishing, invitation et mentions de masse, message copié partout). Au-delà du seuil : compte gelé, dossier pour le staff."
            ))
            items.append(v2_body(
                f"**Seuil** · `{c.get('compromised_alert_threshold', 60)}`/100  ·  "
                f"**Anti-rafale** · `{c.get('compromised_alert_cooldown', 300)}` s\n"
                f"**Dossier envoyé dans** · "
                f"{_cad_ch.mention if _cad_ch else '⚠️ _aucun salon — utilise « Log »_'}"
            ))

        elif self.key == "anti_qrcode":
            items.append(v2_body(
                "Arnaques au QR code : faux cadeaux, vol de compte."
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_phishing":
            items.append(v2_body(
                "Faux sites, typosquatting, liens masqués, raccourcisseurs suspects."
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))
            items.append(v2_body(f"-# `{len(PHISHING_DOMAINS)}` domaines connus"))

        elif self.key == "anti_scam":
            items.append(v2_body(
                "Faux Nitro, crypto, vérification d'âge, faux jeux, urgence artificielle."
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))
            items.append(v2_body(f"-# `{len(SCAM_KEYWORDS)}` mots-clés connus"))

        elif self.key == "anti_alt":
            alt_cfg = c.get('alt_config', {})
            action = c.get('alt_action', 'kick')
            auto = alt_cfg.get('auto_action', False)
            min_conf = alt_cfg.get('min_confidence', 70)
            try:
                alts = await get_alt_accounts(self.g.id)
                suspected = len([a for a in alts if a[5] == 'suspected'])
                confirmed = len([a for a in alts if a[5] == 'confirmed'])
            except Exception:
                suspected = confirmed = 0
            items.append(v2_body(
                "Avatar ou pseudo copié, compte créé juste après un ban, comportement suspect."
            ))
            items.append(v2_body(
                f"**Action** · `{action.upper()}`  ·  "
                f"**Action auto** · {'✅' if auto else '❌'}  ·  "
                f"**Confiance min.** · `{min_conf}%`\n"
                f"**Détections** · ⚠️ `{suspected}` suspects · ✅ `{confirmed}` confirmés"
            ))

        # Salon de log (commun à toutes)
        log_ch = self.g.get_channel(c.get(f'log_{self.key}', 0))
        site = bool(c.get('logs_sur_site_v1'))
        #  En mode site, seules les protections qui alertent gardent un salon : le salon unique.
        sur_site = site and f'log_{self.key}' not in CLES_ALERTES
        items.append(v2_divider())
        if sur_site:
            items.append(v2_body("**Salon de log** · 🌐 sur le site — journal du tableau de bord"))
        else:
            items.append(v2_body(f"**{'Salon des alertes' if site else 'Salon de log'}** · "
                                 f"{log_ch.mention if log_ch else '⚪ _non configuré_'}"))

        # Boutons
        self.clear_items()
        b_toggle = Button(
            emoji=(visuels.icone("pause") if on else visuels.icone("activer")), label=("Désactiver" if on else "Activer"),
            style=(discord.ButtonStyle.danger if on else discord.ButtonStyle.success),
            custom_id="pdv2_toggle",
        )
        b_toggle.callback = self._cb_toggle
        b_config = Button(emoji=visuels.icone("reglages"), label="Configurer", style=discord.ButtonStyle.primary, custom_id="pdv2_config")
        b_config.callback = self._cb_config
        b_sanction = Button(emoji=visuels.icone("sanction"), label="Sanction", style=discord.ButtonStyle.secondary, custom_id="pdv2_sanction")
        b_sanction.callback = self._cb_sanction
        b_log = Button(emoji=visuels.icone("journal"), label="Log : sur le site" if sur_site else "Définir Log",
                       style=discord.ButtonStyle.secondary, custom_id="pdv2_log", disabled=sur_site)
        b_log.callback = self._cb_log
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="pdv2_back")
        b_back.callback = self._cb_back

        items.append(v2_divider())
        items.append(discord.ui.ActionRow(b_toggle, b_config, b_sanction, b_log, b_back))

        color = Palette.SUCCESS if on else Palette.DANGER
        self.add_item(v2_container(*items, color=color))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_toggle(self, i):
        c = await cfg(self.g.id)
        new_val = 0 if c.get(self.key) else 1
        await db_set(self.g.id, self.key, new_val)
        await ProtDetailV2(self.u, self.g, self.prot).render_to(i, edit=True)

    async def _cb_config(self, i):
        # Sub-configs V2 dédiés
        if self.key == "anti_image":
            v = ImageConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        if self.key == "anti_badwords":
            v = BadwordsConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        if self.key == "anti_link":
            v = LinkConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        # Modals directs
        if self.key in ["anti_spam", "anti_caps", "anti_newaccount", "anti_mass_mention"]:
            return await i.response.send_modal(NumberConfigModal(self.g, self.u, self.key))
        # Sub-configs V2 dédiés (suite)
        if self.key == "anti_alt":
            v = AltConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        # Default : ActionConfigPanelV2 pour toutes les autres protections
        v = ActionConfigPanelV2(self.u, self.g, self.key)
        await v.render_to(i, edit=True)

    async def _cb_sanction(self, i):
        # Trois protections ne se règlent PAS par ActionConfigPanelV2 : il écrirait une clé
        # que le chemin d'exécution ne relit jamais, donc un bouton sans effet (UI.md §3).
        if self.key == "anti_badwords":
            # La sanction réelle est badwords_sanction_action / badwords_sanction_duration,
            # lues par _badword_strike. ActionConfigPanelV2 écrirait `badwords_action`,
            # clé qui n'existe nulle part ailleurs dans le fichier.
            return await _BadwordsSanctionActionView(self.u, self.g).render_to(i, edit=True)
        if self.key == "anti_compromised":
            # Cette protection ne sanctionne pas automatiquement : le panneau doit le dire
            # plutôt que de proposer un réglage qui ne s'appliquerait jamais.
            return await i.response.send_message(
                "ℹ️ Cette protection ne sanctionne **pas** automatiquement : elle gèle le "
                "compte et ouvre un dossier que le staff tranche à la main.",
                ephemeral=True,
            )
        v = ActionConfigPanelV2(self.u, self.g, self.key)
        await v.render_to(i, edit=True)

    async def _cb_log(self, i):
        # UI.md §2 : ChannelSelect natif via V2GenericChannelPicker. L'ancien
        # LogSelectView paginait les salons 23 par 23 (limite des 25 options d'un
        # Select classique) et renvoyait un Embed depuis un panneau V2.
        try:
            v = V2GenericChannelPicker(
                self.u, self.g,
                config_key=f'log_{self.key}',
                return_panel_factory=lambda: ProtDetailV2(self.u, self.g, self.prot),
                title="Salon de log",
                description=f"Où envoyer les alertes de **{self.prot[2]}**.",
                color=0x9B59B6,
            )
            await v.render_to(i, edit=True)
        except Exception as ex:
            print(f"[ProtDetailV2 _cb_log] {ex}")
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : {ex}", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : {ex}", ephemeral=True)
            except Exception:
                pass

    async def _cb_back(self, i):
        v = ProtPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


# ═══════════════════════════════════════════════════════════════════════════════
#                           🖼️ ANTI-IMAGE CONFIG
