#                           🔗 ANTI-LINK CONFIG
# ═══════════════════════════════════════════════════════════════════════════════

class LinkConfigPanelV2(LayoutView):
    """Configuration anti-liens en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        wl = c.get('link_whitelist', [])
        chs = c.get('link_allowed_channels', [])

        wl_txt = ", ".join(f"`{d}`" for d in wl) if wl else "_Aucun_"
        ch_txt = ", ".join(f"<#{x}>" for x in chs) if chs else "_Aucun_"

        self.clear_items()
        b_add_dom = Button(emoji=visuels.icone("ajouter"), label="Ajouter domaines", style=discord.ButtonStyle.success, custom_id="lcpv2_add_dom")
        b_add_dom.callback = self._cb_add_dom
        b_clear_wl = Button(emoji=visuels.icone("supprimer"), label="Vider whitelist", style=discord.ButtonStyle.danger, disabled=(not wl), custom_id="lcpv2_clear_wl")
        b_clear_wl.callback = self._cb_clear_wl
        b_add_ch = Button(emoji=visuels.icone("ajouter"), label="Ajouter salon", style=discord.ButtonStyle.primary, custom_id="lcpv2_add_ch")
        b_add_ch.callback = self._cb_add_ch
        b_clear_ch = Button(emoji=visuels.icone("supprimer"), label="Vider salons", style=discord.ButtonStyle.danger, disabled=(not chs), custom_id="lcpv2_clear_ch")
        b_clear_ch.callback = self._cb_clear_ch
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="lcpv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("liens", "Anti-liens"),
            v2_subtitle("Domaines whitelist + salons autorisés"),
            v2_divider(),
            v2_title(f"Whitelist domaines ({len(wl)})", level=3),
            v2_body(wl_txt),
            v2_divider(),
            v2_title(f"Salons autorisés ({len(chs)})", level=3),
            v2_body(ch_txt),
            v2_divider(),
            discord.ui.ActionRow(b_add_dom, b_clear_wl, b_add_ch, b_clear_ch),
            discord.ui.ActionRow(b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.INFO))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_add_dom(self, i):
        modal = AddDomainModal(self.g, self.u)
        async def v2_submit(interaction):
            c = await cfg(self.g.id)
            existing = c.get('link_whitelist', [])
            new = [x.strip().lower() for x in modal.doms.value.split(',') if x.strip()]
            for d in new:
                if d and d not in existing:
                    existing.append(d)
            await db_set(self.g.id, 'link_whitelist', existing)
            await LinkConfigPanelV2(self.u, self.g).render_to(interaction, edit=True)
        modal.on_submit = v2_submit
        await i.response.send_modal(modal)

    async def _cb_clear_wl(self, i):
        await db_set(self.g.id, 'link_whitelist', [])
        await LinkConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_add_ch(self, i):
        # UI.md §2 : ChannelSelect natif. `link_allowed_channels` est une LISTE,
        # donc on passe par save_fn plutôt que par l'écriture simple du picker.
        async def _ajouter(guild_id, channel_id):
            c = await cfg(guild_id)
            salons = list(c.get('link_allowed_channels', []) or [])
            if channel_id and channel_id not in salons:
                salons.append(channel_id)
            elif not channel_id:
                # Le bouton « Aucun (reset) » du picker envoie 0 : on vide la liste.
                salons = []
            await db_set(guild_id, 'link_allowed_channels', salons)

        try:
            v = V2GenericChannelPicker(
                self.u, self.g,
                return_panel_factory=lambda: LinkConfigPanelV2(self.u, self.g),
                title="Autoriser un salon",
                description="Les liens resteront permis dans ce salon.",
                color=0x9B59B6,
                save_fn=_ajouter,
            )
            await v.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LinkConfigPanelV2 _cb_add_ch] {ex}")
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : {ex}", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : {ex}", ephemeral=True)
            except Exception:
                pass

    async def _cb_clear_ch(self, i):
        await db_set(self.g.id, 'link_allowed_channels', [])
        await LinkConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_back(self, i):
        prot = next(p for p in PROTS if p[0] == "anti_link")
        v = ProtDetailV2(self.u, self.g, prot)
        await v.render_to(i, edit=True)


class AddDomainModal(Modal, title="Ajouter des domaines"):
    doms = TextInput(
        label="Domaines (séparés par des virgules)",
        placeholder="youtube.com, twitter.com, trello.com",
        style=discord.TextStyle.paragraph,
        max_length=2000
    )
    
    def __init__(self, g, u):
        super().__init__()
        self.g = g
        self.u = u
    
    async def on_submit(self, i):
        c = await cfg(self.g.id)
        items = c.get('link_whitelist', [])
        
        # Nettoyer et normaliser les domaines
        new_domains = []
        for x in self.doms.value.split(','):
            domain = x.strip().lower()
            # Enlever http:// ou https:// si présent
            domain = re.sub(r'^https?://', '', domain)
            # Enlever les / finaux
            domain = domain.rstrip('/')
            # Enlever www. si présent
            if domain.startswith('www.'):
                domain = domain[4:]
            if domain and domain not in items and domain not in new_domains:
                new_domains.append(domain)
        
        # Ajouter les nouveaux domaines
        items.extend(new_domains)
        await db_set(self.g.id, 'link_whitelist', items)
        
        # Phase 3.6 : retour V2
        v = LinkConfigPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)
        try:
            if new_domains:
                await i.followup.send(
                    f"✅ **{len(new_domains)} domaine(s) ajouté(s) !**\n"
                    f"`{', '.join(new_domains)}`",
                    ephemeral=True,
                )
            else:
                await i.followup.send(
                    "⚠️ Aucun nouveau domaine ajouté (déjà présents ou invalides)",
                    ephemeral=True,
                )
        except Exception:
            pass


