class AltConfigPanelV2(LayoutView):
    """Configuration Anti-MultiCompte (alts) en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        alt_cfg = c.get('alt_config', {})

        enabled = bool(c.get('anti_alt', 0))
        action = c.get('alt_action', 'kick')
        action_emoji = {'kick': '👢', 'ban': '🔨', 'mute': '🔇'}.get(action, '⚡')
        auto = alt_cfg.get('auto_action', False)
        min_conf = alt_cfg.get('min_confidence', 70)

        try:
            alts = await get_alt_accounts(self.g.id)
            suspected = len([a for a in alts if a[5] == 'suspected'])
            confirmed = len([a for a in alts if a[5] == 'confirmed'])
            actioned = len([a for a in alts if a[7]])
        except Exception:
            suspected = confirmed = actioned = 0

        # Phase 11 : radio dots + compact
        self.clear_items()
        if enabled:
            b_toggle = Button(emoji='⚪', label="Désactiver", style=discord.ButtonStyle.danger, custom_id="alcv2_toggle")
        else:
            b_toggle = Button(emoji='🔘', label="Activer", style=discord.ButtonStyle.success, custom_id="alcv2_toggle")
        b_toggle.callback = self._cb_toggle
        b_action = Button(emoji=visuels.icone("sanction"), label=f"Action · {action.upper()}", style=discord.ButtonStyle.primary, custom_id="alcv2_action")
        b_action.callback = self._cb_cycle_action
        b_auto = Button(
            emoji=('🔘' if auto else '⚪'), label=("Auto" if auto else "Auto"),
            style=(discord.ButtonStyle.success if auto else discord.ButtonStyle.secondary),
            custom_id="alcv2_auto",
        )
        b_auto.callback = self._cb_toggle_auto
        b_conf = Button(emoji=visuels.icone("stats"), label=f"Confiance · {min_conf}%", style=discord.ButtonStyle.primary, custom_id="alcv2_conf")
        b_conf.callback = self._cb_conf
        b_scan = Button(emoji=visuels.icone("recherche"), label="Scanner", style=discord.ButtonStyle.success, custom_id="alcv2_scan")
        b_scan.callback = self._cb_scan
        b_view = Button(emoji=visuels.icone("journal"), label="Détections", style=discord.ButtonStyle.secondary, disabled=(not (suspected or confirmed)), custom_id="alcv2_view")
        b_view.callback = self._cb_view
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="alcv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("multicomptes", "Anti multi-comptes"),
            v2_subtitle(f"{'🔘 actif' if enabled else '⚪ désactivé'} · `{suspected}` suspect(s)"),
            v2_divider(),
        ]

        if enabled:
            items.append(v2_body(
                f"**Action** · `{action.upper()}`\n"
                f"{'🔘' if auto else '⚪'} **Action auto**\n"
                f"**Confiance minimum** · `{min_conf}%`"
            ))
            items.append(v2_divider())
            items.append(v2_body(
                f"⚠️ Suspects · `{suspected}`  ·  "
                f"✅ Confirmés · `{confirmed}`  ·  "
                f"Sanctionnés · `{actioned}`"
            ))
            items.append(v2_divider())

        items.append(discord.ui.ActionRow(b_toggle, b_action, b_auto, b_conf))
        items.append(discord.ui.ActionRow(b_scan, b_view, b_back))

        self.add_item(v2_container(*items, color=Palette.ACCENT))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_toggle(self, i):
        c = await cfg(self.g.id)
        await db_set(self.g.id, 'anti_alt', 0 if c.get('anti_alt') else 1)
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_cycle_action(self, i):
        c = await cfg(self.g.id)
        actions = ['kick', 'ban', 'mute']
        current = c.get('alt_action', 'kick')
        try:
            next_idx = (actions.index(current) + 1) % len(actions)
        except ValueError:
            next_idx = 0
        await db_set(self.g.id, 'alt_action', actions[next_idx])
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_toggle_auto(self, i):
        c = await cfg(self.g.id)
        alt_cfg = c.get('alt_config', {})
        alt_cfg['auto_action'] = not alt_cfg.get('auto_action', False)
        await db_set(self.g.id, 'alt_config', alt_cfg)
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_conf(self, i):
        await i.response.send_modal(AltConfidenceModal(self.g, self.u))

    async def _cb_scan(self, i):
        await i.response.send_message("🔍 **Scan des comptes secondaires en cours…**", ephemeral=True)
        try:
            detected = await scan_all_members_for_alts(self.g)
            if detected:
                v = AltScanResultsPanelV2(self.u, self.g, detected)
                await v.render_after_defer(i)
            else:
                await i.edit_original_response(
                    content="✅ **Aucun compte secondaire détecté !**\n\nTous les membres semblent être des comptes uniques.",
                    embed=None,
                    view=None,
                )
        except Exception as ex:
            print(f"[ALT SCAN V2] {ex}")
            try:
                await i.edit_original_response(content=f"❌ Erreur: {ex}")
            except Exception:
                pass

    async def _cb_view(self, i):
        alts = await get_alt_accounts(self.g.id)
        if not alts:
            return await i.response.send_message("📋 Aucun compte secondaire détecté.", ephemeral=True)
        v = AltDetectionsPanelV2(self.u, self.g, alts)
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        prot = next(p for p in PROTS if p[0] == "anti_alt")
        v = ProtDetailV2(self.u, self.g, prot)
        await v.render_to(i, edit=True)


class AltConfidenceModal(Modal, title="Confiance minimum"):
    value = TextInput(
        label="Pourcentage de confiance (40-100)",
        placeholder="70",
        default="70",
        max_length=3
    )
    
    def __init__(self, g, u):
        super().__init__()
        self.g = g
        self.u = u
    
    async def on_submit(self, i):
        try:
            val = int(self.value.value)
            val = max(40, min(100, val))
            
            c = await cfg(self.g.id)
            alt_cfg = c.get('alt_config', {})
            alt_cfg['min_confidence'] = val
            await db_set(self.g.id, 'alt_config', alt_cfg)
            
            # Phase 3.6 : retour V2
            v = AltConfigPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
            try:
                await i.followup.send(f"✅ Confiance minimum définie à **{val}%**", ephemeral=True)
            except Exception:
                pass
        except Exception:
            try:
                await i.response.send_message("❌ Valeur invalide", ephemeral=True)
            except discord.InteractionResponded:
                pass

class AltScanResultsPanelV2(LayoutView):
    """Resultats d'un scan d'alts en V2."""

    def __init__(self, u, g, detected):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.detected = detected
        self.page = 0
        self.per_page = 5

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    def _build(self):
        total = len(self.detected)
        high_conf = len([d for d in self.detected if d['confidence'] >= 70])
        very_high = len([d for d in self.detected if d['confidence'] >= 80])
        max_page = max(0, (total - 1) // self.per_page) if total else 0
        start = self.page * self.per_page
        end = start + self.per_page
        page_items = self.detected[start:end]

        item_blocks = []
        for item in page_items:
            member = item['member']
            confidence = item['confidence']
            main_id = item['main_id']
            reasons = item['reasons']
            conf_emoji = "🔴" if confidence >= 80 else ("🟠" if confidence >= 60 else "🟡")
            main_member = self.g.get_member(main_id)
            main_txt = f"{main_member.name}" if main_member else f"ID `{main_id}` (parti)"
            block = (
                f"**👤 {member.display_name}** (`{member.id}`)\n"
                f"  ┣ Confiance · {conf_emoji} `{confidence}%`\n"
                f"  ┣ Compte principal · {main_txt}\n"
                f"  ┗ Raisons · {', '.join(reasons[:2])}"
            )
            item_blocks.append(block)
        list_block = "\n\n".join(item_blocks) if item_blocks else "_Aucun résultat sur cette page_"

        self.clear_items()
        b_prev = Button(emoji=visuels.icone("retour", '◀️'), style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="asrv2_prev")
        b_prev.callback = self._cb_prev
        b_page = Button(label=f"Page {self.page + 1}/{max_page + 1}", style=discord.ButtonStyle.secondary, disabled=True, custom_id="asrv2_page")
        b_next = Button(emoji=visuels.icone("activer", '▶️'), style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="asrv2_next")
        b_next.callback = self._cb_next
        b_kick70 = Button(emoji=visuels.icone("expulser"), label="Isoler ≥ 70 %", style=discord.ButtonStyle.danger, disabled=(high_conf == 0), custom_id="asrv2_kick70")
        b_kick70.callback = self._cb_kick70
        b_ban80 = Button(emoji=visuels.icone("interdit"), label="Isoler ≥ 80 %", style=discord.ButtonStyle.danger, disabled=(very_high == 0), custom_id="asrv2_ban80")
        b_ban80.callback = self._cb_ban80
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="asrv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("scan_resultats", "Résultats du scan"),
            v2_subtitle(f"`{total}` alts potentiels · `{high_conf}` haute confiance (>=70%) · `{very_high}` très haute (>=80%)"),
            v2_divider(),
            v2_body(list_block),
            v2_divider(),
            discord.ui.ActionRow(b_prev, b_page, b_next),
            discord.ui.ActionRow(b_kick70, b_ban80, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.DANGER))

    async def render_to(self, interaction, *, edit=True):
        self._build()
        await _afficher_panneau(self, interaction, edit)

    async def render_after_defer(self, interaction):
        self._build()
        await interaction.edit_original_response(view=self, embed=None, attachments=[], content=None)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.detected) - 1) // self.per_page) if self.detected else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_kick70(self, i):
        high_conf = [d for d in self.detected if d['confidence'] >= 70]
        if not high_conf:
            return await i.response.send_message("✅ Aucun compte avec >=70% de confiance", ephemeral=True)
        await i.response.send_message(view=ConfirmerIsolementV2(self.u, self.g, high_conf, 'alts'), ephemeral=True)

    async def _cb_ban80(self, i):
        very_high = [d for d in self.detected if d['confidence'] >= 80]
        if not very_high:
            return await i.response.send_message("✅ Aucun compte avec >=80% de confiance", ephemeral=True)
        await i.response.send_message(view=ConfirmerIsolementV2(self.u, self.g, very_high, 'alts'), ephemeral=True)

    async def _cb_back(self, i):
        v = AltConfigPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class ConfirmerIsolementV2(LayoutView):
    """Isoler en masse (règle fondateur-only : quarantaine RÉVERSIBLE, jamais de renvoi ni de ban) — ou
    renvoyer les bots non vérifiés, réservé au fondateur. 20/10/2026 : les confirmations disaient
    « KICK », « BAN », « irréversible » pour un isolement, comptaient réussi ce qui avait échoué, et
    « Kick Bots » ne faisait rien. `genre` : 'suspects', 'alts' ou 'bots'."""

    def __init__(self, u, g, cibles, genre: str):
        super().__init__(timeout=60)
        self.u, self.g, self.cibles, self.genre = u, g, list(cibles), genre
        if genre == 'bots':
            texte = (f"### Renvoyer {len(self.cibles)} bot(s) non vérifié(s) ?\n"
                     "Ils quittent le serveur et peuvent être ré-invités. Réservé au fondateur.")
        else:
            texte = (f"### Isoler {len(self.cibles)} compte(s) ?\n"
                     "Quarantaine réversible : ils lisent encore, mais ne peuvent plus écrire, réagir ni parler "
                     "en vocal ; leurs rôles leur sont rendus à la levée. Le bannissement reste au fondateur.")
        ok = Button(label="Confirmer", style=discord.ButtonStyle.danger, emoji=visuels.icone("valider"))
        ok.callback = self._confirmer
        non = Button(label="Annuler", style=discord.ButtonStyle.secondary, emoji=visuels.icone("fermer"))
        non.callback = self._annuler
        self.add_item(v2_container(v2_body(texte), discord.ui.ActionRow(ok, non), color=Palette.DANGER))

    async def interaction_check(self, i) -> bool:
        if i.user.id != self.u.id:  # anti-clic d'un tiers
            await i.response.send_message("⛔ Ce panneau ne t'est pas destiné.", ephemeral=True)
            return False
        return True

    def _fin(self, texte: str, couleur) -> None:
        self.clear_items()
        self.add_item(v2_container(v2_body(texte), color=couleur))

    async def _annuler(self, i):
        self._fin("Action annulée.", Palette.NEUTRAL)
        await i.response.edit_message(view=self)

    async def _confirmer(self, i):
        if self.genre == 'bots' and not owner_ids_module.is_super_owner(i.user.id):
            return await i.response.send_message("Renvoyer des bots est réservé au fondateur.", ephemeral=True)
        self._fin("⏳ En cours…", Palette.NEUTRAL)
        await i.response.edit_message(view=self)
        faits = rates = 0
        for t in self.cibles:
            membre = t['member']
            try:
                if self.genre == 'bots':
                    await membre.kick(reason=f"Bot non vérifié renvoyé par {i.user} ({i.user.id})")
                    faits += 1
                    continue
                motif = (f"Compte secondaire (confiance: {t.get('confidence')}%)" if self.genre == 'alts'
                         else f"Anti-Raid: {t.get('reason', 'Compte suspect')} (score: {t.get('score', 'N/A')})")
                res = await isolate_member(membre, motif)
                if not (res or {}).get('isolated'):
                    rates += 1  # bot, hiérarchie : rien n'a été fait, on ne le compte pas réussi
                    continue
                if self.genre == 'alts':
                    await update_alt_status(self.g.id, membre.id, 'actioned', 'isolate')
                faits += 1
            except Exception as ex:
                _logerr("isolement.masse", ex, guild_id=self.g.id)
                rates += 1
        verbe = "renvoyé(s)" if self.genre == 'bots' else "isolé(s)"
        self._fin(f"### Terminé\n**{faits}** {verbe} · **{rates}** échec(s)",
                  Palette.SUCCESS if not rates else Palette.WARNING)
        await i.edit_original_response(view=self)


class AltDetectionsPanelV2(LayoutView):
    """Historique des detections d'alts en V2."""

    def __init__(self, u, g, alts):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.alts = alts
        self.page = 0
        self.per_page = 5

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit=True):
        total = len(self.alts)
        max_page = max(0, (total - 1) // self.per_page) if total else 0
        start = self.page * self.per_page
        end = start + self.per_page
        page_items = self.alts[start:end]

        item_blocks = []
        for alt in page_items:
            _, main_id, alt_id, confidence, reasons_json, status, detected_at, action_taken = alt
            try:
                reasons = json.loads(reasons_json) if reasons_json else []
            except Exception:
                reasons = []
            status_emoji = {'suspected': '⚠️', 'confirmed': '✅', 'dismissed': '❌', 'actioned': '⚡'}.get(status, '❓')
            conf_emoji = "🔴" if confidence >= 80 else ("🟠" if confidence >= 60 else "🟡")
            alt_member = self.g.get_member(alt_id)
            main_member = self.g.get_member(main_id)
            alt_txt = f"{alt_member.name}" if alt_member else f"ID `{alt_id}` (parti)"
            main_txt = f"{main_member.name}" if main_member else f"ID `{main_id}`"
            block = (
                f"**👤 {alt_txt}**\n"
                f"  ┣ Principal · {main_txt}\n"
                f"  ┣ Confiance · {conf_emoji} `{confidence}%`\n"
                f"  ┣ Status · {status_emoji} `{status}`\n"
                f"  ┗ Raisons · {', '.join(reasons[:2]) if reasons else '_N/A_'}"
            )
            if action_taken:
                block += f"\n  ⚡ **Action** · `{action_taken.upper()}`"
            item_blocks.append(block)
        list_block = "\n\n".join(item_blocks) if item_blocks else "_Aucune détection enregistrée_"

        self.clear_items()
        b_prev = Button(emoji=visuels.icone("retour", '◀️'), style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="adpv2_prev")
        b_prev.callback = self._cb_prev
        b_page = Button(label=f"Page {self.page + 1}/{max_page + 1}", style=discord.ButtonStyle.secondary, disabled=True, custom_id="adpv2_page")
        b_next = Button(emoji=visuels.icone("activer", '▶️'), style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="adpv2_next")
        b_next.callback = self._cb_next
        b_clear = Button(emoji=visuels.icone("supprimer"), label="Effacer historique", style=discord.ButtonStyle.danger, disabled=(not self.alts), custom_id="adpv2_clear")
        b_clear.callback = self._cb_clear
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="adpv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("multicomptes_detections", "Comptes secondaires"),
            v2_subtitle(f"`{total}` détection(s) enregistrée(s)"),
            v2_divider(),
            v2_body(list_block),
            v2_divider(),
            discord.ui.ActionRow(b_prev, b_page, b_next),
            discord.ui.ActionRow(b_clear, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.ACCENT))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.alts) - 1) // self.per_page) if self.alts else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_clear(self, i):
        try:
            async with get_db() as db:
                await db.execute('DELETE FROM alt_accounts WHERE guild_id = ?', (self.g.id,))
                await db.commit()
            v = AltConfigPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
        except Exception as ex:
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur: {ex}", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur: {ex}", ephemeral=True)
            except Exception:
                pass

    async def _cb_back(self, i):
        v = AltConfigPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class SuspectScanPanelV2(LayoutView):
    """Resultats du scan suspects en V2 (delegue le scan a SuspectScanPanel V1)."""

    def __init__(self, u, g, suspects=None, bots=None):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.suspects = suspects if suspects is not None else []
        self.bots = bots if bots is not None else []
        self.page = 0
        self.per_page = 8

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def scan_members(self):
        helper = SuspectScanPanel(self.u, self.g)
        await helper.scan_members()
        self.suspects = helper.suspects
        self.bots = helper.bots

    def _build(self):
        critical = len([s for s in self.suspects if s['severity'] == 'critical'])
        high = len([s for s in self.suspects if s['severity'] == 'high'])
        medium = len([s for s in self.suspects if s['severity'] == 'medium'])
        max_page = max(0, (len(self.suspects) - 1) // self.per_page) if self.suspects else 0

        start = self.page * self.per_page
        end = start + self.per_page
        page_suspects = self.suspects[start:end]

        sus_lines = []
        for s in page_suspects:
            member = s['member']
            severity_emoji = {'critical': '🚨', 'high': '⚠️', 'medium': '⚡', 'low': '📋'}.get(s['severity'], '📋')
            reasons_short = ", ".join(s['reasons'][:2])
            sus_lines.append(f"{severity_emoji} **{member.display_name}** (`{member.id}`)\n  ┗ {reasons_short}")
        sus_block = "\n".join(sus_lines) if sus_lines else "✅ _Aucun compte suspect détecté !_"

        bot_lines = []
        for b in self.bots[:5]:
            bot_lines.append(f"🤖 **{b['member'].name}** (`{b['member'].id}`)")
        if len(self.bots) > 5:
            bot_lines.append(f"_… et {len(self.bots) - 5} autres_")
        bot_block = "\n".join(bot_lines) if bot_lines else None

        self.clear_items()
        b_prev = Button(emoji=visuels.icone("retour"), label="Préc.", style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="sspv2_prev")
        b_prev.callback = self._cb_prev
        b_next = Button(emoji=visuels.icone("activer"), label="Suiv.", style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="sspv2_next")
        b_next.callback = self._cb_next
        b_rescan = Button(emoji=visuels.icone("actualiser"), label="Re-scanner", style=discord.ButtonStyle.primary, custom_id="sspv2_rescan")
        b_rescan.callback = self._cb_rescan
        b_kick_crit = Button(emoji=visuels.icone("expulser"), label="Isoler critiques", style=discord.ButtonStyle.danger, disabled=(critical == 0), custom_id="sspv2_kick_crit")
        b_kick_crit.callback = self._cb_kick_crit
        b_kick_bots = Button(emoji=visuels.icone("robot"), label="Renvoyer les bots", style=discord.ButtonStyle.danger, disabled=(not self.bots), custom_id="sspv2_kick_bots")
        b_kick_bots.callback = self._cb_kick_bots
        b_kick_all = Button(emoji=visuels.icone("expulser"), label="Isoler les suspects", style=discord.ButtonStyle.danger, disabled=((critical + high) == 0), custom_id="sspv2_kick_all")
        b_kick_all.callback = self._cb_kick_all
        b_close = Button(emoji=visuels.icone("fermer"), label="Fermer", style=discord.ButtonStyle.secondary, custom_id="sspv2_close")
        b_close.callback = self._cb_close

        items: list = [
            visuels.bandeau("scan_suspects", "Comptes suspects"),
            v2_subtitle(f"{critical} crit · ⚠️ {high} elevés · ⚡ {medium} moyens · 🤖 {len(self.bots)} bots non vérifiés"),
            v2_divider(),
            v2_title(f"Suspects ({len(self.suspects)}) — Page {self.page + 1}/{max_page + 1}", level=3),
            v2_body(sus_block),
        ]
        if bot_block:
            items.append(v2_divider())
            items.append(v2_title("Bots non vérifiés", level=3))
            items.append(v2_body(bot_block))
        items.append(v2_divider())
        items.append(v2_subtitle("⚠️ Vérifie manuellement avant d'agir · Les scores sont indicatifs"))
        items.append(discord.ui.ActionRow(b_prev, b_next, b_rescan))
        items.append(discord.ui.ActionRow(b_kick_crit, b_kick_bots, b_kick_all))
        items.append(discord.ui.ActionRow(b_close))

        self.add_item(v2_container(*items, color=Palette.DANGER))

    async def render_to(self, interaction, *, edit=True):
        self._build()
        await _afficher_panneau(self, interaction, edit)

    async def render_after_defer(self, interaction):
        self._build()
        await interaction.edit_original_response(view=self, embed=None, attachments=[], content=None)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.suspects) - 1) // self.per_page) if self.suspects else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_rescan(self, i):
        await i.response.defer()
        await self.scan_members()
        self.page = 0
        await self.render_after_defer(i)

    async def _cb_kick_crit(self, i):
        critical = [s for s in self.suspects if s['severity'] == 'critical']
        if not critical:
            return await i.response.send_message("✅ Aucun compte critique à isoler", ephemeral=True)
        await i.response.send_message(view=ConfirmerIsolementV2(self.u, self.g, critical, 'suspects'), ephemeral=True)

    async def _cb_kick_bots(self, i):
        if not self.bots:
            return await i.response.send_message("✅ Aucun bot non vérifié", ephemeral=True)
        await i.response.send_message(view=ConfirmerIsolementV2(self.u, self.g, self.bots, 'bots'), ephemeral=True)

    async def _cb_kick_all(self, i):
        high_and_critical = [s for s in self.suspects if s['severity'] in ['critical', 'high']]
        if not high_and_critical:
            return await i.response.send_message("✅ Aucun compte à isoler", ephemeral=True)
        await i.response.send_message(view=ConfirmerIsolementV2(self.u, self.g, high_and_critical, 'suspects'),
                                      ephemeral=True)

    async def _cb_close(self, i):
        # Une carte V2 n'a ni texte ni embed : `content=` valait une erreur 400 (revue 24/10/2026).
        await i.response.edit_message(view=carte_texte("✅ Scan fermé"), attachments=[])


class SuspectScanPanel:
    """Le scanner des comptes suspects (l'affichage est `SuspectScanPanelV2`)."""
    def __init__(self, u, g):
        self.u = u
        self.g = g
        self.suspects = []
        self.bots = []
        self.page = 0
        self.per_page = 8
        self.scan_complete = False
    
    async def scan_members(self):
        """Scanne tous les membres pour détecter les comptes suspects"""
        self.suspects = []
        self.bots = []
        self.scan_complete = False
        
        try:
            # Récupérer la liste des membres
            members = list(self.g.members)
            print(f"[SCANNER] Scan de {len(members)} membres sur {self.g.name}")
            
            for member in members:
                try:
                    # Ignorer le bot lui-même
                    if member.id == bot.user.id:
                        continue
                    
                    if member.bot:
                        # Vérifier si c'est un bot non vérifié
                        try:
                            if not member.public_flags.verified_bot:
                                self.bots.append({
                                    'member': member,
                                    'reason': "Bot non vérifié par Discord",
                                    'severity': 'medium'
                                })
                        except:
                            pass
                        continue
                    
                    # Calculer le score de suspicion
                    suspicion_score = 0
                    reasons = []
                    
                    # 1. Âge du compte
                    try:
                        created = member.created_at
                        if created.tzinfo is None:
                            created = created.replace(tzinfo=timezone.utc)
                        account_age = (now() - created).days
                        
                        if account_age < 1:
                            suspicion_score += 50
                            reasons.append(f"Créé aujourd'hui")
                        elif account_age < 7:
                            suspicion_score += 30
                            reasons.append(f"Compte récent ({account_age}j)")
                        elif account_age < 30:
                            suspicion_score += 10
                            reasons.append(f"Compte jeune ({account_age}j)")
                    except Exception as e:
                        print(f"[SCANNER] Erreur âge {member.id}: {e}")
                    
                    # 2. Pas d'avatar personnalisé
                    try:
                        if member.avatar is None:
                            suspicion_score += 15
                            reasons.append("Pas d'avatar")
                    except:
                        pass
                    
                    # 3. Nom suspect
                    try:
                        name = member.name.lower()
                        # Finit par des chiffres
                        if len(name) > 4 and name[-4:].isdigit():
                            suspicion_score += 10
                            reasons.append("Nom générique")
                        # Pattern de bot (User1234)
                        if re.match(r'^[a-z]+\d{4,}$', name):
                            suspicion_score += 20
                            reasons.append("Pattern bot")
                    except:
                        pass
                    
                    # 4. Flags Discord
                    try:
                        flags = member.public_flags
                        if flags.spammer:
                            suspicion_score += 100
                            reasons.append("🚨 SPAMMER Discord")
                    except:
                        pass
                    
                    # 5. Pas de rôles
                    try:
                        if len(member.roles) <= 1:
                            suspicion_score += 5
                            reasons.append("Aucun rôle")
                    except:
                        pass
                    
                    # 6. Rejoint récemment
                    try:
                        if member.joined_at:
                            joined = member.joined_at
                            if joined.tzinfo is None:
                                joined = joined.replace(tzinfo=timezone.utc)
                            joined_hours = (now() - joined).total_seconds() / 3600
                            if joined_hours < 1:
                                suspicion_score += 15
                                reasons.append("Rejoint < 1h")
                            elif joined_hours < 24:
                                suspicion_score += 5
                                reasons.append("Rejoint aujourd'hui")
                    except:
                        pass
                    
                    # Ajouter si score suffisant
                    if suspicion_score >= 15 and reasons:
                        severity = 'critical' if suspicion_score >= 80 else 'high' if suspicion_score >= 50 else 'medium' if suspicion_score >= 30 else 'low'
                        self.suspects.append({
                            'member': member,
                            'score': suspicion_score,
                            'reasons': reasons,
                            'severity': severity
                        })
                        
                except Exception as ex:
                    print(f"[SCANNER] Erreur membre {member.id}: {ex}")
                    continue
            
            # Trier par score décroissant
            self.suspects.sort(key=lambda x: x['score'], reverse=True)
            self.scan_complete = True
            print(f"[SCANNER] Terminé: {len(self.suspects)} suspects, {len(self.bots)} bots non vérifiés")
            
        except Exception as ex:
            print(f"[SCANNER] Erreur globale: {ex}")
            import traceback
            traceback.print_exc()
            self.scan_complete = True


# ═══════════════════════════════════════════════════════════════════════════════
#                           🔨 MODÉRATION PANEL
# ═══════════════════════════════════════════════════════════════════════════════

async def send_mod_log(guild, action, mod, target, reason=None, duration=None, extra=None):
    """Envoie un log de modération.

    Phase 3.7 : envoie AUSSI dans le salon unifié (ulogger2026) si configuré.
    Le canal legacy `mod_log_channel` continue de fonctionner pour la rétrocompat.
    """
    # ───── Salon unifié (Phase 3.7) ─────
    try:
        action_to_event = {
            'warn':        ulogger2026.EventType.MOD_WARN,
            'unwarn':      ulogger2026.EventType.MOD_UNWARN,
            'mute':        ulogger2026.EventType.MOD_MUTE,
            'unmute':      ulogger2026.EventType.MOD_UNMUTE,
            'kick':        ulogger2026.EventType.MOD_KICK,
            'ban':         ulogger2026.EventType.MOD_BAN,
            'unban':       ulogger2026.EventType.MOD_UNBAN,
            'timeout':     ulogger2026.EventType.MOD_TIMEOUT,
            'purge':       ulogger2026.EventType.MOD_PURGE,
            'lock':        ulogger2026.EventType.MOD_LOCK,
            'unlock':      ulogger2026.EventType.MOD_UNLOCK,
            'slowmode':    ulogger2026.EventType.MOD_SLOWMODE,
            'infractions': ulogger2026.EventType.COMMAND_EXEC,
            'anti_raid':   ulogger2026.EventType.SEC_RAID,
            'anti_alt':    ulogger2026.EventType.SEC_ALT,
            'anti_newaccount': ulogger2026.EventType.SEC_NEWACCOUNT,
        }
        ev = action_to_event.get(action, ulogger2026.EventType.COMMAND_EXEC)
        action_labels = {
            'warn': "avertissement", 'unwarn': "retrait d'avertissement",
            'mute': "mute", 'unmute': "unmute", 'kick': "expulsion",
            'ban': "bannissement", 'unban': "débannissement",
            'timeout': "timeout", 'purge': "purge de messages",
        }
        verb = action_labels.get(action, action)
        try:
            target_name = f"{target.mention} (`{target}`)" if target else "_cible inconnue_"
        except Exception:
            target_name = "_cible_"
        desc = f"**{verb.capitalize()}** appliqué à {target_name}."
        extra_dict = {}
        if duration:
            extra_dict["⏱️ Durée"] = duration
        if extra:
            extra_dict["ℹ️ Détail"] = str(extra)
        await ulogger2026.log_event(
            bot, guild, ev,
            description=desc,
            user=target,
            moderator=mod,
            reason=reason,
            extra=extra_dict or None,
        )
    except Exception as ex:
        print(f"[UNIFIED MOD LOG] {ex}")

    # ───── Salon legacy (rétrocompat) ─────
    try:
        c = await cfg(guild.id)
        log_ch = None if c.get('logs_sur_site_v1') else guild.get_channel(c.get('mod_log_channel', 0))
        if not log_ch:
            return

        colors = {'warn': 0xF39C12, 'unwarn': 0x2ECC71, 'mute': 0xE67E22, 'unmute': 0x2ECC71, 'kick': 0xE74C3C, 'ban': 0xC0392B, 'unban': 0x27AE60, 'infractions': 0x3498DB}
        emojis = {'warn': '⚠️', 'unwarn': '✅', 'mute': '🔇', 'unmute': '🔊', 'kick': '👢', 'ban': '🔨', 'unban': '🔓', 'infractions': '📋'}
        titles = {'warn': 'Avertissement', 'unwarn': 'Warn supprimé', 'mute': 'Mute', 'unmute': 'Unmute', 'kick': 'Expulsion', 'ban': 'Bannissement', 'unban': 'Débannissement', 'infractions': 'Consultation infractions'}

        e = discord.Embed(
            color=colors.get(action, C.ORANGE),
            timestamp=now()
        )
        e.set_author(name=f"{emojis.get(action, '🔨')} {titles.get(action, action.upper())}", icon_url=guild.icon.url if guild.icon else None)
        e.add_field(name="Modérateur", value=f"{mod.mention}\n`{mod.id}`", inline=True)
        e.add_field(name="Membre", value=f"{target.mention}\n`{target.id}`", inline=True)

        if duration:
            e.add_field(name="Durée", value=duration, inline=True)
        if reason:
            e.add_field(name="Raison", value=reason[:1024], inline=False)
        if extra:
            e.add_field(name="Info", value=extra, inline=False)

        e.set_thumbnail(url=target.display_avatar.url)
        e.set_footer(text=f"ID cible: {target.id}")
        await webhook_send(log_ch, 'mod_log', view=carte_embed(e), allowed_mentions=discord.AllowedMentions.none())
    except Exception as ex:
        print(f"[MOD LOG ERROR] {ex}")

# NOTE: ModerationPanel (View V1, embed) supprime — remplace par ModerationPanelV2 (LayoutView).
# Jamais instancie (seule ref externe etait dans MainPanel V1, lui aussi supprime).

class ModerationPanelV2(LayoutView):
    """Panneau de modération en V2 — config rôles + salon logs."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self._loading = True
        # Build initial (sera complété en async)

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        """Construit le LayoutView et l'envoie/édite via interaction."""
        c = await cfg(self.g.id)

        # Compter les infractions
        inf_count = 0
        try:
            async with get_db() as db:
                async with db.execute('SELECT COUNT(*) FROM infractions WHERE guild_id=?', (self.g.id,)) as cur:
                    row = await cur.fetchone()
                    inf_count = row[0] if row else 0
        except Exception as ex:
            print(f"[MOD-V2] Erreur count infractions: {ex}")

        # Récupérer les éléments configurés
        log_ch = self.g.get_channel(c.get('mod_log_channel', 0))
        warn_role = self.g.get_role(c.get('mod_warn_role', 0))
        mute_role = self.g.get_role(c.get('mod_mute_role', 0))
        inf_role = self.g.get_role(c.get('mod_infractions_role', 0))
        clear_role = self.g.get_role(c.get('mod_clear_role', 0))
        #  ⚠️ SANS CE PICKER, LA CLÉ RESTAIT À 0 POUR TOUJOURS : `/off` et
        #  `/mod direction` étaient donc réservés aux administrateurs, quoi
        #  qu'on lise dans le code.
        dir_role = self.g.get_role(c.get('direction_allowed_role', 0))

        def dot(item):
            return f"🔘 {item.mention if hasattr(item, 'mention') else item.name}" if item else "⚪ _non défini_"

        # Reconstruire les boutons à chaque render (pour les ré-attacher)
        self.clear_items()

        site = bool(c.get('logs_sur_site_v1'))
        b_logs = Button(emoji=visuels.icone("journal"), label="Salon des alertes" if site else "Salon Logs",
                        style=discord.ButtonStyle.primary, custom_id="mpv2_set_logs")
        b_logs.callback = self._cb_set_logs
        b_warn = Button(emoji=visuels.icone("avertir"), label="Rôle warn", style=discord.ButtonStyle.primary, custom_id="mpv2_set_warn")
        b_warn.callback = self._cb_set_warn
        b_mute = Button(emoji=visuels.icone("muet"), label="Rôle mute", style=discord.ButtonStyle.primary, custom_id="mpv2_set_mute")
        b_mute.callback = self._cb_set_mute
        b_inf = Button(emoji=visuels.icone("journal"), label="Rôle infractions", style=discord.ButtonStyle.primary, custom_id="mpv2_set_inf")
        b_inf.callback = self._cb_set_inf
        b_clear = Button(emoji=visuels.icone("balai"), label="Rôle clear", style=discord.ButtonStyle.primary, custom_id="mpv2_set_clear")
        b_clear.callback = self._cb_set_clear
        b_dir = Button(emoji=visuels.icone("interdit"), label="Rôle Direction", style=discord.ButtonStyle.danger,
                       custom_id="mpv2_set_direction")
        b_dir.callback = self._cb_set_direction
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="mpv2_back")
        b_back.callback = self._cb_back

        items: list = []
        items.append(visuels.bandeau("sanctions", "Modération"))
        items.append(v2_subtitle(f"`{inf_count}` infractions enregistrées"))

        items.append(v2_divider())
        items.append(v2_body(
            (f"**Salon des alertes** · {dot(log_ch)} — les sanctions sont sur le site\n" if site
             else f"**Salon logs** · {dot(log_ch)}\n")
            + f"⚠️ **Rôle /warn** · {dot(warn_role)}\n"
            f"**Rôle /mute** · {dot(mute_role)}\n"
            f"**Rôle /infractions** · {dot(inf_role)}\n"
            f"**Rôle /mod clear** · {dot(clear_role)}\n"
            f"**Rôle Direction** · {dot(dir_role)} — `/off`, `/mod direction`"
        ))
        items.append(v2_divider())

        items.append(discord.ui.ActionRow(b_logs, b_warn, b_mute, b_inf, b_clear))
        items.append(discord.ui.ActionRow(b_dir, b_back))

        self.add_item(v2_container(*items, color=Palette.WARNING))

        await _afficher_panneau(self, interaction, edit)

    async def _open_channel_picker(self, interaction, key, label):
        """Phase 3.0k : V2 native picker (plus de transition V2->V1 qui plantait)."""
        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key=key,
            return_panel_factory=lambda: ModerationPanelV2(self.u, self.g),
            title=f"{label}",
            description=f"Sélectionne le salon. {len(list(self.g.text_channels))} disponibles.",
            color=0xE67E22,
        )
        await v.render_to(interaction, edit=True)

    async def _open_role_picker(self, interaction, key, label):
        """Phase 3.0k : V2 native picker."""
        v = V2GenericRolePicker(
            self.u, self.g,
            config_key=key,
            return_panel_factory=lambda: ModerationPanelV2(self.u, self.g),
            title=f"{label}",
            description="Sélectionne le rôle minimum requis pour cette commande.",
            color=0xE67E22,
        )
        await v.render_to(interaction, edit=True)

    async def _cb_set_logs(self, i):
        await self._open_channel_picker(i, 'mod_log_channel', 'Salon Logs')

    async def _cb_set_warn(self, i):
        await self._open_role_picker(i, 'mod_warn_role', 'Rôle /warn')

    async def _cb_set_mute(self, i):
        await self._open_role_picker(i, 'mod_mute_role', 'Rôle /mute')

    async def _cb_set_inf(self, i):
        await self._open_role_picker(i, 'mod_infractions_role', 'Rôle /infractions')

    async def _cb_set_clear(self, i):
        await self._open_role_picker(i, 'mod_clear_role', 'Rôle /mod clear')

    async def _cb_set_direction(self, i):
        await self._open_role_picker(i, 'direction_allowed_role',
                                     'Rôle Direction (/off, /mod direction)')

    async def _cb_back(self, i):
        # Refonte 2026-08 : retour direct à la racine /configure (MainPanelV2).
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


