class ImmunePanelV2(LayoutView):
    """Panneau Immunités en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        async with get_db() as db:
            async with db.execute('SELECT role_id FROM immune_roles WHERE guild_id=?', (self.g.id,)) as c:
                rids = [r[0] for r in await c.fetchall()]
            async with db.execute('SELECT user_id FROM immune_users WHERE guild_id=?', (self.g.id,)) as c:
                uids = [r[0] for r in await c.fetchall()]
            async with db.execute('SELECT channel_id FROM immune_channels WHERE guild_id=?', (self.g.id,)) as c:
                chids = [r[0] for r in await c.fetchall()]

        total = len(rids) + len(uids) + len(chids)

        # Phase 6 : affichage compact, 6 max par catégorie
        def _list(items, fmt, label):
            if not items:
                return f"⚪ _aucun {label}_"
            shown = ", ".join(fmt(x) for x in items[:6])
            if len(items) > 6:
                shown += f" *(+{len(items) - 6})*"
            return shown

        roles_txt = _list(rids, lambda r: f"<@&{r}>", "rôle")
        users_txt = _list(uids, lambda u: f"<@{u}>", "utilisateur")
        chans_txt = _list(chids, lambda c: f"<#{c}>", "salon")

        # Boutons
        self.clear_items()
        b_add_role = Button(emoji=visuels.icone("ajouter"), label="Rôle", style=discord.ButtonStyle.success, custom_id="ipv2_add_role")
        b_add_role.callback = self._cb_add_role
        b_add_user = Button(emoji=visuels.icone("ajouter"), label="Utilisateur", style=discord.ButtonStyle.success, custom_id="ipv2_add_user")
        b_add_user.callback = self._cb_add_user
        b_add_chan = Button(emoji=visuels.icone("ajouter"), label="Salon", style=discord.ButtonStyle.success, custom_id="ipv2_add_chan")
        b_add_chan.callback = self._cb_add_chan
        b_remove = Button(emoji=visuels.icone("supprimer"), label="Retirer", style=discord.ButtonStyle.danger, disabled=(total == 0), custom_id="ipv2_remove")
        b_remove.callback = self._cb_remove
        b_clear = Button(emoji=visuels.icone("balai"), label="Tout effacer", style=discord.ButtonStyle.danger, disabled=(total == 0), custom_id="ipv2_clear")
        b_clear.callback = self._cb_clear
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="ipv2_back")
        b_back.callback = self._cb_back

        items: list = []
        items.append(visuels.bandeau("immunites", "Immunités"))
        items.append(v2_subtitle(f"`{total}` élément(s) · bypass des filtres"))

        items.append(v2_divider())
        items.append(v2_body(
            f"**Rôles** *(`{len(rids)}`)* · {roles_txt}\n"
            f"**Utilisateurs** *(`{len(uids)}`)* · {users_txt}\n"
            f"**Salons** *(`{len(chids)}`)* · {chans_txt}"
        ))
        items.append(v2_divider())
        items.append(v2_body(
            "-# Ignorent liens, images, GIFs, invitations et majuscules — jamais le phishing ni les scams."
        ))
        items.append(v2_divider())
        items.append(discord.ui.ActionRow(b_add_role, b_add_user, b_add_chan))
        items.append(discord.ui.ActionRow(b_remove, b_clear, b_back))

        self.add_item(v2_container(*items, color=Palette.PREMIUM))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_add_role(self, i):
        # Phase 21 : RoleSelect natif (affiche TOUS les rôles via Discord)
        try:
            v = View(timeout=180)
            role_select = discord.ui.RoleSelect(
                placeholder="Choisir le(s) rôle(s) à immuniser…",
                min_values=1, max_values=25,
            )

            async def _on_pick(ix):
                try:
                    role_ids = [int(rid) for rid in ix.data.get('values', [])]
                    added = 0
                    async with get_db() as db:
                        for rid in role_ids:
                            await db.execute(
                                'INSERT OR IGNORE INTO immune_roles VALUES(?,?)',
                                (self.g.id, rid),
                            )
                            added += 1
                        await db.commit()
                        # Effet IMMÉDIAT : sans ça, le cache d'immunité garde l'ancien
                        # état jusqu'à l'expiration de son TTL.
                        _invalidate_immunity(self.g.id)
                    mentions = ", ".join(f"<@&{r}>" for r in role_ids[:10])
                    await ix.response.send_message(
                        f"✅ {added} rôle(s) ajouté(s) aux immunisés : {mentions}",
                        ephemeral=True,
                    )
                    try:
                        new_panel = ImmunePanelV2(self.u, self.g)
                        await new_panel.render_to(ix, edit=False)
                    except Exception:
                        pass
                except Exception as ex:
                    print(f"[immune add_role pick] {ex}")

            role_select.callback = _on_pick
            v.add_item(role_select)
            await i.response.send_message(
                "🎭 Sélectionne le(s) rôle(s) à immuniser :",
                view=v, ephemeral=True,
            )
        except Exception as ex:
            print(f"[_cb_add_role immune] {ex}")

    async def _cb_add_user(self, i):
        # Phase 21 : picker natif Discord (affiche tous les users avec recherche)
        try:
            v = View(timeout=180)
            user_select = discord.ui.UserSelect(
                placeholder="Choisir l'utilisateur à immuniser…",
                min_values=1, max_values=1,
            )

            async def _on_pick(ix):
                try:
                    uid = int(ix.data['values'][0])
                    member = self.g.get_member(uid)
                    async with get_db() as db:
                        await db.execute(
                            'INSERT OR IGNORE INTO immune_users VALUES(?,?)',
                            (self.g.id, uid),
                        )
                        await db.commit()
                        # Effet IMMÉDIAT : sans ça, le cache d'immunité garde l'ancien
                        # état jusqu'à l'expiration de son TTL.
                        _invalidate_immunity(self.g.id)
                    name = member.mention if member else f"`{uid}`"
                    await ix.response.send_message(
                        f"✅ {name} ajouté aux utilisateurs immunisés.",
                        ephemeral=True,
                    )
                    # Re-render le panel parent
                    try:
                        new_panel = ImmunePanelV2(self.u, self.g)
                        await ix.edit_original_response(view=new_panel)
                    except Exception:
                        pass
                except Exception as ex:
                    print(f"[immune add_user pick] {ex}")

            user_select.callback = _on_pick
            v.add_item(user_select)
            await i.response.send_message(
                "👤 Sélectionne l'utilisateur à ajouter aux immunisés :",
                view=v, ephemeral=True,
            )
        except Exception as ex:
            print(f"[_cb_add_user] {ex}")
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : `{ex}`", ephemeral=True)
            except Exception:
                pass

    async def _cb_add_chan(self, i):
        # Phase 21 : ChannelSelect natif (affiche TOUS les salons via Discord)
        try:
            v = View(timeout=180)
            channel_select = discord.ui.ChannelSelect(
                channel_types=[discord.ChannelType.text, discord.ChannelType.news],
                placeholder="Choisir le(s) salon(s) à immuniser…",
                min_values=1, max_values=25,
            )

            async def _on_pick(ix):
                try:
                    chan_ids = [int(cid) for cid in ix.data.get('values', [])]
                    added = 0
                    async with get_db() as db:
                        for cid in chan_ids:
                            await db.execute(
                                'INSERT OR IGNORE INTO immune_channels VALUES(?,?)',
                                (self.g.id, cid),
                            )
                            added += 1
                        await db.commit()
                        # Effet IMMÉDIAT : sans ça, le cache d'immunité garde l'ancien
                        # état jusqu'à l'expiration de son TTL.
                        _invalidate_immunity(self.g.id)
                    mentions = ", ".join(f"<#{c}>" for c in chan_ids[:10])
                    await ix.response.send_message(
                        f"✅ {added} salon(s) ajouté(s) aux immunisés : {mentions}",
                        ephemeral=True,
                    )
                    try:
                        new_panel = ImmunePanelV2(self.u, self.g)
                        await new_panel.render_to(ix, edit=False)
                    except Exception:
                        pass
                except Exception as ex:
                    print(f"[immune add_chan pick] {ex}")

            channel_select.callback = _on_pick
            v.add_item(channel_select)
            await i.response.send_message(
                "📺 Sélectionne le(s) salon(s) à immuniser :",
                view=v, ephemeral=True,
            )
        except Exception as ex:
            print(f"[_cb_add_chan immune] {ex}")

    async def _cb_remove(self, i):
        v = ImmuneRemoveViewV2(self.u, self.g)
        await v.render_to(i, edit=True)

    async def _cb_clear(self, i):
        async with get_db() as db:
            await db.execute('DELETE FROM immune_roles WHERE guild_id=?', (self.g.id,))
            await db.execute('DELETE FROM immune_users WHERE guild_id=?', (self.g.id,))
            await db.execute('DELETE FROM immune_channels WHERE guild_id=?', (self.g.id,))
            await db.commit()
            # Effet IMMÉDIAT : sans ça, le cache d'immunité garde l'ancien
            # état jusqu'à l'expiration de son TTL.
            _invalidate_immunity(self.g.id)
        new_panel = ImmunePanelV2(self.u, self.g)
        await new_panel.render_to(i, edit=True)

    async def _cb_back(self, i):
        # Refonte 2026-08 : retour direct à la racine /configure (MainPanelV2).
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class ImmuneRemoveViewV2(LayoutView):
    """Hub V2 pour supprimer une immunite (role / utilisateur / salon)."""

    def __init__(self, u, g):
        super().__init__(timeout=120)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        # Compter les immunités existantes pour disabled
        async with get_db() as db:
            async with db.execute('SELECT COUNT(*) FROM immune_roles WHERE guild_id=?', (self.g.id,)) as c:
                role_count = (await c.fetchone())[0]
            async with db.execute('SELECT COUNT(*) FROM immune_users WHERE guild_id=?', (self.g.id,)) as c:
                user_count = (await c.fetchone())[0]
            async with db.execute('SELECT COUNT(*) FROM immune_channels WHERE guild_id=?', (self.g.id,)) as c:
                chan_count = (await c.fetchone())[0]

        self.clear_items()
        b_role = Button(
            emoji=visuels.icone("role"), label=f"Rôle ({role_count})",
            style=discord.ButtonStyle.primary,
            disabled=(role_count == 0),
            custom_id="irvv2_role",
        )
        b_role.callback = self._cb_role
        b_user = Button(
            emoji=visuels.icone("membre"), label=f"Utilisateur ({user_count})",
            style=discord.ButtonStyle.primary,
            disabled=(user_count == 0),
            custom_id="irvv2_user",
        )
        b_user.callback = self._cb_user
        b_chan = Button(
            emoji=visuels.icone("video"), label=f"Salon ({chan_count})",
            style=discord.ButtonStyle.primary,
            disabled=(chan_count == 0),
            custom_id="irvv2_chan",
        )
        b_chan.callback = self._cb_chan
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="irvv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("immunites_retrait", "Retirer une immunité"),
            v2_subtitle("Choisis le type d'élément à retirer"),
            v2_divider(),
            v2_body(
                f"**Rôles immunisés** · `{role_count}`\n"
                f"**Utilisateurs immunisés** · `{user_count}`\n"
                f"**Salons immunisés** · `{chan_count}`"
            ),
            v2_divider(),
            v2_subtitle("Les boutons sont désactivés si aucun élément du type n'existe"),
            discord.ui.ActionRow(b_role, b_user, b_chan, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.DANGER))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_role(self, i):
        # Phase 3.0d : pagination, plus de truncation a 25
        async with get_db() as db:
            async with db.execute('SELECT role_id FROM immune_roles WHERE guild_id=?', (self.g.id,)) as c:
                rids = [r[0] for r in await c.fetchall()]
        if not rids:
            return await i.response.send_message("❌ Aucun rôle immunisé", ephemeral=True)
        await PaginatedImmuneRemoveView(self.u, self.g, 'role', rids, page=0).render_to(i, edit=True)

    async def _cb_user(self, i):
        async with get_db() as db:
            async with db.execute('SELECT user_id FROM immune_users WHERE guild_id=?', (self.g.id,)) as c:
                uids = [r[0] for r in await c.fetchall()]
        if not uids:
            return await i.response.send_message("❌ Aucun utilisateur immunisé", ephemeral=True)
        await PaginatedImmuneRemoveView(self.u, self.g, 'user', uids, page=0).render_to(i, edit=True)

    async def _cb_chan(self, i):
        async with get_db() as db:
            async with db.execute('SELECT channel_id FROM immune_channels WHERE guild_id=?', (self.g.id,)) as c:
                chids = [r[0] for r in await c.fetchall()]
        if not chids:
            return await i.response.send_message("❌ Aucun salon immunisé", ephemeral=True)
        await PaginatedImmuneRemoveView(self.u, self.g, 'channel', chids, page=0).render_to(i, edit=True)

    async def _cb_back(self, i):
        v = ImmunePanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class PaginatedImmuneRemoveView(LayoutView):
    """Retirer une immunité (rôle, membre ou salon), 24 par page. 19/10/2026 : en V2 — le menu parent
    est en V2, et l'éditer avec un embed répondait « Erreur 400 » : seul « Tout effacer » marchait."""

    KIND_TABLE = {'role': 'immune_roles', 'user': 'immune_users', 'channel': 'immune_channels'}
    KIND_COL = {'role': 'role_id', 'user': 'user_id', 'channel': 'channel_id'}
    KIND_LABEL_FN = {
        'role': lambda g, x: f"@{g.get_role(x).name if g.get_role(x) else x}"[:25],
        'user': lambda g, x: f"@{g.get_member(x).display_name if g.get_member(x) else x}"[:25],
        'channel': lambda g, x: (lambda c: f"# {c.name if c else x}"[:25])(g.get_channel(x)),
    }
    TITRES = {'role': "Retirer un rôle immunisé", 'user': "Retirer un membre immunisé",
              'channel': "Retirer un salon immunisé"}

    def __init__(self, u, g, kind: str, items: list[int], page: int = 0):
        super().__init__(timeout=180)
        self.u, self.g, self.kind, self.items, self.page = u, g, kind, items, page
        self.max_page = max(0, (len(items) - 1) // 24)

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, i, *, edit=True):
        label_fn = self.KIND_LABEL_FN[self.kind]
        opts = []
        for item_id in self.items[self.page * 24:(self.page + 1) * 24]:
            try:
                label = label_fn(self.g, item_id)
            except Exception:
                label = str(item_id)[:25]
            opts.append(discord.SelectOption(label=label, value=str(item_id)))
        lignes = [v2_title(f"{self.TITRES[self.kind]} ({len(self.items)})", level=3)]
        if opts:
            sel = discord.ui.Select(placeholder="Choisir l'immunité à retirer…", options=opts)

            async def _choisir(it):
                await self._retirer(it, int(sel.values[0]))
            sel.callback = _choisir
            lignes.append(discord.ui.ActionRow(sel))
        boutons = []
        if self.max_page > 0:
            prec = Button(emoji=visuels.icone("retour", '◀️'), style=discord.ButtonStyle.secondary,
                          disabled=self.page == 0)
            page = Button(label=f"{self.page + 1}/{self.max_page + 1}", style=discord.ButtonStyle.primary,
                          disabled=True)
            suiv = Button(emoji=visuels.icone("activer", '▶️'), style=discord.ButtonStyle.secondary,
                          disabled=self.page >= self.max_page)

            async def _prec(it):
                self.page -= 1
                await self.render_to(it, edit=True)

            async def _suiv(it):
                self.page += 1
                await self.render_to(it, edit=True)
            prec.callback, suiv.callback = _prec, _suiv
            boutons += [prec, page, suiv]
        retour = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.danger)

        async def _retour(it):
            await ImmuneRemoveViewV2(self.u, self.g).render_to(it, edit=True)
        retour.callback = _retour
        boutons.append(retour)
        lignes.append(discord.ui.ActionRow(*boutons))
        self.clear_items()
        self.add_item(v2_container(*lignes, color=Palette.DANGER))
        await _afficher_panneau(self, i, edit)

    async def _retirer(self, i, item_id: int):
        async with get_db() as db:
            await db.execute(f'DELETE FROM {self.KIND_TABLE[self.kind]} WHERE guild_id=? AND {self.KIND_COL[self.kind]}=?',
                             (self.g.id, item_id))
            await db.commit()
        _invalidate_immunity(self.g.id)  # effet immédiat, pas d'attente du cache
        await ImmuneRemoveViewV2(self.u, self.g).render_to(i, edit=True)


