async def get_webhook(channel, platform: str):
    """Récupère ou crée un webhook pour une plateforme dans un salon"""
    cache_key = (channel.id, platform)
    
    if cache_key in _webhook_cache:
        return _webhook_cache[cache_key]
    
    wh_name = f"Bot-{platform}"
    
    try:
        webhooks = await channel.webhooks()
        for wh in webhooks:
            if wh.name == wh_name and wh.user and wh.user.id == channel.guild.me.id:
                _webhook_cache[cache_key] = wh
                return wh
        
        # Avatar personnalisé du bot pour les modules serveur
        wh = await channel.create_webhook(name=wh_name, reason=f"Notifications {platform}")
        _webhook_cache[cache_key] = wh
        return wh
    except discord.Forbidden:
        return None
    except Exception as ex:
        print(f"Erreur webhook {platform} dans #{channel.name}: {ex}")
        return None

async def _deja_poste(channel, kw: dict, depuis, cle=None):
    """Après un 5xx ou un délai dépassé, Discord a pu garder le message : on le cherche parmi les
    derniers du salon avant de renvoyer (sinon deux exemplaires). Rend le message trouvé, ou None.
    24/10/2026 : une carte V2 n'a ni contenu ni embed — la clé valait None et chaque annonce repartait
    en double. `cle` (l'URL publiée) se cherche dans le texte des cartes récentes ; une carte envoyée
    sans clé se reconnaît à son texte entier."""
    guild = getattr(channel, 'guild', None)
    explicite = bool(cle)
    if not cle:
        e = kw.get('embed') or next(iter(kw.get('embeds') or []), None)
        cle = (getattr(e, 'url', None) or getattr(e, 'title', None)) if e is not None else kw.get('content')
    carte = "" if cle or kw.get('view') is None else _texte_v2(getattr(kw['view'], 'children', None) or [], guild)
    if not (cle or carte):
        return None
    try:
        async for m in channel.history(limit=10, after=depuis):
            if m.webhook_id is None and m.author.id != bot.user.id:
                continue
            if cle and (m.content == cle or any((x.url or x.title) == cle for x in m.embeds)):
                return m
            if (explicite or carte) and getattr(m, 'components', None):
                texte = _texte_v2(m.components, guild)
                if (explicite and cle in texte) or (carte and texte == carte):
                    return m
    except discord.HTTPException as ex:
        _logerr("webhook.verif", ex, guild_id=getattr(guild, 'id', 0))
    return None


async def webhook_send(channel, platform: str, embed=None, content=None, file=None, files=None, embeds=None, view=None,
                       allowed_mentions=None, cle=None):
    """Envoie un message via webhook avec le profil de la plateforme.
    Supporte: content, embed, embeds, file, files, view, allowed_mentions
    Fallback automatique sur channel.send si webhook impossible.
    `cle` (24/10/2026) : ce qui identifie une publication (son URL). Après un 5xx ou un délai dépassé,
    on la cherche dans les derniers messages du salon avant de renvoyer (`_deja_poste`).

    Phase 3.8 : logging exhaustif des échecs pour traquer les publications fantômes.

    ⚠️ `allowed_mentions` AJOUTÉ LE 19/08/2026, ET IL EST INDISPENSABLE AU PING.
    Les rôles de notification de la veille Roblox sont créés `mentionable=False`
    (un membre ne doit pas pouvoir réveiller le serveur avec). La contrepartie :
    l'expéditeur doit autoriser explicitement ce rôle, sinon le `<@&id>` du
    message s'affiche en pastille et ne notifie PERSONNE. Un ping silencieux
    est indiscernable d'un ping réussi — d'où ce paramètre plutôt qu'un défaut.
    """
    chan_info = f"#{getattr(channel, 'name', '?')}/{getattr(channel, 'id', '?')}"
    if isinstance(channel, discord.Thread):
        kw = {k: v for k, v in (('content', content), ('embed', embed), ('embeds', embeds),
                                ('file', file), ('files', files), ('view', view),
                                ('allowed_mentions', allowed_mentions)) if v is not None}
        return await channel.send(**kw)

    def _build_kwargs(include_profile=True):
        kw = {}
        if content is not None: kw['content'] = content
        if embed: kw['embed'] = embed
        if embeds: kw['embeds'] = embeds
        if file: kw['file'] = file
        if files: kw['files'] = files
        if view: kw['view'] = view
        #  `is not None` : on distingue « rien de demandé » (on laisse le défaut
        #  de discord.py) de « fermeture explicite » (AllowedMentions.none()),
        #  qui doit être transmise telle quelle.
        if allowed_mentions is not None: kw['allowed_mentions'] = allowed_mentions
        if include_profile:
            profile = WEBHOOK_PROFILES.get(platform, {'name': '📢 Notifications'})
            kw['username'] = profile['name']
            # Avatar : TOUJOURS l'avatar du bot (stocké dans _BOT_AVATAR_URL au ready)
            # Cela garantit un logo UNIFORME sur TOUS les messages webhook
            if _BOT_AVATAR_URL:
                kw['avatar_url'] = _BOT_AVATAR_URL
            else:
                try:
                    kw['avatar_url'] = bot.user.display_avatar.url
                except:
                    pass  # Bot pas encore prêt
            kw['wait'] = True
        return kw

    # Sanity check : au moins UN payload est requis pour envoyer
    _kw_check = _build_kwargs(False)
    if not _kw_check:
        print(f"[webhook_send] {platform} {chan_info}: AUCUN payload (content/embed/file vide)")
        return None

    wh = await get_webhook(channel, platform)
    if not wh:
        # Pas de webhook dispo : fallback channel.send
        try:
            return await channel.send(**_build_kwargs(False))
        except discord.Forbidden as ex:
            print(f"[webhook_send] {platform} {chan_info}: FORBIDDEN (permissions manquantes) : {ex}")
            return None
        except discord.HTTPException as ex:
            print(f"[webhook_send] {platform} {chan_info}: HTTPException fallback channel.send : {ex}")
            return None
        except Exception as ex:
            print(f"[webhook_send] {platform} {chan_info}: erreur inattendue channel.send : {type(ex).__name__}: {ex}")
            return None

    _avant = discord.utils.utcnow() - timedelta(seconds=10)
    try:
        return await wh.send(**_build_kwargs(True))
    except (discord.NotFound, discord.InvalidData) as ex:
        print(f"[webhook_send] {platform} {chan_info}: webhook invalide ({type(ex).__name__}), recréation")
        cache_key = (channel.id, platform)
        _webhook_cache.pop(cache_key, None)
        try:
            wh = await channel.create_webhook(name=f"Bot-{platform}", reason=f"Recréation webhook {platform}")
            _webhook_cache[cache_key] = wh
            return await wh.send(**_build_kwargs(True))
        except discord.Forbidden:
            print(f"[webhook_send] {platform} {chan_info}: FORBIDDEN à la recréation webhook, fallback channel.send")
            try:
                return await channel.send(**_build_kwargs(False))
            except Exception as ex2:
                print(f"[webhook_send] {platform} {chan_info}: fallback aussi échoué : {ex2}")
                return None
        except Exception as ex2:
            print(f"[webhook_send] {platform} {chan_info}: recréation webhook échouée : {ex2}")
            try:
                return await channel.send(**_build_kwargs(False))
            except Exception as ex3:
                print(f"[webhook_send] {platform} {chan_info}: fallback aussi échoué : {ex3}")
                return None
    except discord.Forbidden as ex:
        print(f"[webhook_send] {platform} {chan_info}: FORBIDDEN webhook.send : {ex}")
        try:
            return await channel.send(**_build_kwargs(False))
        except Exception as ex2:
            print(f"[webhook_send] {platform} {chan_info}: fallback channel.send échoué : {ex2}")
            return None
    except discord.HTTPException as ex:
        # Inclut 40062 (rate-limited), 50013 (perms), etc.
        print(f"[webhook_send] {platform} {chan_info}: HTTPException status={getattr(ex, 'status', '?')} code={getattr(ex, 'code', '?')} : {ex}")
        if (getattr(ex, 'status', 0) or 0) >= 500:
            deja = await _deja_poste(channel, _build_kwargs(False), _avant, cle)
            if deja is not None:
                return deja
        try:
            return await channel.send(**_build_kwargs(False))
        except Exception as ex2:
            print(f"[webhook_send] {platform} {chan_info}: fallback channel.send échoué : {ex2}")
            return None
    except Exception as ex:
        print(f"[webhook_send] {platform} {chan_info}: erreur inattendue webhook : {type(ex).__name__}: {ex}")
        deja = await _deja_poste(channel, _build_kwargs(False), _avant, cle)  # délai dépassé : peut-être reçu
        if deja is not None:
            return deja
        try:
            return await channel.send(**_build_kwargs(False))
        except Exception as ex2:
            print(f"[webhook_send] {platform} {chan_info}: fallback channel.send échoué : {ex2}")
            return None




