class NewPanelModal(Modal, title="Nouveau Panel"):
    name = TextInput(label="Nom du panel", placeholder="Support, Partenariat...", max_length=30)
    mx = TextInput(label="Max tickets par utilisateur", placeholder="1", default="1", max_length=2)
    
    def __init__(self, u, g):
        super().__init__()
        self.u = u
        self.g = g
    
    async def on_submit(self, i):
        pid = str(int(time.time()))
        mxt = max(1, min(10, int(self.mx.value) if self.mx.value.isdigit() else 1))
        c = await cfg(self.g.id)
        panels = c.get('ticket_panels', {})
        panels[pid] = {'name': self.name.value, 'category': 0, 'questions': [], 'max': mxt}
        await db_set(self.g.id, 'ticket_panels', panels)
        # FIX : ouvrir l'éditeur V2 (avant : PanelEditView legacy + embed posé sur un
        # message LayoutView V2 → HTTP 400 « Échec de l'interaction » alors que le panel
        # ÉTAIT créé en DB). render_to édite le message V2 proprement.
        await PanelEditViewV2(self.u, self.g, pid).render_to(i, edit=True)

class EditPanelSelectViewV2(LayoutView):
    """V2 wrapper pour la selection d'un panel de tickets a modifier."""

    def __init__(self, u, g, opts):
        super().__init__(timeout=120)
        self.u = u
        self.g = g
        self.opts = opts

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    def _build(self):
        sel = Select(placeholder="Choisir un panel...", options=self.opts, custom_id="epsv2_sel") if self.opts else None
        if sel:
            sel.callback = self._cb_select
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="epsv2_back")
        b_back.callback = self._cb_back

        self.clear_items()
        items: list = [
            visuels.bandeau("tickets_modifier", "Modifier un panneau"),
            v2_subtitle(f"`{len(self.opts)}` panel(s) configuré(s)"),
            v2_divider(),
            v2_body("Choisis le panel à modifier dans le menu ci-dessous."),
            v2_divider(),
        ]
        if sel:
            items.append(discord.ui.ActionRow(sel))
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.ACCENT))

    async def render_to(self, interaction, *, edit=True):
        self._build()
        await _afficher_panneau(self, interaction, edit)

    async def _cb_select(self, i):
        pid = i.data['values'][0]
        v = PanelEditViewV2(self.u, self.g, pid)
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = TicketMainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


class PanelEditViewV2(LayoutView):
    """Edition d'un panel de tickets en V2."""

    def __init__(self, u, g, pid):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.pid = pid

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def _get_panel(self):
        c = await cfg(self.g.id)
        return c.get('ticket_panels', {}).get(self.pid, {})

    async def render_to(self, interaction, *, edit=True):
        pnl = await self._get_panel()
        c = await cfg(self.g.id)
        cat = self.g.get_channel(pnl.get('category', 0))

        # Rôle staff
        staff_role_id = pnl.get('staff_role', 0)
        if staff_role_id:
            staff_role = self.g.get_role(staff_role_id)
            staff_txt = staff_role.mention if staff_role else "_Rôle introuvable_"
        else:
            global_staff = self.g.get_role(c.get('ticket_staff', 0))
            staff_txt = f"{global_staff.mention} _(global)_" if global_staff else "⚪ _non configuré_"

        qs = pnl.get('questions', [])
        qs_block = "\n".join(f"• {q['title']}" for q in qs[:5]) if qs else "_Aucune question_"

        embed_title = pnl.get('embed_title', '')
        embed_desc = pnl.get('embed_description', '')
        if embed_title or embed_desc:
            apparence = ""
            if embed_title:
                apparence += f"**Titre :** {embed_title[:50]}{'…' if len(embed_title) > 50 else ''}\n"
            if embed_desc:
                apparence += f"**Description :** {embed_desc[:50]}{'…' if len(embed_desc) > 50 else ''}"
        else:
            apparence = "_Par défaut_"

        welcome = pnl.get('welcome_message', '')
        welcome_txt = (welcome[:80] + "…") if len(welcome) > 80 else welcome
        welcome_block = f"_{welcome_txt}_" if welcome else "_Aucun message configuré_"

        blacklist = pnl.get('blacklist', [])
        bl_txt = f"`{len(blacklist)}` membre(s)" if blacklist else "_Aucun_"

        self.clear_items()
        b_cat = Button(emoji=visuels.icone("dossier"), label="Catégorie", style=discord.ButtonStyle.primary, custom_id="pevv2_cat")
        b_cat.callback = self._cb_cat
        b_staff = Button(emoji=visuels.icone("membres"), label="Rôle Staff", style=discord.ButtonStyle.primary, custom_id="pevv2_staff")
        b_staff.callback = self._cb_staff
        b_qs = Button(emoji=visuels.icone("modifier"), label="Questions", style=discord.ButtonStyle.primary, custom_id="pevv2_qs")
        b_qs.callback = self._cb_qs
        b_max = Button(emoji=visuels.icone("numero"), label="Max", style=discord.ButtonStyle.secondary, custom_id="pevv2_max")
        b_max.callback = self._cb_max
        b_apparence = Button(emoji=visuels.icone("palette"), label="Apparence", style=discord.ButtonStyle.success, custom_id="pevv2_app")
        b_apparence.callback = self._cb_apparence
        b_welcome = Button(emoji=visuels.icone("accueil"), label="Message accueil", style=discord.ButtonStyle.success, custom_id="pevv2_wel")
        b_welcome.callback = self._cb_welcome
        b_blacklist = Button(emoji=visuels.icone("interdit"), label="Blacklist", style=discord.ButtonStyle.danger, custom_id="pevv2_bl")
        b_blacklist.callback = self._cb_blacklist
        b_send = Button(emoji=visuels.icone("exporter"), label="Envoyer", style=discord.ButtonStyle.primary, custom_id="pevv2_send")
        b_send.callback = self._cb_send
        b_delete = Button(emoji=visuels.icone("supprimer"), label="Supprimer", style=discord.ButtonStyle.danger, custom_id="pevv2_del")
        b_delete.callback = self._cb_delete
        b_back = Button(emoji=visuels.icone("retour"), label="Retour", style=discord.ButtonStyle.secondary, custom_id="pevv2_back")
        b_back.callback = self._cb_back

        items: list = [
            visuels.bandeau("tickets_panneau", "Panneau de tickets"),
            v2_title(f"{pnl.get('name', '?')}", level=3),
            v2_subtitle("Configuration spécifique de ce panel de tickets"),
            v2_divider(),
            v2_body(
                f"**Catégorie** · `{cat.name if cat else 'Non configurée'}`\n"
                f"**Max tickets** · `{pnl.get('max', 1)}`\n"
                f"**Rôle Staff** · {staff_txt}"
            ),
            v2_divider(),
            v2_title(f"Questions ({len(qs)})", level=3),
            v2_body(qs_block),
            v2_divider(),
            v2_title("Apparence", level=3),
            v2_body(apparence),
            v2_divider(),
            v2_title("Message d'accueil", level=3),
            v2_body(welcome_block),
            v2_divider(),
            v2_body(f"**Blacklist** · {bl_txt}"),
            v2_divider(),
            discord.ui.ActionRow(b_cat, b_staff, b_qs, b_max),
            discord.ui.ActionRow(b_apparence, b_welcome, b_blacklist),
            discord.ui.ActionRow(b_send, b_delete, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.ACCENT))

        await _afficher_panneau(self, interaction, edit)

    # Phase 16 : Helper de fallback erreur pour TOUS les boutons (pattern robuste)
    async def _safe_error(self, i, ex):
        """Envoie un message d'erreur safe selon l'état de l'interaction."""
        print(f"[PanelEditViewV2] {type(ex).__name__}: {ex}")
        import traceback; traceback.print_exc()
        try:
            if i.response.is_done():
                await i.followup.send(f"❌ Erreur : `{type(ex).__name__}: {ex}`", ephemeral=True)
            else:
                await i.response.send_message(f"❌ Erreur : `{type(ex).__name__}: {ex}`", ephemeral=True)
        except Exception:
            pass

    async def _cb_cat(self, i):
        try:
            if not self.g.categories:
                return await i.response.send_message("❌ Aucune catégorie sur ce serveur", ephemeral=True)
            pid = self.pid

            async def _save(guild_id, cat_id):
                c = await cfg(guild_id)
                panels = c.get('ticket_panels', {}) or {}
                if pid in panels:
                    panels[pid]['category'] = cat_id
                    await db_set(guild_id, 'ticket_panels', panels)
            v = V2GenericChannelPicker(
                self.u, self.g,
                return_panel_factory=lambda: PanelEditViewV2(self.u, self.g, self.pid),
                title="Catégorie des tickets",
                description="Les tickets de ce type s'ouvrent dans cette catégorie.",
                color=0x9B59B6, channel_types=[discord.ChannelType.category], save_fn=_save)
            await v.render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_staff(self, i):
        try:
            # Phase 3.0k : V2 native picker avec save_fn nested (ticket_panels[pid].staff_role)
            pid = self.pid
            async def _save(guild_id, role_id):
                c = await cfg(guild_id)
                panels = c.get('ticket_panels', {}) or {}
                if pid in panels:
                    panels[pid]['staff_role'] = role_id
                    await db_set(guild_id, 'ticket_panels', panels)
            v = V2GenericRolePicker(
                self.u, self.g,
                return_panel_factory=lambda: PanelEditViewV2(self.u, self.g, self.pid),
                title="Rôle Staff du Panel",
                description="Le rôle qui gère ce panel. Aucun = utilise le rôle staff global.",
                color=0x9B59B6,
                save_fn=_save,
            )
            await v.render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_qs(self, i):
        try:
            await PanelQsView(self.u, self.g, self.pid).render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_max(self, i):
        try:
            await i.response.send_modal(SetMaxModal(self.u, self.g, self.pid))
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_apparence(self, i):
        try:
            modal = PanelAppearanceModalSimple(self.u, self.g, self.pid)
            await i.response.send_modal(modal)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_welcome(self, i):
        try:
            modal = WelcomeMessageModalSimple(self.u, self.g, self.pid)
            await i.response.send_modal(modal)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_blacklist(self, i):
        try:
            await PanelBlacklistView(self.u, self.g, self.pid).render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_send(self, i):
        # Phase 16 : defer IMMÉDIAT + try/except complet
        # L'utilisateur signalait "Échec de l'interaction" sur ce bouton
        # parce qu'il y avait 2 await cfg() avant la réponse → timeout possible
        try:
            # Defer pour ack instantané (ephemeral car la source est déjà ephemeral)
            try:
                await i.response.defer()
            except (discord.InteractionResponded, discord.NotFound):
                pass

            pnl = await self._get_panel()
            c = await cfg(self.g.id)

            # Validations
            if not pnl.get('category'):
                return await i.followup.send(
                    "❌ Configure la catégorie d'abord !",
                    ephemeral=True,
                )
            if not pnl.get('staff_role') and not c.get('ticket_staff'):
                return await i.followup.send(
                    "❌ Configure le rôle Staff d'abord (panel ou global) !",
                    ephemeral=True,
                )

            v = SendPanelPaginatedView(self.u, self.g, self.pid)
            # Phase 17 : V2 LayoutView, plus d'embed (interdit en V2)
            await i.edit_original_response(
                embed=None,
                view=v,
                attachments=[],
            )
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_delete(self, i):
        try:
            c = await cfg(self.g.id)
            panels = c.get('ticket_panels', {})
            if self.pid in panels:
                del panels[self.pid]
            await db_set(self.g.id, 'ticket_panels', panels)
            v = TicketMainPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)

    async def _cb_back(self, i):
        try:
            v = TicketMainPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
        except Exception as ex:
            await self._safe_error(i, ex)


