@bot.event
async def on_guild_join(guild):
    """Pose les commandes sur un serveur qui vient d'inviter le bot.

    ⚠️ INDISPENSABLE DEPUIS LA PURGE DU REGISTRE GLOBAL (06/09/2026). Les
    commandes ne vivent plus que dans les registres de guilde : sans ce
    raccord, un nouveau serveur n'aurait AUCUNE commande jusqu'au prochain
    redémarrage. Le symptôme — « le bot ne répond à rien » — ne ressemble pas
    à sa cause, et se chercherait longtemps.

    Fail-safe : une erreur ici ne doit pas empêcher l'arrivée sur le serveur.
    """
    try:
        bot.tree.copy_global_to(guild=guild)
        s = await bot.tree.sync(guild=guild)
        print(f"✅ {len(s)} commandes posées sur le nouveau serveur "
              f"{guild.name} ({guild.id})")
    except Exception as ex:
        print(f"⚠️ sync à l'arrivée sur {getattr(guild, 'id', '?')} "
              f"échouée: {ex}")


@bot.event
async def on_thread_create(thread):
    """Ouvrir un fil est un geste d'animation : celui qui le fait est présent."""
    try:
        if thread.guild and thread.owner_id:
            membre = thread.guild.get_member(thread.owner_id)
            if membre is not None and not membre.bot:
                await activite_module.marquer_actif(
                    thread.guild.id, thread.owner_id, activite_module.SOURCE_FIL)
    except Exception as ex:
        print(f"[activite on_thread_create] {ex}")


@bot.event
async def on_raw_poll_vote_add(payload):
    """Voter à un sondage : exactement comme une réaction, un clic délibéré.

    On écoute la version RAW pour capter aussi les votes sur d'anciens sondages
    sortis du cache — même raison que pour les réactions.
    """
    try:
        gid = getattr(payload, "guild_id", None)
        uid = getattr(payload, "user_id", None)
        if gid and uid:
            await activite_module.marquer_actif(
                gid, uid, activite_module.SOURCE_SONDAGE)
    except Exception as ex:
        print(f"[activite on_poll_vote] {ex}")


@bot.event
async def on_interaction(interaction: discord.Interaction):
    """Une interaction (commande, bouton, menu) est un geste délibéré : elle compte pour l'activité."""
    if not interaction.channel or not interaction.guild:
        return

    # ═══ ACTIVITÉ — la source la plus fiable : un geste délibéré ═══
    # Lancer une commande, cliquer un bouton ou choisir dans un menu ne peut pas
    # arriver par accident, ni pendant qu'on dort. C'est le contraire du statut
    # « en ligne » : ici, quelqu'un a forcément agi.
    try:
        if interaction.user is not None and not interaction.user.bot:
            await activite_module.marquer_actif(
                interaction.guild.id, interaction.user.id,
                activite_module.SOURCE_INTERACTION)
    except Exception as _ex_act:
        print(f"[activite on_interaction] {_ex_act}")


# Phase 254 HOTFIX : le lancement du tournoi N'EST PLUS une sous-commande /owner —
# le groupe /owner était DÉJÀ à la limite Discord de 25 sous-commandes (ajouter
# `tournoi` faisait planter `faction_war` à l'import → crash-loop, et la CI ne voit
# pas les erreurs d'import runtime). Le lancement repasse par un BOUTON admin
# (alliance_war.start_war), zéro coût sur l'arbre de commandes — voir commit suivant.


@owner_group.command(name="sync", description="🔄 Synchroniser les commandes (Admin)")
async def sync_cmd(i: discord.Interaction):
    if not i.user.guild_permissions.administrator:
        return await i.response.send_message("❌ Admin requis", ephemeral=True)

    await i.response.defer(ephemeral=True)
    try:
        #  ⚠️ SYNC SUR CETTE GUILDE, PAS EN GLOBAL. Un `tree.sync()` global
        #  RECRÉERAIT le registre qu'on vient de purger — et les doublons
        #  reviendraient au premier clic sur ce bouton, sans que personne ne
        #  fasse le lien avec cette commande.
        bot.tree.copy_global_to(guild=i.guild)
        synced = await bot.tree.sync(guild=i.guild)
        cmd_list = "\n".join([f"• `/{c.name}`" for c in synced])
        await i.followup.send(
            f"✅ **{len(synced)} commandes synchronisées sur ce serveur !**\n"
            f"-# Propagation immédiate. Si vous voyez encore des doublons, "
            f"quittez et rouvrez Discord (cache client).\n\n{cmd_list}"[:1900],
            ephemeral=True)
    except Exception as ex:
        await i.followup.send(f"❌ Erreur: {ex}", ephemeral=True)


