async def _tix_staff(i) -> bool:
    """Le staff des tickets : rôle staff (ou au-dessus), propriétaire, administration. 20/10/2026 :
    « Gérer les messages » suffisait — n'importe quel modérateur de salon y avait accès."""
    try:
        return i.user.id == SUPER_OWNER_ID or _staff_ou_plus(i.guild, i.user, await cfg(i.guild.id))
    except Exception as ex:
        _logerr("ticket.droit", ex, guild_id=getattr(i.guild, 'id', 0))
        return False


async def _tix_direction(i) -> bool:
    """Transcripts (le contenu privé des tickets) et réglages : direction et au-dessus, comme les logs."""
    try:
        return i.user.id in TETE_IDS or _direction_ou_plus(i.guild, i.user, await cfg(i.guild.id))
    except Exception as ex:
        _logerr("ticket.droit", ex, guild_id=getattr(i.guild, 'id', 0))
        return False


async def _tix_is_in_ticket(channel) -> bool:
    """Check si on est dans un channel ticket actuel (status open)."""
    if not isinstance(channel, (discord.TextChannel, discord.Thread)):
        return False
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT 1 FROM tickets WHERE channel_id=? AND status='open'",
                (channel.id,),
            ) as cur:
                return (await cur.fetchone()) is not None
    except Exception:
        return False


@ticket_group.command(name="transcripts", description="📄 Les transcripts d'un membre (ou les derniers)")
@app_commands.describe(membre="Le membre dont on veut les transcripts (vide = les 20 derniers)")
async def ticket_transcripts_cmd(i: discord.Interaction, membre: discord.User | None = None):
    """19/10/2026 : « qu'on sache quel transcript appartient à qui, que si on a besoin de
    filtrer, on sache exactement »."""
    if not await _tix_direction(i):
        return await i.response.send_message("❌ Réservé à la direction et au fondateur.", ephemeral=True)
    await i.response.defer(ephemeral=True)
    q = ("SELECT ticket_id, user_id, user_name, panel, url, closed_at, jeton FROM ticket_transcripts "
         "WHERE guild_id=?" + (" AND user_id=?" if membre else "")
         + " ORDER BY closed_at DESC LIMIT 20")
    async with get_db() as db:
        async with db.execute(q, (i.guild.id, membre.id) if membre else (i.guild.id,)) as cur:
            rows = await cur.fetchall()
    if not rows:
        return await i.followup.send("📄 Aucun transcript" + (f" pour {membre.mention}." if membre else "."),
                                     ephemeral=True)
    lignes = []
    for tid, uid, nom, panel, url, quand, jeton in rows:
        try:
            t = f"<t:{int(datetime.fromisoformat(quand).timestamp())}:d>"
        except (TypeError, ValueError):
            t = "?"
        #  Sans adresse publique, le transcript enregistré se lit sur le site (par son jeton).
        lien = f"[ouvrir]({url})" if url else ("sur le site" if jeton else "fichier dans le salon des logs")
        lignes.append(f"🎫 #{tid} · **{nom}** (`{uid}`)" + (f" · {panel}" if panel else "")
                      + f" · {t} · {lien}")
    await i.followup.send(("**📄 Transcripts" + (f" de {membre.mention}" if membre else "")
                           + f"** ({len(rows)})\n" + "\n".join(lignes))[:1950], ephemeral=True,
                          allowed_mentions=discord.AllowedMentions.none())


@ticket_group.command(name="search", description="🔎 Liste les tickets ouverts (option : seulement les non pris)")
@app_commands.describe(non_pris="N'afficher que les tickets PAS encore pris en charge")
async def ticket_search_cmd(i: discord.Interaction, non_pris: bool = False):
    # #18 : triage des tickets — LECTURE SEULE (le bot ne ferme/mute jamais un ticket).
    if not await _tix_staff(i):
        return await i.response.send_message("❌ Réservé au staff.", ephemeral=True)
    try:
        await i.response.defer(ephemeral=True)
    except Exception:
        pass
    try:
        q = ("SELECT id, channel_id, user_id, claimed_by, created_at FROM tickets "
             "WHERE guild_id=? AND status='open'")
        if non_pris:
            q += " AND (claimed_by IS NULL OR claimed_by=0)"
        q += " ORDER BY created_at ASC LIMIT 40"
        async with get_db() as db:
            async with db.execute(q, (i.guild.id,)) as cur:
                rows = await cur.fetchall()
    except Exception as ex:
        return await i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
    if not rows:
        return await i.followup.send("✅ Aucun ticket ouvert" + (" non pris." if non_pris else "."), ephemeral=True)
    lines = []
    for tid, chid, uid, claimed, cat in rows:
        #  24/10/2026 (revue) : `get_channel` ne rend jamais un fil — les tickets en fil privé sortaient en
        #  identifiants bruts. La mention marche pour un salon comme pour un fil (même archivé).
        chm = f"<#{int(chid)}>" if chid else "`?`"
        claim_txt = f"pris par <@{int(claimed)}>" if claimed else "**non pris**"
        age = ""
        try:
            if cat:
                st = datetime.fromisoformat(cat)
                if st.tzinfo is None:
                    st = st.replace(tzinfo=timezone.utc)
                age = f" · <t:{int(st.timestamp())}:R>"
        except Exception:
            pass
        lines.append(f"🎫 #{tid} {chm} · <@{int(uid)}> · {claim_txt}{age}")
    txt = ("**🔎 Tickets ouverts" + (" (non pris)" if non_pris else "") + f"** ({len(rows)})\n"
           + "\n".join(lines))
    await i.followup.send(txt[:1900], ephemeral=True, allowed_mentions=discord.AllowedMentions.none())


@ticket_group.command(name="queue", description="📊 Charge des tickets par staff + nombre de non assignés")
async def ticket_queue_cmd(i: discord.Interaction):
    # #19 : équilibrage de charge — LECTURE SEULE.
    if not await _tix_staff(i):
        return await i.response.send_message("❌ Réservé au staff.", ephemeral=True)
    try:
        await i.response.defer(ephemeral=True)
    except Exception:
        pass
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT claimed_by, COUNT(*) FROM tickets WHERE guild_id=? AND status='open' "
                "GROUP BY claimed_by", (i.guild.id,)) as cur:
                rows = await cur.fetchall()
    except Exception as ex:
        return await i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
    unclaimed = 0
    by_staff = []
    for claimed, cnt in rows:
        if not claimed:
            unclaimed += int(cnt)
        else:
            by_staff.append((int(claimed), int(cnt)))
    by_staff.sort(key=lambda x: -x[1])
    txt = "**📊 Charge des tickets ouverts**\n"
    txt += (f"🆕 **Non assignés : `{unclaimed}`** — à prendre en charge\n\n" if unclaimed
            else "✅ Aucun ticket non assigné.\n\n")
    if by_staff:
        txt += "\n".join(f"👮 <@{sid}> · `{cnt}` ticket(s)" for sid, cnt in by_staff[:30])
        if len(by_staff) > 1:
            _least = by_staff[-1]
            txt += f"\n\n💡 Le moins chargé : <@{_least[0]}> (`{_least[1]}`)."
    else:
        txt += "_Aucun ticket actuellement pris en charge._"
    await i.followup.send(txt[:1900], ephemeral=True)


