async def _audit_actor(guild, action, *, target_id=None, within_sec: int = 15):
    """« QUI a fait quoi à qui » (owner 2026-06-14) : retrouve l'AUTEUR d'une action via
    les AUDIT LOGS Discord. Renvoie (actor_user_or_None, reason_or_None).

    Les events gateway (on_member_update, on_guild_role_update…) ne disent PAS qui a agi
    → on lit l'entrée d'audit correspondante (action + cible + fenêtre temporelle récente).
    FAIL-SAFE : nécessite la perm « Voir les logs d'audit » ; sinon (None, None). N'appeler
    QUE quand un log va effectivement être émis (1 appel API audit par event loggé)."""
    try:
        me = guild.me
        if me is None or not me.guild_permissions.view_audit_log:
            return (None, None)
        cutoff = discord.utils.utcnow() - timedelta(seconds=within_sec)
        async for entry in guild.audit_logs(action=action, limit=6):
            try:
                if entry.created_at is not None and entry.created_at < cutoff:
                    break  # entrées triées récent→ancien : au-delà de la fenêtre = stop
                if target_id is not None:
                    tid = getattr(getattr(entry, 'target', None), 'id', None)
                    if tid is not None and int(tid) != int(target_id):
                        continue
                return (entry.user, getattr(entry, 'reason', None))
            except Exception:
                continue
    except discord.Forbidden:
        return (None, None)
    except Exception:
        return (None, None)
    return (None, None)


async def _log_audited(guild, event_type, actions, target_id, desc_fn, *,
                       channel=None, require_actor=False, user=None):
    """Loggue un event d'audit (création/suppression/permission/sanction) AVEC son AUTEUR
    (via _audit_actor) et en IGNORANT les actions AUTOMATIQUES du bot — sinon les logs sont
    NOYÉS par la création/suppression incessante des salons d'event (owner « pas de logs
    inutiles »). `actions` = une AuditLogAction ou une liste (essayées dans l'ordre).
    `desc_fn(actor)` -> description (si elle renvoie un faux → pas de log). L'auteur est
    passé en `moderator=` (rendu joli par le logger). `require_actor=True` → ne loggue QUE
    si un auteur a été trouvé (sert au KICK : sans entrée d'audit kick = simple départ
    volontaire → on ne loggue rien). FAIL-SAFE."""
    try:
        if not isinstance(actions, (list, tuple)):
            actions = [actions]
        actor, reason = (None, None)
        for _act in actions:
            actor, reason = await _audit_actor(guild, _act, target_id=target_id)
            if actor is not None:
                break
        if require_actor and actor is None:
            return  # pas d'auteur trouvé → événement non confirmé (ex. départ ≠ kick)
        me = guild.me
        if actor is not None and me is not None and actor.id == me.id:
            return  # action automatique du bot → pas de log (anti-spam)
        _desc = desc_fn(actor)
        if not _desc:
            return  # pas de description → pas de log (garde)
        await ulogger2026.log_event(
            bot, guild, event_type,
            description=_desc,
            user=user,                     # cible → champ « 👤 Concerné » (@mention cliquable)
            moderator=actor,
            reason=(str(reason)[:300] if reason else None),
            channel=channel,
        )
    except Exception as ex:
        print(f"[_log_audited {getattr(event_type, 'value', '?')}] {ex}")


