async def _handle_rogue_bot(m):
    """ANTI-BOT-VOYOU (owner 2026-06-21) : un BOT tiers NON approuvé qui arrive avec des
    permissions DANGEREUSES (admin/gestion/ban/kick/webhooks) = vecteur de nuke n°1 (ajouté
    via un compte privilégié compromis) → on l'EXPULSE (neutralisation) + alerte owner. Bot
    sans risque → alerte seule. Le bot lui-même + les bots approuvés (`approved_bots`) sont
    épargnés. Seul l'owner peut ajouter un bot (Manage Server) → la menace = compte owner
    compromis, donc on agit même sur un ajout « owner ». FAIL-SAFE."""
    try:
        guild = m.guild
        if guild is None:
            return
        me = guild.me
        if me is not None and m.id == me.id:
            return
        c = await cfg(guild.id)
        if not c.get('anti_rogue_bot', 1):
            return
        try:
            approved = {int(x) for x in (c.get('approved_bots', []) or []) if str(x).isdigit()}
        except Exception:
            approved = set()
        if m.id in approved:
            return
        try:
            p = m.guild_permissions
            dangerous = bool(p.administrator or p.manage_guild or p.manage_channels
                             or p.manage_roles or p.manage_webhooks or p.ban_members or p.kick_members)
        except Exception:
            dangerous = False
        actor = None
        try:
            actor, _r = await _audit_actor(guild, discord.AuditLogAction.bot_add, target_id=m.id)
        except Exception:
            actor = None
        if not dangerous:
            try:
                await ulogger2026.log_event(
                    bot, guild, ulogger2026.EventType.SEC_ESCALATION,
                    description=(f"🤖 Bot {m.mention} (`{m.id}`) a rejoint"
                                 + (f", ajouté par {actor.mention}" if actor else "")
                                 + ". Permissions sans risque (info)."),
                    user=m, moderator=(actor or bot.user))
            except Exception:
                pass
            return
        action_txt = "→ ⚠️ expulsion impossible (hiérarchie/permissions) — **interviens vite**."
        try:
            if me is not None and me.guild_permissions.kick_members and m.top_role < me.top_role:
                await m.kick(reason="Bot non approuvé avec permissions dangereuses (anti-bot-voyou)")
                action_txt = "→ **expulsé** (neutralisé)."
        except Exception:
            pass
        txt = (f"🚨 **BOT NON APPROUVÉ À PERMISSIONS DANGEREUSES** — {m.mention} (`{m.id}`)"
               + (f", ajouté par {actor.mention} (`{actor.id}`)" if actor else "") + f". {action_txt}\n"
               f"_Si c'était voulu : « Approuver ce bot » sous cette alerte, puis ré-ajoute-le._")
        _BOTS_REFUSES[m.id] = time.time()
        while len(_BOTS_REFUSES) > 100:
            _BOTS_REFUSES.pop(next(iter(_BOTS_REFUSES)))
        try:
            await ulogger2026.log_event(bot, guild, ulogger2026.EventType.SEC_ESCALATION,
                                        description=txt, user=m, moderator=(actor or bot.user))
        except Exception:
            pass
        # (MP au propriétaire SUPPRIMÉ le 12/08/2026, à sa demande. Le même texte
        #  part déjà dans le journal de sécurité juste au-dessus — rien n'est perdu.)
    except Exception as ex:
        print(f"[_handle_rogue_bot] {ex}")


async def _age_gate_nsfw(member):
    """Gate +18 (owner 2026-06-27, OPT-IN) : un compte Discord plus RÉCENT que `age_gate_min_days`
    se voit REFUSER l'accès aux salons NSFW (overwrite DENY par-membre, réversible). L'âge du
    COMPTE ≠ âge réel → contrôle imparfait → OFF par défaut (0). No-op s'il n'y a pas de salon NSFW.
    Owner/super-owner/immunisés exemptés. FAIL-SAFE, throttlé anti-429."""
    try:
        guild = getattr(member, 'guild', None)
        if guild is None or getattr(member, 'bot', False):
            return
        c = await cfg(guild.id)
        days = int(c.get('age_gate_min_days', 0) or 0)
        if days <= 0:
            return
        if member.id == guild.owner_id or owner_ids_module.is_super_owner(member.id):
            return
        try:
            if await is_fully_immune(member):
                return
        except Exception:
            pass
        try:
            acct_age = (discord.utils.utcnow() - member.created_at).days
        except Exception:
            return
        if acct_age >= days:
            return  # compte assez ancien → pas de restriction
        me = guild.me
        if me is None or not me.guild_permissions.manage_roles:
            return
        nsfw = [ch for ch in guild.channels
                if callable(getattr(ch, 'is_nsfw', None)) and ch.is_nsfw()]
        for ch in nsfw[:15]:
            try:
                await ch.set_permissions(
                    member, view_channel=False,
                    reason=f"Gate +18 : compte créé il y a {acct_age} j (< {days} j)")
                await asyncio.sleep(0.4)
            except Exception:
                continue
    except Exception as ex:
        print(f"[_age_gate_nsfw] {ex}")


async def _reposer_sanction_au_retour(m) -> str:
    """Une sanction ne s'efface pas en quittant le serveur (24/10/2026, revue : un radié qui partait
    puis revenait retrouvait tout, auto-rôle compris). À l'arrivée, AVANT tout rôle : la radiation
    (/off), l'isolement (quarantaine) ou la restriction (/mod direction) encore actifs sont reposés.
    Rend la sanction trouvée ('radiation', 'isolement', 'restriction') — même si la reposer a échoué,
    pour que l'arrivée ne donne aucun rôle — ou '' . Base illisible : on laisse entrer, et on le dit."""
    g = m.guild
    fiches = {}
    try:
        async with get_db() as db:
            for nom, sql in (
                    ("radiation", "SELECT 1 FROM radiated_members WHERE guild_id=? AND user_id=?"),
                    ("isolement", "SELECT genre FROM isolements WHERE guild_id=? AND user_id=?"),
                    ("restriction", "SELECT duration, restricted_at FROM restricted_members "
                                    "WHERE guild_id=? AND user_id=?")):
                try:
                    async with db.execute(sql, (g.id, m.id)) as cur:
                        fiches[nom] = await cur.fetchone()
                except aiosqlite.OperationalError as ex:
                    if "no such table" not in str(ex):
                        raise
                    fiches[nom] = None  # table jamais créée : personne n'a reçu cette sanction ici
    except Exception as ex:
        _logerr("arrivee.sanctions", ex, guild_id=g.id)
        return ""
    sanction = next((nom for nom in ("radiation", "isolement") if fiches.get(nom)), "")
    restriction = fiches.get("restriction")
    if not sanction and restriction:
        duree, debut = int(restriction[0] or 0), restriction[1]
        depuis = None
        try:
            depuis = datetime.fromisoformat(debut) if debut else None
        except ValueError as ex:
            _logerr("arrivee.restriction_date", ex, guild_id=g.id)
        if depuis is not None and depuis.tzinfo is None:
            depuis = depuis.replace(tzinfo=timezone.utc)
        # Échue : rien à reposer, la boucle de levée efface la fiche.
        if duree <= 0 or depuis is None or (now() - depuis).total_seconds() / 60 < duree:
            sanction = "restriction"
    if not sanction:
        return ""
    raison = "Sanction toujours active — reposée au retour sur le serveur"
    repose = False
    try:
        if sanction == "radiation":
            role = discord.utils.get(g.roles, name=_RADIE_ROLE_NAME)
            nouveau = role is None
            if nouveau:
                role = await g.create_role(name=_RADIE_ROLE_NAME, colour=discord.Colour(_RADIE_COULEUR),
                                           hoist=False, mentionable=False, reason=raison)
            await m.add_roles(role, reason=raison)
            if nouveau:  # refus pas encore posés sur les salons : le silence d'abord, les salons en fond
                await m.timeout(timedelta(days=28), reason=raison)
                t = asyncio.create_task(_verrouiller_salons_radie(g, role, m.id))
                _VERROUS_RADIATION.add(t)
                t.add_done_callback(_VERROUS_RADIATION.discard)
            try:
                await m.edit(nick=_radie_pseudo(m), reason=raison)
            except discord.HTTPException as ex:
                _logerr("arrivee.radie_pseudo", ex, guild_id=g.id)
        elif sanction == "isolement":
            role = await _ensure_quarantine_role(g)
            if role is None:
                raise RuntimeError("Quarantine role unavailable")
            await m.add_roles(role, reason=raison)
        else:
            role = discord.utils.get(g.roles, name="🔒 Restricted")
            if role is None:
                raise RuntimeError("Restricted role missing")
            await m.add_roles(role, reason=raison)
        repose = True
    except (discord.HTTPException, RuntimeError) as ex:
        _logerr("arrivee.sanction_reposee", ex, guild_id=g.id)
    quoi = {"radiation": "une radiation", "isolement": "un isolement"}.get(sanction, "une restriction")
    try:
        await ulogger2026.log_event(
            bot, g, ulogger2026.EventType.SEC_ESCALATION,
            description=(f"🔁 {m.mention} (`{m.id}`) est revenu sur le serveur avec **{quoi}** en cours : "
                         + ("reposée, et l'arrivée ne lui a donné aucun rôle."
                            if repose else "⚠️ elle n'a **pas pu** être reposée (rôle ou permission) — aucun "
                                           "rôle d'arrivée donné, intervenez.")),
            user=m, moderator=bot.user)
    except Exception as ex:
        _logerr("arrivee.sanction_alerte", ex, guild_id=g.id)
    return sanction


@bot.event
async def on_member_join(m):
    """⚠️ CE DÉCORATEUR A ÉTÉ RÉTABLI LE 12/08/2026. NE JAMAIS LE RETIRER.

    ═══════════════════════════════════════════════════════════════════════════
    LA PANNE LA PLUS GRAVE TROUVÉE DANS CE DÉPÔT
    ═══════════════════════════════════════════════════════════════════════════
    Cette fonction n'avait AUCUN décorateur, et aucun `bot.add_listener` ne la
    visait — vérifié à l'AST sur les 28 gestionnaires `on_*` du fichier : elle
    était la SEULE dans ce cas. C'était donc une fonction ordinaire que personne
    n'appelait jamais. Depuis des mois, il ne se passait littéralement RIEN
    quand quelqu'un rejoignait un serveur :

      · l'ANTI-RAID ne comptait aucune arrivée — son compteur ne montait jamais,
        donc le verrouillage du serveur ne pouvait pas se déclencher, jamais ;
      · l'anti-compte-récent, l'anti-alt et l'empreinte du membre : muets ;
      · le bot voyou tiers n'était pas neutralisé ;
      · le rôle d'arrivée n'était pas posé, le gate +18 pas appliqué ;
      · les statistiques comptaient 0 arrivée — d'où l'alerte « perte nette de
        membres » qui affichait toujours « 0 arrivés », symptôme visible de la
        panne que personne n'avait relié à sa cause.

    Le correctif d'ordre de l'anti-raid livré plus tôt dans la refonte était donc
    juste, mais inerte : il corrigeait la place d'un appel dans une fonction
    morte.

    ⚠️ `ast.parse` ne voit PAS ce genre de panne, et `import bot` non plus : le
    fichier est parfaitement valide sans le décorateur. Le contrôle qui l'attrape
    est `outils/verif_evenements.py`, qui vérifie que chaque `on_*` de Discord
    est bien enregistrée. À lancer avant tout push touchant aux événements.
    """
    # ── ANTI-BOT-VOYOU (owner 2026-06-21) : un bot tiers dangereux non approuvé → neutralisé.
    try:
        if getattr(m, 'bot', False):
            await _handle_rogue_bot(m)
    except Exception as ex:
        print(f"[on_member_join rogue_bot] {ex}")

    # Gate +18 (owner 2026-06-27, OPT-IN via age_gate_min_days) : compte trop récent → accès NSFW
    # refusé. En tâche de fond, no-op si désactivé / pas de salon NSFW. FAIL-SAFE.
    try:
        asyncio.create_task(_age_gate_nsfw(m))
    except Exception:
        pass

    # ── UNE SANCTION NE S'EFFACE PAS EN QUITTANT LE SERVEUR (revue 24/10/2026) ──
    # Radiation, isolement, restriction : reposés AVANT tout rôle d'arrivée. Un
    # membre sanctionné ne reçoit ni ses anciens rôles, ni l'auto-rôle, ni son
    # rôle de langue (un rôle qui « autorise » un salon rouvrirait ce salon).
    try:
        _sanctionne = await _reposer_sanction_au_retour(m) if not m.bot else ""
    except Exception as ex:  # l'arrivée continue (anti-raid, empreinte…) quoi qu'il arrive
        _logerr("on_member_join.sanction", ex, guild_id=getattr(m.guild, "id", 0))
        _sanctionne = ""

    # ── UN MEMBRE QUE L'ANCIEN SYSTÈME D'ACTIVITÉ AVAIT DÉPOUILLÉ REVIENT ───
    # Il récupère ses rôles dès l'arrivée (voir `activite_demontage`) : une
    # lecture en base par arrivée. En tâche de fond, APRÈS l'anti-raid.
    try:
        if not m.bot and not _sanctionne:
            _t_ret = asyncio.create_task(_rendre_roles_au_retour(m))
            _TACHES_RETOUR_ROLES.add(_t_ret)
            _t_ret.add_done_callback(_TACHES_RETOUR_ROLES.discard)
    except Exception as ex:
        print(f"[on_member_join activite] {ex}")

    # AUTO-RÔLE à l'arrivée (quick-win pro) : donne le rôle « Membre » configuré
    # (welcome_autorole) à chaque nouveau. FAIL-SAFE : no-op si non configuré / rôle
    # introuvable / au-dessus du bot / géré par une intégration / perms manquantes.
    try:
        if not m.bot and not _sanctionne:
            c = await cfg(m.guild.id)
            rid = int(c.get('welcome_autorole', 0) or 0)
            if rid:
                role = m.guild.get_role(rid)
                me = m.guild.me
                if (role and me and me.guild_permissions.manage_roles
                        and not role.managed and role < me.top_role and role not in m.roles):
                    await m.add_roles(role, reason="Auto-rôle d'arrivée (welcome)")
    except Exception as ex:
        _logerr("on_member_join.autorole", ex, guild_id=getattr(m.guild, "id", 0))

    # ═══ Tracking stats journalières ═══
    try:
        today = now().strftime('%Y-%m-%d')
        async with get_db() as db:
            await db.execute('''
                INSERT INTO daily_guild_stats (guild_id, date, new_members)
                VALUES (?, ?, 1)
                ON CONFLICT(guild_id, date) DO UPDATE SET new_members = new_members + 1
            ''', (m.guild.id, today))
            await db.commit()
    except Exception as ex:
        _logerr("on_member_join.daily_stats", ex, guild_id=getattr(m.guild, "id", 0))

    # ═══ Phase 147 : raid_detector smart (account-signature based) ═══
    # Ne déclenche QUE si plusieurs comptes suspects join en cluster.
    # Friendly aux surges légitimes (lives streaming → comptes variés).
    try:
        await raid_module.on_member_join(m)
    except Exception as ex:
        print(f"[on_member_join raid_module] {ex}")

    # (Blocs SUPPRIMÉS le 12/08/2026 en rebranchant l'événement — voir le décorateur.
    #  Tous appartenaient à des systèmes retirés par la refonte, et les réveiller d'un
    #  coup aurait inondé le serveur au lieu de le protéger :
    #    · parcours d'onboarding et parrainage — déjà vidés, il ne restait que le try ;
    #    · célébration des paliers de membres — système d'engagement ;
    #    · rôle « 📢 Tous les Événements » posé d'office — système d'events ;
    #    · rôle « 🛒 Collectionneur UGC » posé d'office — Roblox UGC.
    #  Les deux derniers ajoutaient un rôle à CHAQUE arrivée : rebrancher l'événement
    #  sans les retirer aurait collé deux rôles morts à tous les nouveaux venus.)

    # ═══ i18n : restaure le rôle drapeau d'un MEMBRE REVENU (zéro DM, zéro message) ═══
    # Discord n'expose PAS la locale sur un on_member_join → l'auto-détection « vraie »
    # se fait au 1er clic (interaction porteuse de locale). Ici on se contente de
    # REPOSER le rôle drapeau si le membre avait DÉJÀ choisi une langue auparavant
    # (préférence persistée globale). Aucun spam, aucun MP. FAIL-SAFE : no-op total.
    if not m.bot and not _sanctionne:
        try:
            _pref = await i18n_module.get_user_lang(m.id)
            if _pref:
                await _i18n_assign_lang_role(m, _pref)
        except Exception as ex:
            _logerr("on_member_join.i18n_role", ex, guild_id=getattr(m.guild, "id", 0))

    # ═══ Phase 139 : Observabilité (join tracking pour retention) ═══
    try:
        await obs_module.record_join(m.guild.id, m.id)
    except Exception as ex:
        print(f"[on_member_join obs_record_join] {ex}")

    # ═══ Log unifié (Phase 3.7) ═══
    try:
        await ulogger2026.log_member_join(bot, m.guild, m)
    except Exception as ex:
        print(f"[UNIFIED LOG member_join] {ex}")
    
    # ⚠️ ANTI-RAID EN PREMIER — NE PAS REDESCENDRE CET APPEL.
    # Il était placé en fin de fonction, après plusieurs `return` (anti-raid legacy,
    # anti_newaccount). Résultat : tout membre traité par l'un de ces chemins était
    # invisible pour le compteur de raid, qui n'atteignait donc jamais son seuil —
    # le verrouillage du serveur ne se déclenchait jamais. Le compteur doit voir
    # CHAQUE arrivée, avant tout traitement susceptible de sortir de la fonction.
    try:
        if await _handle_antiraid_join(m):
            # Le membre vient d'être isolé par l'anti-raid : on s'arrête là plutôt
            # que de l'expulser derrière (l'isolement conserve les preuves).
            return
    except Exception as ex:
        print(f"[antiraid_join] {ex}")

    try:
        c = await cfg(m.guild.id)
        guild_id = m.guild.id
        
        
        # ═══════════════ ANTI-NEWACCOUNT (standalone) ═══════════════
        if c.get('anti_newaccount'):
            days = c.get('newaccount_days', 7)
            age = (now() - m.created_at.replace(tzinfo=timezone.utc)).days
            if age < days:
                # Le bouton « ⚡ Sanction » de cette protection n'avait AUCUNE clé lisible :
                # le kick était codé en dur, donc le réglage était purement décoratif.
                act = str(c.get('newaccount_action', 'kick') or 'kick')
                if act not in ('delete', 'mute', 'kick', 'ban'):
                    act = 'kick'
                await send_log(
                    m.guild, 'anti_newaccount', m, None,
                    f"Compte trop récent — {'SURVEILLANCE' if act == 'delete' else act.upper()}",
                    f"Âge: {age} jour(s)",
                )
                # owner 2026-06-21 : compte trop jeune → KICK + DM (jamais ban/isolement),
                # seuil JAMAIS révélé au membre. « kick » RESTE LE DÉFAUT et passe toujours
                # par _kick_young_account (DM + immunités + kick direct) — surtout PAS par
                # sanction(), qui dégraderait ce kick automatique en isolement.
                if act == 'kick':
                    if await _kick_young_account(m, f"Compte trop récent ({age} j) — anti-raid auto"):
                        return  # parti : plus rien à faire
                elif act in ('mute', 'ban'):
                    await sanction(m, act, int(c.get('newaccount_mute_duration', 60) or 60),
                                   f"Compte trop récent ({age} j)", m.guild)
                # act == 'delete' : surveillance seule. Toujours là (surveillé, exclu, ou expulsion
                # refusée) : la suite de l'arrivée continue — l'anti-double-compte compte surtout pour
                # les comptes récents (audit 19/10/2026).
        
        # ═══════════════ ANTI-ALT (Comptes Secondaires) ═══════════════
        # Toujours sauvegarder le fingerprint du nouveau membre
        await save_user_fingerprint(m.guild.id, m)

        # Surveillance profils (owner 2026-06-21) : alerte si pseudo/nom anti-TOS OU
        # antécédents de sanctions sur ce serveur. INFORMATIF (zéro sanction auto). FAIL-SAFE.
        try:
            await _flag_dangerous_profile(m, on_join=True)
        except Exception as _exp:
            print(f"[on_member_join profile scan] {_exp}")
        
        if c.get('anti_alt'):
            alt_cfg = c.get('alt_config', {})
            auto_action = alt_cfg.get('auto_action', False)
            min_confidence = alt_cfg.get('min_confidence', 70)
            action = c.get('alt_action', 'kick')
            
            # Détecter si c'est un compte secondaire
            is_alt, confidence, main_id, reasons = await detect_alt_account(m.guild, m)
            
            if is_alt and confidence >= min_confidence:
                # Envoyer le log
                main_member = m.guild.get_member(main_id)
                main_txt = f"{main_member.name} ({main_id})" if main_member else f"ID: {main_id} (banni/parti)"
                
                await _au_journal(m.guild, "Sécurité", "sec.alt",
                                  f"Compte secondaire présumé : {m} · ressemble à {main_txt} · confiance {confidence} %",
                                  membre_id=m.id, detail=" · ".join(str(r) for r in reasons[:5]), gravite=1)
                #  28/10/2026, le fondateur : « les comptes doubles… ça crée des gros warnings dans un salon et ça spamme
                #  tout ». Le journal du site garde chaque détection ; le salon reçoit UNE ligne courte, au plus une par
                #  compte principal et par jour, et 3 par serveur en 10 minutes (un raid ne noie plus le salon) ; rien
                #  quand les journaux vivent sur le site.
                log_ch = None if c.get('logs_sur_site_v1') else m.guild.get_channel(c.get('log_anti_alt', 0))
                if log_ch and _alt_alerte_permise(m.guild.id, main_id):
                    await log_ch.send(view=_vue_ticket_message(
                        f"👥 **Compte secondaire présumé** : {m.mention} · ressemble à {main_txt} · confiance {confidence} %"
                        f"\n-# {' · '.join(str(r) for r in reasons[:3])[:300]}", Palette.WARNING),
                        allowed_mentions=discord.AllowedMentions.none())
                
                # Appliquer l'action automatique si activée
                if auto_action:
                    # IMMUNITÉ (audit 2026-06-21) : owner / super-owner / immunisés JAMAIS
                    # isolés, même flaggés « alt » (détection heuristique → faux positif possible).
                    # Aligne ce chemin sur _kick_young_account et les 8+ autres sites de sanction.
                    if (m.id == m.guild.owner_id or owner_ids_module.is_super_owner(m.id)
                            or await is_fully_immune(m)):
                        return
                    reason = f"Compte secondaire détecté (confiance: {confidence}%, principal: {main_id})"
                    try:
                        if action in ('ban', 'kick'):
                            # RÈGLE FONDATEUR-ONLY : alt détecté → on ISOLE (jamais kick/ban auto).
                            await isolate_member(m, reason)
                        elif action == 'mute':
                            await m.timeout(timedelta(hours=24), reason=reason)

                        await update_alt_status(m.guild.id, m.id, 'actioned', action)
                        await send_log(m.guild, 'anti_alt', m, None, "Compte secondaire", f"Confiance: {confidence}%, Action: {action.upper()}")
                    except Exception as ex:
                        print(f"[ALT] Erreur action: {ex}")
                    
                    return  # Ne pas continuer


    except Exception as ex:
        print(f"Erreur on_member_join: {ex}")

    # ═══ Phase 28.3 : Welcome message ═══
    #  24/10/2026 (revue) : pas de « Bienvenue » public pour un sanctionné qui revient (sa sanction vient d'être
    #  reposée) ; et une erreur de l'accueil se dit.
    try:
        if not _sanctionne:
            await _handle_welcome(m)
    except Exception as ex:
        _logerr("welcome.arrivee", ex, guild_id=getattr(m.guild, "id", 0))

    # ═══ Phase 64 : alt detection heuristic ═══
    try:
        await _check_alt_account(m)
    except Exception as ex:
        print(f"[_check_alt_account] {ex}")

    # (Accueil « parcours / hub d'events » et salutation par un PNJ SUPPRIMÉS le
    #  12/08/2026 : le premier poussait le hub d'events, le second faisait parler un
    #  personnage du lore dans le salon à chaque arrivée. Les deux systèmes ont été
    #  retirés par la refonte ; rebrancher l'événement les aurait ressuscités.)


async def _handle_antiraid_join(member):
    """Détecte les vagues d'arrivées et isole les comptes concernés.

    SEUL système anti-raid depuis 08/2026 : le précédent (clé `anti_raid` +
    `raid_config`) le neutralisait au lieu de le compléter — voir le commentaire
    en tête de `on_member_join`.

    Renvoie True si une action a été appliquée AU MEMBRE DÉCLENCHEUR, pour que
    l'appelant s'arrête et ne le sanctionne pas une seconde fois.

    Le compteur d'arrivées est incrémenté À CHAQUE APPEL, même hors raid : c'est
    lui qui permet de détecter la vague. Ne jamais sortir avant.
    """
    c = await cfg(member.guild.id)

    # ── Reprise de l'ancien système, une fois par serveur ────────────────────
    # Un serveur qui avait configuré l'anti-raid legacy verrait sinon sa protection
    # tomber en silence. On reprend ses réglages en gardant, pour chaque valeur, la
    # PLUS PROTECTRICE des deux (seuil le plus bas, fenêtre la plus large, âge de
    # compte le plus exigeant). On ne peut donc que renforcer, jamais affaiblir.
    if c.get('anti_raid') and not c.get('antiraid_enabled', False):
        legacy = c.get('raid_config', {}) or {}
        try:
            await db_set(member.guild.id, 'antiraid_join_threshold', min(
                int(c.get('antiraid_join_threshold', 5) or 5),
                int(legacy.get('join_threshold', 10) or 10)))
            await db_set(member.guild.id, 'antiraid_join_window_sec', max(
                int(c.get('antiraid_join_window_sec', 10) or 10),
                int(legacy.get('join_interval', 10) or 10)))
            await db_set(member.guild.id, 'antiraid_min_account_age_days', max(
                int(c.get('antiraid_min_account_age_days', 7) or 7),
                int(legacy.get('min_account_age', 7) or 7)))
            if not int(c.get('antiraid_log_channel', 0) or 0):
                await db_set(member.guild.id, 'antiraid_log_channel',
                             int(c.get('log_anti_raid', 0) or 0))
            await db_set(member.guild.id, 'antiraid_enabled', True)
            await db_set(member.guild.id, 'anti_raid', 0)
            print(f"[ANTIRAID] guild={member.guild.id} réglages legacy repris")
            c = await cfg(member.guild.id)
        except Exception as ex:
            print(f"[ANTIRAID migration] {ex}")

    if not c.get('antiraid_enabled', False):
        return False

    threshold = int(c.get('antiraid_join_threshold', 5))
    window = int(c.get('antiraid_join_window_sec', 10))
    min_age_days = int(c.get('antiraid_min_account_age_days', 7))
    action = str(c.get('antiraid_action', 'kick'))

    now_ts = time.time()
    joins = _recent_joins.setdefault(member.guild.id, [])
    # Purge anciens (garde uniquement les joins dans la fenêtre)
    cutoff = now_ts - window
    joins[:] = [entry for entry in joins if isinstance(entry, tuple) and entry[0] > cutoff]
    joins.append((now_ts, member.id))

    # Compte d'âge suspect ?
    account_age_days = (datetime.now(timezone.utc) - member.created_at).days
    is_suspect = account_age_days < min_age_days

    if len(joins) < threshold:
        return False  # Pas encore raid : le join est compté, rien à appliquer

    # ── Raid détecté ──
    print(f"[ANTIRAID] guild={member.guild.id} {len(joins)} joins en {window}s → RAID")

    # TASK C.1 : ouvre/prolonge la fenêtre de suppression des bienvenues
    # individuelles → un seul récap groupé sera posté en fin de vague.
    mark_welcome_raid(member.guild.id)

    # Récupérer les membres récents pour action
    recent_member_ids = [mid for (_, mid) in joins[-threshold:]]
    recent_members = []
    for mid in recent_member_ids:
        m = member.guild.get_member(mid)
        # IMMUNITÉ (audit 2026-06-21) : owner / super-owner / immunisés JAMAIS isolés pendant
        # un raid (aligne sur _kick_young_account ; sinon le super-owner rejoignant en plein
        # raid se faisait retirer ses rôles + timeout 28 j).
        # 19/10/2026 : seuls les comptes Discord récents sont isolés ; une vague de vrais joueurs
        # (une vidéo, un évènement) n'isole personne.
        if (m and not m.bot and m.id != member.guild.owner_id
                and (datetime.now(timezone.utc) - m.created_at).days < min_age_days
                and not owner_ids_module.is_super_owner(m.id)
                and not await is_fully_immune(m)):
            recent_members.append(m)

    # Appliquer l'action
    applied = 0
    failed = 0
    isoles = set()
    if action == 'lockdown':
        # Une fois par vague, que des comptes récents soient là ou non.
        try:
            await _verrou_raid(member.guild)
        except discord.HTTPException as ex:
            _logerr("security.lockdown_set", ex, guild_id=member.guild.id)
    elif action in ('kick', 'ban'):
        for m in recent_members:
            # RÈGLE FONDATEUR-ONLY : raid → on ISOLE chaque compte récent (jamais kick/ban auto).
            try:
                res = await isolate_member(m, f"Anti-Raid auto : {len(joins)} joins en {window}s")
            except Exception as ex:
                _logerr("security.raid_isolement", ex, guild_id=member.guild.id)
                res = {}
            if res.get("isolated"):
                applied += 1
                isoles.add(m.id)
            else:
                failed += 1

    # Journal unifié + casier. L'ancien système alimentait send_log('anti_raid'),
    # pas celui-ci : les raids n'apparaissaient donc ni dans le journal unifié ni
    # dans l'historique des membres. Capacité reprise ici.
    try:
        await send_log(
            member.guild, 'anti_raid', member, None,
            f"Raid détecté : {len(joins)} arrivées en {window}s",
            f"Action: {action.upper()} · {applied}/{len(recent_members)} membre(s)",
        )
    except Exception as ex:
        print(f"[ANTIRAID send_log] {ex}")

    # Log dans le salon dédié
    log_ch_id = int(c.get('antiraid_log_channel', 0) or 0)
    log_ch = member.guild.get_channel(log_ch_id) if log_ch_id else None
    if log_ch:
        try:
            e = discord.Embed(
                title="RAID DÉTECTÉ",
                description=(
                    f"**{len(joins)}** joins en `{window}`s (seuil : `{threshold}`)\n"
                    f"**Action** : `{action}` appliquée à `{applied}`/`{len(recent_members)}` membres"
                ),
                color=0xE74C3C,
                timestamp=datetime.now(timezone.utc),
            )
            e.add_field(name="Membres concernés", value="\n".join(f"• {m.mention} (`{m.id}`)" for m in recent_members[:10]) or "_aucun_", inline=False)
            if is_suspect:
                e.add_field(name="⚠️ Compte suspect", value=f"Le dernier compte a `{account_age_days}`j d'âge (seuil : `{min_age_days}`j)", inline=False)
            await log_ch.send(view=carte_embed(e, _vue_alerte(0)), allowed_mentions=discord.AllowedMentions.none())
        except Exception as ex:
            print(f"[ANTIRAID log] {ex}")

    # Reset le tracker après action
    _recent_joins[member.guild.id] = []
    return member.id in isoles  # isolé : l'arrivée s'arrête là (l'isolement garde les preuves)


VERROU_RAID_MINUTES = 10


async def _verrou_raid(guild) -> None:
    """Niveau de vérification au maximum pendant VERROU_RAID_MINUTES. Le niveau d'AVANT est noté en
    base au premier déclenchement seulement : un 2e raid prolonge le verrou sans écraser ce niveau,
    et un redémarrage ne le fait pas oublier (audit 19/10/2026)."""
    c = await cfg(guild.id)
    if not c.get('antiraid_verrou_actif'):
        await db_set(guild.id, 'antiraid_niveau_avant', int(guild.verification_level.value))
        await db_set(guild.id, 'antiraid_verrou_actif', 1)
    await db_set(guild.id, 'antiraid_verrou_fin', time.time() + VERROU_RAID_MINUTES * 60)
    if guild.verification_level != discord.VerificationLevel.highest:
        await guild.edit(verification_level=discord.VerificationLevel.highest, reason="Anti-Raid lockdown")


async def _lever_verrou_raid(guild) -> None:
    """Le verrou est échu : le niveau d'avant revient (appelé par `server_controls_task`)."""
    c = await cfg(guild.id)
    if not c.get('antiraid_verrou_actif') or time.time() < float(c.get('antiraid_verrou_fin', 0) or 0):
        return
    try:
        niveau = discord.VerificationLevel(int(c.get('antiraid_niveau_avant', 1) or 0))
    except ValueError:
        niveau = discord.VerificationLevel.low
    try:
        await guild.edit(verification_level=niveau, reason="Anti-Raid lockdown terminé")
    except discord.HTTPException as ex:  # l'appelant avale ses erreurs : on la dit ici
        _logerr("security.lockdown_restore", ex, guild_id=guild.id)
        return
    await db_set(guild.id, 'antiraid_verrou_actif', 0)
    print(f"[ANTIRAID] guild={guild.id} verrou levé")


def _nombre_membres(guild) -> str:
    """Le nombre de membres, groupé à la française (1 234)."""
    return f"{int(getattr(guild, 'member_count', 0) or 0):,}".replace(",", "\u202f")


async def _track_welcome_msg(guild_id: int, channel_id: int, message_id: int):
    """owner 2026-06-30 : enregistre une carte d'accueil pour la purge périodique (elle RESTE
    visible `welcome_lifetime_minutes` puis est supprimée → le chat ne s'encombre pas). FAIL-SAFE."""
    try:
        async with get_db() as db:
            await db.execute(
                "INSERT OR REPLACE INTO welcome_msgs(guild_id, channel_id, message_id) VALUES(?,?,?)",
                (int(guild_id), int(channel_id), int(message_id)))
            await db.commit()
    except Exception as ex:
        print(f"[_track_welcome_msg] {ex}")


@tasks.loop(minutes=10)
async def welcome_cleanup_task():
    """owner 2026-06-30 : « la carte reste pas mal de temps puis, toutes les heures, celles de
    tous les arrivants se suppriment ». On supprime les cartes d'accueil plus vieilles que
    `welcome_lifetime_minutes` (déf 60). get_partial_message → suppression SANS fetch (anti-429).
    Reboot-safe (table SQLite). FAIL-SAFE."""
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT guild_id, channel_id, message_id, "
                "CAST((julianday('now') - julianday(posted_at)) * 1440 AS INTEGER) AS age_min "
                "FROM welcome_msgs") as cur:
                rows = await cur.fetchall()
    except Exception:
        rows = []
    for gid, ch_id, msg_id, age_min in rows:
        try:
            c = await cfg(int(gid))
            life = int(c.get('welcome_lifetime_minutes', 60) or 60)
            if int(age_min or 0) < life:
                continue
            guild = bot.get_guild(int(gid))
            ch = guild.get_channel_or_thread(int(ch_id)) if guild else None   # un post de forum compris
            if ch is not None:
                try:
                    await ch.get_partial_message(int(msg_id)).delete()
                except discord.NotFound:
                    pass
                except Exception:
                    pass
            try:
                async with get_db() as db:
                    await db.execute(
                        "DELETE FROM welcome_msgs WHERE guild_id=? AND message_id=?",
                        (int(gid), int(msg_id)))
                    await db.commit()
            except Exception:
                pass
            await asyncio.sleep(0.3)   # throttle anti-429
        except Exception:
            continue


@welcome_cleanup_task.before_loop
async def _welcome_cleanup_before():
    await bot.wait_until_ready()


_DERNIER_ACCUEIL: dict = {}


async def _handle_welcome(member):
    """L'accueil d'un nouveau membre : UNE ligne de texte dans le salon d'accueil — sa mention, la bienvenue, le
    nombre de membres. Pas de carte ni de bouton (24/10/2026, le fondateur : « un petit texte… c'est tout »).
    Elle reste `welcome_lifetime_minutes`, puis `welcome_cleanup_task` la retire."""
    c = await cfg(member.guild.id)
    if not c.get('welcome_enabled', False):
        return
    ch_id = int(c.get('welcome_channel', 0) or 0)
    if not ch_id:
        return
    ch = member.guild.get_channel_or_thread(ch_id)  # un post de forum (💬 Chat) compris
    if not ch:
        return
    perms = ch.permissions_for(member.guild.me)
    if not (perms.send_messages_in_threads if isinstance(ch, discord.Thread) else perms.send_messages):
        return
    # Pendant une vague d'arrivées (raid), une seule ligne groupée à la fin de la vague.
    if _defer_welcome_during_raid(member.guild.id, ch, member.id):
        return
    # Sa langue s'il l'a déjà choisie (un ancien qui revient) ; sinon celle du serveur, puis le français.
    try:
        _wlang = await i18n_module.lang_of(member.id, guild_id=member.guild.id)
    except Exception:
        _wlang = "fr"
    texte = i18n_module.t("welcome.short", _wlang or "fr", user=member.mention, count=_nombre_membres(member.guild))
    try:
        _wm = await ch.send(texte, allowed_mentions=discord.AllowedMentions(
            everyone=False, roles=False, users=[member], replied_user=False))
        try:
            await _track_welcome_msg(member.guild.id, ch.id, getattr(_wm, 'id', 0))
        except Exception as ex:
            print(f"[_track_welcome_msg] {ex}")
        _DERNIER_ACCUEIL.update(quand=int(time.time()), lignes=texte.count("\n") + 1, boutons=0,
                                mention=member.mention in texte, membres=int(member.guild.member_count or 0))
        print(f"[WELCOME] posté msg={getattr(_wm, 'id', 0)} ch={ch.id} guild={member.guild.id}")
    except Exception as ex:
        _logerr("welcome.send", ex, guild_id=member.guild.id)


