async def _scan_security_on_edit(after) -> bool:
    """Rejoue la chaîne de scan sécurité de on_message sur un message ÉDITÉ.

    FIX sécu 2026 (audit P0-2/P0-4) : toute la détection (token/webhook/grabber/
    phishing/scam) ne tournait qu'à la CRÉATION du message. Un membre pouvait poster
    un message anodin puis l'ÉDITER pour y injecter un webhook, un token, un lien de
    phishing ou un lien masqué → aucun re-scan, aucune suppression, aucune révocation.
    On rejoue ici EXACTEMENT les mêmes scanners que on_message, sur `after`.
    Retourne True si un scanner a agi (message supprimé/sanctionné) → l'appelant NE
    doit alors PAS logger `after.content` en clair. Fail-safe : une exception d'un
    scanner ne bloque jamais la chaîne (sécurité best-effort, comme on_message)."""
    if after.author is None or after.author.bot:
        return False
    # 1) Scanners de secrets/grabber auto-suppresseurs (mêmes que on_message), avec les mêmes
    #    exemptions qu'à l'envoi : le piège à bots épargne la tête, le staff et les immunisés, et le
    #    module des jetons ne les sanctionne pas (19/10/2026).
    exempt = await is_fully_immune(after.author)
    for _mod, _name in (
        (honeypot_module, "honeypot"),
        (anti_token_leak_module, "anti_token_leak"),
        (webhook_leak_module, "webhook_leak"),
        (token_grabber_module, "token_grabber"),
    ):
        if _mod is honeypot_module and exempt:
            continue
        #  Le salon-piège juge aussi un message SANS texte (image, sticker, transfert) ; les
        #  scanners de texte, eux, n'ont rien à lire (revue 24/10/2026).
        if _mod is not honeypot_module and not after.content:
            continue
        try:
            if _mod is token_grabber_module:
                fait = await _mod.on_message_hook(after, sanctionner=not exempt)
            else:
                fait = await _mod.on_message_hook(after)
            if fait:
                return True  # message déjà supprimé par le scanner
        except Exception as ex:
            print(f"[on_message_edit {_name}] {ex}")
    # 2) Phishing / liens masqués / scam (mêmes vérifs que on_message:46979-47017)
    try:
        c = await cfg(after.guild.id)
        ct = after.content or ""
        if c.get('anti_phishing'):
            f, d = check_phishing(ct)
            if f:
                try:
                    await after.delete()
                except Exception:
                    pass  # audit 2026-07-02 : delete peut échouer (perms/déjà supprimé) → la
                          # sanction+log DOIVENT quand même s'exécuter (invariant #5)
                await send_log(after.guild, 'anti_phishing', after.author, after, "Lien de phishing détecté (édition)", f"`{d}`")
                await sanction(after.author, c.get('phishing_action', 'delete'), c.get('phishing_mute_duration', 60), "Phishing (édition)", after.guild)
                return True
            f_mask, d_mask = check_masked_links(ct)
            if f_mask:
                try:
                    await after.delete()
                except Exception:
                    pass
                await send_log(after.guild, 'anti_phishing', after.author, after, "Lien masqué détecté (édition)", f"`{d_mask}`")
                await sanction(after.author, c.get('phishing_action', 'delete'), c.get('phishing_mute_duration', 60), "Lien masqué phishing (édition)", after.guild)
                return True
        if c.get('anti_scam'):
            f, p = check_scam(ct)
            if f:
                try:
                    await after.delete()
                except Exception:
                    pass
                await send_log(after.guild, 'anti_scam', after.author, after, "Message de scam détecté (édition)", f"`{p}`")
                await sanction(after.author, c.get('scam_action', 'mute'), c.get('scam_mute_duration', 60), "Scam (édition)", after.guild)
                return True
    except Exception as ex:
        print(f"[on_message_edit phishing/scam] {ex}")
    # 3) CONTENU MODÉRÉ (owner 2026-06-29, audit) : grooming / doxxing / menaces / validisme /
    #    insultes / off-topic ne tournaient QU'à la création → un membre pouvait éditer un message
    #    anodin pour y injecter ces contenus (bypass de la protection mineurs). On rejoue les MÊMES
    #    détecteurs sur `after`, avec la MÊME garde immunisés/tickets. FAIL-SAFE (best-effort).
    try:
        guild = after.guild
        author = after.author
        if guild is None or author is None:
            return False
        #  Même exemption qu'à l'envoi : la tête et le staff ne sont jamais sanctionnés par un
        #  automatisme (revue 24/10/2026, règle du 19/10).
        if await is_immune(author, 'general', after.channel) or await is_fully_immune(author):
            return False
        if await is_ticket_channel(after.channel):
            return False
        c = await cfg(guild.id)
        ct = after.content or ""
        if not ct:
            return False
        _spoken = _URL_INMSG_RE.sub(' ', ct) if ct else ct
        try:
            _ispoken_norm = _normalize_for_scan(_spoken)
        except Exception:
            _ispoken_norm = _spoken
        try:
            _ideob = _deobfuscate_for_insult(_spoken)
        except Exception:
            _ideob = ""

        # — APPROCHE PRÉDATRICE : mêmes règles qu'à l'envoi (retiré, direction alertée) —
        if c.get('anti_grooming', 1):
            _pm = pmineurs.analyser(ct)
            if _pm.get("touche"):
                try:
                    await after.delete()
                except discord.HTTPException:
                    pass
                await send_log(guild, 'anti_scam', author, after, "Approche prédatrice (édition)",
                               pmineurs.resume(_pm))
                return True

        # — DOXXING —
        if c.get('anti_doxxing', 1):
            try:
                if await _doxxing_check(after, ct):
                    return True
            except Exception:
                pass

        # — MENACES / INTIMIDATION IRL —
        _thr, _thr_dur = None, False
        try:
            if c.get('anti_threat', 1):
                _thr = insult_filter.threat_hit(_spoken, _ispoken_norm)
                if not _thr and _ideob:
                    _thr = insult_filter.threat_hit(_ideob)
                _thr_dur = bool(_thr)
                if not _thr and not _GAMING_CTX_RE.search(_spoken or ''):
                    _thr = insult_filter.threat_soft_hit(_spoken, _ispoken_norm)
                    if not _thr and _ideob:
                        _thr = insult_filter.threat_soft_hit(_ideob)
        except Exception:
            _thr = None
        if _thr:
            try:
                await after.delete()
            except Exception:
                pass
            if _thr_dur:
                try:
                    await author.timeout(timedelta(hours=1), reason=f"Menace (édition) : {str(_thr)[:40]}")
                except Exception:
                    pass
            try:
                await _record_infraction(guild.id, author.id, 'menace',
                                         f"Menace/intimidation IRL (édition) : {str(_thr)[:50]}",
                                         '1h' if _thr_dur else '')
            except Exception:
                pass
            try:
                await ulogger2026.log_event(
                    bot, guild, ulogger2026.EventType.SEC_ESCALATION,
                    description=(f"⚔️ **MENACE / INTIMIDATION (édition)** de {author.mention} "
                                 f"(`{author.id}`) dans {after.channel.mention} → message retiré"
                                 f"{' + exclusion 1 h' if _thr_dur else ''}.\n**Extrait :** ||{str(_thr)[:60]}||\n"
                                 f"➡️ Si menace réelle, **bannis** (`/off`)."),
                    user=author, moderator=bot.user, channel=after.channel,
                    extra={"⚔️ Gravité": "Menace IRL (édition)"})
            except Exception:
                pass
            try:
                await _note_attack(after, 'menace', _thr)
            except Exception:
                pass
            return True

        # — VALIDISME / DISCRIMINATION —
        _abl = None
        try:
            _abl = insult_filter.ableist_hit(_spoken, _ispoken_norm)
            if not _abl and _ideob:
                _abl = insult_filter.ableist_hit(_ideob)
        except Exception:
            _abl = None
        if _abl:
            try:
                await after.delete()
            except Exception:
                pass
            try:
                await send_log(guild, 'anti_badwords', author, after,
                               "Terme discriminatoire (validisme) retiré (édition)", f"||{str(_abl)[:40]}||")
            except Exception:
                pass
            try:
                await _record_infraction(guild.id, author.id, 'discrimination',
                                         f"Validisme (édition) : {str(_abl)[:40]}", '')
            except Exception:
                pass
            try:
                await _cumulative_offense_sanction(guild, author, after.channel, 'propos discriminatoire')
            except Exception:
                pass
            try:
                await _note_attack(after, 'discrimination', _abl)
            except Exception:
                pass
            return True

        # — INSULTES (général, niveau ≥2) —
        if c.get('anti_insults', 1):
            try:
                _ilvl, _iterm = insult_filter.scan(_spoken, _ispoken_norm)
                if _ideob:
                    _dlvl, _dterm = insult_filter.scan(_ideob)
                    if _dlvl > _ilvl:
                        _ilvl, _iterm = _dlvl, _dterm
            except Exception:
                _ilvl, _iterm = 0, None
            # Insulte vulgaire claire (con/trou du cul/fils de pute…) glissée par ÉDITION → même
            # traitement, peu importe la cible (cf. _DIRECT_VULGAR_RE, liste zéro-FP testée).
            if _ilvl < 3:
                try:
                    _dv = _DIRECT_VULGAR_RE.search(_spoken or '')
                    if not _dv and _ideob:
                        _dv = _DIRECT_VULGAR_RE.search(_ideob)
                    if (_dv and _dv.group(0).lower().startswith(('con', 'c0n', 'fil'))
                            and not _insulte_visee(after, _spoken) and _GAMING_CTX_RE.search(_spoken or '')):
                        _dv = None  # « ce boss est un fils de pute » : une chose du jeu, comme à l'envoi
                except Exception:
                    _dv = None
                if _dv:
                    try:
                        await after.delete()
                    except Exception:
                        pass
                    try:
                        await _record_infraction(guild.id, author.id, 'insulte',
                                                 f"Insulte vulgaire (édition) : {_dv.group(0)[:40]}", '')
                    except Exception:
                        pass
                    try:
                        await _warn_calm_down(
                            after.channel,
                            f"⛔ {author.mention}, ton message édité contenait une insulte — retiré. 🙏")
                    except Exception:
                        pass
                    try:
                        await _note_attack(after, 'insulte', _dv.group(0))
                    except Exception:
                        pass
                    # Symétrie avec on_message (audit 2026-06-30) : l'édition ALIMENTE aussi
                    # l'escalade graduée + le burst-autoban → un récidiviste 100 %-édition ne peut
                    # plus échapper au mute/blacklist. _cumulative/_offense_tick ont leurs gardes
                    # d'immunité. FAIL-SAFE.
                    try:
                        if await _offense_tick(guild, author, after.channel):
                            return True   # exclu par la rafale → on s'arrête là
                    except Exception:
                        pass
                    try:
                        await _cumulative_insult_sanction(after, _dv.group(0))
                    except Exception:
                        pass
                    return True
            if _ilvl >= 3 or (_ilvl == 2 and _insulte_visee(after, _spoken)):
                try:
                    await after.delete()
                except Exception:
                    pass
                try:
                    await _record_infraction(guild.id, author.id, 'insulte',
                                             f"Insulte (édition) : {str(_iterm or '')[:40]}", '')
                except Exception:
                    pass
                try:
                    await _warn_calm_down(
                        after.channel,
                        f"⛔ {author.mention}, ton message édité contenait des propos déplacés — retiré. 🙏")
                except Exception:
                    pass
                try:
                    await _note_attack(after, 'insulte', _iterm)
                except Exception:
                    pass
                return True

        # — OFF-TOPIC (politique / religion / militantisme) —
        if c.get('anti_offtopic', 1):
            try:
                _ot = _sujet_interdit(c, ct, after)
            except Exception:
                _ot = None
            if _ot:
                try:
                    await after.delete()
                except Exception:
                    pass
                try:
                    _ots = _register_protection_strike(guild.id, author.id, 'offtopic')
                except Exception:
                    _ots = 1
                if _ot.startswith("extremisme"):   # la plus grave : la pause tout de suite
                    _ots = max(_ots, 3)
                if _ots >= 3:
                    try:
                        await author.timeout(timedelta(minutes=5),
                                             reason="Contenu politique/religieux répété (édition)")
                    except Exception:
                        pass
                    try:
                        await _warn_calm_down(
                            after.channel,
                            f"🎮 {author.mention}, ici c'est **gaming & chill** — pas de politique ni "
                            f"de religion. Pause de **5 min** 🙏")
                    except Exception:
                        pass
                else:
                    try:
                        await _warn_calm_down(
                            after.channel,
                            f"🎮 {author.mention}, on garde la politique et la religion **hors** du serveur 🙏")
                    except Exception:
                        pass
                try:
                    await send_log(guild, 'anti_badwords', author, after,
                                   "Contenu politique/religieux/militant (édition)", f"||{str(_ot or '')[:60]}||")
                except Exception:
                    pass
                return True
    except Exception as ex:
        print(f"[on_message_edit content-moderation] {ex}")
    return False


@bot.event
async def on_message_edit(before, after):
    """Re-scan SÉCURITÉ du contenu ÉDITÉ (phishing/scam/token/webhook — anti-contournement
    par édition). Owner 2026-06-14 : le LOG d'édition de message = bruit inutile → SUPPRIMÉ.
    On garde UNIQUEMENT le re-scan de sécurité."""
    try:
        if before.author is None or before.author.bot or before.guild is None:
            return
        # Ignore si contenu identique (Discord renvoie on_message_edit pour les previews d'embed)
        if (before.content or "") == (after.content or ""):
            return
        # FIX sécu P0-2 : re-scanner le contenu ÉDITÉ (phishing/token/webhook/scam).
        try:
            await _scan_security_on_edit(after)
        except Exception as _ex:
            print(f"[on_message_edit rescan] {_ex}")
        # LOG MSG_EDIT RETIRÉ (anti-spam logs, demande owner 2026-06-14) — une édition de
        # message n'est pas un événement important. Le re-scan sécurité ci-dessus suffit.
    except Exception as ex:
        print(f"[on_message_edit] {ex}")


@bot.event
async def on_guild_channel_create(channel):
    try:
        if channel.guild is None:
            return
        # Salon d'entraide 🆘 éphémère créé par le bot → jamais loggé (anti-bruit).
        if (getattr(channel, 'name', '') or '').startswith('🆘'):
            return
        if channel.id not in temp_voice_channels:  # les vocaux temporaires sont l'œuvre du bot
            await _antinuke_check(channel.guild, 'channel_create', channel.id)  # nuke par création massive
        # RADIATION (/off) : si le rôle « 🚫 Radié » existe, poser le DENY sur ce NOUVEAU salon.
        # Sans ça, un membre radié verrait tout salon créé APRÈS sa radiation (audit 2026-06-21 :
        # _ensure_radie_role ne couvrait que les salons EXISTANTS — fuite de lecture). Idempotent,
        # une seule pose par création (événement rare → coût anti-429 négligeable). Fail-safe.
        try:
            radie = discord.utils.get(channel.guild.roles, name=_RADIE_ROLE_NAME)
            if radie is not None and hasattr(channel, 'set_permissions'):
                await channel.set_permissions(
                    radie, overwrite=_radie_overwrite(),
                    reason="Radiation totale (/off) — couverture du nouveau salon")
        except Exception as _rex:
            print(f"[radie chan_create] {_rex}")
        # QUARANTAINE : même chose — sans ça, un membre en quarantaine parlait dans tout salon créé
        # après sa mise à l'écart (audit 19/10/2026).
        try:
            quar = next((r for r in channel.guild.roles if (r.name or "").lower() in _QUARANTINE_ROLE_NAMES), None)
            if quar is not None and hasattr(channel, 'set_permissions'):
                # Le refus complet (fils, forums, vocal compris), comme sur les salons existants.
                await channel.set_permissions(quar, overwrite=_quarantaine_overwrite(),
                                              reason="Isolement sécurité (nouveau salon)")
        except discord.HTTPException as _qex:
            _logerr("quarantaine.nouveau_salon", _qex, guild_id=channel.guild.id)
        #  29/10/2026 : un nouveau studio, forum ou vocal — le staff peut y modérer tout de suite (droits_staff.py).
        try:
            if hasattr(channel, 'set_permissions') and channel.guild.me.guild_permissions.manage_roles:
                await droits_staff.nouveau_salon(channel, *_equipes_droits(channel.guild, await cfg(channel.guild.id)))
        except Exception as _dex:
            _logerr("droits_staff.nouveau_salon", _dex, guild_id=channel.guild.id)
        await _log_audited(
            channel.guild, ulogger2026.EventType.CHAN_CREATE,
            discord.AuditLogAction.channel_create, channel.id,
            lambda a: (f"➕ **{a}** a créé le salon {channel.mention} (`#{channel.name}`)."
                       if a else f"➕ Salon créé : {channel.mention} (`#{channel.name}`)."),
            channel=channel,
        )
    except Exception as ex:
        print(f"[UNIFIED LOG chan_create] {ex}")


# ═══════════════ ANTI-NUKE + GARDE WEBHOOKS (audit 2026-06-14) ═══════════════
# Détecte une suppression MASSIVE de salons/rôles par un MÊME acteur en quelques secondes
# (compte compromis / staff malveillant) → retire ses rôles à RISQUE (best-effort, réversible)
# + alerte l'owner en DM. Owner / super-owner / bot JAMAIS visés. Seuil élevé = très peu de
# faux positifs (une suppression manuelle est bien plus lente). Tout est FAIL-OPEN.
_antinuke_events = {}      # (guild_id, actor_id) -> [timestamps récents]
_antinuke_triggered = {}   # (guild_id, actor_id) -> dernier déclenchement (anti-rejeu)
_webhook_guard_cd = {}     # guild_id -> dernière alerte webhook (cooldown anti-bruit)


async def _antinuke_check(guild, kind, cible_id=None):
    """kind = 'channel' | 'role' | 'channel_create' | 'role_create'. `cible_id` : le salon ou le rôle
    concerné — l'auteur est celui de CETTE entrée d'audit, pas le dernier venu (19/10/2026)."""
    try:
        if guild is None:
            return
        c = await cfg(guild.id)
        if not c.get('antinuke_enabled', True):
            return
        _ANTINUKE_ACTS = {
            'channel': discord.AuditLogAction.channel_delete,
            'role': discord.AuditLogAction.role_delete,
            'channel_create': discord.AuditLogAction.channel_create,  # owner 2026-06-27 : nuke par CRÉATION
            'role_create': discord.AuditLogAction.role_create,
        }
        act = _ANTINUKE_ACTS.get(kind)
        if act is None:
            return
        actor, _r = await _audit_actor(guild, act, target_id=cible_id, within_sec=12)
        if actor is None:
            return  # auteur non identifiable (perm audit manquante) → on n'agit pas (fail-open)
        me = guild.me
        if getattr(actor, 'bot', False) or actor.id == guild.owner_id \
           or (me is not None and actor.id == me.id) or owner_ids_module.is_super_owner(actor.id):
            return  # exemptions absolues
        now = discord.utils.utcnow().timestamp()
        window = int(c.get('antinuke_window_sec', 12) or 12)
        threshold = max(2, int(c.get('antinuke_threshold', 4) or 4))
        key = (guild.id, actor.id)
        recent = [t for t in _antinuke_events.get(key, []) if now - t <= window]
        recent.append(now)
        if len(_antinuke_events) > 500:        # borne mémoire (éviction brutale acceptable ici)
            _antinuke_events.clear()
        _antinuke_events[key] = recent
        if len(recent) < threshold:
            return
        if now - _antinuke_triggered.get(key, 0) < 300:
            return  # déjà traité récemment (anti-rejeu)
        if len(_antinuke_triggered) > 500:        # borne mémoire (symétrie avec _antinuke_events)
            _antinuke_triggered.clear()
        _antinuke_triggered[key] = now
        await _antinuke_respond(guild, actor, kind, len(recent), c)
    except Exception as ex:
        print(f"[antinuke check] {ex}")


async def _antinuke_respond(guild, actor, kind, count, c):
    """Neutralise l'acteur (retrait des rôles à risque, best-effort) + alerte owner. Réversible."""
    removed = []
    mode = c.get('antinuke_action', 'quarantine')
    member = guild.get_member(actor.id)
    if mode == 'quarantine' and member is not None:
        me = guild.me
        for r in list(getattr(member, 'roles', [])):
            try:
                if r.is_default() or r.managed:
                    continue
                p = r.permissions
                if (p.administrator or p.manage_guild or p.manage_channels or p.manage_roles
                        or p.manage_webhooks or p.ban_members or p.kick_members) \
                        and me is not None and r < me.top_role:
                    await member.remove_roles(r, reason="Anti-nuke : suppression massive détectée")
                    removed.append(r.name)
                    await asyncio.sleep(0.3)   # throttle anti-429
            except Exception:
                continue
    quoi = 'salons' if kind.startswith('channel') else 'rôles'
    verbe = 'créé' if kind.endswith('_create') else 'supprimé'
    if removed:
        action_txt = f"🛡️ Rôles à risque retirés : {', '.join(removed[:15])}"
    elif mode == 'quarantine':
        action_txt = "⚠️ Impossible de retirer ses rôles (hiérarchie/permissions) — **interviens vite**."
    else:
        action_txt = "ℹ️ Mode alerte seule (aucun retrait automatique)."
    txt = (f"🚨 **ANTI-NUKE** — {actor.mention} (`{actor.id}`) a {verbe} **{count}** {quoi} "
           f"en quelques secondes.\n{action_txt}\n"
           f"_Fausse alerte ? Restaure ses rôles. Seuil/mode réglables (clés `antinuke_*`)._")
    try:  # journal sécurité routé — PAS de mass-ping (anti-bruit serveur)
        await ulogger2026.log_event(bot, guild, ulogger2026.EventType.SEC_ESCALATION, description=txt)
    except Exception:
        pass
    # (MP au propriétaire SUPPRIMÉ le 12/08/2026, à sa demande. Le même texte part
    #  déjà dans le journal de sécurité juste au-dessus.
    #  ⚠️ RÉSERVE ASSUMÉE : pendant un nuke, le salon de logs est la PREMIÈRE cible.
    #  Le message privé était le seul canal qui y survivait. Le propriétaire a été
    #  prévenu de ce compromis et l'a accepté ; remettre ce bloc suffit à revenir
    #  en arrière.)


def _has_risky_perms(member) -> bool:
    try:
        p = member.guild_permissions
        return bool(p.administrator or p.manage_guild or p.manage_channels or p.manage_roles
                    or p.manage_webhooks or p.ban_members or p.kick_members)
    except Exception:
        return False


_compromised_riposte_cd = {}  # (gid, uid) -> ts (anti-rejeu)


async def _compromised_riposte(msg, reason):
    """#4 (owner 2026-06-21) — RIPOSTE COMPTE PIRATÉ. Si l'AUTEUR d'un contenu malveillant
    (phishing/scam) est un membre PRIVILÉGIÉ (admin/manage_*/ban/kick/webhooks), c'est très
    vraisemblablement un compte PIRATÉ → on lui retire SUR-LE-CHAMP ses rôles à risque
    (réversible) + exclusion 1 h + alerte owner, AVANT qu'il puisse nuke. Pour un membre
    lambda (sans perms) → no-op (la suppression + sanction normale suffit). Owner/super-owner
    JAMAIS visés. Anti-rejeu 5 min. FAIL-SAFE."""
    try:
        member = getattr(msg, 'author', None)
        guild = getattr(msg, 'guild', None)
        if member is None or guild is None or getattr(member, 'bot', False):
            return
        if member.id in (guild.owner_id, *TETE_IDS) or owner_ids_module.is_super_owner(member.id):
            return
        if not _has_risky_perms(member):
            return
        now_ts = discord.utils.utcnow().timestamp()
        if now_ts - _compromised_riposte_cd.get((guild.id, member.id), 0) < 300:
            return
        _compromised_riposte_cd[(guild.id, member.id)] = now_ts
        if len(_compromised_riposte_cd) > 500:
            _compromised_riposte_cd.clear()
        me = guild.me
        removed = []
        for r in list(getattr(member, 'roles', [])):
            try:
                if r.is_default() or r.managed:
                    continue
                p = r.permissions
                if (p.administrator or p.manage_guild or p.manage_channels or p.manage_roles
                        or p.manage_webhooks or p.ban_members or p.kick_members) \
                        and me is not None and r < me.top_role:
                    await member.remove_roles(r, reason=f"Compte piraté présumé ({reason}) — retrait préventif")
                    removed.append(r.name)
                    await asyncio.sleep(0.3)
            except Exception:
                continue
        try:
            await member.timeout(timedelta(hours=1), reason=f"Compte piraté présumé ({reason})")
        except Exception:
            pass
        act = (f"🛡️ Rôles à risque retirés : {', '.join(removed[:15])}" if removed
               else "⚠️ Rôles non retirables (hiérarchie) — interviens vite.")
        txt = (f"🚨 **COMPTE PIRATÉ PRÉSUMÉ** — {member.mention} (`{member.id}`), un membre "
               f"PRIVILÉGIÉ, a posté du **{reason}**. {act} + exclusion 1 h.\n"
               f"_Fausse alerte ? Rends-lui ses rôles. (Riposte anti-nuke compte piraté.)_")
        try:
            await ulogger2026.log_event(bot, guild, ulogger2026.EventType.SEC_ESCALATION,
                                        description=txt, user=member, moderator=bot.user)
        except Exception:
            pass
        # (MP au propriétaire SUPPRIMÉ le 12/08/2026, à sa demande. Le même texte
        #  part déjà dans le journal de sécurité juste au-dessus — rien n'est perdu.)
    except Exception as ex:
        print(f"[_compromised_riposte] {ex}")


@bot.event
async def on_webhooks_update(channel):
    """Garde webhooks : alerte l'owner si un NON-owner crée un webhook (vecteur de nuke/spam/
    exfiltration via un staff compromis). Alerte SEULE (des intégrations légitimes créent des
    webhooks → pas de suppression auto). Cooldown par guilde (anti-bruit / anti-429)."""
    try:
        guild = getattr(channel, 'guild', None)
        if guild is None:
            return
        c = await cfg(guild.id)
        if not c.get('webhook_guard_enabled', True):
            return
        now = discord.utils.utcnow().timestamp()
        if now - _webhook_guard_cd.get(guild.id, 0) < 30:
            return  # cooldown anti-bruit
        actor, _r = await _audit_actor(guild, discord.AuditLogAction.webhook_create, within_sec=15)
        if actor is None:
            return
        me = guild.me
        if getattr(actor, 'bot', False) or actor.id == guild.owner_id \
           or (me is not None and actor.id == me.id) or owner_ids_module.is_super_owner(actor.id):
            return
        _webhook_guard_cd[guild.id] = now
        if len(_webhook_guard_cd) > 500:
            _webhook_guard_cd.clear()
        # #5 (owner 2026-06-21) : AUTO-SUPPRESSION des webhooks créés par un NON-admin (un
        # membre lambda / compte piraté ne devrait jamais créer de webhook). Les admins sont
        # épargnés (alerte seule) pour ne pas casser une intégration légitime. Nécessite la
        # perm Manage Webhooks du bot. FAIL-SAFE.
        _deleted_wh = 0
        try:
            _am = guild.get_member(actor.id)
            _actor_admin = bool(_am and _am.guild_permissions.administrator)
        except Exception:
            _actor_admin = False
        if c.get('webhook_autodelete', 1) and not _actor_admin:
            try:
                for wh in await channel.webhooks():
                    try:
                        if getattr(wh, 'user', None) is not None and wh.user.id == actor.id:
                            await wh.delete(reason="Webhook créé par un non-admin — auto-suppression (sécurité)")
                            _deleted_wh += 1
                            await asyncio.sleep(0.3)
                    except Exception:
                        continue
            except Exception:
                pass
        if _deleted_wh:
            txt = (f"🪝 **Garde webhooks** — {actor.mention} (`{actor.id}`) a créé un webhook dans "
                   f"{getattr(channel, 'mention', '#?')} → **{_deleted_wh} webhook(s) supprimé(s) "
                   f"automatiquement** (créateur non-admin). Vérifie si c'était volontaire.")
        else:
            txt = (f"🪝 **Garde webhooks** — {actor.mention} (`{actor.id}`) vient de créer un webhook "
                   f"dans {getattr(channel, 'mention', '#?')}. Si ce n'est pas une intégration que tu "
                   f"connais, **supprime-le** (un webhook détourné permet spam / exfiltration).")
        try:
            await ulogger2026.log_event(bot, guild, ulogger2026.EventType.SEC_ESCALATION, description=txt)
        except Exception:
            pass
        # (MP au propriétaire SUPPRIMÉ le 12/08/2026, à sa demande. Le même texte
        #  part déjà dans le journal de sécurité juste au-dessus — rien n'est perdu.)
    except Exception as ex:
        print(f"[on_webhooks_update] {ex}")


@tasks.loop(hours=6)
async def tickets_inactifs_task():
    """19/10/2026 : un ticket sans message depuis `tickets_inactivite_jours` jours (7 par
    défaut, 0 = jamais) est fermé comme au bouton 🔒 : log + transcript — sans MP au créateur ni annonce
    (« ils n'ont pas à le savoir » : un nettoyage)."""
    for g in list(bot.guilds):
        try:
            jours = int((await cfg(g.id)).get('tickets_inactivite_jours', 7) or 0)
            if jours <= 0:
                continue
            async with get_db() as db:
                async with db.execute(
                        "SELECT id, channel_id, user_id, claimed_by, answers, panel_id FROM tickets "
                        "WHERE guild_id=? AND status='open'", (g.id,)) as cur:
                    lignes = await cur.fetchall()
            fermes = 0
            for tid, chid, uid, claimed, answers, pid in lignes:
                if fermes >= 25:
                    break
                ch = await tickets_fils.salon(g, chid)
                if ch is None:
                    async with get_db() as db:
                        await db.execute("UPDATE tickets SET status='closed' WHERE id=?", (tid,))
                        await db.commit()
                    continue
                dernier = discord.utils.snowflake_time(getattr(ch, 'last_message_id', None) or ch.id)
                if (now() - dernier).days < jours:
                    continue
                try:
                    ans = json.loads(answers) if answers else {}
                except ValueError:
                    ans = {}
                tk = {'id': tid, 'user': uid, 'claimed': claimed or 0, 'answers': ans,
                      'panel_id': pid or ''}
                await _fermer_ticket(g, ch, tk, g.me, f"{jours} jours sans message", inactif_jours=jours)
                fermes += 1
                await asyncio.sleep(3)
        except Exception as ex:
            _logerr("ticket.inactifs", ex, guild_id=g.id)


@tickets_inactifs_task.before_loop
async def _tickets_inactifs_wait():
    await bot.wait_until_ready()


