# ═══════════════════════════════════════════════════════════════════════════════

def _vue_blacklist(texte: str, avatar, couleur) -> LayoutView:
    """Réponse privée de /mod ticketblacklist (Components V2)."""
    v = LayoutView(timeout=60)
    corps = discord.ui.TextDisplay(texte)
    v.add_item(v2_container(discord.ui.Section(corps, accessory=discord.ui.Thumbnail(avatar)) if avatar else corps,
                            color=couleur))
    return v


@mod_group.command(name="ticketblacklist", description="🚫 Gérer la blacklist des tickets")
@app_commands.describe(
    action="Ajouter ou retirer de la blacklist",
    membre="Le membre à blacklister/déblacklister",
    panel="Le nom du panel (laissez vide pour voir la liste)"
)
@app_commands.choices(action=[
    app_commands.Choice(name="➕ Ajouter à la blacklist", value="add"),
    app_commands.Choice(name="➖ Retirer de la blacklist", value="remove"),
    app_commands.Choice(name="📋 Voir la liste", value="list")
])
async def ticketblacklist_cmd(
    i: discord.Interaction, 
    action: str,
    membre: discord.Member = None,
    panel: str = None
):
    c = await cfg(i.guild.id)
    panels = c.get('ticket_panels', {})
    
    # ═══════════════════════════════════════════════════════════════════════════════
    #                    🔒 VÉRIFICATION DES PERMISSIONS
    # ═══════════════════════════════════════════════════════════════════════════════
    # Peut utiliser si : Admin OU Owner OU a le rôle ticket_blacklist_role OU a le rôle ticket_staff
    is_admin = i.user.guild_permissions.administrator
    is_owner = i.user.id == i.guild.owner_id
    
    blacklist_role_id = c.get('ticket_blacklist_role', 0)
    staff_role_id = c.get('ticket_staff', 0)
    
    has_blacklist_role = blacklist_role_id and i.guild.get_role(blacklist_role_id) in i.user.roles
    has_staff_role = staff_role_id and i.guild.get_role(staff_role_id) in i.user.roles
    
    if not (is_admin or is_owner or has_blacklist_role or has_staff_role):
        return await i.response.send_message(
            "❌ Vous n'avez pas la permission d'utiliser cette commande.\n"
            "*Requis : Admin, rôle Staff tickets, ou rôle Blacklist configuré*",
            ephemeral=True
        )
    
    if not panels:
        return await i.response.send_message("❌ Aucun panel de ticket configuré.", ephemeral=True)
    
    # Si action = list, afficher tous les panels et leurs blacklists
    if action == "list":
        lignes = []
        for pid, pdata in panels.items():
            blacklist = pdata.get('blacklist', [])
            noms = [f"<@{uid}>" for uid in blacklist[:10]] + ([f"… +{len(blacklist) - 10}"] if len(blacklist) > 10 else [])
            lignes.append(f"**{pdata.get('name', pid)}** ({len(blacklist)}) · " + (", ".join(noms) or "personne"))
        return await i.response.send_message(view=_vue_blacklist(
            "### Interdictions de tickets\n" + "\n".join(lignes)
            + "\n-# `/mod ticketblacklist` pour ajouter ou retirer quelqu'un.", None, Palette.DANGER),
            ephemeral=True, allowed_mentions=discord.AllowedMentions.none())
    
    # Pour add/remove, membre requis
    if not membre:
        return await i.response.send_message("❌ Spécifiez un membre.", ephemeral=True)
    
    # Trouver le panel
    target_pid = None
    if panel:
        # Chercher par nom
        for pid, pdata in panels.items():
            if pdata.get('name', '').lower() == panel.lower() or pid == panel:
                target_pid = pid
                break
        if not target_pid:
            panel_names = [pdata.get('name', pid) for pid, pdata in panels.items()]
            return await i.response.send_message(
                f"❌ Panel introuvable.\n\n**Panels disponibles:**\n" + "\n".join([f"• {n}" for n in panel_names]),
                ephemeral=True
            )
    else:
        # Si pas de panel spécifié et qu'il n'y en a qu'un, l'utiliser
        if len(panels) == 1:
            target_pid = list(panels.keys())[0]
        else:
            # Afficher le sélecteur
            panel_names = [pdata.get('name', pid) for pid, pdata in panels.items()]
            return await i.response.send_message(
                f"❌ Plusieurs panels disponibles, spécifiez lequel:\n" + "\n".join([f"• `{n}`" for n in panel_names]),
                ephemeral=True
            )
    
    panel_name = panels[target_pid].get('name', target_pid)
    blacklist = panels[target_pid].get('blacklist', [])
    
    if action == "add":
        # Vérifier que ce n'est pas un admin
        if membre.guild_permissions.administrator or membre.id == i.guild.owner_id:
            return await i.response.send_message("❌ Impossible de blacklister un administrateur.", ephemeral=True)
        
        if membre.id in blacklist:
            return await i.response.send_message(f"❌ {membre.mention} est déjà blacklisté du panel **{panel_name}**.", ephemeral=True)
        
        blacklist.append(membre.id)
        panels[target_pid]['blacklist'] = blacklist
        if not await db_set(i.guild.id, 'ticket_panels', panels):
            return await i.response.send_message("❌ L'interdiction n'a pas pu être enregistrée.", ephemeral=True)
        await _au_journal(i.guild, "Tickets", "ticket.interdit",
                          f"{membre.display_name} interdit de tickets « {panel_name} » par {i.user.display_name}",
                          membre_id=membre.id, auteur_id=i.user.id)
        await i.response.send_message(view=_vue_blacklist(
            f"### Interdit de tickets\n{membre.mention} ne peut plus ouvrir de ticket « {panel_name} ».\n"
            "-# Il n'est pas prévenu : s'il essaie, un avis générique le lui dit.", membre.display_avatar.url,
            Palette.DANGER), ephemeral=True, allowed_mentions=discord.AllowedMentions.none())
        #  27/10/2026 : qui, depuis quand — lu sur sa fiche (le site). Rien ne lui est envoyé.
        await tickets_interdits.noter(i.guild, membre.id, [target_pid], par=i.user.id, source="commande")

    elif action == "remove":
        if membre.id not in blacklist:
            return await i.response.send_message(f"❌ {membre.mention} n'est pas blacklisté du panel **{panel_name}**.", ephemeral=True)

        blacklist.remove(membre.id)
        panels[target_pid]['blacklist'] = blacklist
        if not await db_set(i.guild.id, 'ticket_panels', panels):
            return await i.response.send_message("❌ Le retrait n'a pas pu être enregistré.", ephemeral=True)
        await _au_journal(i.guild, "Tickets", "ticket.autorise",
                          f"{membre.display_name} de nouveau autorisé (tickets « {panel_name} ») par {i.user.display_name}",
                          membre_id=membre.id, auteur_id=i.user.id)
        await i.response.send_message(view=_vue_blacklist(
            f"### Tickets de nouveau ouverts\n{membre.mention} peut à nouveau ouvrir un ticket « {panel_name} ».",
            membre.display_avatar.url, Palette.SUCCESS), ephemeral=True, allowed_mentions=discord.AllowedMentions.none())
        #  27/10/2026 : un panneau du clan rouvert lève aussi l'entrée de la liste noire du recrutement (elle interdit tout
        #  le clan) ; le décor de la fiche suit. Rien ne lui est envoyé.
        await tickets_interdits.apres_levee(i.guild, i.user, membre.id, [target_pid])


