async def _forget_temp_voice_room(channel_id):
    """Oublie un vocal temporaire (ligne DB)."""
    try:
        async with get_db() as _db:
            await _db.execute(
                "DELETE FROM temp_voice_rooms WHERE channel_id=?", (channel_id,))
            await _db.commit()
    except Exception as ex:
        print(f"[temp_voice forget] {ex}")


@tasks.loop(minutes=2)
async def temp_voice_watchdog():
    """Phase 235.5 : nettoie les vocaux temporaires « Voc Build » ORPHELINS.

    L'état ne vivait que dans le dict mémoire `temp_voice_channels` → après un
    reboot, tout vocal temporaire déjà vide (ou devenu vide pendant que le bot
    était hors-ligne) n'était JAMAIS supprimé et s'empilait en bas du serveur
    (plainte récurrente de l'owner). On rejoue la vérité depuis `temp_voice_rooms` :
    salon disparu → on oublie la ligne ; salon vide → on le supprime + oublie ;
    salon vivant → on re-synchronise le dict mémoire (perdu au reboot) pour que la
    suppression-à-la-sortie refonctionne. 1re itération immédiate au boot.
    """
    try:
        async with get_db() as _db:
            async with _db.execute(
                "SELECT guild_id, channel_id, hub_id, owner_id FROM temp_voice_rooms"
            ) as cur:
                rows = await cur.fetchall()
        for gid, ch_id, hub_id, owner_id in rows:
            try:
                guild = bot.get_guild(int(gid))
                if guild is None:
                    continue
                ch = guild.get_channel(int(ch_id))
                if ch is None:
                    temp_voice_channels.pop(int(ch_id), None)
                    await _forget_temp_voice_room(int(ch_id))
                    continue
                if len(ch.members) == 0:
                    try:
                        await ch.delete(reason="Vocal temporaire vide (watchdog)")
                    except Exception:
                        pass
                    temp_voice_channels.pop(int(ch_id), None)
                    await _forget_temp_voice_room(int(ch_id))
                elif int(ch_id) not in temp_voice_channels:
                    temp_voice_channels[int(ch_id)] = {
                        'owner': int(owner_id or 0),
                        'hub_id': int(hub_id or 0),
                        'created_at': now(),
                    }
            except Exception as ex:
                print(f"[temp_voice_watchdog room={ch_id}] {ex}")
    except Exception as ex:
        print(f"[temp_voice_watchdog] {ex}")


@temp_voice_watchdog.before_loop
async def before_temp_voice_watchdog():
    await bot.wait_until_ready()


# Anti-spam création de vocaux (owner 2026-06-18) : borne les « join-create » répétés
# d'un même membre sur un hub (un spammeur pouvait inonder le serveur de salons vides plus
# vite que l'auto-clean 5 min). Mémoire bornée, fenêtre glissante, fail-open. {(gid,uid): [ts]}.
_voice_hub_join_log: dict = {}
_VOICE_HUB_MAX = 6          # créations max par membre…
_VOICE_HUB_WINDOW = 600.0   # …par fenêtre de 10 min


# Mise à jour activité sur vocal + Vocaux Temporaires
@bot.event
async def on_voice_state_update(member, before, after):
    if member.bot:
        return

    # ═══ ACTIVITÉ — le vocal, compté comme un GESTE et non comme une présence ═══
    # RESTER assis dans un salon ne prouve rien : on peut y dormir des jours. Ne
    # compter que l'entrée ne suffit pas non plus — quelqu'un entré lundi 20h et
    # resté jusqu'à mardi 2h ne serait crédité que du lundi.
    # On retient donc les gestes VOLONTAIRES, qui se reproduisent naturellement
    # au fil d'une vraie session :
    #   · entrer dans un salon, ou en changer ;
    #   · reprendre son micro (sortir de sourdine) — l'intention de parler ;
    #   · lancer un partage d'écran ou la caméra.
    try:
        entre = after.channel is not None and before.channel is None
        change = (after.channel is not None and before.channel is not None
                  and after.channel.id != before.channel.id)
        reprend_micro = before.self_mute and not after.self_mute
        se_montre = ((after.self_stream and not before.self_stream)
                     or (after.self_video and not before.self_video))
        if entre or change or reprend_micro or se_montre:
            await activite_module.marquer_actif(
                member.guild.id, member.id, activite_module.SOURCE_VOCAL)
    except Exception as _ex_act:
        print(f"[activite on_voice] {_ex_act}")

    guild_id = member.guild.id
    user_id = member.id
    key = (guild_id, user_id)
    
    # ═══════════════ VOCAUX TEMPORAIRES (MULTI-HUBS) ═══════════════
    try:
        c = await cfg(guild_id)
        voice_cfg = c.get('temp_voice_config', {})
        
        if voice_cfg.get('enabled', False):
            hubs = voice_cfg.get('hubs', {})
            perms = voice_cfg.get('owner_permissions', {
                'can_rename': True, 'can_limit': True, 'can_mute': True, 'can_kick': True
            })
            
            # Vérifier si l'utilisateur REJOINT un des hubs configurés. 19/10/2026 (audit) : couper
            # son micro ou allumer sa caméra dans le hub n'est pas une arrivée — ça créait un salon de
            # plus, et au 6e en 10 min le membre était déconnecté sans un mot.
            if after.channel and (before.channel is None or before.channel.id != after.channel.id):
                hub_data = hubs.get(str(after.channel.id))
                
                if hub_data:
                    # Anti-spam : borne les créations répétées (flood de salons vides).
                    # Owner/super-owner exemptés. Fail-open (toute erreur → on laisse créer).
                    try:
                        _vexempt = (user_id == member.guild.owner_id
                                    or owner_ids_module.is_super_owner(user_id))
                    except Exception:
                        _vexempt = False
                    if not _vexempt:
                        try:
                            _vnow = time.time()
                            _vlog = [t for t in _voice_hub_join_log.get(key, [])
                                     if _vnow - t < _VOICE_HUB_WINDOW]
                            if len(_vlog) >= _VOICE_HUB_MAX:
                                _voice_hub_join_log[key] = _vlog  # conserve la fenêtre
                                try:
                                    await member.move_to(None)  # déconnexion silencieuse (zéro MP)
                                except Exception:
                                    pass
                                print(f"[TEMP VOICE] anti-spam : {member.display_name} "
                                      f"({len(_vlog)} créations / {int(_VOICE_HUB_WINDOW//60)} min) → bloqué")
                                return
                            _vlog.append(_vnow)
                            _voice_hub_join_log[key] = _vlog
                            if len(_voice_hub_join_log) > 2000:  # borne mémoire
                                for _k in [k2 for k2, ts in list(_voice_hub_join_log.items())
                                           if not ts or _vnow - ts[-1] > _VOICE_HUB_WINDOW]:
                                    _voice_hub_join_log.pop(_k, None)
                        except Exception:
                            pass
                    # C'est un hub configuré !
                    print(f"[TEMP VOICE] {member.display_name} a rejoint le hub "
                          f"'{after.channel.name}' → création du salon perso…")
                    cat_id = hub_data.get('category', 0)
                    required_role_id = hub_data.get('required_role', 0)
                    default_name = hub_data.get('default_name', '🔊 Vocal de {user}')
                    
                    # Vérifier si le membre a le rôle requis (si défini)
                    if required_role_id:
                        required_role = member.guild.get_role(required_role_id)
                        if required_role and required_role not in member.roles:
                            # Le membre n'a pas le rôle requis → le déconnecter
                            try:
                                await member.move_to(None)
                                # Envoyer un message privé expliquant pourquoi
                                await _mp_une_fois(
                                    member, f"hub_role:{after.channel.id}",
                                    f"❌ Vous ne pouvez pas créer de vocal dans ce hub.\n"
                                    f"🔒 Rôle requis: **{required_role.name}**\n"
                                    f"📍 Serveur: {member.guild.name}")
                                print(f"[TEMP VOICE] {member.display_name} expulsé du hub (rôle manquant: {required_role.name})")
                            except:
                                pass
                            return
                    
                    # Le membre peut créer un vocal
                    # Phase 221 : la catégorie peut avoir été supprimée/déplacée →
                    # on crée QUAND MÊME (salon non catégorisé) plutôt que de laisser
                    # le membre bloqué dans le hub sans rien qui se passe.
                    category = member.guild.get_channel(cat_id)
                    # Phase 221bis (owner 2026-07-10) : un id qui existe mais N'EST PAS une catégorie
                    # (salon texte/vocal collé par erreur, ou id réattribué à un autre type) → on le
                    # traite comme None pour créer QUAND MÊME (salon non catégorisé) au lieu de laisser
                    # le membre coincé dans le hub sans salon ni feedback.
                    if category is not None and not isinstance(category, discord.CategoryChannel):
                        category = None
                    if category is None or isinstance(category, discord.CategoryChannel):
                        channel_name = default_name.replace('{user}', member.display_name)[:50]
                        # Phase 25 : taille (user_limit) configurable par hub
                        try:
                            default_user_limit = int(hub_data.get('default_limit', 0) or 0)
                            if default_user_limit < 0 or default_user_limit > 99:
                                default_user_limit = 0
                        except Exception:
                            default_user_limit = 0
                        
                        # Récupérer le rôle requis pour les permissions
                        required_role = member.guild.get_role(required_role_id) if required_role_id else None
                        
                        # Permissions de base
                        overwrites = {}
                        
                        if required_role:
                            # ═══ VOCAL RESTREINT AU RÔLE ═══
                            # @everyone ne peut PAS voir ni rejoindre le vocal
                            overwrites[member.guild.default_role] = discord.PermissionOverwrite(
                                view_channel=False,  # ❌ Invisible pour ceux sans le rôle
                                connect=False,
                                speak=False
                            )
                            
                            # Le rôle requis PEUT voir et rejoindre le vocal
                            overwrites[required_role] = discord.PermissionOverwrite(
                                view_channel=True,   # ✅ Visible pour ceux avec le rôle
                                connect=True,
                                speak=True,
                                use_voice_activation=True,
                                stream=True,
                                send_messages=False,
                                read_messages=True
                            )
                        else:
                            # ═══ VOCAL PUBLIC ═══
                            # @everyone peut voir et rejoindre
                            overwrites[member.guild.default_role] = discord.PermissionOverwrite(
                                view_channel=True,
                                connect=True,
                                speak=True,
                                use_voice_activation=True,
                                stream=True,
                                send_messages=False,
                                read_messages=True
                            )
                        
                        # Le propriétaire — Phase 221 : on n'accorde les perms ÉLEVÉES
                        # (mute/move/manage) que SI le bot les possède lui-même. Sinon
                        # Discord refuse TOUTE la création (403 « Missing Permissions »)
                        # → le salon ne se créait jamais, le membre restait bloqué.
                        _me_perms = member.guild.me.guild_permissions
                        owner_ow = discord.PermissionOverwrite(
                            view_channel=True, connect=True, speak=True,
                            use_voice_activation=True, stream=True,
                            send_messages=False, read_messages=True,
                        )
                        if _me_perms.mute_members and perms.get('can_mute', True):
                            owner_ow.mute_members = True
                        if _me_perms.move_members and perms.get('can_kick', True):
                            owner_ow.move_members = True
                        if _me_perms.manage_channels and (perms.get('can_rename', True) or perms.get('can_limit', True)):
                            owner_ow.manage_channels = True
                        overwrites[member] = owner_ow
                        
                        # Le bot — Phase 221 : ne fixe en overwrite que les perms
                        # élevées qu'il possède réellement (sinon 403 à la création).
                        bot_ow = discord.PermissionOverwrite(
                            view_channel=True, connect=True, speak=True,
                            send_messages=True,
                        )
                        if _me_perms.manage_channels:
                            bot_ow.manage_channels = True
                        if _me_perms.move_members:
                            bot_ow.move_members = True
                        overwrites[member.guild.me] = bot_ow

                        #  14/10/2026 : la DIRECTION et le FONDATEUR déplacent
                        #  les membres d'ici vers un autre vocal. Le salon a ses
                        #  PROPRES permissions : celles de la catégorie (où le
                        #  staff tient « Déplacer ») ne le suivent pas.
                        for _r in acces_direction.roles(member.guild):
                            overwrites[_r] = acces_direction.permission(_me_perms)
                        #  19/10/2026 : « les staffs et ceux plus hauts que staff peuvent déplacer ».
                        for _r in _roles_staff_et_plus(member.guild, c):
                            overwrites.setdefault(_r, acces_direction.permission(_me_perms))

                        # Phase 221 : création ROBUSTE. Si Discord refuse les overwrites
                        # (perm manquante au bot → 403), on retente avec des overwrites
                        # MINIMAUX, puis SANS overwrites (hérite de la catégorie). Le
                        # salon DOIT se créer, sinon le membre reste coincé dans le hub.
                        new_channel = None
                        try:
                            new_channel = await member.guild.create_voice_channel(
                                name=channel_name, category=category,
                                overwrites=overwrites, user_limit=default_user_limit)
                        except discord.Forbidden:
                            try:
                                _safe = {t: discord.PermissionOverwrite(
                                            view_channel=getattr(o, 'view_channel', None),
                                            connect=getattr(o, 'connect', None),
                                            speak=getattr(o, 'speak', None))
                                         for t, o in overwrites.items()}
                                new_channel = await member.guild.create_voice_channel(
                                    name=channel_name, category=category,
                                    overwrites=_safe, user_limit=default_user_limit)
                                print("[TEMP VOICE] créé avec overwrites minimaux (perms bot limitées)")
                            except Exception:
                                try:
                                    new_channel = await member.guild.create_voice_channel(
                                        name=channel_name, category=category,
                                        user_limit=default_user_limit)
                                    print("[TEMP VOICE] créé SANS overwrites (hérite catégorie)")
                                except Exception as ex_c:
                                    print(f"[TEMP VOICE] création IMPOSSIBLE (manage_channels ?) : {ex_c}")
                        except Exception as ex_c:
                            print(f"[TEMP VOICE] création échouée : {ex_c}")

                        # ── GARANTIE D'ACCÈS + PAROLE (owner 2026-07-10) ──
                        # Objectif owner : à la création, TOUT LE MONDE peut voir, rejoindre ET PARLER
                        # (le point le plus important) ; seul le créateur a les boutons de gestion
                        # (fermer/renommer/limiter/kick) via son panneau. Si le bot ne peut pas poser
                        # les overwrites (perm « Gérer les rôles » manquante), le salon hérite de la
                        # catégorie/serveur → les gens rejoignent mais ne peuvent PAS parler (ou même
                        # pas entrer). On (re-)pose ici l'accès + la PAROLE pour le public (ou le rôle
                        # autorisé) + le créateur ; si c'est impossible, on prévient et on nettoie
                        # plutôt que de laisser un salon muet. No-op si tout est déjà bon (cas normal).
                        if new_channel is not None:
                            try:
                                # « audience » = qui doit pouvoir PARLER : public → @everyone ;
                                # hub restreint à un rôle → ce rôle.
                                audience = required_role if required_role else member.guild.default_role
                                ap = new_channel.permissions_for(audience)
                                cp = new_channel.permissions_for(member)
                                if not (ap.connect and ap.speak and cp.connect and cp.speak):
                                    try:
                                        if required_role:
                                            await new_channel.set_permissions(
                                                member.guild.default_role,
                                                view_channel=False, connect=False,
                                                reason="Vocal temp : masquer @everyone")
                                            await new_channel.set_permissions(
                                                required_role,
                                                view_channel=True, connect=True, speak=True,
                                                use_voice_activation=True, stream=True,
                                                reason="Vocal temp : rôle autorisé peut parler")
                                        else:
                                            await new_channel.set_permissions(
                                                member.guild.default_role,
                                                view_channel=True, connect=True, speak=True,
                                                use_voice_activation=True, stream=True,
                                                reason="Vocal temp : public peut parler")
                                        await new_channel.set_permissions(
                                            member, view_channel=True, connect=True, speak=True,
                                            use_voice_activation=True, stream=True,
                                            reason="Vocal temp : accès créateur")
                                    except Exception as _reex:
                                        print(f"[TEMP VOICE] re-pose overwrites échouée : {_reex}")
                                    ap = new_channel.permissions_for(audience)
                                # Si, même après, l'audience ne peut ni rejoindre ni parler → le bot
                                # n'a pas « Gérer les rôles » : on ne laisse pas un salon muet.
                                if not (ap.connect and ap.speak):
                                    print("🚨 [TEMP VOICE] audience sans accès/parole : il manque "
                                          "au bot « Gérer les rôles » — salon-piège nettoyé")
                                    try:
                                        await member.move_to(None)
                                    except Exception:
                                        pass
                                    try:
                                        await new_channel.delete(
                                            reason="Vocal temp muet (bot sans Gérer les rôles)")
                                    except Exception:
                                        pass
                                    new_channel = None
                            except Exception as _gaex:
                                print(f"[TEMP VOICE] garantie d'accès : {_gaex}")

                        if new_channel is not None:
                            temp_voice_channels[new_channel.id] = {
                                'owner': member.id,
                                'hub_id': after.channel.id,
                                'created_at': now(),
                            }
                            # Phase 235.5 : persister en DB pour le nettoyage au reboot
                            # (anti-orphelins — plainte récurrente des salons en bas).
                            try:
                                async with get_db() as _tvdb:
                                    await _tvdb.execute(
                                        "INSERT OR REPLACE INTO temp_voice_rooms"
                                        "(guild_id, channel_id, hub_id, owner_id) "
                                        "VALUES(?,?,?,?)",
                                        (member.guild.id, new_channel.id,
                                         after.channel.id, member.id))
                                    await _tvdb.commit()
                            except Exception as _tvex:
                                print(f"[TEMP VOICE persist] {_tvex}")
                            # Panneau de contrôle in-room (owner 2026-06-15) : poste dans le
                            # chat texte du vocal les boutons renommer/limite/lock/kick/transfert
                            # pour le propriétaire. FAIL-SAFE (n'empêche jamais la création/move).
                            # Déplacer le membre DANS son salon. Si le bot n'a pas
                            # « Déplacer des membres », on le prévient en DM.
                            try:
                                await member.move_to(new_channel)
                                print(f"[TEMP VOICE] Créé vocal '{channel_name}' pour {member.display_name} (hub: {after.channel.name})")
                            except discord.Forbidden:
                                print("🚨 [TEMP VOICE] il manque au bot « Déplacer des membres »")
                                await _mp_une_fois(
                                    member, "hub_deplacement",
                                    f"🔊 Ton salon **{channel_name}** est prêt sur "
                                    f"**{member.guild.name}** : rejoins-le directement.")
                            except Exception as ex_m:
                                print(f"[TEMP VOICE] move échoué : {ex_m}")
                            #  24/10/2026 : le panneau du vocal — son but (aide, farm, chill…), visible
                            #  dans son nom, pour que ceux qui ont le même besoin le rejoignent.
                            try:
                                await vocaux.poser_panneau(new_channel, str(hub_data.get('contexte') or 'commu'),
                                                           member)
                            except discord.HTTPException as _pex:
                                _logerr("vocaux.panneau", _pex, guild_id=member.guild.id)
            
            # Si l'utilisateur quitte un vocal temporaire → vérifier si vide et supprimer.
            # owner 2026-06-18 (« les vocaux ne se suppriment pas ») : on reconnaît le vocal
            # temp via le dict mémoire OU la table temp_voice_rooms (DB). Le dict est VIDÉ à
            # chaque reboot (Railway redéploie souvent) → sans la DB, un vocal créé AVANT un
            # redémarrage n'était plus reconnu à la sortie et s'empilait. Désormais :
            # suppression IMMÉDIATE dès que le salon devient vide, même juste après un reboot.
            # owner 2026-07-10 : garde de MOUVEMENT (comme les blocs entraide/tracking voisins) → on
            # ne teste la suppression QU'à un vrai départ/changement de salon, pas sur les toggles
            # self_mute/self_deaf/go-live/caméra (events vocaux les + fréquents) → supprime un SELECT
            # temp_voice_rooms par toggle sur TOUS les salons (même non temp) à l'échelle.
            if before.channel and (after.channel is None or before.channel.id != after.channel.id):
                _bid = before.channel.id
                _is_temp = _bid in temp_voice_channels
                if not _is_temp:
                    try:
                        async with get_db() as _ckdb:
                            async with _ckdb.execute(
                                "SELECT 1 FROM temp_voice_rooms WHERE channel_id=?",
                                (_bid,)) as _ck:
                                _is_temp = (await _ck.fetchone()) is not None
                    except Exception:
                        _is_temp = False
                if _is_temp:
                    await asyncio.sleep(1)
                    try:
                        channel = member.guild.get_channel(_bid)
                        if channel and len(channel.members) == 0:
                            await channel.delete(reason="Vocal temporaire vide")
                            temp_voice_channels.pop(_bid, None)
                            await _forget_temp_voice_room(_bid)
                            print(f"[TEMP VOICE] Supprimé vocal vide: {before.channel.name}")
                    except discord.NotFound:
                        temp_voice_channels.pop(_bid, None)
                        await _forget_temp_voice_room(_bid)
                    except Exception as ex:
                        print(f"[TEMP VOICE] Erreur suppression: {ex}")
                    
    except Exception as ex:
        print(f"Erreur temp voice: {ex}")

    # ═══════════════ VOCAL TEMP D'ENTRAIDE — auto-suppression si VIDE ═══════════════
    # Quand quelqu'un quitte un salon, si c'est un vocal temporaire d'entraide (nom « 🆘 … »
    # DANS la catégorie configurée) devenu VIDE, on le supprime. Double garde dans le helper :
    # jamais un vocal occupé, jamais un vocal non-entraide (incident connu). FAIL-SAFE.
    try:
        if before.channel and (after.channel is None or before.channel.id != after.channel.id):
            if (before.channel.name or '').startswith('🆘'):
                await asyncio.sleep(1)  # anti-course : laisse Discord propager le départ
                await _entraide_maybe_delete_empty_voice(member.guild, before.channel)
    except Exception as ex:
        print(f"[on_voice_state_update entraide] {ex}")

    # Rell Seas : un retour en vocal compte comme une présence du clan (le reste du suivi
    # vocal — XP, temps cumulé — est retiré le 19/10/2026).
    try:
        if after.channel and (before.channel is None or before.channel.id != after.channel.id):
            await update_realsy_activity(guild_id, user_id)
    except Exception as ex:
        print(f"[on_voice_state_update rellseas] {ex}")

async def _activite_suivi(guild_id, user_id) -> bool:
    """19/10/2026 : « un système d'inactivité en fonction d'un rôle que j'aurai moi-même
    prédéfini » — le « Rôle attribué » du menu Rell Seas. Sans rôle choisi : personne."""
    c = await cfg(guild_id)
    rid = int(c.get('rellseas_role', 0) or 0)
    g = bot.get_guild(int(guild_id))
    m = g.get_member(int(user_id)) if g else None
    if m is None:
        return False
    if rid and any(r.id == rid for r in m.roles):
        return True
    #  31/10/2026 : « le même système d'activité » pour le staff (onglet Staff de L'Équipage).
    return _est_du_staff(g, m, c)


def _roles_staff_suivis(g, c) -> list:
    """Les rôles du staff suivis (sans la Direction ni les fondateurs, qui sont mis à part)."""
    return list(_equipes_droits(g, c)[0])


def _est_du_staff(g, m, c) -> bool:
    ids = {r.id for r in _roles_staff_suivis(g, c)}
    return bool(ids) and any(r.id in ids for r in getattr(m, "roles", []) or [])


def _membres_du_staff(g, c) -> tuple:
    """(membres du staff suivis, leurs rôles) — pour le site ; jamais un bot."""
    roles = _roles_staff_suivis(g, c)
    ids = {r.id for r in roles}
    membres = [m for m in getattr(g, "members", []) or [] if not m.bot and any(r.id in ids for r in m.roles)]
    return membres, roles


# ═══════════════════════════════════════════════════════════════════════════════
#                           📨 TÂCHE AUTOMATIQUE MESSAGES PROGRAMMÉS
# ═══════════════════════════════════════════════════════════════════════════════





# ═══════════════════════════════════════════════════════════════════════════════
#                           📈 COMMANDES NIVEAU & BOUTIQUE
# ═══════════════════════════════════════════════════════════════════════════════


# Tâche pour retirer les rôles expirés
_ACHATS_VIDES = False


@tasks.loop(minutes=1)
async def check_expired_roles():
    """Rôles temporaires de l'ancienne boutique. Plus rien n'en vend : une table vide le
    reste, la boucle cesse alors de lire la base."""
    global _ACHATS_VIDES
    if _ACHATS_VIDES:
        return
    try:
        async with get_db() as db:
            now_str = now().isoformat()
            
            # Récupérer les achats expirés
            async with db.execute(
                'SELECT id, guild_id, user_id, role_id FROM shop_purchases WHERE expires_at < ?',
                (now_str,)
            ) as cursor:
                expired = await cursor.fetchall()
            if not expired:
                async with db.execute('SELECT COUNT(*) FROM shop_purchases') as cur:
                    _ACHATS_VIDES = not (await cur.fetchone())[0]
            
            for purchase_id, guild_id, user_id, role_id in expired:
                try:
                    guild = bot.get_guild(guild_id)
                    if guild:
                        member = guild.get_member(user_id)
                        role = guild.get_role(role_id)
                        
                        if member and role and role in member.roles:
                            await member.remove_roles(role, reason="Rôle boutique expiré")
                except:
                    pass
                
                # Supprimer l'entrée
                await db.execute('DELETE FROM shop_purchases WHERE id=?', (purchase_id,))
            
            await db.commit()
    except:
        pass

