async def _entraide_voice_category(guild):
    """Catégorie configurée pour les vocaux temporaires d'entraide, ou None.
    FAIL-SAFE : None (pas de vocal créé, le reste fonctionne quand même)."""
    try:
        if guild is None:
            return None
        c = await cfg(guild.id)
        cat_id = int(c.get('entraide_voice_category', 0) or 0)
        if not cat_id:
            return None
        cat = guild.get_channel(cat_id)
        if cat is None or not isinstance(cat, discord.CategoryChannel):
            return None
        return cat
    except Exception as ex:
        print(f"[_entraide_voice_category] {ex}")
        return None


async def _entraide_maybe_delete_empty_voice(guild, channel):
    """Supprime un vocal temporaire d'entraide DEVENU VIDE. Double garde stricte :
    (1) nom « 🆘 … » ET (2) parent == catégorie d'entraide configurée. Ne touche
    JAMAIS un vocal occupé ou non-entraide (incident connu). FAIL-SAFE : avale tout.
    Appelé depuis on_voice_state_update (quelqu'un vient de quitter) et depuis la
    tâche périodique (balayage des orphelins)."""
    try:
        if guild is None or channel is None or not isinstance(channel, discord.VoiceChannel):
            return
        if not (channel.name or '').startswith('🆘'):
            return  # garde 1 : pas un vocal d'entraide
        cat = await _entraide_voice_category(guild)
        # NB : si la catégorie n'est plus configurée, on ne supprime rien (fail-safe :
        # on évite de toucher un vocal dont on n'est plus sûr de l'appartenance).
        if cat is None or channel.category_id != cat.id:
            return  # garde 2 : hors de la catégorie d'entraide → on ne touche pas
        # Re-fetch frais (les .members peuvent être périmés) + petite latence anti-course.
        fresh = guild.get_channel(channel.id)
        if fresh is None or not isinstance(fresh, discord.VoiceChannel):
            return
        if len(fresh.members) != 0:
            return  # OCCUPÉ → on ne supprime JAMAIS un vocal occupé
        try:
            await fresh.delete(reason="Vocal d'entraide temporaire vide")
        except discord.NotFound:
            pass
        except discord.Forbidden:
            pass  # pas la perm → fail-safe
        except Exception as ex:
            print(f"[_entraide_maybe_delete_empty_voice delete] {ex}")
    except Exception as ex:
        print(f"[_entraide_maybe_delete_empty_voice] {ex}")






















# ═══════════════════════════════════════════════════════════════════════════════
#  VEILLEUR DE QUESTIONS SANS RÉPONSE (serveur entier) — anti « personne ne m'a aidé »
#
#  OBJECTIF : ne laisser AUCUN joueur sans la moindre réponse pendant ~10 min après
#  une VRAIE question, SAUF si c'est banal (affirmation, remerciement, message court…).
#  Choix owner validés : portée = TOUT le serveur (salons chatty) · délai ~10 min ·
#  action = nudge DISCRET dans le salon (+ bouton entraide pré-rempli si configuré) ·
#  JAMAIS @everyone/@here/rôle, JAMAIS de MP, au plus une mention NORMALE de l'auteur.
#
#  PERFORMANCE (tourne à CHAQUE message / reaction) :
#    • on_message  : 1er passage 100% MÉMOIRE (_is_genuine_question, motifs réutilisés).
#                    AUCUNE DB tant qu'il n'y a pas de match « vraie question ».
#    • on_raw_reaction_add : test d'appartenance O(1) au dict pending → return immédiat
#                    si le message réagi n'est pas suivi (chemin chaud = 1 dict.get).
#  Le suivi vit dans un dict mémoire BORNÉ `_unanswered_pending` (cap + éviction FIFO).
#  Le SWEEP périodique (supervisé, fail-open) poste les nudges après ~10 min.
#  Tout en try/except : ne casse JAMAIS on_message / on_raw_reaction_add.
# ═══════════════════════════════════════════════════════════════════════════════


# Suivi mémoire BORNÉ des questions en attente de réponse :
#   message_id -> {guild_id, channel_id, author_id, ts (datetime), game_key (str|None)}
_unanswered_pending: dict = {}


def _unanswered_clear(message_id) -> None:
    """Retire une entrée du pending (cheap, idempotent). FAIL-SAFE."""
    try:
        _unanswered_pending.pop(int(message_id), None)
    except Exception:
        pass


def _unanswered_on_reaction(payload):
    """Hook appelé depuis on_raw_reaction_add. CHEMIN CHAUD : test O(1) au dict pending.
    Si le message réagi n'est pas suivi → return immédiat (zéro travail).

    ⚠️ CORRECTION owner 2026-06-14 (CAUSE RACINE) : une RÉACTION n'est PAS une réponse →
    elle NE clôt PLUS une question suivie. AVANT, une réaction de N'IMPORTE QUI (y compris
    une auto-réaction du bot ou un simple emoji de sympathie 👏/☀️/🌙) clôturait la question
    → le veilleur ne nudgeait JAMAIS ces demandes (EXACTEMENT les exemples montrés par
    l'owner : tous réagis, jamais répondus). SEULE exception : l'AUTEUR marque LUI-MÊME sa
    question résolue (✅/☑️/✔️/👍). FAIL-SAFE."""
    try:
        if not _unanswered_pending:
            return
        mid = int(getattr(payload, 'message_id', 0) or 0)
        ent = _unanswered_pending.get(mid)
        if ent is None:
            return  # pas suivi → return immédiat (chemin chaud)
        reactor_id = int(getattr(payload, 'user_id', 0) or 0)
        # Réaction de l'AUTEUR avec un emoji « résolu » → il clôt sa propre question.
        # Toute autre réaction (autre membre, bot) est IGNORÉE (n'est pas une réponse).
        if reactor_id and reactor_id == int(ent.get('author_id', 0)):
            emoji = str(getattr(payload, 'emoji', '') or '')
            if any(e in emoji for e in ("✅", "☑️", "✔️", "👍")):
                _unanswered_clear(mid)
    except Exception:
        pass


def _unanswered_clear_for_author(guild_id: int, author_id: int) -> None:
    """Retire toutes les questions suivies d'un auteur (départ du serveur). FAIL-SAFE."""
    try:
        gid, aid = int(guild_id), int(author_id)
        for mid, e in list(_unanswered_pending.items()):
            try:
                if int(e.get('guild_id', 0)) == gid and int(e.get('author_id', 0)) == aid:
                    _unanswered_pending.pop(mid, None)
            except Exception:
                continue
    except Exception:
        pass












































# ═══════════════════════════════════════════════════════════════════════════════
#  i18n — SÉLECTEUR DE LANGUE (zéro slash, tout bouton/DynamicItem, FAIL-SAFE)
#
#  Serveur INTERNATIONAL : un membre choisit sa langue via un bouton du hub (catégorie
#  « Récit & Aide »). Au clic on : (1) persiste la préférence (i18n.set_user_lang),
#  (2) attribue un ROLE DRAPEAU décoratif (zéro perm) en retirant les autres rôles de
#  langue, (3) confirme en ÉPHÉMÈRE DANS LA LANGUE choisie via i18n.t(). Les boutons
#  de choix sont des DynamicItem (custom_id i18n_setlang:<lang>) → ils survivent au
#  reboot. AUTO-DÉTECTION : à la 1re ouverture sans préférence, on pose la langue
#  déduite de la locale Discord (silencieux, sans MP, sans spam).
# ═══════════════════════════════════════════════════════════════════════════════

# Préfixe des rôles drapeau (décoratifs). Sert à les reconnaître pour en retirer les
# autres quand un membre change de langue. Globe neutre + libellé natif → « 🌐 Français ».
LANG_ROLE_PREFIX = "🌐 "


def _i18n_lang_role_name(lang: str) -> str:
    """Nom du rôle drapeau pour une langue : « 🌐 English ». FAIL-SAFE."""
    try:
        label = i18n_module.LANG_LABELS.get(i18n_module.normalize_lang(lang), lang)
    except Exception:
        label = str(lang)
    return f"{LANG_ROLE_PREFIX}{label}"


def _i18n_all_lang_role_names() -> set:
    """Tous les noms de rôles de langue gérés (pour le nettoyage). FAIL-SAFE."""
    try:
        return {_i18n_lang_role_name(l) for l in i18n_module.SUPPORTED_LANGS}
    except Exception:
        return set()


async def _i18n_assign_lang_role(member, lang) -> None:
    """Attribue le rôle drapeau de `lang` au membre et retire les autres rôles de
    langue. Crée le rôle s'il n'existe pas (décoratif : aucune permission, hoist off,
    mentionnable off). TOTALEMENT FAIL-SAFE : si « Gérer les rôles » manque ou que le
    rôle est trop haut, on n'échoue PAS — la préférence reste enregistrée, on saute
    juste le rôle. Aucune exception ne sort jamais."""
    try:
        guild = getattr(member, "guild", None)
        if guild is None:
            return
        me = guild.me
        if me is None or not me.guild_permissions.manage_roles:
            return  # pas la perm → on garde juste la préférence (fail-safe)

        target_name = _i18n_lang_role_name(lang)
        managed_names = _i18n_all_lang_role_names()

        # Rôle cible : réutilise s'il existe, sinon le crée (décoratif).
        target_role = discord.utils.get(guild.roles, name=target_name)
        if target_role is None:
            try:
                target_role = await guild.create_role(
                    name=target_name,
                    permissions=discord.Permissions.none(),
                    mentionable=False,
                    hoist=False,
                    reason="i18n : rôle de langue décoratif",
                )
            except Exception as ex:
                print(f"[i18n create_role] {ex}")
                target_role = None

        # Retire les AUTRES rôles de langue que le membre porterait déjà.
        try:
            to_remove = [
                r for r in getattr(member, "roles", [])
                if r.name in managed_names and (target_role is None or r.id != target_role.id)
                and r < me.top_role and not r.managed
            ]
            if to_remove:
                await member.remove_roles(*to_remove, reason="i18n : changement de langue")
        except Exception as ex:
            print(f"[i18n remove old lang roles] {ex}")

        # Ajoute le rôle cible (s'il a pu être obtenu et qu'on est au-dessus).
        try:
            if (target_role is not None and target_role < me.top_role
                    and not target_role.managed and target_role not in getattr(member, "roles", [])):
                await member.add_roles(target_role, reason="i18n : langue choisie")
        except Exception as ex:
            print(f"[i18n add lang role] {ex}")
    except Exception as ex:
        print(f"[_i18n_assign_lang_role] {ex}")


async def _i18n_apply_lang(i: discord.Interaction, lang: str) -> None:
    """Cœur commun du choix de langue (appelé par les boutons drapeau). Defer-first,
    persiste la préférence, attribue le rôle drapeau, confirme EN ÉPHÉMÈRE dans la
    langue choisie via i18n.t(). FAIL-SAFE de bout en bout."""
    try:
        lang = i18n_module.normalize_lang(lang)
        if not await _safe_defer(i, ephemeral=True):
            return
        uid = getattr(getattr(i, "user", None), "id", None)
        if uid is not None:
            await i18n_module.set_user_lang(uid, lang)
        member = getattr(i, "user", None)
        if getattr(i, "guild", None) is not None and member is not None:
            await _i18n_assign_lang_role(member, lang)
        # Confirmation DANS la langue choisie (label natif + drapeau).
        try:
            label = i18n_module.lang_choice_label(lang)  # « 🇫🇷 Français »
            msg = i18n_module.t("lang.changed", lang, lang=label)
        except Exception:
            msg = "✅"
        await _safe_followup(i, content=f"✅ {msg}")
    except Exception as ex:
        print(f"[_i18n_apply_lang] {ex}")
        try:
            await _safe_followup(i, content="✅")
        except Exception:
            pass


class LangSelectButton(
    discord.ui.DynamicItem[Button],
    template=r"i18n_setlang:(?P<lang>[a-z]{2})",
):
    """Bouton PERSISTANT d'un drapeau de langue (un par langue supportée). DynamicItem
    → re-capté au reboot via le custom_id i18n_setlang:<lang>. Au clic → applique la
    langue (préférence + rôle + confirmation traduite)."""

    def __init__(self, lang: str):
        self.lang = i18n_module.normalize_lang(lang)
        super().__init__(
            Button(
                label=i18n_module.LANG_LABELS.get(self.lang, self.lang),
                emoji=i18n_module.LANG_FLAGS.get(self.lang) or None,
                style=discord.ButtonStyle.secondary,
                custom_id=f"i18n_setlang:{self.lang}",
            )
        )

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["lang"])

    async def callback(self, i: discord.Interaction):
        await _i18n_apply_lang(i, self.lang)


class RobloxPingButton(discord.ui.DynamicItem[discord.ui.Button],
                       template=r"rbxping:(?P<cle>[a-z_]+)"):
    """Le bouton « 🔔 Me prévenir · arrêter » sous chaque annonce Roblox.

    Demande du propriétaire (19/08/2026) : un rôle de ping par TYPE d'annonce,
    pris et rendu d'un seul clic sur le bouton posé sous la fiche.

    ⚠️ `DynamicItem`, pas une View fixe. Le `custom_id` porte la catégorie
    (`rbxping:studio`, `rbxping:limited`…) : une seule classe couvre les huit,
    et le clic reste capté après un redémarrage parce que
    `bot.add_dynamic_items(RobloxPingButton)` la réenregistre au boot. Sans ce
    réenregistrement, TOUS les boutons déjà posés dans l'historique du salon
    deviendraient muets — c'est exactement ce qui est arrivé au bouton langue
    de l'accueil, réparé le matin même.

    ⚠️ ACQUITTER D'ABORD. La bascule touche la base ET l'API des rôles ; sans
    `defer` immédiat, un démarrage à froid dépasse les trois secondes de
    Discord et le membre voit « n'a pas répondu à temps ».

    Réponse ÉPHÉMÈRE : l'abonnement d'un membre ne regarde personne d'autre, et
    un salon d'actualités ne doit pas se remplir de confirmations.
    """

    def __init__(self, cle: str):
        self.cle = cle
        super().__init__(discord.ui.Button(
            label="Me prévenir · arrêter", emoji=visuels.icone("cloche"),
            style=discord.ButtonStyle.secondary,
            custom_id=roblox_pings_module.custom_id(cle)))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["cle"])

    async def callback(self, i: discord.Interaction):
        if not await _safe_defer(i, ephemeral=True):
            return
        try:
            if i.guild is None:
                await _safe_followup(i, content="❌ Serveur uniquement.")
                return
            etat, _role = await roblox_pings_module.basculer(
                i.guild, i.user, self.cle)
            #  `phrase` dit l'état RÉEL, y compris les deux échecs distincts
            #  (permission manquante / rôle trop haut). On ne répond jamais
            #  « c'est fait » sans que ce soit fait.
            await _safe_followup(i, content=roblox_pings_module.phrase(etat, self.cle))
        except Exception as ex:
            print(f"[RobloxPingButton {self.cle}] {ex}")
            await _safe_followup(i, content="❌ Impossible pour le moment.")


class AccueilLangueView(discord.ui.View):
    """Le bouton « 🌍 Ma langue / My language » de la carte d'accueil.

    ⚠️ VUE PERSISTANTE — `timeout=None` + custom_id stable, réenregistrée au
    boot par `bot.add_view(AccueilLangueView())`. SANS ce réenregistrement,
    personne n'écoute le custom_id `onb_lang` : Discord attend trois secondes
    puis affiche « n'a pas répondu à temps ». C'est exactement ce qui est
    arrivé quand la purge a emporté `OnboardingView` en laissant le bouton
    posé sur chaque carte d'accueil (constaté par le propriétaire le 19/08).

    ⚠️ ELLE NE DÉCIDE RIEN. Elle ouvre le sélecteur qui existe déjà —
    `LangSelectButton` → `_i18n_apply_lang` (préférence + rôle drapeau +
    confirmation traduite). Un second chemin de choix de langue divergerait du
    premier au premier correctif. Ne PAS en écrire un ici.

    Ne porte QUE la langue : les anciens boutons hub / parcours / notifications
    appartenaient à l'animation retirée, ils ne reviennent pas.
    """

    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(emoji=visuels.icone("globe"), label="Ma langue / My language",
                       style=discord.ButtonStyle.secondary,
                       custom_id="onb_lang")
    async def _cb_langue(self, i: discord.Interaction, _b: discord.ui.Button):
        #  ⚠️ ACQUITTER AVANT TOUTE LECTURE : `lang_of` touche la base, et un
        #  démarrage à froid dépasserait les trois secondes de Discord.
        if not await _safe_defer(i, ephemeral=True):
            return
        try:
            actuelle = await i18n_module.lang_of(
                user_id=getattr(getattr(i, "user", None), "id", None),
                interaction=i,
                guild_id=(i.guild.id if getattr(i, "guild", None) else None))
        except Exception as ex:
            print(f"[AccueilLangueView lang_of] {ex}")
            actuelle = "fr"
        try:
            v = discord.ui.View(timeout=None)
            #  Les SIX langues supportées, pas seulement celles du serveur : la
            #  préférence est personnelle (elle suit le membre d'un serveur à
            #  l'autre) et le catalogue les traduit toutes.
            for _l in i18n_module.SUPPORTED_LANGS:
                v.add_item(LangSelectButton(_l))
            entete = i18n_module.t("lang.choose", actuelle)
            await _safe_followup(
                i,
                content=(f"🌍 **{entete}**\n"
                         f"— {i18n_module.lang_choice_label(actuelle)}"),
                view=v)
        except Exception as ex:
            print(f"[AccueilLangueView] {ex}")
            await _safe_followup(
                i, content="❌ Sélecteur de langue indisponible — réessaie dans un instant.")


