# ─── ALT DETECTION (heuristique légère sur on_member_join) ──────────────────


async def _check_alt_account(member: discord.Member):
    """Check si un nouveau membre ressemble suspectement à un membre existant.

    Heuristique :
    - Compte créé < 7 jours
    - Username similar (≥80%) à un membre banni récent OU à un membre actuel
    """
    if not member.guild or member.bot:
        return
    try:
        # Skip si compte créé > 7 jours (probablement pas un alt)
        if member.created_at and (datetime.now(timezone.utc) - member.created_at).days > 7:
            return
        # Récupérer un échantillon de membres pour comparaison
        from difflib import SequenceMatcher
        my_name = (member.name or "").lower()
        if not my_name or len(my_name) < 3:
            return
        candidates = []
        for other in list(member.guild.members)[:200]:
            if other.bot or other.id == member.id:
                continue
            other_name = (other.name or "").lower()
            if not other_name or len(other_name) < 3:
                continue
            ratio = SequenceMatcher(None, my_name, other_name).ratio()
            if ratio >= 0.80:
                candidates.append((other, ratio))
        if not candidates:
            return
        # Pick le top candidat
        candidates.sort(key=lambda x: -x[1])
        top, ratio = candidates[0]
        # Log
        async with get_db() as db:
            await db.execute(
                "INSERT INTO alt_detection_log"
                "(guild_id, new_user_id, similar_to_user_id, reason, confidence) "
                "VALUES(?, ?, ?, ?, ?)",
                (member.guild.id, member.id, top.id,
                 f"username similar (ratio={ratio:.2f}) + account < 7 days", ratio),
            )
            await db.commit()
        # ⚠️ EN SALON, PAS EN MP (12/08/2026). Contrairement aux autres alertes,
        # celle-ci n'était écrite QUE dans `alt_detection_log` : aucun salon ne la
        # recevait. La supprimer aurait perdu l'information au lieu de la déplacer.
        if ratio >= 0.90:
            try:
                _c = await cfg(member.guild.id)
                _lid = int(_c.get('log_anti_alt', 0) or _c.get('mod_log_channel', 0) or 0)
                _lch = member.guild.get_channel(_lid) if _lid else None
                if _lch is not None:
                    await _lch.send(
                        allowed_mentions=discord.AllowedMentions.none(),
                        view=carte_embed(discord.Embed(
                            title="Compte secondaire présumé — nouveau membre",
                            description=(
                                f"**Nouveau :** {member.mention} (`{member.name}`)" + chr(10) +
                                f"**Ressemble à :** {top.mention} (`{top.name}`)" + chr(10) +
                                f"**Similarité :** `{ratio:.0%}` · compte de moins de 7 jours"
                            ),
                            color=0xE67E22,
                        ), _vue_alerte(member.id)),
                    )
            except Exception as _exalt:
                print(f"[alt detection salon] {_exalt}")
    except Exception as ex:
        print(f"[_check_alt_account] {ex}")


# ─── SLOW MODE AUTO-DYNAMIQUE ────────────────────────────────────────────────


_channel_msg_rates: dict = {}  # channel_id → [timestamps des derniers msgs]


_auto_slow_pending: dict = {}  # {channel_id: epoch} anti-rafale d'edit (audit 2026-07-02)


async def _lever_ralentis(guild) -> None:
    """Le ralentissement automatique est levé dès que le calme revient, vérifié toutes les 5 min par
    `server_controls_task` à partir de `auto_slow_log` : aussi après un redémarrage, ou quand le salon
    était encore agité à +2 min (avant, il restait pour toujours — audit 19/10/2026)."""
    async with get_db() as db:
        async with db.execute("SELECT DISTINCT channel_id FROM auto_slow_log WHERE guild_id=? AND cleared_at IS NULL",
                              (guild.id,)) as cur:
            salons = [r[0] for r in await cur.fetchall()]
    maintenant = time.time()
    for cid in salons:
        ch = guild.get_channel(cid)
        if ch is not None and len([t for t in _channel_msg_rates.get(cid, []) if t > maintenant - 60]) >= 10:
            continue  # toujours agité : on revient dans 5 min
        if ch is not None and getattr(ch, "slowmode_delay", 0) == 5:  # un autre réglage est celui du staff
            await ch.edit(slowmode_delay=0, reason="Auto-slow : calme revenu")
        async with get_db() as db:
            await db.execute("UPDATE auto_slow_log SET cleared_at=CURRENT_TIMESTAMP WHERE channel_id=? AND cleared_at IS NULL",
                             (cid,))
            await db.commit()


async def _check_auto_slow_mode(msg):
    """Active slow mode si > 30 msgs/min dans un channel."""
    if not msg.guild or msg.author.bot:
        return
    try:
        cid = msg.channel.id
        now_ts = datetime.now(timezone.utc).timestamp()
        # MÉMOIRE (revue totale) : éviction paresseuse — sans purge, ce dict module-level
        # grossit à vie (1 clé/salon-ou-thread ayant reçu un msg ; les threads éphémères
        # fuient). Quand il dépasse 2000 clés, on retire celles inactives depuis > 5 min
        # (inutiles pour le calcul 60s). Auto-contenu : pas de 2e @bot.event (piège mémoire).
        if len(_channel_msg_rates) > 2000:
            _cut = now_ts - 300
            for _k, _v in list(_channel_msg_rates.items()):
                if not _v or _v[-1] < _cut:
                    _channel_msg_rates.pop(_k, None)
        timestamps = _channel_msg_rates.setdefault(cid, [])
        # Purge old (> 60s)
        timestamps = [t for t in timestamps if t > now_ts - 60]
        timestamps.append(now_ts)
        _channel_msg_rates[cid] = timestamps[-100:]  # garde max 100 last
        # Si > 30 msgs/min, activer slow 5s
        if len(timestamps) > 30:
            # Check si déjà en slow
            if msg.channel.slowmode_delay > 0:
                return
            # Anti-rafale (audit 2026-07-02) : slowmode_delay est mis en cache et n'est rafraîchi
            # qu'au CHANNEL_UPDATE (après RTT) → plusieurs messages de la rafale lisaient 0 et
            # lançaient chacun un edit + un lift. Garde synchrone (aucun await avant le set) :
            _prev = _auto_slow_pending.get(cid)
            if _prev is not None and (now_ts - _prev) < 130:
                return
            _auto_slow_pending[cid] = now_ts
            if len(_auto_slow_pending) > 2000:
                _cut2 = now_ts - 300
                for _k2, _v2 in list(_auto_slow_pending.items()):
                    if _v2 < _cut2:
                        _auto_slow_pending.pop(_k2, None)
            try:
                await msg.channel.edit(slowmode_delay=5, reason="Auto-slow : > 30 msgs/min")
                async with get_db() as db:
                    await db.execute(
                        "INSERT INTO auto_slow_log(guild_id, channel_id, slow_delay) VALUES(?,?,?)",
                        (msg.guild.id, cid, 5),
                    )
                    await db.commit()
                # Schedule lift après 2 min de calme
                async def _lift_slow(ch_id):
                    await asyncio.sleep(120)
                    try:
                        # Check si toujours bas
                        now_ts2 = datetime.now(timezone.utc).timestamp()
                        rt = _channel_msg_rates.get(ch_id, [])
                        rt = [t for t in rt if t > now_ts2 - 60]
                        if len(rt) < 10:
                            ch_obj = msg.guild.get_channel(ch_id)
                            if ch_obj and ch_obj.slowmode_delay > 0:
                                await ch_obj.edit(slowmode_delay=0, reason="Auto-slow : calme revenu")
                                async with get_db() as db:
                                    await db.execute(
                                        "UPDATE auto_slow_log SET cleared_at=CURRENT_TIMESTAMP "
                                        "WHERE channel_id=? AND cleared_at IS NULL",
                                        (ch_id,),
                                    )
                                    await db.commit()
                    except Exception:
                        pass
                    finally:
                        _auto_slow_pending.pop(ch_id, None)  # ré-armable pour une future rafale
                asyncio.create_task(_lift_slow(cid))
                print(f"[AUTO SLOW] channel={cid} 5s activé")
            except discord.Forbidden:
                pass
            except Exception as ex:
                print(f"[auto_slow edit] {ex}")
    except Exception as ex:
        print(f"[_check_auto_slow_mode] {ex}")


